(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("appian-foreign-wars-2-e", [{"sp": "HDR", "t": "Ῥωμαϊκά"}, {"sp": "HDR", "t": "Ἐκ τῆς Νομαδικῆς", "st": "1"}, {"sp": "N", "t": "ὅτι Βομίλχας κατηγορούμενος ἔφυγε πρὸ δίκης, καὶ Ἰογόρθας σὺν αὐτῷ, τοῦτο δὴ τὸ περιφερόμενον ἐς τοὺς δωροδοκοῦντας εἰπών, ὅτι Ῥωμαίων ἡ πόλις ἐστὶν ὠνία πᾶσα, εἴ τις ὠνητὴς αὐτῆς εὑρεθείη.", "st": "1.1"}, {"sp": "N", "t": "ὅτι Μέτελλος ἀνεζεύγνυεν ἐς Λιβύην τὴν ὑπὸ Ῥωμαίοις αἰτίαν ἔχων παρὰ τῷ στρατῷ βραδυτῆτος ἐς τοὺς πολεμίους καὶ ἐπὶ σφίσιν ὠμότητος· σφόδρα γὰρ τοὺς ἁμαρτάνοντας ἐκόλαζεν.", "st": "1.2"}, {"sp": "N", "t": "ὅτι Μέτελλος Βαγαίων ἀνῄρει τὴν βουλὴν ὅλην ὡς τὴν φρουρὰν προδόντας Ἰογόρθᾳ, καὶ τὸν φρούραρχον Τουρπίλιον, ἄνδρα Ῥωμαῖον οὐκ ἀνυπόπτως ἑαυτὸν ἐγχειρίσαντα τοῖς πολεμίοις, ἐπαπκέτεινε τῇ βουλῇ. Θρᾷκας δὲ καὶ Λίγυας αὐτομόλους λαβὼν παρὰ Ἰογόρθα, τῶν μὲν τὰς χεῖρας ἀπέτεμνε, τοὺς δὲ ἐς τὴν γῆν μέχρι γαστρὸς κατώρυσσε, καὶ περιτοξεύων ἢ ἐσακοντίζων ἔτι ἐμπνέουσι πῦρ ὑπετίθει.", "st": "1.3"}, {"sp": "N", "t": "ὅτι τοῦ Μαρίου ἐς Κίρταν ἀφικομένου πρέσβεις Βόκχου παρῆσαν, οἳ πεμφθῆναί τινας ἐς λόγους Βόκχῳ παρεκάλουν. καὶ ἐπέμφθησαν Αὖλός τε Μάλλιος ὁ πρεσβευτὴς καὶ Κορνήλιος Σύλλας ὁ ταμίας, οἷς ὁ Βόκχος ἔφη Ῥωμαίοις πολεμῆσαι διὰ Μάριον· γῆν γὰρ ἣν αὐτὸς Ἰογόρθαν ἀφείλετο, πρὸς Μαρίου νῦν ἀφῃρῆσθαι. Βόκχος μὲν δὴ ταῦτα ἐνεκάλει, Μάλλιος δ’ ἔφη τὴν γῆν τήνδε Ῥωμαίους ἀφελέσθαι Σύφακα πολέμου νόμῳ καὶ δοῦναι Μασσανάσσῃ δωρεάν, διδόναι δὲ Ῥωμαίους τὰς δωρεὰς ἔχειν τοῖς λαβοῦσιν ἕως ἂν τῇ βουλῇ καὶ τῷ δήμῳ δοκῇ. οὐ μὴν ἀλόγως μεταγνῶναι· Μασσανάσσην τε γὰρ ἀποθανεῖν, καὶ τοὺς Μασσανάσσου παῖδας Ἰογόρθαν κατακαίνοντα Ῥωμαίοις πολέμιον γενέσθαι. οὐκ οὖν ἔτι εἶναι δίκαιον οὔτε τὸν πολέμιον ἔχειν δωρεὰν ἣν ἔδομεν φίλῳ, οὔτε σὲ δοκεῖν Ἰογόρθαν ἀφαιρεῖσθαι τὰ Ῥωμαίων. καὶ Μάλλιος μὲν τάδε περὶ τῆς γῆς ἔλεξεν.", "st": "1.4"}, {"sp": "N", "t": "ὅτι ὁ Βόκχος ἑτέρους ἔπεμψε πρέσβεις, οἳ Μαρίου μὲν ἔμελλον περὶ εἰρήνης δεήσεσθαι, Σύλλα δὲ ἵνα συμπράξειεν ἐς τὰς διαλύσεις. λῃστευθέντας δ’ ἐν ὁδῷ τοὺς πρέσβεις τούσδε ὁ Σύλλας ὑπεδέξατο, καὶ ξενίζει μέχρι Μάριον ἀπὸ Γαιτούλων ἐπανελθεῖν. παρῄνει δὲ Βόκχον διδάσκειν ὅτι χρὴ Σύλλᾳ πείθεσθαι περὶ ἁπάντων. ἐνδιδοὺς οὖν ἤδη πρὸς τὴν τοῦ Ἰογόρθα προδοσίαν ὁ Βόκχος, ἐς μὲν ὑπόκρισιν ἐπ’ ἄλλον στρατὸν περιέπεμπεν ἐς Αἰθίοπας τοὺς γείτονας, οἳ ἐπὶ ἑσπέραν ἀπὸ τῶν ἑώων Αἰθιόπων διήκουσιν ἐς τὸ Μαυρούσιον ὄρος ὃ καλοῦσιν Ἄτλαντα, Μάριον δ’ ἠξίου Σύλλαν οἱ πέμψαι συνελθεῖν ἐς λόγους. καὶ Μάριος μὲν ἔπεμπε τὸν Σύλλαν, Ἄψαρα δὲ Ἰογόρθα φίλον, ἐν Βόκχου καταλελειμμένον ἐφορᾶν τὰ γιγνόμενα, αὐτός τε Βόκχος καὶ Μαγδάλσης φίλος Βόκχου, καί τις ἐξελεύθερος ἀνδρὸς Καρχηδονίου, Κορνήλιος, ἐνήδρευσαν ὧδε.", "st": "1.5"}, {"sp": "HDR", "t": "Ἐκ τῆς Μακεδονικῆς", "st": "2"}, {"sp": "N", "t": "ὅτι Ῥωμαῖοι τοῦ Φιλίππου τοῦ Μακεδόνος τοῦ πολεμήσαντος αὐτοῖς πέρι πάμπαν ἐπολυπραγμόνουν οὐδέν, οὐδὲ σφίσιν ἐνθύμιος ἦν ὅλως πονουμένης ἔτι τῆς Ἰταλίας ὑπὸ Ἀννίβου τοῦ Καρχηδονίων στρατηγοῦ, καὶ αὐτοὶ μεγάλοις στρατοῖς Λιβύην καὶ Καρχηδόνα καὶ Ἰβηρίαν περικαθήμενοι, καὶ καθιστάμενοι Σικελίαν. αὐτὸς δὲ Φίλιππος ἀρχῆς ἐπιθυμίᾳ μείζονος, οὐδέν τι προπαθών, ἔπεμπε πρὸς Ἀννίβαν ἐς τὴν Ἰταλίαν πρέσβεις, ὧν ἡγεῖτο Ξενοφάνης, ὑπισχνούμενος αὐτῷ συμμαχήσειν ἐπὶ τὴν Ἰταλίαν, εἰ κἀκεῖνος αὐτῷ σύνθοιτο κατεργάσασθαι τὴν Ἑλλάδα. συμβάντος δ’ ἐς ταῦτα τοῦ Ἀννίβου καὶ ἐπὶ τῇ συνθήκῃ ὀμόσαντος, πρέσβεις τε ἀντιπέμψαντος ἐπὶ τοὺς ὅρκους τοῦ Φιλίππου, Ῥωμαίων τριήρης ἔλαβε τοὺς ἑκατέρων πρέσβεις ἀναπλέοντας, καὶ ἐς Ῥώμην ἐκόμισεν. ἐφ’ ᾧ Φίλιππος ἀγανακτῶν Κερκύρᾳ προσέβαλεν, ἣ Ῥωμαίοις συνεμάχει.", "st": "2.1"}, {"sp": "N", "t": "ότι ἐνῆγε τοὺς Ῥωμαίους τὰ Σιβύλλεια εἰς τὸν Φιλίππου πόλεμον. ἔστι δὲ ταῦτα· αὐχοῦντες βασιλεῦσι Μακηδόνες Ἀργεάδῃσιν, ὑμῖν κοιρανέων ἀγαθὸν καὶ πῆμα Φίλιππος. ἤτοι ὁ μὲν πρότερος πόλεσιν λαοῖσί τ’ ἄνακτας θήσει, ὁ δ’ ὁπλότερος τιμὴν ἀπὸ πᾶσαν ὀλέσσει, δμηθεὶς δ’ ἑσπερίοισιν ὑπ’ ἀνδράσιν ἐνθάδ’ ὀλεῖται.", "st": "2.2"}, {"sp": "N", "t": "ὅτι Πτολεμαίου τοῦ βασιλεύοντος Αἰγύπτου πρέσβεις, καὶ σὺν αὐτοῖς ἕτεροι παρά τε Χίων καὶ Μιτυληναίων καὶ Ἀμυνάνδρου τοῦ Ἀθαμάνων βασιλέως, δίς, ἔνθα περ οἱ Αἰτωλοὶ τὰς πόλεις ἐπισκεψομένας ἐκάλουν, συνῆλθον ἐπὶ διαλλαγῇ Ῥωμαίων καὶ Αἰτωλῶν καὶ Φιλίππου. Σουλπικίου δ’ εἰπόντος οὐκ εἶναι κυρίου περὶ τῆς εἰρήνης τι κρῖναι, καὶ ἐς τὴν βουλὴν κρύφα ἐπιστέλλοντος ὅτι Ῥωμαίοις συμφέρει πολεμεῖν Αἰτωλοὺς Φιλίππῳ, ἡ μὲν βουλὴ τὰς συνθήκας ἐκώλυσε, καὶ τοῖς Αἰτωλοῖς ἔπεμπε συμμαχίαν πεζοὺς μυρίους καὶ ἱππέας χιλίους, μεθ’ ὧν οἱ Αἰτωλοὶ κατέλαβον Ἀμβρακίαν, ἣν οὐ πολὺ ὕστερον αὐτῶν Φίλιππος ἀποπλευσάντων ἀνέλαβεν. οἱ δὲ πρέσβεις αὖθις συνῆλθον, καὶ πολλὰ φανερῶς ἔλεγον, ὅτι Φίλιππος καὶ Αἰτωλοὶ διαφερόμενοι τοὺς Ἕλληνας ἐς δουλείαν Ῥωμαίοις ὑποβάλλουσιν, ἐθίζοντες αὐτοὺς τῆς Ἑλλάδος θαμινὰ πειρᾶσθαι. ἐφ’ οἷς ὁ μὲν Σουλπίκιος ἀντιλέξων ἀνίστατο, τὸ δὲ πλῆθος οὐκ ἤκουσεν, ἀλλ’ ἐκεκράγεσαν τοὺς πρέσβεις εὖ λέγειν.", "st": "2.3"}, {"sp": "N", "t": "καὶ τέλος Αἰτωλοί τε πρῶτοι κατὰ σφᾶς, ἄνευ Ῥωμαίων, Φιλίππῳ συνέβησαν, καὶ πρέσβεις αὐτοῦ Φιλίππου καὶ Ῥωμαίων ἐπὶ διαλλαγαῖς ἀφίκοντο ἐς Ῥώμην. καὶ ἐγένοντο συνθῆκαι Ῥωμαίοις καὶ Φιλίππῳ, μηδετέρους ἀδικεῖν τοὺς ἑκατέρωθεν φίλους. ἐς μὲν δὴ τοῦτ’ ἔληξεν ἡ Φιλίππου καὶ Ῥωμαίων ἐς ἀλλήλους πεῖρα πρώτη, καὶ τὰς συνθήκας οὐδέτεροι βεβαίους, οὐδ’ ἀπ’ εὐνοίας, ἐδόκουν πεποιῆσθαι.", "st": "2.3"}, {"sp": "N", "t": "ὅτι μετ’ οὐ πολὺ Φίλιππος μὲν τῶν ὑπηκόων τοῖς ἐπὶ θαλάσσης στόλον ἐπαγγείλας, Σάμον καὶ Χίον εἷλε, καὶ μέρος τῆς Ἀττάλου γῆς ἐπόρθησε, καὶ αὐτῆς ἀπεπείρασε Περγάμου, μὴ φειδόυενος ἱερῶν ἢ τάφων, τήν τε Ῥοδίων περαίαν ἐδῄου διαλλακτήρων οἱ γεγονότων, καὶ ἑτέρῳ μέρει στρατοῦ τὴν Ἀττικὴν ἐλυμαίνετο καὶ τὰς Ἀθήνας ἐπολιόρκει, ὡς οὐδὲν τῶνδε Ῥωμαίοις προσηκόντων. λόγος τε ἦν ὅτι Φίλιππος καὶ Ἀντίοχος ὁ Σύρων βασιλεὺς ὑπόσχοιντο ἀλλήλοις, Ἀντιόχῳ μὲν ὁ Φίλιππος συστρατεύσειν ἐπί τε Αἴγυπτον καὶ ἐπὶ Κύπρον, ὧν τότε ἦρχεν ἔτι παῖς ὢν Πτολεμαῖος ὁ τέταρτος, ᾧ φιλοπάτωρ ἐπώνυμον ἦν, Φιλίππῳ δ’ Ἀντίοχος ἐπὶ Κυρήνην καὶ τὰς Κυκλάδας νήσους καὶ Ἰωνίαν.", "st": "2.4"}, {"sp": "N", "t": "καὶ τήνδε τὴν δόξαν, ἐκταράσσουσαν ἅπαντας Ῥόδιοι μὲν Ῥωμαίοις ἐμήνυσαν, ἐπὶ δὲ τοῖς Ῥοδίων Ἀθηναίων πρέσβεις ᾐτιῶντο Φίλιππον τῆς πολιορκίας. καὶ Αἰτωλοὶ μεταγιγνώσκοντες κατηγόρουν ὡς καὶ περὶ σφᾶς ἀπίστου γεγονότος, ἠξίουν τε αὖθις ἐς τοὺς Ῥωμαίων συμμάχους ἐγγραφῆναι. Ῥωμαῖοι δ’ Αἰτωλοῖς ἐμέμψαντο τῆς οὐ πρὸ πολλοῦ μεταβολῆς, πρέσβεις δ’ ἐς τοὺς βασιλέας ἔπεμπον, οἳ προηγόρευον αὐτοῖς Ἀντίοχον μὲν Αἰγύπτῳ μὴ ἐπιχειρεῖν, Φίλιππον δὲ μηδὲν ἐς Ῥοδίους ἢ Ἀθηναίους ἢ Ἄτταλον ἢ ἐς ἄλλον τινὰ Ῥωμαίων φίλον ἁμαρτάνειν. τούτοις ὁ Φίλιππος ἀπεκρίνατο Ῥωμαίοις ἕξειν καλῶς, ἂν ἐμμένωσιν ᾗ συνέθεντο πρὸς αὐτὸν εἰρήνῃ. οὕτω μὲν αἱ γενόμεναι σπονδαὶ ἐλέλυντο, καὶ στρατιὰ Ῥωμαίων ἐς τὴν Ἑλλάδα ἠπείγετο, στρατηγοῦντος Ποπλίου καὶ ναυαρχοῦντος Λευκίου.", "st": "2.4"}, {"sp": "N", "t": "ὅτι ὁ Φίλιππος ὁ Μακεδόνων βασιλεὺς τῷ Φλαμινίνῳ … σητει, συναγόντων αὐτοὺς Ἠπειρωτῶν πρέσβεων. ὡς δὲ ὁ Φλαμινῖνος Φίλιππον ἐκέλευσεν ἐκστῆναι τῆς Ἑλλάδος οὐ Ῥωμαίοις ἀλλὰ ταῖς πόλεσιν αὐταῖς, καὶ τὰς βλάβας ταῖς προειρημέναις ἀποδοθῆναι, ὁ μὲν Φίλιππος τὰ μὲν …", "st": "2.5"}, {"sp": "N", "t": "ποιμὴν ὑπέσχετο στρατὸν εὔζωνον ἄξειν ὁδὸν ἀτριβῆ τρισὶν ἡμέραις.", "st": "2.6"}, {"sp": "N", "t": "ὅτι Λεύκιος Κοΐντιος ἐς τὸν τῶν Ἀχαιῶν σύλλογον ἀπέστειλε πρέσβεις, οἳ μετὰ Ἀθηναίων καὶ Ῥοδίων ἔπειθον αὐτοὺς μεταθέσθαι πρὸς σφᾶς ἀπὸ τοῦ Φιλίππου, διεπρεσβεύετο δὲ καὶ Φίλιππος αἰτῶν βοήθειαν ὡς συμμάχους. οἱ δὲ ἐνοχλούμενοι μὲν οἰκείῳ καὶ γείτονι πολέμῳ Νάβιδος τοῦ Λακεδαιμονίων τυράννου, διεστῶτες δὲ ταῖς γνώμαις ἠπόρουν, καὶ οἱ πλείονες ᾑροῦντο τὰ Φιλίππου καὶ ἀπεστρέφοντο Ῥωμαίους διά τινα ἐς τὴν Ἑλλάδα Σουλπικίου τοῦ στρατηγοῦ παρανομήματα. ἐγκειμένων δὲ βιαίως τῶν ῥωμαϊζόντων, οἱ πολλοὶ τῆς ἐκκλησίας ἀπεχώρουν δυσχεραίνοντες, καὶ οἱ λοιποὶ διὰ τὴν ὀλιγότητα ἐκβιασθέντες συνέθεντο τῷ Λευκίῳ, καὶ εὐθὺς ἠκολούθουν ἐπὶ Κόρινθον μηχανήματα φέροντες.", "st": "2.7"}, {"sp": "N", "t": "ὅτι Φλαμινῖνος αὖθις συνῆλθεν ἐς λόγους Φιλίππῳ κατὰ τὸν Μηλιέα κόλπον, ἔνθα κατηγορούντων τοῦ Φιλίππου Ῥοδίων καὶ Αἰτωλῶν καὶ Ἀμυνάνδρου τοῦ Ἀθαμᾶνος ἐκέλευσε Φίλιππον ἐξάγειν τὰς φρουρὰς ἐκ Φωκίδος, καὶ πρέσβεις ἐς Ῥώμην ἀμφοτέρους ἀποστεῖλαι. γενομένων δὲ τούτων, οἱ μὲν Ἕλληνες ἐν τῇ βουλῇ τῇ Ῥωμαίων ἠξίουν τὸν Φίλιππον ἐξαγαγεῖν ἐκ τῆς Ἑλλάδος τὰς τρεῖς φρουρὰς ἃς αὐτὸς πέδας ἐκάλει τῆς Ἑλλάδος, τὴν μὲν ἐν Χαλκίδι· Βοιωτοῖς καὶ Εὐβοεῦσι καὶ Λοκροῖς ἐπικειμένην, τὴν δὲ ἐν Κορίνθῳ καθάπερ πύλαις τὴν Πελοπόννησον ἀποκλείουσαν, καὶ τρίτην ἐν Δημητριάδι τὴν Αἰτωλοῖς καὶ Μάγνησιν ἐφεδρεύουσαν· ἡ δὲ βουλὴ τοὺς Φιλίππου πρέσβεις ἤρετο τί φρονοίη περὶ τῶνδε τῶν φρουρῶν ὁ βασιλεύς, ἀποκριναμένων δὲ ἀγνοεῖν, Φλαμινῖνον ἔφη κρινεῖν, καὶ πράξειν ὅ τι ἂν δίκαιον ἡγῆται. οὕτω μὲν οἱ πρέσβεις ἐκ Ῥώμης ἐπανῄεσαν, Φλαμινῖνος δὲ καὶ Φίλιππος ἐς οὐδὲν συμβαίνοντες ἀλλήλοις αὖθις ἐς πόλεμον καθίσταντο.", "st": "2.8"}, {"sp": "N", "t": "ὅτι ἡττηθεὶς πάλιν ὁ Φίλιππος περὶ συμβάσεων ἐπεκηρυκεύετο πρὸς Φλαμινῖνον, ὁ δ’ αὖθις αὐτῷ συνελθεῖν ἐς λόγους συνεχώρει, πολλὰ μὲν τῶν Αἰτωλῶν δυσχεραινόντων, καὶ διαβαλλόντων αὐτὸν ἐς δωροδοκίαν, καὶ καταγιγνωσκόντων τῆς ἐς ἅπαντα εὐχεροῦς μεταβολῆς, ἡγούμενος δ’ οὔτε Ῥωμαίοις συμφέρειν οὔτε τοῖς Ἕλλησι Φιλίππου καθαιρεθέντος ἐπιπολάσαι τὴν Αἰτωλῶν βίαν. τάχα δ’ αὐτὸν καὶ τὸ παράδοξον τῆς νίκης ἀγαπᾶν ἐποίει. συνθέμενος δὲ χωρίον οἷ τὸν Φίλιππον ἐπελθεῖν ἔδει τοὺς συμμάχους ἐκέλευσε γνώμην προαποφήνασθαι κατὰ πόλεις. τὰ μὲν δὴ παρὰ τῶν ἄλλων φιλάνθρωπα ἦν, τό τε τῆς τύχης ἄδηλον ἐξ ὧν ἔπαθεν ὁ Φίλιππος ὑφορωμένων, καὶ τὸ πταῖσμα τοῦτο οὐ κατ’ ἀσθένειαν ἀλλὰ πλέον ἐκ συντυχίας αὐτὸν παθεῖν ἡγουμένων· Ἀλέξανδρος δὲ ὁ τῶν Αἰτωλῶν πρόεδρος ἀγνοεῖν ἔφη τὸν Φλαμινῖνον ὅτι μηδὲν ἄλλο μήτε Ῥωμαίοις μήθ’ Ἕλλησι συνοίσει πλὴν ἐξαιρεθῆναι τὴν ἀρχὴν τὴν Φιλίππου.", "st": "2.9"}, {"sp": "N", "t": "ὁ δὲ Ἀλέξανδρον ἀγνοεῖν ἔφη τὴν Ῥωμαιων φύσιν, οἳ οὐδένα πω τῶν ἐχθρῶν εὐθὺς ἀπ’ ἀρχῆς ἀνέτρεψαν, ἀλλὰ πολλῶν ἐς αὐτοὺς ἁμαρτόντων, καὶ Καρχηδονίων ἔναγχος, ἐφείσαντο, τὰ σφέτερα αὐτοῖς ἀποδόντες καὶ φίλους ποιησάμενοι τους ἠδικηκότας. “ἀγνοεῖς δ’,” ἔφη, “καὶ τοῦθ’, ὅτι τοῖς Ἕλλησιν ἔθνη πολλά, ὅσα βάρβαρα τὴν Μακεδονίαν περικάθηται, εἴ τις ἐξέλοι τοὺς Μακεδόνων βασιλέας, ἐπιδραμεῖται ῥᾳδίως. ὅθεν ἐγὼ δοκιμάζω τὴν μὲν ἀρχὴν ἐᾶν τῶν Μακεδόνων προπολεμεῖν ὑμῶν πρὸς τοὺς βαρβάρους, Φίλιππον δὲ ἐκστῆναι τοῖς Ἕλλησιν ὧν πρότερον ἀντέλεγε χωρίων, καὶ Ῥωμαίοις ἐς τὴν τοῦ πολέμου δαπάνην ἐσενεγκεῖν τάλαντα διακόσια, ὅμηρά τε δοῦναι τὰ ἀξιολογώτατα καὶ τὸν υἱὸν αὐτοῦ Δημήτριον, μέχρι δὲ ταῦθ’ ἡ σύγκλητος ἐπικυρώσει, τετραμήνους ἀνοχὰς γενέσθαι.”", "st": "2.9"}, {"sp": "N", "t": "δεξαμένου δὲ πάντα τοῦ Φιλίππου, τὴν μὲν εἰρήνην ἡ βουλὴ μαθοῦσα ἐπεκύρωσε, τὰς δὲ προτάσεις τὰς Φλαμινίνου σμικρύνασα καὶ φαυλίσασα, ἐκέλευσε τὰς πόλεις ὅσαι ἦσαν Ἑλληνίδες ὑπὸ Φιλίππῳ, πάσας ἐλευθέρας εἶναι, καὶ τὰς φρουρὰς ἀπ’ αὐτῶν Φίλιππον ἐξαγαγεῖν πρὸ τῶν ἐπιόντων Ἰσθμίων, ναῦς τε ὅσας ἔχει, χωρὶς ἑξήρους μιᾶς καὶ σκαφῶν πέντε καταφράκτων, παραδοῦναι τῷ Φλαμινίνῳ, καὶ ἀργυρίου τάλαντα Ῥωμαίοις ἐσενεγκεῖν πεντακόσια μὲν αὐτίκα πεντακόσια δὲ ἔτεσι δέκα, ἑκάστου τὸ μέρος ἔτους ἐς Ῥώμην ἀναφέροντα, ἀποδοῦναι δὲ καὶ αἰχμάλωτα καὶ αὐτόμολα αὐτῶν ὅσα ἔχοι. τάδε μὲν ἡ βουλὴ προσέθηκε, καὶ Φίλιππος ἐδέξατο ἅπαντα· ᾧ καὶ μάλιστα ἡ σμικρολογία Φλαμινίνου καταφανὴς ἐγένετο. συμβούλους δ’ ἔπεμπον αὐτῷ, καθάπερ εἰώθεσαν ἐπὶ τοῖς λήγουσι πολέμοις, δέκα ἄνδρας, μεθ’ ὧν αὐτὸν ἔδει τὰ εἰλημμένα καθίστασθαι.", "st": "2.9"}, {"sp": "N", "t": "καὶ τάδε μὲν διετίθετο σὺν ἐκείνοις, αὐτὸς δ’ ἐς τὸν τῶν Ἰσθμίων ἀγῶνα ἐπελθών, πληθύοντος τοῦ σταδίου, σιωπήν τε ἐσήμηνεν ὑπὸ σάλπιγγι, καὶ τὸν κήρυκα ἀνειπεῖν ἐκέλευσεν· “ὁ δῆμος ὁ Ῥωμαίων καὶ ἡ σύγκλητος καὶ Φλαμινῖνος ὁ στρατηγός, Μακεδόνας καὶ βασιλέα Φίλιππον ἐκπολεμήσαντες, ἀφιᾶσι τὴν Ἑλλάδα ἀφρούρητον ἀφορολόγητον ἰδίοις ἤθεσι καὶ νόμοις χρῆσθαι.” πολλῆς δ’ ἐπὶ τούτῳ βοῆς καὶ χαρᾶς γενομένης θόρυβος ἥδιστος ἦν, ἑτέρων μεθ’ ἑτέρους τὸν κήρυκα καὶ παρὰ σφᾶς ἀνειπεῖν μετακαλούντων. στεφάνους τε καὶ ταινίας ἐπέβαλλον τῷ στρατηγῷ, καὶ ἀνδριάντας ἐψηφίζοντο κατὰ πόλεις. πρέσβεις τε μετὰ χρυσῶν στεφάνων ἔπεμπον ἐς τὸ Καπιτώλιον, οἳ χάριν ὡμολόγουν, καὶ ἐς τοὺς Ῥωμαίων συμμάχους ἀνεγράφοντο. καὶ δεύτερος ὅδε πόλεμος Ῥωμαίοις τε καὶ Φιλίππῳ ἐς τοῦτο ἐτελεύτα.", "st": "2.9"}, {"sp": "N", "t": "οὐ πολὺ δὲ ὕστερον καὶ συνεμάχησε Ῥωμαίοις ὁ Φίλιππος ἐν τῇ Ἑλλάδι κατ’ Ἀντιόχου βασιλέως, περῶντάς τε ἐπὶ Ἀντίοχον ἐς τὴν Ἀσίαν διὰ Θρᾴκης καὶ Μακεδονίας ὁδὸν οὐκ εὐμαρῆ παρέπεμπεν οἰκείοις τέλεσι καὶ τροφαῖς, ὁδοποιῶν καὶ ποταμοὺς δυσπόρους ζευγνὺς καὶ τοὺς ἐπικειμένους Θρᾷκας διακόπτων, ἕως ἐπὶ τὸν Ἑλλήσποντον ἤγαγεν. ἐφ’ οἷς ἡ μὲν βουλὴ τὸν υἱὸν αὐτῷ Δημήτριον παρὰ σφίσιν ὁμηρεύοντα ἀπέλυσε, καὶ τῶν χρημάτων ἀφῆκεν ὧν ἔτι ὤφειλεν· οἱ δὲ Θρᾷκες οἵδε Ῥωμαίους ἀπὸ τῆς ἐπ’ Ἀντιόχῳ νίκης, ἐπανιόντας, οὐκέτι Φιλίππου παρόντος, τήν τε λείαν ἀφείλοντο καὶ πολλοὺς διέφθειραν, ᾧ καὶ μάλιστα ἐπεδείχθη ὅσον αὐτοὺς ἀνιόντας ὤνησεν ὁ Φίλιππος.", "st": "2.9"}, {"sp": "N", "t": "Ἐκτελεσθέντος δὲ τοῦ κατ’ Ἀντιόχου πολέμου πολλοὶ κατηγόρουν τοῦ Φιλίππου, τὰ μὲν ἀδικεῖν αὐτόν, τὰ δὲ οὐ ποιεῖν ὧν ὥρισε Φλαμινῖνος, ὅτε διετίθετο τὴν Ἑλλάδα. καὶ Δημήτριος ἐς ἀντιλογίαν ἐπρέσβευεν ὑπὲρ αὐτοῦ, κεχαρισμένος μὲν ἔκπαλαι Ῥωμαίοις ἀπὸ τῆς ὁμηρείας, Φλαμινίνου δὲ αὐτὸν τῇ βουλῇ γνωρίζοντος ἰσχυρῶς. νεώτερον δ’ ὄντα καὶ θορυβούμενον ἐκέλευσαν τὰ τοῦ πατρὸς ὑπομνήματα ἀναγνῶναι, ἐν οἷς ἦν ἐφ’ ἑκάστου, τὰ μὲν ἤδη γεγονέναι, τὰ δὲ γενήσεσθαι, καίπερ ἀδίκως ὡρισμένα· καὶ γὰρ τοῦτο προσέκειτο πολλοῖς. ἡ δὲ βουλὴ τὴν ὑπόγυον αὐτοῦ ἐς Ἀντίοχον προθυμίαν αἰδουμένη, συγγιγνώσκειν τε ἔφη, καὶ προσεπεῖπε διὰ Δημήτριον. ὁ δ’ ὁμολογουμένως αὐτοῖς ἐς τὸν Ἀντιόχου πόλεμον χρησιμώτατός τε γεγονώς, καὶ βλαβερώτατος ἂν φανεὶς εἰ Ἀντιόχῳ παρακαλοῦντι συνέπραξε, πολλὰ ἐλπίσας ἐπὶ τῷδε, καὶ ὁρῶν αὑτὸν ἀπιστούμενον καὶ κατηγορούμενον καὶ συγγνώμης ἀντὶ χαρίτων ἀξιούμενον, καὶ τῆσδε διὰ Δημήτριον, ἤχθετο καὶ ἠγανάκτει, καὶ ἐπέκρυπτεν ἄμφω. ὡς δὲ καὶ ἐν δίκῃ τινὶ Ῥωμαῖοι πολλὰ τῶν Φιλίππου πρὸς Εὐμένη μετέφερον, ἀσθενοποιοῦντες ἀεὶ τὸν Φίλιππον, ἐς πόλεμον ἤδη λανθάνων ἡτοιμάζετο.", "st": "2.9"}, {"sp": "N", "t": "ὁ δὲ Φίλιππος τοὺς ἐπιπλέοντας διέφθειρεν, ἵνα μὴ Ῥωμαίοις λέγοιεν τὰ Μακεδόνων ἐκτετρῦσθαι.", "st": "2.10"}, {"sp": "N", "t": "ὅτι Ῥωμαῖοι ταχέως αὐξανόμενον τὸν Περσέα ὑφεωρῶντο· καὶ μάλιστα αὐτοὺς ἠρέθιζεν ἡ τῶν Ἑλλήνων φιλία καὶ γειτνίασις, οἷς ἔχθος ἐς Ῥωμαίους ἐπεποιήκεσαν οἱ Ῥωμαίων στρατηγοί. ὡς δὲ καὶ οἱ πρέσβεις οἱ ἐς Βαστέρνας ἀπεσταλμένοι τὴν Μακεδονίαν ἔφασκον ἰδεῖν ἀσφαλῶς ὠχυρωμένην καὶ παρασκευὴν ἱκανὴν καὶ νεότητα γεγυμνασμένην, Ῥωμαίους καὶ τάδε διετάρασσεν. αἰσθόμενος δ’ ὁ Περσεὺς ἑτέρους ἔπεμπε πρέσβεις, τὴν ὑπόνοιαν ἐκλύων. ἐν δὲ τούτῳ καὶ Εὐμένης ὁ τῆς περὶ τὸ Πέργαμον Ἀσίας βασιλεύς, ἀπὸ τῆς πρὸς Φίλιππον ἔχθρας δεδιὼς Περσέα ἧκεν ἐς Ῥώμην, καὶ κατηγόρει φανερῶς αὐτοῦ, παρελθὼν ἐς τὸ βουλευτήριον, ὅτι Ῥωμαίοις δυσμενὴς γένοιτο ἀεί, καὶ τὸν ἀδελφὸν οἰκείως ἐς αὐτοὺς ἔχοντα ἀνέλοι, καὶ Φιλίππῳ τε παρασκευὴν τοσήνδε κατ’ αὐτῶν συναγαγόντι συμπράξειε, καὶ βασιλεὺς γενόμενος οὐδὲν ἐκλύσειεν αὐτῆς ἀλλὰ καὶ προσεξεργάσαιτο ἕτερα, καὶ τὴν Ἑλλάδα ἀμέτρως θεραπεύοι, Βυζαντίοις τε καὶ Αἰτωλοῖς καὶ Βοιωτοῖς συμμαχήσας, καὶ Θρᾴκην κατακτῷτο, μέγα ὁρμητήριον, καὶ Θετταλοὺς καὶ Περραιβοὺς διαστασιάσειε βουλομένους τι πρεσβεῦσαι πρὸς ὑμᾶς.", "st": "2.11"}, {"sp": "N", "t": "“καὶ τῶν ὑμετέρων,” ἔφη, “φίλων καὶ συμμάχων Ἀβρούπολιν μὲν ἀφῄρηται τὴν ἀρχήν, Ἀρθέταυρον δ’ ἐν Ἰλλυριοῖς δυνάστην καὶ ἔκτεινεν ἐπιβουλεύσας, καὶ τοὺς ἐργασαμένους ὑποδέδεκται.” διέβαλλε δ’ αὐτοῦ καὶ τὰς ἐπιγαμίας βασιλικὰς ἄμφω γενομένας, καὶ τὰς νυμφαγωγίας ὅλῳ τῷ Ῥοδίων στόλῳ παραπεμφθείσας. ἔγκλημα δ’ ἐποίει καὶ τὴν ἐπιμέλειαν αὐτοῦ καὶ τὸ νηφάλιον τῆς διαίτης, ὄντος οὕτω νέου, καὶ ὅτι πρὸς πολλῶν ὀξέως ἐν ὀλίγῳ ἀγαπῷτο καὶ ἐπαινοῖτο. ζήλου τε καὶ φθόνου καὶ δέους μᾶλλον ἢ ἐγκλημάτων οὐδὲν ὁ Εὐμένης ἀπολιπών, ἐκέλευε τὴν σύγκλητον ὑφορᾶσθαι νέον ἐχθρὸν εὐδοκιμοῦντα καὶ γειτονεύοντα.", "st": "2.11"}, {"sp": "N", "t": "ἡ δ’ ἔργῳ μὲν οὐκ ἀξιοῦσα βασιλέα σώφρονα καὶ φιλόπονον καὶ ἐς πολλοὺς φιλάνθρωπον, ἀθρόως οὕτως ἐπαιρόμενον καὶ πατρικὸν ὄντα σφίσιν ἐχθρόν, ἐν πλευραῖς ἔχειν, λόγῳ δ’ ἃ προύτεινεν ὁ Εὐμένης αἰτιωμένη, πολεμεῖν ἔκρινε τῷ Περσεῖ. καὶ τοῦτ’ ἀπόρρητον ἔτι ἐν σφίσιν αὐτοῖς ποιούμενοι, Ἅρπαλόν τε πεμφθέντα παρὰ Περσέως ἐς ἀντιλογίαν Εὐμένους, καὶ Ῥοδίων τινὰ πρεσβευτήν, βουλομένους ἐς ὄψιν τὸν Εὐμένη διελέγχειν, παρόντος μὲν ἔτι τοῦ Εὐμένους οὐ προσήκαντο, μεταστάντος δὲ ἐδέξαντο. καὶ οἱ μὲν ἐπὶ τῷδε πρῶτον ἀγανακτοῦντές τε καὶ παρρησίᾳ χρώμενοι πλέον πολεμεῖν βουλομένους ἤδη Ῥωμαίους Περσεῖ καὶ Ῥοδίοις μᾶλλον ἐξηγρίωσαν· τῶν δὲ βουλευτῶν πολλοὶ τὸν Εὐμένη δι’ αἰτίας εἶχον ὑπὸ φθόνου καὶ δέους αἴτιον τοσοῦδε πολέμου γενόμενον. καὶ Ῥόδιοι τὴν θεωρίαν αὐτοῦ, μόνου βασιλέων, ἐς τὴν ἑορτὴν τοῦ Ἡλίου πεμπομένην οὐκ ἐδέξαντο.", "st": "2.11"}, {"sp": "N", "t": "αὐτὸς δ’ ἐς τὴν Ἀσίαν ἐπανιὼν ἐκ Κίρρας ἐς Δελφοὺς ἀνέβαινε θύσων, καὶ αὐτῷ τέσσαρες ἄνδρες ὑπὸ τὸ τειχίον ὑποστάντες ἐπεβούλευον. καὶ ἄλλας δέ τινας αἰτίας οἱ Ῥωμαῖοι ἐς τὸν Περσέως πόλεμον ὡς οὔπω κεκριμένον προσελάμβανον, καὶ πρέσβεις ἐς τοὺς φίλους βασιλέας, Εὐμένη καὶ Ἀντίοχον καὶ Ἀριαράθην καὶ Μασσανάσσην καὶ Πτολεμαῖον τὸν Αἰγύπτου, περιέπεμπον, ἑτέρους δ’ ἐς τὴν Ἑλλάδα καὶ Θεσσαλίαν καὶ Ἤπειρον καὶ Ἀκαρνανίαν, καὶ ἐς τὰς νήσους, ὅσας δύναιντο προσαγαγέσθαι· ὃ καὶ μάλιστα τοὺς Ἕλληνας ἐτάραττεν, ἡδομένους μὲν τῷ Περσεῖ φιλέλληνι ὄντι, ἀναγκαζομένους δ’ ἐνίους Ῥωμαίοις ἐς συμβάσεις χωρεῖν.", "st": "2.11"}, {"sp": "N", "t": "ὧν ὁ Περσεὺς αἰσθόμενος ἔπεμπεν ἐς Ῥώμην, ἀπορῶν τε καὶ πυνθανόμενος τί παθόντες ἐκλήθονται τῶν συγκειμένων καὶ πρέσβεις κατ’ αὐτοῦ περιπέμπουσιν ὄντος φίλου, δέον, εἰ καί τι μέμφονται, λόγῳ διακριθῆναι. οἱ δ’ ἐνεκάλουν ὅσα Εὐμένης εἴποι καὶ πάθοι, καὶ μάλιστα ὅτι Θρᾴκην κατακτῷτο, καὶ στρατιὰν ἔχοι καὶ παρασκευὴν οὐκ ἠρεμήσοντος ἀνδρός. ὁ δ’ αὖθις ἔπεμπεν ἑτέρους, οἳ ἐς τὸ βουλευτήριον ἀπαχθέντες ἔλεγον ὧδε· “τοῖς μὲν προφάσεως ἐς πόλεμον, ὦ Ῥωμαῖοι, δεομένοις ἱκανὰ πάντα ἐς τὴν πρόφασιν ἐστίν. εἰ δ’ αἰδεῖσθε συνθήκας οἱ πολὺν ἀξιοῦντες αὐτῶν λόγον ἔχειν, τί παθόντες ὑπὸ Περσέως αἴρεσθε πόλεμον; οὐ γὰρ ὅτι στρατιὰν ἔχει καὶ παρασκευήν. οὐ γὰρ ἔχει ταῦτα καθ’ ὑμῶν. οὐδὲ τοὺς ἄλλους κεκτῆσθαι βασιλέας κωλύετε· οὐδ’ ἄδικον ἀσφαλῶς ἔχειν ἐς τοὺς ἀρχομένους καὶ τὰ περίοικα, καὶ εἴ τις ἔξωθεν ἐπιβουλεύοι. πρὸς δὲ ὑμᾶς, ὦ ἄνδρες Ῥωμαῖοι, ὑπὲρ τῆς εἰρήνης ἐπρέσβευσε καὶ τὰς συνθήκας ἔναγχος ἀνεκαίνισεν.”", "st": "2.11"}, {"sp": "N", "t": "“ἀλλ’ Ἀβρούπολιν ἐξέβαλε τῆς ἀρχῆς. ἐπιδραμόντα γε τοῖς ἡμετέροις ἀμυνόμενος. καὶ τοῦτ’ αὐτὸς ὑμῖν ἐδήλωσε Περσεύς, καὶ τὰς συνθήκας αὐτῷ μετὰ τοῦτο ἀνενεώσασθε, οὔπω διαβάλλοντος Εὐμένους. τὸ μὲν δὴ περὶ Ἀβρούπολιν καὶ πρεσβύτερόν ἐστι τῶν συνθηκῶν, καὶ παρ’ ὑμῖν, ὅτε συνετίθεσθε, δίκαιον ἐφάνη. Δόλοψι γὰρ ἐπεστράτευσεν οὖσι τῆς ἰδίας ἀρχῆς, καὶ δεινὸν εἰ τῶν ἑαυτοῦ λογισμὸν ὑμῖν ὀφλήσει. δίδωσι δ’ ὅμως, περὶ πολλοῦ ποιούμενος ὑμᾶς τε καὶ δόξαν ἀγαθήν. ἔκτειναν δ’ οἱ Δόλοπες οἵδε τὸν ἡγούμενον αὐτῶν αἰκισάμενοι, καὶ ζητεῖ Περσεὺς τί ἂν ὑμεῖς ἐδράσατε τοὺς ὑπηκόους τοιαῦτα πράξαντας. ἀλλ’ Ἀρθέταυρόν τινες ἀνελοντες ἐν Μακεδονίᾳ διέτριβον. κοινῷ γε πάντων ἀνθρώπων νόμῳ, καθὰ καὶ ὑμεῖς τοὺς ἑτέρωθεν φεύγοντας ὑποδέχεσθε. μαθὼν δὲ καὶ τοῦθ’ ὅτι ἔγκλημα ποιεῖσθε, ἐξεκήρυξεν αὐτοὺς τῆς ἀρχῆς ὅλης.", "st": "2.11"}, {"sp": "N", "t": "“Βυζαντίοις δὲ καὶ Αἰτωλοῖς καὶ Βοιωτοῖς οὐ καθ’ ὑμῶν ἀλλὰ καθ’ ἑτέρων συνεμάχησεν. καὶ ταῦτα πάλαι ὑμῖν ἡμέτεποι πρέσβεις ἐμήνυον, καὶ οὐκ ἐμέμφεσθε μέχρι τῆς Εὐμένους διαβολῆς, ἣν οὐκ εἰάσατε τοὺς ἡμετέρους πρέσβεις ἐς ὄψιν αὐτὸν ἐλέγξαι. ἀλλὰ τὴν ἐπιβουλὴν τὴν ἐν Δελφοῖς αὐτῷ γενομένην προσγράφετε Περσεῖ, πόσων Ἑλλήνων, πόσων δὲ βαρβάρων κατ’ Εὐμένους πρεσβευσάντων πρὸς ὑμᾶς οἷς πᾶσιν ἐχθρός ἐστι τοιοῦτος ὤν. Ἐρέννιον δὲ τὸν ἐν Βρεντεσίῳ τίς ἂν πιστεύσειεν ὅτι Περσεύς, Ῥωμαῖον ὄντα καὶ φίλον ὑμέτερον καὶ πρόξενον, εἴληφεν ἐπὶ τὴν τῆς βουλῆς φαρμακείαν, ὡς ἀναλῶσαι τὴν σύγκλητον δι’ αὐτοῦ δυνάμενος, ἢ τοὺς ὑπολοίπους εὐμενεστέρους ἕξων διὰ τοὺς ἀναιρουμένους; ἀλλ’ Ἐρέννιος μὲν ἐψεύσατο τοῖς ἐπιτρίβουσιν ἐς τὸν πόλεμον ὑμᾶς πρόφασιν εὐσχήμονα διδούς, Εὐμένης δ’ ὑπ’ ἔχθρας τε καὶ φθόνου καὶ δέους οὐδὲ ταῦτ’ ὤκνησεν ἐγκαλέσαι Περσεῖ, ὅτι πολλοῖς ἔθνεσι κεχαρισμένος καὶ φιλέλλην, καὶ σωφρόνως ἀντὶ μέθης καὶ τρυφῆς ἄρχει. καὶ ταῦθ’ ὑμεῖς αὐτοῦ λέγοντος ὑπέστητε ἀκροάσασθαι.", "st": "2.11"}, {"sp": "N", "t": "“τοιγάρτοι τὴν ἐκείνου διαβολὴν αὔξετε καθ’ ὑμῶν ὡς οὐ φέροντες σώφρονας καὶ δικαίους καὶ φιλοπόνους γείτονας. Περσεὺς δ’ Ἐρέννιον μὲν καὶ Εὐμένη, καὶ εἴ τις ἄλλος ἐθέλοι, προκαλεῖται παρ’ ὑμῖν ἐς ἐξέτασιν καὶ κρίσιν, ὑμᾶς δ’ ἀναμιμνήσκει μὲν τῆς ἐς Ἀντίοχον τὸν μέγαν τοῦ πατρὸς ἑαυτοῦ προθυμίας καὶ βοηθείας, ἧς ἐπιγιγνομένης καλῶς ᾐσθάνεσθε, αἰσχρὸν δὲ παρελθούσης ἐπιλαθέσθαι, προφέρει δὲ συνθήκας πατρῴας τε καὶ ἰδίας πρὸς αὐτὸν ὑμῖν γενομένας. καὶ ἐπὶ τοῖσδε οὐκ ὀκνεῖ καὶ παρακαλεῖν ὑμᾶς, θεοὺς οὓς ὠμόσατε αἰδεῖσθαι, καὶ μὴ πολέμου κατάρχειν ἀδίκως ἐς φίλους, μηδ’ ἔγκλημα ποιεῖσθαι γειτνίασιν καὶ σωφροσύνην καὶ παρασκευήν, οὐ γὰρ ἄξιον, ὡς Εὐμένους, καὶ ὑμῶν ἅπτεσθαι φθόνον ἢ φόβον. τὸ δὲ ἐναντίον ἐστὶ σῶφρον, φείδεσθαι γειτόνων ἐπιμελῶν, καὶ ὡς Εὐμένης φησίν, εὖ παρεσκευασμένων.”", "st": "2.11"}, {"sp": "N", "t": "οἱ μὲν δὴ πρέσβεις τοιαῦτα εἶπον, οι δὲ οὐδὲν αὐτοῖς ἀποκρινάμενοι τὸν πόλεμον ἐς τὸ φανερὸν ἐκύρουν. καὶ ὁ ὕπατος ἐκέλευε τοὺς πρέσβεις ἐκ μεν τῆς πόλεως αὐτῆς ἡμέρας, ἐκ δὲ τῆς Ἰταλίας τριάκοντα ἄλλαις ἐξιέναι. τὰ δὲ αὐτὰ καὶ τοῖς ἐπιδημοῦσι Μακεδόνων ἐκήρυττεν. καὶ θόρυβος αὐτίκα μετὰ τὸ βουλευτήριον ἐπίφθονος ἦν, ἐν ὀλίγαις ὥραις ἐλαυνομένων τοσῶνδε ὁμοῦ, καὶ οὐδὲ ὑποζύγια εὑρεῖν ἐν οὕτω βραχεῖ διαστήματι, οὐδὲ πάντα φέρειν δυναμένων. ὑπὸ δὲ σπουδῆς οἱ μὲν οὐκ ἔφθανον ἐπὶ τοὺς σταθμούς, ἀλλ’ ἐν μέσαις ἀνεπαύοντο ταῖς ὁδοῖς, οἱ δὲ παρὰ ταῖς πύλαις μετὰ παίδων ἑαυτοὺς ἐρρίπτουν καὶ μετὰ γυναικῶν. πάντα τε ἐγίγνετο ὅσα εἰκος ἐν αἰφνιδίῳ καὶ τοιῷδε κηρύγματι· αἰφνίδιον γὰρ αὐτοῖς ἐφαίνετο διὰ τὰς ἔτι πρεσβείας.", "st": "2.11"}, {"sp": "N", "t": "ὅτι μετὰ τὴν νίκην ὁ Περσεύς, εἴτ’ ἐπιγελῶν Κράσσῳ καὶ τωθάζων αὐτόν, εἴτ’ ἀποπειρώμενος ὅπως ἔτι φρονήματος ἔχοι, εἴτε τὴν Ῥωμαίων δύναμίν τε καὶ παρασκευὴν ὑφορώμενος, εἴθ’ ἑτέρῳ τῳ λογισμῷ, προσέπεμπεν αὐτῷ περὶ διαλλαγῶν, καὶ πολλὰ δώσειν ὑπισχνεῖτο ὧν ὁ πατὴρ Φίλιππος οὐ συνεχώρει· ᾧ καὶ μᾶλλον ὕποπτος ἦν ἐπιγελῶν καὶ πειρώμενος. ὁ δὲ Περσεῖ μὲν ἀπεκρίνατο Ῥωμαίων ἀξίας οὐκ εἶναι διαλύσεις αὐτῷ, εἰ μὴ καὶ Μακεδόνας καὶ ἑαυτὸν ἐπιτρέψειε Ῥωμαίοις· αἰδούμενος δ’ ὅτι Ῥωμαῖοι τῆς ἥττης κατῆρξαν, ἐκκλησίαν συναγαγὼν Θεσσαλοῖς μὲν ἐμαρτύρησεν ὡς ἀνδράσιν ἀγαθοῖς περὶ τὴν συμφορὰν γενομένοις, Αἰτωλῶν δὲ καὶ ἑτέρων Ἑλλήνων κατεψεύσατο ὡς πρώτων τραπέντων. καὶ τούτους ἐς Ῥώμην ἔπεμψεν.", "st": "2.12"}, {"sp": "N", "t": "τὸ δὲ λοιπὸν τοῦ θέρους ἀμφότεροι περὶ σιτολογίαν ἐγίγνοντο, Περσεὺς μὲν ἐν τοῖς πεδίοις ἁλωνευόμενος, Ῥωμαῖοι δὲ ἐν τῷ στρατοπέδῳ.", "st": "2.13"}, {"sp": "N", "t": "ὃς δὲ πρῶτος ἐξῆρχε τοῦ πόνου, ἑξηκοντούτης ὢν καὶ βαρὺς τὸ σῶμα καὶ πιμελής.", "st": "2.14"}, {"sp": "N", "t": "τότε δὲ ἔθει τις δρόμῳ δηλώσων τῷ Περσεῖ λουομένῳ καὶ τὸ σῶμα ἀναλαμβάνοντι. ὁ δὲ ἐξήλατο τοῦ ὕδατος βοῶν ὅτι ἑαλώκοι πρὸ τῆς μάχης.", "st": "2.15"}, {"sp": "N", "t": "ὅτι Περσεὺς ἀναθαρρῶν ἤδη κατ’ ὀλίγον μετὰ τὴν φυγήν, Νικίαν καὶ Ἀνδρόνικον, οὓς ἐπὶ τὸν καταποντισμὸν τῶν χρημάτων καὶ τὸν ἐμπρησμὸν τῶν νεῶν ἐπεπόμφει, περιποιήσας αὑτῷ καὶ τὰς ναῦς καὶ τὰ χρήματα, συνίστορας ἡγούμενος αἰσχροῦ φόβου καὶ ἑτέροις ἐξαγγελεῖν, ἀπέκτεινεν ἀθεμίστως, καὶ ἀπὸ τοῦδε εὐθὺς ἐκ μεταβολῆς ὠμὸς καὶ εὐχερὴς ἐς ἅπαντας ἐγένετο, καὶ οὐδὲν ὑγιὲς οὐδ’ εὔβουλόν οἱ ἔτι ἦν, ἀλλ’ ὁ πιθανώτατος ἐς εὐβουλίαν καὶ λογίσασθαι δεξιὸς καὶ εὐτολμότατος ἐς μάχας, ὅσα γε μὴ σφάλλοιτο δι’ ἀπειρίαν, ἀθρόως τότε καὶ παραλόγως ἐς δειλίαν καὶ ἀλογιστίαν ἐτράπετο, καὶ ταχὺς καὶ εὐμετάθετος ἄφνω καὶ σκαιὸς ἐς πάντα ἐγένετο, ἀρχομένης αὐτὸν ἐπιλείπειν τῆς τύχης. ὅπερ ἔστι πολλοὺς ἰδεῖν, μεταβολῆς προσιούσης ἀλογωτέρους γιγνομένους ἑαυτῶν.", "st": "2.16"}, {"sp": "N", "t": "ὅτι Ῥόδιοι πρέσβεις ἐς Μάρκιον ἔπεμψαν, συνηδόμενοι τῶν γεγονότων [Περσεῖ]. ὁ δὲ Μάρκιος τοὺς πρέσβεις ἐδίδασκε Ῥοδίους πεῖσαι πέμψαντας ἐς Ῥώμην διαλῦσαι τὸν πόλεμον Ῥωμαίοις τε καὶ Περσεῖ. καὶ Ῥόδιοι πυθόμενοι μετέπιπτον ὡς οὐ φαύλως ἔχοντος τοῦ Περσέως· οὐ γὰρ εἴκαζον ἄνευ Ῥωμαίων ταῦτα Μάρκιον ἐπισκήπτειν. ὁ δ’ ἀφ’ ἑαυτοῦ καὶ τάδε καὶ ἕτερα πολλὰ δι’ ἀτολμίαν ἔπραττεν. Ῥόδιοι μὲν οὖν καὶ ὣς πρέσβεις ἔπεμπον ἐς Ῥώμην, καὶ ἑτέρους πρὸς Μάρκιον.", "st": "2.17"}, {"sp": "N", "t": "ὅτι Γένθιος βασιλεὺς Ἰλλυριῶν ἑνὸς ἔθνους προσοίκου Μακεδόσι, Περσεῖ συμμαχῶν ἐπὶ τριακοσίοις ταλάντοις, ὧν τι καὶ προειλήθει, ἐσέβαλεν ἐς τὴν ὑπὸ Ῥωμαίοις Ἰλλυρίδα, καὶ πρέσβεις περὶ τούτων πρὸς αὐτὸν ἐλθόντας Περπένναν καὶ Πετίλιον ἔδησεν. ὧν ὁ Περσεὺς αἰσθόμενος οὐκέτι τὰ λοιπὰ τῶν χρημάτων ἔπεμπεν ὡς ἤδη καὶ δι’ αὐτὸν Ῥωμαίοις πεπολεμωμένον. ἐς δὲ Γέτας ἔπεμπε τοὺς ὑπὲρ Ἴστρον, καὶ Εὐμένους ἀπεπείρασεν ἐπὶ χρήμασιν ἢ μεταθέσθαι πρὸς αὑτόν, ἢ διαλῦσαι τὸν πόλεμον, ἢ ἀμφοτέροις ἐκστῆναι τοῦ ἀγῶνος, εὖ μὲν εἰδὼς οὐ λησόμενα ταῦτα Ῥωμαίους, ἐλπίζων δ’ ἢ πράξειν τι αὐτῶν ἢ τῇ πείρᾳ διαβαλεῖν τὸν Εὐμένη. ὁ δὲ μεταθήσεσθαι μὲν οὐκ ἔφη, τάλαντα δ’ ᾔτει τῆς μὲν διαλύσεως χίλια καὶ πεντακόσια, τῆς δὲ ἡσυχίας χίλια. καὶ ὁ Περσεὺς ἤδη Γετῶν αὑτῷ προσιέναι μισθοφόρους μυρίους ἱππέας καὶ μυρίους πεζοὺς πυθόμενος, αὐτίκα τοῦ Εὐμένους κατεφρόνει, καὶ τῆς μὲν ἡσυχίας οὐκ ἔφη δώσειν οὐδέν (αἰσχύνην γὰρ φέρειν ἀμφοῖν), τὰ δὲ τῆς διαλύσεως οὐ προδώσειν, ἀλλ’ ἐν Σαμοθρᾴκῃ καταθήσειν μέχρι γένοιτο ἡ διάλυσις, εὐμετάβολος ἤδη καὶ μικρολόγος ὑπὸ θεοβλαβείας ἐς πάντα γενόμενος. ἑνὸς δὲ ὧν ἤλπισεν ὅμως οὐκ ἀπέτυχε, Ῥωμαίοις Εὐμένους ὑπόπτου γενομένου.", "st": "2.18"}, {"sp": "N", "t": "Γετῶν δὲ τὸν Ἴστρον περασάντων, ἐδόκει Κλοιλίῳ μὲν τῷ ἡγεμόνι δοθῆναι χιλίους χρυσοῦς στατῆρας, ἱππεῖ δ’ ἑκάστῳ δέκα, καὶ τὰ ἡμίσεα πεζῷ· καὶ τοῦτο σύμπαν ἦν ὀλίγῳ πλέον πεντεκαίδεκα μυριάδων χρυσίου. ὁ δὲ χλαμύδας μέν τινας ἐπήγετο καὶ ψέλια χρυσᾶ καὶ ἵππους ἐς δωρεὰν τοῖς ἡγουμένοις, καὶ στατῆρας φερομένους μυρίους, καὶ πλησιάσας μετεπέμπετο Κλοίλιον. ὁ δὲ τοὺς ἐλθόντας, εἰ φέρουσι τὸ χρυσίον, ἤρετο, καὶ μαθὼν οὐκ ἔχοντας ἀναστρέφειν ἐπ’ αὐτὸν ἐκέλευσεν. ὧν ὁ Περσεὺς πυθόμενος, πάλιν αὐτὸν ἐλαύνοντος θεοῦ, κατηγόρει τῶν Γετῶν ἐν τοῖς φίλοις ἐκ μεταβολῆς ὡς φύσεως ἀπίστου, καὶ ὑπεκρίνετο μὴ θαρρεῖν δισμυρίους αὐτῶν ἐς τὸ στρατόπεδον ὑποδέξασθαι, μόλις δ’ ἔφη μυρίους, ὧν καὶ νεωτεριζόντων κρατῆσαι δύνασθαι.", "st": "2.18"}, {"sp": "N", "t": "ταῦτα δὲ τοῖς φίλοις εἰπὼν ἕτερα τοῖς Γέταις ἐπλάττετο, καὶ τὸ ἥμισυ τῆς στρατιᾶς ᾔτει, τὸ χρυσίον τὸ γιγνόμενον ὑπισχνούμενος δώσειν. τοσαύτης ἀνωμαλίας ἔγεμε, φροντίζων χρημάτων τῶν πρὸ βραχέος ἐς θάλασσαν μεθειμένων. ὁ δὲ Κλοίλιος τοὺς ἀφικομένους ἰδὼν ἤρετο μετὰ βοῆς εἰ τὸ χρυσίον κεκομίκασι, καὶ βουλομένους τι λέγειν ἐκέλευε πρῶτον εἰπεῖν περὶ τοῦ χρυσίου. ὡς δ’ ἔμαθεν οὐκ ἔχοντας, οὐκ ἀνασχόμενος αὐτῶν οὐδ’ ἀκοῦσαι, τὴν στρατιὰν ἀπῆγεν ὀπίσω. καὶ Περσεὺς ἀφῄρητο καὶ τῆσδε συμμαχίας, πολλῆς τε καὶ κατὰ καιρὸν ἐλθούσης. ὑπὸ δ’ ἀφροσύνης, ἐν Φίλᾳ χειμάζων καὶ στρατὸν ἔχων πολὺν Θεσσαλίαν μὲν οὐκ ἐπέτρεχεν, ἣ Ῥωμαίοις ἐχορήγει τροφάς, ἐς δὲ τὴν Ἰωνίαν ἔπεμπε κωλύειν τὴν ἀγορὰν τὴν ἐκεῖθεν αὐτοῖς φερομένην.", "st": "2.18"}, {"sp": "N", "t": "ὅτι Παύλῳ ἐπ’ εὐτυχίας τοσῆσδε γενομένῳ τὸ δαιμόνιον ἐφθόνησε τῆς εὐτυχίας. καί οἱ τεσσάρων παίδων ὄντων τοὺς μὲν πρεσβυτέρους αὐτῶν ἐς θέσιν ἄλλοις ἐδεδώκει, Μάξιμόν τε καὶ Σκιπίωνα, τοὺς δὲ νεωτέρους ἄμφω συνέβη, τὸν μὲν πρὸ τριῶν ἡμερῶν τοῦ θριάμβου τὸν δὲ μετὰ πέντε, ἀποθανεῖν. καὶ τοῦτ’ οὐδενὸς ἧττον ὁ Παῦλος κατελογίσατο τῷ δήμῳ. ἔθους γὰρ ὄντος τοῖς στρατηγοῖς καταλέγειν τὰ πεπραγμένα, παρελθὼν ἐς τὴν ἀγορὰν εἶπεν ἐς μὲν Κέρκυραν ἐκ Βρεντεσίου διαπλεῦσαι μιᾶς ἡμέρας, ἐκ δὲ Κερκύρας πέντε μὲν ἐς Δελφοὺς ὁδεῦσαι καὶ θῦσαι τῷ θεῷ, πέντε δὲ ἄλλαις ἐς Θεσσαλίαν παραγενέσθαι καὶ παραλαβεῖν τὸν στρατόν, ἀπὸ δὲ ταύτης πεντεκαίδεκα ἄλλαις ἑλεῖν Περσέα καὶ Μακεδόνας παραλαβεῖν. οὕτω δὲ ὀξέως ἁπάντων ἐπιτυχὼν δεῖσαι μή τι τῷ στρατῷ συμπέσοι πρὸς ὑμᾶς ἐπανιόντι. “διασωθέντος δὲ τοῦ στρατοῦ περὶ ὑμῶν ἐδεδοίκειν,” ἔφη· “φθονερὸς γὰρ ὁ δαίμων. ἐς ἐμὲ δὲ ἀποσκήψαντος τοῦ κακοῦ, καὶ ἀθρόως μοι τῶν δύο παίδων ἀποθανόντων, ἐπ’ ἐμαυτῷ μέν εἰμι βαρυσυμφορώτατος, ἐπὶ δὲ ὑμῖν ἀμέριμνος.” ταῦτ’ εἰπών, καὶ καταθαυμαζόμενος ἐπὶ πᾶσιν, οἰκτιζόμενος δὲ ἐπὶ τοῖς τέκνοις, μετ’ οὐ πολὺν χρόνον ἀπέθανεν.", "st": "2.19"}, {"sp": "HDR", "t": "Ἰλλυρική", "st": "3"}, {"sp": "N", "t": "Ἰλλυριοὺς Ἕλληνες ἡγοῦνται τοὺς ὑπέρ τε Μακεδονίαν καὶ Θρᾴκην ἀπὸ Χαόνων καὶ Θεσπρωτῶν ἐπὶ ποταμὸν Ἴστρον. καὶ τοῦτ’ ἐστὶ τῆς χώρας τὸ μῆκος, εὖρος δ’ ἐκ Μακεδόνων τε καὶ Θρᾳκῶν τῶν ὀρείων ἐπὶ Παιονας καὶ τὸν Ἰόνιον καὶ τὰ πρόποδα τῶν Ἄλπεων. καὶ ἔστι τὸ μὲν εὖρος ἡμερῶν πέντε, τὸ δὲ μῆκος τριάκοντα, καθὰ καὶ τοῖς Ἕλλησιν εἴρηται. Ῥωμαίων δὲ τὴν χώραν μετρησαμένων ἔστιν ὑπὲρ ἑξακισχιλίους σταδίους τὸ μῆκος, καὶ τὸ πλάτος ἀμφὶ τοὺς χιλίους καὶ διακοσίους.", "st": "3.1"}, {"sp": "N", "t": "φασὶ δὲ τὴν μὲν χώραν ἐπώνυμον Ἰλλυριοῦ τοῦ Πολυφήμου γενέσθαι· Πολυφήμῳ γὰρ τῷ Κύκλωπι καὶ Γαλατείᾳ Κελτὸν καὶ Ἰλλυριὸν καὶ Γάλαν παῖδας ὄντας ἐξορμῆσαι Σικελίας, καὶ ἄρξαι τῶν δι’ αὐτοὺς Κελτῶν καὶ Ἰλλυριῶν καὶ Γαλατῶν λεγομένων. καὶ τόδε μοι μάλιστα, πολλὰ μυθευόντων ἕτερα πολλῶν, ἀρέσκει. Ἰλλυριῷ δὲ παῖδας Ἐγχέλεα καὶ Αὐταριέα καὶ Δάρδανον καὶ Μαῖδον καὶ Ταύλαντα καὶ Περραιβὸν γενέσθαι, καὶ θυγατέρας Παρθὼ καὶ Δαορθὼ καὶ Δασσαρὼ καὶ ἑτέρας, ὅθεν εἰσὶ Ταυλάντιοί τε καὶ Περραιβοὶ καὶ Ἐγχέλεες καὶ Αὐταριεῖς καὶ Δάρδανοι καὶ Παρθηνοὶ καὶ Δασσαρήτιοι καὶ Δάρσιοι. Αὐταριεῖ δὲ αὐτῷ Παννόνιον ἡγοῦνται παῖδα ἢ Παίονα γενέσθαι, καὶ Σκορδίσκον Παίονι καὶ Τριβαλλόν, ὧν ὁμοίως τὰ ἔθνη παρώνυμα εἶναι. καὶ τάδε μὲν τοῖς ἀρχαιολογοῦσι μεθείσθω,", "st": "3.2"}, {"sp": "N", "t": "γένη δ’ ἔστιν Ἰλλυριῶν, ὡς ἐν τοσῇδε χώρᾳ, πολλά. καὶ περιώνυμα ἔτι νῦν, χώραν νεμόμενα πολλὴν, Σκορδίσκων καὶ Τριβαλλῶν, οἳ ἐς τοσοῦτον ἀλλήλους πολέμῳ διέφθειραν ὡς Τριβαλλῶν εἴ τι ὑπόλοιπον ἦν ἐς Γέτας ὑπὲρ Ἴστρον φυγεῖν, καὶ γένος ἀκμάσαν μέχρι Φιλίππου τε καὶ Ἀλεξάνδρου νῦν ἔρημον καὶ ἀνώνυμον τοῖς τῇδε εἶναι, Σκορδίσκους δὲ ἀσθενεστάτους ἀπὸ τοῦδε γενομένους ὑπὸ Ῥωμαίων ὕστερον ὅμοια παθεῖν καὶ ἐς τὰς νήσους τοῦ αὐτοῦ ποταμοῦ φυγεῖν, σὺν χρόνῳ δέ τινας ἐπανἐλθεῖν καὶ Παιόνων ἐσχατιαῖς παροικῆσαι· ὅθεν ἔστι καὶ νῦν Σκορδίσκων γένος ἐν Παίοσιν. τῷ δ’ αὐτῷ τρόπῳ καὶ Ἀρδιαῖοι τὰ θαλάσσια ὄντες ἄριστοι πρὸς Αὐταριέων ἀρίστων ὄντων τὰ κατὰ γῆν, πολλὰ βλάψαντες αὐτούς, ὅμως ἐφθάρησαν. καὶ ναυτικοὶ μὲν ἐπὶ τοῖς Ἀρδιαίοις ἐγένοντο Λιβυρνοί, γένος ἕτερον Ἰλλυριῶν, οἳ τὸν Ἰόνιον καὶ τὰς νήσους ἐλῄστευον ναυσὶν ὠκείαις τε καὶ κούφαις, ὅθεν ἔτι νῦν Ῥωμαῖοι τὰ κοῦφα καὶ ὀξέα δίκροτα Λιβυρνίδας προσαγορεύουσιν.", "st": "3.3"}, {"sp": "N", "t": "Αὐταριέας δὲ φασὶν ἐκ θεοβλαβείας Ἀπόλλωνος ἐς ἔσχατον κακοῦ περιελθεῖν. Μολιστόμῳ γὰρ αὐτοὺς καὶ Κελτοῖς τοῖς Κίμβροις λεγομένοις ἐπὶ Δελφοῦς συστρατεῦσαι, καὶ φθαρῆναι μὲν αὐτίκα τοὺς πλέονας αὐτῶν πρὸ ἐπιχειρήσεως, ὑετῶν σφίσι καὶ θυέλλης καὶ πρηστήρων ἐμπεσοντων, ἐπιγενέσθαι δὲ τοῖς ὑποστρέψασιν ἄπειρον βατράχων πλῆθος, οἳ διασαπέντες τὰ νάματα διέφθειραν. καὶ ἐκ τῆς γῆς ἀτμῶν ἀτόπων γενομένων λοιμὸς ἦν Ἰλλυριῶν καὶ φθόρος Αὐταριέων μάλιστα, μέχρι φεύγοντες τὰ οἰκεῖα, καὶ τὸν λοιμὸν σφίσι περιφέροντες, οὐδενὸς αὐτοὺς δεχομένου διὰ τοῦτο τὸ δέος ὑπερῆλθον ὁδὸν ἡμερῶν εἴκοσι καὶ τριῶν, καὶ τὴν Γετῶν ἑλώδη καὶ ἀοίκητον, παρὰ τὸ Βαστερνῶν ἔθνος, ᾤκησαν. Κελτοῖς δὲ ὁ θεὸς τὴν γῆν ἔσεισε καὶ τὰς πόλεις κατήνεγκε· καὶ τὸ κακὸν οὐκ ἔληγε, μέχρι καὶ οἵδε τὰ οἰκεῖα φεύγοντες ἐνέβαλον ἐς Ἰλλυριοὺς τοὺς συναμαρτοντας σφίσιν, ἀσθενεῖς ὑπὸ τοῦ λοιμοῦ γενομένους, καὶ ἐδῄωσάν τε τὰ ἐκείνων, καὶ τοῦ λοιμοῦ μετασχόντες ἔφυγον καὶ μέχρι Πυρήνης ἐλεηλάτουν. ἐπιστρέφουσι δ’ αὐτοῖς ἐς τὴν ἕω, Ῥωμαῖοι, δεδιότες ὑπὸ μνήμης τῶν προπεπολεμηκότων σφίσι Κελτῶν, μὴ καὶ οἵδε ἐς τὴν Ἰταλίαν ὑπὲρ Ἄλπεις ἐσβάλοιεν, ἀπήντων ἅμα τοῖς ὑπάτοις καὶ πανστρατιᾷ διώλλυντο. καὶ τὸ πάθος τοῦτο Ῥωμαίων μέγα δέος Κελτῶν ἐς ὅλην τὴν Ἰταλίαν ἐνέβαλε, μέχρι Γάιον Μάριον ἑλόμενοι σφῶν οἱ Ῥωμαῖοι στρατηγεῖν, ἄρτι Λιβύων τοῖς Νομάσι καὶ Μαυρουσίοις ἐγκρατῶς πεπολεμηκότα, τοὺς Κίμβρους ἐνίκων καὶ πολὺν φόνον αὐτῶν εἰργάσαντο πολλάκις, ὥς μοι περὶ Κελτῶν λέγοντι εἴρηται. οἱ δὲ ἀσθενεῖς τε ἤδη γενόμενοι καὶ πάσης γῆς ἀποκλειόμενοι διὰ τὸ ἀσθενές, ἐς τὰ οἰκεῖα ἐπανῆλθον πολλὰ καὶ δράσαντες καὶ παθόντες.", "st": "3.4"}, {"sp": "N", "t": "τοιοῦτον μὲν δὴ τέλος τῆς ἀσεβείας ὁ θεὸς ἐπέθηκεν Ἰλλυριοῖς τε καὶ Κελτοῖς· οὐ μὴν ἀπέσχοντο τῆς ἱεροσυλίας, ἀλλ’ αὖθις, ἅμα τοῖς Κελτοῖς, Ἰλλυριῶν οἱ Σκορδίσκοι μάλιστα καὶ Μαῖδοι καὶ Δάρδανοι τὴν Μακεδονίαν ἐπέδραμον ὁμοῦ καὶ τὴν Ἑλλάδα, καὶ πολλὰ τῶν ἱερῶν καὶ τὸ Δελφικὸν ἐσύλησαν, πολλοὺς ἀποβαλόντες ὅμως καὶ τότε. Ῥωμαῖοι δ’ ἔχοντες ἤδη δεύτερον καὶ τριακοστὸν ἔτος ἀπὸ τῆς πρώτης ἐς Κελτοὺς πείρας, καὶ ἐξ ἐκείνου πολεμοῦντες αὐτοῖς ἐκ διαστημάτων, ἐπιστρατεύουσι τοῖς Ἰλλυριοῖς ἐπὶ τῇδε τῇ ἱεροσυλίᾳ ἡγουμένου Λευκίου Σκιπίωνος, ἤδη τῶν τε Ἑλλήνων καὶ Μακεδόνων προστατοῦντες. καί φασι τοὺς μὲν περιχώρους οὐ συμμαχῆσαι τοῖς ἱεροσύλοις, ἀλλ’ ἑκόντας ἐγκαταλιπεῖν τῷ Σκιπίωνι ἀβοηθήτους, μνήμῃ τῶν δι’ Αὐταριέας ἐς πάντας Ἰλλυριοὺς συμπεσόντων· Σκιπίωνα δὲ Σκορδίσκους μὲν διαφθεῖραι, καὶ εἴ τι λοιπὸν αὐτῶν ἦν, ἐς τὸν Ἴστρον καὶ τὰς νήσους τοῦ ποταμοῦ μετοικῆσαι φυγόντας, Μαίδοις δὲ καὶ Δαρδανεῦσι συνθέσθαι δωροδοκήσαντα τοῦ ἱεροῦ χρυσίου. καί τις ἔφη τῶν Ἰταλικῶν συγγραφέων ὡς διὰ τοῦτο μάλιστα Ῥωμαίοις πλεόνως μετὰ Λεύκιον τὰ ἐμφύλια ἤκμασε μέχρι μοναρχίας· καὶ περὶ μὲν τῶν νομιζομένων εἶναι τοῖς Ἕλλησιν Ἰλλυριῶν τοσαῦτά μοι προλελέχθω.", "st": "3.5"}, {"sp": "N", "t": "Ῥωμαῖοι δὲ καὶ τούσδε καὶ Παίονας ἐπ’ αὐτοῖς καὶ Ῥαιτοὺς καὶ Νωρικοὺς καὶ Μυσοὺς τοὺς ἐν Εὐρώτῃ, καὶ ὅσα ἄλλα ὅμορα τούτοις ἐν δεξιᾷ τοῦ Ἴστρου καταπλέοντι ᾤκηται, διαιροῦσι μὲν ὁμοίως τοῖς Ἕλλησιν ἀπὸ Ἑλλήνων, καὶ καλοῦσι τοῖς ἰδίοις ἑκάστους ὀνόμασι, κοινῇ δὲ πάντας Ἰλλυρίδα ἡγοῦνται, ὅθεν μὲν ἀρξάμενοι τῆσδε τῆς δόξης, οὐκ ἔσχον εὑρεῖν, χρώμενοι δ’ αὐτῇ καὶ νῦν, ὅπου καὶ τὸ τέλος τῶνδε τῶν ἐθνῶν, ἀπὸ ἀνίσχοντος Ἴστρου μέχρι τῆς Ποντικῆς θαλάσσης, ὑφ’ ἓν ἐκμισθοῦσι καὶ Ἰλλυρικὸν τέλος προσαγορεύουσιν. ὅπως δὲ αὐτοὺς ὑπηγάγοντο Ῥωμαῖοι, ὡμολόγησα μὲν καὶ περὶ Κρήτης λέγων οὐχ εὑρεῖν τὰς ἀκριβεῖς τῶν πολέμων ἀρχάς τε καὶ προφάσεις, καὶ ἐς τοῦτο τοὺς δυναμένους τι πλέον εἰπεῖν παρεκάλουν· ὅσα δ’ αὐτὸς ἔγνων, ἀναγράψω.", "st": "3.6"}, {"sp": "N", "t": "Ἄγρων ἦν βασιλεὺς Ἰλλυριῶν μέρους ἀμφὶ τὸν κόλπον τῆς θαλάσσης τὸν Ἰόνιον, ὃν δὴ καὶ Πύρρος ὁ τῆς Ἠπείρου βασιλεὺς κατεῖχε καὶ οἱ τὰ Πύρρου διαδεξάμενοι. Ἄγρων δ’ ἔμπαλιν τῆς τε Ἠπείρου τινὰ καὶ Κόρκυραν ἐπ’ αὐτοῖς καὶ Ἐπίδαμνον καὶ Φάρον καταλαβὼν ἔμφρουρα εἶχεν. ἐπιπλέοντος δ’ αὐτοῦ καὶ τὸν ἄλλον Ἰόνιον, νῆσος, ᾗ ὄνομα Ἴσσα, ἐπὶ Ῥωμαίους κατέφυγεν. οἱ δὲ πρέσβεις τοῖς Ἰσσίοις συνέπεμψαν, εἰσομένους τὰ Ἄγρωνος ἐς αὐτοὺς ἐγκλήματα. τοῖς δὲ πρέσβεσιν ἔτι προσπλέουσιν ἐπαναχθέντες Ἰλλυρικοὶ λέμβοι τῶν μὲν Ἰσσίων πρεσβευτὴν Κλεέμπορον, τῶν δὲ Ῥωμαίων Κορογκάνιον ἀναιροῦσιν· οἱ δὲ λοιποὶ διέδρασαν αὐτούς. καὶ ἐπὶ τῷδε Ῥωμαίων ἐπ’ Ἰλλυριοὺς ναυσὶν ὁμοῦ καὶ πεζῷ στρατευόντων, Ἄγρων μὲν ἐπὶ παιδίῳ σμικρῷ, Πίννῃ ὄνομα, ἀποθνήσκει, τῇ γυναικὶ τὴν ἀρχὴν ἐπιτροπεύειν τῷ παιδὶ παραδούς, καίπερ οὐκ οὔσῃ μητρὶ τοῦ παιδίου, Δημήτριος δ’ ὁ Φάρου ἡγούμενος Ἄγρωνι (Φάρου τε γὰρ αὐτῆς ἦρχε, καὶ ἐπὶ τῇδε Κορκύρας) παρέδωκεν ἄμφω Ῥωμαίοις ἐπιπλέουσιν ἐκ προδοσίας. οἱ δ’ ἐπὶ ταύταις Ἐπίδαμνον ἐς φιλίαν ὑπηγάγοντο, καὶ τοῖς Ἰσσίοις καὶ Ἐπιδαμνίοις πολιορκουμένοις ὑπὸ Ἰλλυριῶν ἐς ἐπικουρίαν ἔπλεον. Ἰλλυριοὶ μὲν δὴ τὰς πολιορκίας λύσαντες ἀνεχώρουν, καί τινες αὐτῶν ἐς Ῥωμαίους, οἱ Ἀτιντανοὶ λεγόμενοι, μετετίθεντο. μετὰ ταῦτα δὲ ἡ Ἄγρωνος γυνὴ πρέσβεις ἐς Ῥώμην ἔπεμψε τά τε αἰχμάλωτα ἀποδιδόντας αὐτοῖς καὶ τοὺς αὐτομόλους ἄγοντας, καὶ ἐδεῖτο συγγνώμης τυχεῖν τῶν οὐκ ἐφ’ ἑαυτῆς ἀλλ’ ἐπὶ Ἄγρωνος γενομένων. οἱ δὲ ἀπεκρίναντο Κόρκυραν μὲν καὶ Φάρον καὶ Ἴσσαν καὶ Ἐπίδαμνον καὶ Ἰλλυριῶν τοὺς Ἀτιντανοὺς ἤδη Ῥωμαίων ὑπηκόους εἶναι, Πίννην δὲ τὴν ἄλλην Ἄγρωνος ἀρχὴν ἔχειν καὶ φίλον εἶναι Ῥωμαίοις, ἢν ἀπέχηταί τε τῶν προλελεγμένων, καὶ τὴν Λίσσον μὴ παραπλέωσιν Ἰλλυρικοὶ λέμβοι δυοῖν πλείονες, καὶ τούτοιν δὲ ἀνόπλοιν.", "st": "3.7"}, {"sp": "N", "t": "ἡ μὲν δὴ ταῦτα πάντα ἐδέχετο, καὶ γίγνονται Ῥωμαίοις αἵδε πρῶται πρὸς Ἰλλυριοὺς πεῖραί τε καὶ συνθῆκαι· Ῥωμαῖοι δ’ ἐπ’ αὐταῖς Κόρκυραν μὲν καὶ Ἀπολλωνίαν ἀφῆκαν ἐλευθέρας, Δημητρίῳ δ’ ἔστιν ἃ χωρία μισθὸν ἔδοσαν τῆς προδοσίας, ἐπειπόντες ὅτι ἐν τοσῷδε διδόασι, τὴν ἀπιστίαν ἄρα τοῦ ἀνδρὸς ὑφορώμενοι. ἣ δὴ καὶ ἦρξεν αὐτοῦ μετ’ ὀλίγον· Ῥωμαίων γὰρ Κελτοῖς ἐπὶ τριετὲς τοῖς ἀμφὶ τὸν Ἠριδανὸν οὖσι πολεμούντων, ὁ Δημήτριος ὡς ὄντων ἐν ἀσχολίᾳ τὴν θάλασσαν ἐλῄζετο, καὶ Ἴστρους ἔθνος ἕτερον Ἰλλυριῶν ἐς τοῦτο προσελάμβανε, καὶ τοὺς Ἀτιντανοὺς ἀπὸ Ῥωμαίων ἀφίστη. οἱ δέ, ἐπεὶ τὰ Κελτῶν διετέθειτο, εὐθὺς μὲν ἐπιπλεύσαντες αἱροῦσι τοὺς λῃστάς, ἐς νεώτα δὲ ἐστράτευον ἐπὶ Δημήτριον καὶ Ἰλλυριῶν τοὺς συναμαρτόντας αὐτῷ. Δημήτριον μὲν δὴ πρὸς Φίλιππον τὸν Μακεδόνων βασιλέα φυγόντα καὶ αὖθις ἐπιόντα καὶ λῃστεύοντα τὸν Ἰόνιον κτείνουσι, καὶ τὴν πατρίδα αὐτῷ Φάρον συναμαρτοῦσαν ἐπικατέσκαψαν, Ἰλλυριῶν δ’ ἐφείσαντο διὰ Πίννην αὖθις δεηθέντα. καὶ δεύτεραι πεῖραί τε καὶ συνθῆκαι πρὸς Ἰλλυριοὺς αὐτοῖς ἐγίγνοντο.", "st": "3.8"}, {"sp": "N", "t": "τὰ λοιπὰ δ’ οὔτι μοι πάντα χρόνῳ καὶ τάξει μᾶλλον ἢ κατὰ ἔθνος Ἰλλυριῶν ἕκαστον, ὅσα ηὗρον, συγγέγραπται.", "st": "3.9"}, {"sp": "N", "t": "Ῥωμαῖοι Μακεδόσιν ἐπολέμουν, καὶ Περσεὺς ἦν ἤδη Μακεδόνων βασιλεὺς μετὰ Φίλιππον· Περσεῖ δὲ Γένθιος Ἰλλυριῶν ἑτέρων βασιλεὺς ἐπὶ χρήμασι συνεμάχει, καὶ ἐς τοὺς Ῥωμαίων Ἰλλυριοὺς ἐνέβαλε, καὶ πρέσβεις Ῥωμαίων πρὸς αὐτὸν ἐλθόντας ἔδησεν, αἰτιώμενος οὐ πρέσβεις ἀλλὰ κατασκόπους ἐλθεῖν. Ἀνίκιος δὲ Ῥωμαίων στρατηγὸς λέμβους τε τοῦ Γενθίου τινὰς εἷλεν ἐπιπλεύσας, καὶ κατὰ γῆν αὐτῷ συνενεχθεὶς ἐκράτει τὴν μάχην, καὶ συνέκλεισεν ἔς τι χωρίον, ὅθεν αὐτῷ δεομένῳ ὁ μὲν Ἀνίκιος ἐκέλευσε Ῥωμαίοις ἑαυτὸν ἐπιτρέψαι, ὁ δ’ ἐς βουλὴν ᾔτησε τρεῖς ἡμέρας, καὶ ἔλαβεν. ἐν δὲ ταύταις τῶν ὑπηκόων αὐτοῦ πρὸς τὸν Ἀνίκιον μετατιθεμένων ἠξίωσεν ἐντυχεῖν τῷ Ἀνικίῳ, καὶ γονυπετὴς ἐδεῖτο αὐτοῦ πάνυ αἰσχρῶς. ὁ δὲ αὐτὸν ἐπιθαρρύνων κατεπτηχότα ἀνίστη, καὶ καλέσας ἐπὶ ἑστίασιν, ἀπιόντα ἀπὸ τοῦ δείπνου προσέταξε τοῖς ὑπηρέταις ἐς φυλακὴν ἐμβαλεῖν. καὶ τόνδε μὲν ἐς θρίαμβον ἅμα τοῖς παισὶν ὁ Ἀνίκιος ἐς Ῥώμην ἤγαγε, καὶ ὁ Γενθίου πόλεμος ἅπας εἴκοσιν ἡμέραις ἐπεπολέμητο· ἑβδομήκοντα δ’ αὐτοῦ πόλεις οὔσας Αἰμίλιος Παῦλος ὁ τὸν Περσέα ἑλών, τῆς βουλῆς ἐπιστειλάσης ἐν ἀπορρήτῳ, ἐς Ῥώμην παρώδευεν ἐπίτηδες, καὶ δεδιόσιν αὐτοῖς ὑπέσχετο συγγνώσεσθαι τῶν γεγονότων, ἐὰν ὅσον ἔχουσιν ἀργύριόν τε καὶ χρυσίον ἐσενέγκωσιν. ὑποδεξαμένων δ’ ἐκείνων συνέπεμπεν αὐτοῖς τοῦ στρατοῦ μέρος ἐς πόλιν ἑκάστην, ὁρίσας ἡμέραν τοῖς στρατηγοῦσι τοῦ στρατοῦ πᾶσι τὴν αὐτήν, καὶ ἐντειλάμενος ἅμα ἕῳ κηρύσσειν ἕκαστον ἐν ἑκάστῃ πόλει τρισὶν ὥραις ἐς τὴν ἀγορὰν τὰ χρήματα φέρειν, συνενεγκόντων δὲ τὰ λοιπὰ διαρπάσαι.", "st": "3.9"}, {"sp": "N", "t": "οὕτω μὲν ὁ Παῦλος ἑβδομήκοντα πόλεις διήρπασεν ὥρᾳ μιᾷ· Ἀρδεῖοι δὲ καὶ Παλάριοι, γένη ἕτερα Ἰλλυριῶν, τὴν ὑπὸ Ῥωμαίους Ἰλλυρίδα ἐδῄουν, καὶ οἱ Ῥωμαῖοι δι’ ἀσχολίαν πρέσβεις ἔπεμψαν ἐπιπλήξοντας αὐτοῖς. οὐ μεταθεμένων δὲ ἐκείνων ἐστράτευον ἐπ’ αὐτοὺς μυρίοις πεζοῖς καὶ ἱππεῦσιν ἑξακοσιοις. οἱ δὲ πυθόμενοι, καὶ ἔτι ὄντες ἀπαράσκευοι, πρέσβεις ἔπεμψαν μεταγιγνώσκοντες καὶ δεόμενοι. καὶ ἡ βουλὴ τὰς βλάβας αὐτοῖς ἐκέλευσεν ἀποδοῦναι τοῖς ἠδικημένοις. οὐκ ἀποδιδόντων δὲ ἐστράτευεν ἐπ’ αὐτοὺς Φούλουιος Φλάκκος. καὶ ὁ πόλεμος ἄρα μέχρι καταδρομῆς ἔληξε μόνης. οὐ γὰρ ηὗρον αὐτοῦ τέλος ἀκριβές. Ἰάποσι δὲ τοῖς ἐντὸς Ἄλπεων ἐπολέμησε μὲν Σεμπρώνιος ὁ Τουδιτανὸς ἐπίκλην καὶ Πανδούσας Τιβέριος καὶ ἐοίκασιν οἱ Ἰάποδες αὐτοῖς ὑπακοῦσαι, ἐοίκασι δὲ καὶ Σεγεστανοὶ Λευκίῳ Κόττᾳ καὶ Μετέλλῳ, ἀμφότεροι δ’ οὐ πολὺ ὕστερον ἀποστῆναι.", "st": "3.10"}, {"sp": "N", "t": "Δαλμάται δέ, Ἰλλυριῶν ἕτερον γένος, Ἰλλυριοὺς τοὺς ὑπὸ Ῥωμαίοις κατέθεον, καὶ πρέσβεις ἀφικομένους περὶ τοῦδε Ῥωμαίων οὐ προσίεντο. στρατεύουσιν οὖν ἐπ’ αὐτοὺς οἱ Ῥωμαῖοι, Μαρκίου Φίγλου σφῶν ὑπατεύοντός τε καὶ ἐς τὸν πόλεμον ἡγουμένου. οἱ δὲ ἄρτι τοῦ Φίγλου παραστρατοπεδεύοντος τὰς φυλακὰς ἐνίκων ἐπίδραμόντες, καὶ αὐτὸν ἐκ τοῦ στρατοπέδου κατήραξαν ἐς πεδίον πρανές, μέχρι ἐπὶ Νάρωνα ποταμὸν ἧκεν ὑποφεύγων. ὡς δὲ οἱ μὲν ἀνεχώρουν, ἀρχὴ δὲ χειμῶνος ἦν, ὁ Φίγλος ἐλπίσας αὐτοῖς ἀδοκήτως ἐπιπεσεῖσθαι συνερρυηκότας ηὗρεν ἐκ τῶν πόλεων πρὸς τὴν ἔφοδον αὐτοῦ. καὶ συνήλασεν ὅμως ἐς πόλιν Δελμίνιον, ὅθεν ἄρα καὶ τὸ ὄνομα αὐτοῖς ἐς Δελματέας, εἶτα Δαλμάτας ἐτράπη. οὐδὲν δὲ πρὸς ἐχυρὰν πόλιν ἐξ ἐφόδου δυνάμενος, οὐδὲ μηχανήμασιν ἔχων χρῆσθαι διὰ τὸ ὕψος, ᾕρει τὰς ἄλλας ἐπιθέων, ἐρημοτέρας ἀνδρῶν ὑπὸ τῆς ἐς τὸ Δελμίνιον συνόδου γενομένας. εἶτα διπήχεας κορύνας πίσσῃ καὶ θείῳ καὶ στυππίῳ περιβαλὼν ἐς τὸ Δελμίνιον ἐκ καταπελτῶν ἐσφενδόνα. αἱ δ’ ὑπὸ τῆς ῥύμης ἐξεκαίοντο, καὶ φερόμεναι καθάπερ λαμπάδες ὅπου τύχοιεν ἐνεπίμπρασαν, ἕως πολλὰ μὲν κατεπρήσθη, καὶ τέλος ἄρα τοῦτο ἦν τότε Φίγλῳ τοῦ Δαλματῶν πολέμου. χρόνῳ δ’ ὕστερον Καικίλιος Μέτελλος ὑπατεύων οὐδὲν ἀδικοῦσι τοῖς Δαλμάταις ἐψηφίσατο πολεμεῖν ἐπιθυμίᾳ θριάμβου, καὶ δεχομένων αὐτὸν ἐκείνων ὡς φίλον διεχείμασε παρ’ αὐτοῖς ἐν Σαλώνῃ πόλει, καὶ ἐς Ῥώμην ἐπανῆλθε καὶ ἐθριάμβευσεν.", "st": "3.11"}, {"sp": "N", "t": "τοῦ δὲ Καίσαρος ἡγουμένου Κελτῶν, οἱ Δαλμάται οἵδε, καὶ ὅσοι ἄλλοι Ἰλλυριῶν τότε μάλιστα διηυτύχουν, Λιβυρνούς, ἕτερον ἔθνος Ἰλλυριῶν, Πρωμόναν πόλιν ἀφείλοντο· οἱ δὲ σφᾶς Ῥωμαίοις ἐπιτρέποντες ἐπὶ τὸν Καίσαρα ἐγγὺς ὄντα κατέφευγον. ὁ δὲ ἔπεμψε μέν, καὶ προηγόρευσε τοῖς ἔχουσι τὴν Πρωμόναν ἀποδοῦναι τοῖς Λιβυρνοῖς· οὐ φροντισάντων δὲ ἐκείνων τέλος ἔπεμψε στρατοῦ πολλοῦ, οὓς ἅπαντας ἔκτειναν οἱ Ἰλλυριοί. καὶ ὁ Καῖσαρ οὐκ ἐπεξῆλθεν· οὐ γὰρ ἦν οἱ σχολὴ τότε στασιάζοντι πρὸς Πομπήιον. ἐκραγείσης δὲ ἐς πόλεμον τῆς στάσεως ὁ μὲν Καῖσαρ μεθ’ ὅσων εἶχεν ἐκ Βρεντεσίου χειμῶνος τὸν Ἰόνιον ἐπέρα καὶ Πομπηίῳ κατὰ Μακεδονίαν ἐπολέμει, τοῦ δ’ ἄλλου στρατοῦ τὸν μὲν Ἀντώνιος ἐς τὴν Μακεδονίαν ἦγε τῷ Καίσαρι, περῶν καὶ ὅδε τὸν Ἰόνιον χειμῶνος ἄκρου, σπείρας δὲ πεζοῦ πεντεκαίδεκα καὶ τρισχιλίους ἱππέας Γαβίνιος ἦγεν αὐτῷ διὰ τῆς Ἰλλυρίδος, περιοδεύων τὸν Ἰόνιον. οἱ δὲ Ἰλλυριοὶ φόβῳ τῶν οὐ πρὸ πολλοῦ γεγονότων ἐς Καίσαρα, τὴν νίκην αὐτοῦ νομίζοντες ὄλεθρον γενήσεσθαι ἑαυτοῖς, κτείνουσι πάντα τὸν ὑπὸ τῷ Γαβινίῳ στρατὸν ἐπιδραμόντες, χωρὶς αὐτοῦ Γαβινίου καὶ ὀλίγων διαφυγόντων. καὶ ἐς χρήματα τότε μάλιστα καὶ τὴν ἄλλην ἰσχὺν ἐκ τοσῶνδε λαφύρων ἔστησαν.", "st": "3.12"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ ἠσχολεῖτο μὲν ὑπ’ ἀνάγκης ἐς Πομπήιον, καὶ Πομπηίου καθαιρεθέντος ἐς τὰ ὑπόλοιπα τῆς ἐκείνου στάσεως πολυμερῆ γενόμενα, καταστησάμενος δὲ πάντα ἐπανῆλθεν ἐς Ῥώμην, καὶ ἐστράτευεν ἐπὶ Γέτας τε καὶ Παρθυαίους. ἔδεισαν οὖν οἱ Ἰλλυριοὶ μὴ ἐν ὁδῷ σφίσιν οὖσιν ἐπιθοῖτο, καὶ πρέσβεις πέμψαντες ἐς Ῥώμην ᾔτουν τε συγγνώμην τῶν γεγονότων καὶ ἐς φίλιαν ἑαυτοὺς καὶ συμμαχίαν ἐδίδοσαν, ὡς περὶ ἔθνους ἀλκίμου μάλιστα σεμνολογούμενοι. ὁ δὲ ἐπειγόμενος ἄρα ἐς Παρθυαίους σεμνότερον ὅμως αὐτοῖς ἀπεκρίνατο, φίλους μὲν οὐ θήσεσθαι τοὺς τοιαῦτα δεδρακότας, συγγνώσεσθαι δέ, εἰ φόρους ὑποσταῖεν καὶ ὅμηρα δοῖεν. ὑπισχνουμένων δὲ ἐς ἀμφότερα αὐτῶν Οὐατίνιον ἔπεμψε σὺν στρατοῦ τέλεσι τρισὶ καὶ ἱππεῦσι πολλοῖς, φόρους τε ὀλίγους τάξοντα αὐτοῖς καὶ τὰ ὅμηρα ληψόμενον. ἀναιρεθέντος δὲ τοῦ Καίσαρος, ἡγούμενοι τὴν Ῥωμαίων ἰσχὺν ἐν τῷ Καίσαρι γεγονέναι τε καὶ διεφθάρθαι, οὐδὲν ἔτι τοῦ Οὐατινίου κατήκουον, οὔτε ἐς τοὺς φόρους οὔτε ἐς τὰ ἄλλα, βιάζεσθαι δὲ ἐγχειροῦντος αὐτοὶ πέντε τάξεις ἐπιδραμόντες ἔφθειραν, καὶ τὸν ἡγούμενον τῶν τάξεων Βαίβιον, ἄνδρα ἀπὸ βουλῆς. καὶ Οὐατίνιος μὲν σὺν τοῖς ὑπολοίποις ἐς Ἐπίδαμνον ἀνεχώρει· ἡ δὲ Ῥωμαίων βουλὴ τὸν στρατὸν τόνδε καὶ Μακεδονίαν ἐπ’ αὐτῷ, καὶ Ἰλλυριοὺς ὅσων ἦρχον, ἐνεχείρισε Βρούτῳ Καιπίωνι τῷ κτείναντι Γάιον, ὅτε περ καὶ Συρίαν Κασσίῳ, καὶ τῷδε ἀνδροφόνῳ Γαΐου γενομένῳ. ἀλλὰ καὶ οἵδε, πολεμούμενοι πρὸς Ἀντωνίου καὶ τοῦ δευτέρου Καίσαρος τοῦ Σεβαστοῦ προσαγορευθέντος, ἐς οὐδὲν ἐσχόλασαν Ἰλλυριοῖς.", "st": "3.13"}, {"sp": "N", "t": "οἱ δὲ Παίονές εἰσιν ἔθνος μέγα παρὰ τὸν Ἴστρον, ἐπίμηκες ἐξ Ἰαπόδων ἐπὶ Δαρδάνους, Παίονες μὲν ὑπὸ τῶν Ἑλλήνων λεγόμενοι, καὶ ῥωμαϊστὶ Παννόνιοι, συναριθμούμενοι δὲ ὑπὸ Ῥωμαίων τῇ Ἰλλυρίδι, ὡς προεῖπον. διὸ καὶ περὶ τῶνδέ μοι δοκεῖ νῦν κατὰ τὰ Ἰλλυρικὰ εἰπεῖν. ἔνδοξοι δ’ εἰσὶν ἐκ Μακεδόνων δι’ Ἀγριᾶνας, οἳ τὰ μέγιστα Φιλίππῳ καὶ Ἀλεξάνδρῳ κατεργασάμενοι Παίονές εἰσι τῶν κάτω Παιόνων, Ἰλλυριοῖς ἔποικοι. ἐπεὶ δ’ ἐπὶ τοὺς Παίονας ἐστράτευσε Κορνήλιος, κακῶς ἀπαλλάξας μέγα δέος Παιόνων Ἰταλοῖς ἅπασιν ἐνεποίησε, καὶ ἐς πολὺ τοῖς ἔπειτα ὑπάτοις ὄκνον ἐπὶ Παίονας ἐλαύνειν. τὰ μὲν δὴ πάλαι τοσαῦτα περὶ Ἰλλυριῶν καὶ Παιόνων ἔσχον εὑρεῖν· ἐν δὲ τοῖς ὑπομνήμασι τοῦ δευτέρου Καίσαρος τοῦ κληθέντος Σεβαστοῦ, παλαιότερον μὲν οὐδὲν οὐδ’ ἐν τοῖσδε περὶ Παιόνων ηὗρον.", "st": "3.14"}, {"sp": "N", "t": "Ἰλλυριῶν δέ μοι φαίνεται χωρὶς τῶν εἰρημένων ἐθνῶν καὶ ἕτερα Ῥωμαίων προϋπακοῦσαι. καὶ ὅπως μεν, οὐκ ἔγνων· οὐ γὰρ ἀλλοτρίας πράξεις ὁ Σεβαστός, ἀλλὰ τὰς ἑαυτοῦ συνέγραφεν, ὡς δ’ ἀποστάντας ἐς τοὺς φόρους ἐπανήγαγε, καὶ ἑτέρους ὡς ἀρχῆθεν ἔτι ὄντας αὐτονόμους εἷλε, καὶ πάντας ἐκρατύνατο ὅσοι τὰς κορυφὰς οἰκοῦσι τῶν Ἄλπεων, βάρβαρα καὶ μάχιμα ἔθνη, καὶ κλοπεύοντα τὴν Ἰταλίαν ὡς γείτονα. καί μοι θαῦμά ἐστιν ὅτι καὶ πολλοὶ καὶ μεγάλοι Ῥωμαίων στρατοὶ ἐπὶ Κελτοὺς καὶ Ἴβηρας διὰ τῶν Ἄλπεων ὁδεύοντες ὑπερεῖδον τάδε τὰ ἔθνη, καὶ οὐδὲ Γάιος Καῖσαρ, εὐτυχέστατος ἐς πολέμους ἀνήρ, ἐξήνυσεν αὐτά, ὅτε Κελτοῖς ἐπολέμει καὶ δέκα ἔτεσιν ἀμφὶ τήνδε τὴν χώραν ἐχείμαζεν. ἀλλά μοι δοκοῦσιν οἱ μέν, ἐφ’ ἃ ᾑρέθησαν ἐπειγόμενοι, τῆς διόδου τῶν Ἄλπεων μόνης φροντίσαι, ὁ δὲ Γάιος ἀμφί τε τὰ Κελτικὰ γενέσθαι, καὶ τῆς στάσεως τοῦ Πομπηίου τὰ Κελτικὰ ἐπιλαβούσης τὸ τούτων τέλος ὑπερθέσθαι. φαίνεται μὲν γὰρ καὶ Ἰλλυρίδος ἅμα Κελτοῖς αἱρεθεὶς ἄρχειν, οὐ πάσης δ’ ἄρα ἦρχεν ἀλλ’ ὅση τις ἦν τότε Ῥωμαίοις Ἰλλυρίς.", "st": "3.15"}, {"sp": "N", "t": "ὁ δὲ Σεβαστὸς πάντα ἐχειρώσατο ἐντελῶς, καὶ ἐν παραβολῇ τῆς ἀπραξίας Ἀντωνίου κατελογίσατο τῇ βουλῇ τὴν Ἰταλίαν ἡμερῶσαι δυσμάχων ἐθνῶν θαμινὰ ἐνοχλούντων. Ὀξυαίους μὲν δὴ καὶ Περθεηνάτας καὶ Βαθιάτας καὶ Ταυλαντίους καὶ Καμβαίους καὶ Κινάμβρους καὶ Μερομέννους καὶ Πυρισσαίους εἷλε δι’ ὅλης πείρας· ἔργῳ δὲ μείζονι ἐλήφθησαν, καὶ φόρους ὅσους ἐξέλιπον ἠναγκάσθησαν ἀποδοῦναι, Δοκλεᾶταί τε καὶ Κάρνοι καὶ Ἰντερφρουρῖνοι καὶ Ναρήσιοι καὶ Γλιντιδίωνες καὶ Ταυρίσκοι. ὧν ἁλόντων οἱ ὅμοροι προσέθεντο αὐτῷ καταπλαγέντες, Ἱππασῖνοί τε καὶ Βεσσοί. ἑτέρους δὲ αὐτῶν ἀποστάντας, Μελιτηνοὺς καὶ Κορκυρηνούς, οἳ νήσους ᾤκουν, ἀνέστησεν ἄρδην, ὅτι ἐλῄστευον τὴν θάλασσαν· καὶ τοὺς μὲν ἡβῶντας αὐτῶν ἔκτεινε, τοὺς δ’ ἄλλους ἀπέδοτο. Λιβυρνῶν δὲ τὰς ναῦς ἀφείλετο, ὅτι καὶ οἵδε ἐλῄστευον. Ἰαπόδων δὲ τῶν ἐντὸς Ἄλπεων Μοεντῖνοι μὲν καὶ Αὐενδεᾶται προσέθεντο αὐτῷ προσιόντι, Ἀρουπῖνοι δ’, οἳ πλεῖστοι καὶ μαχιμώτατοι τῶνδε τῶν Ἰαπόδων εἰσίν, ἐκ τῶν κωμῶν ἐς τὸ ἄστυ ἀνῳκίσαντο, καὶ προσιόντος αὐτοῦ ἐς τὰς ὕλας συνέφυγον. ὁ δὲ Καῖσαρ τὸ ἄστυ ἑλὼν οὐκ ἐνέπρησεν, ἐλπίσας ἐνδώσειν αὐτούς· καὶ ἐνδοῦσιν οἰκεῖν ἔδωκεν.", "st": "3.16"}, {"sp": "N", "t": "μάλιστα δ’ ἠνώχλησαν αὐτὸν Σαλασσοί τε καὶ Ἰάποδες οἱ πέραν Ἄλπεων καὶ Σεγεστανοὶ καὶ Δαλμάται καὶ Δαισιτιᾶται καὶ Παίονες, ὄντες ἑκὰς τοῖς Σαλασσοῖς, οἳ κορυφὰς οἰκοῦσι τῶν Ἄλπεων, ὄρη δύσβατα, καὶ στενὴ δίοδός ἐστιν ἐπ’ αὐτὰ καὶ δυσχερής· δι’ ἃ καὶ ἦσαν αὐτόνομοι, καὶ τέλη τοὺς παροδεύοντας ᾔτουν. τούτοις Οὐέτερ ἐμπεσὼν ἀδοκήτως τὰ στενὰ προύλαβε δι’ ἐνέδρας, καὶ ἐπὶ διετὲς αὐτοὺς ἐπολιόρκει. οἱ δὲ ἁλῶν ἀπορίᾳ, ὧν εἰσὶ μάλιστα ἐν χρείᾳ, φρουρὰς ἐδέξαντο. καὶ Οὐέτερος ἀποστάντος τὰς φρουρὰς ἐξέβαλον εὐθύς, καὶ τὰ στενὰ κρατυνάμενοι τοὺς ἐπιπεμπομένους σφίσιν ὑπὸ τοῦ Καίσαρος διέπαιζον, οὐδὲν δρᾶν μέγα ἔχοντας. ὅθεν αὐτοῖς ὁ Καῖσαρ, προσδοκωμένου τοῦ πρὸς Ἀντώνιον πολέμου, συνέθετο αὐτονόμους ἐάσειν, καὶ ἀκολάστους τῶν ἐπὶ Οὐέτερι πραχθέντων. οἱ δ’ ἅτε ἐν ὑποψίᾳ ταῦτ’ ἔχοντες ἅλας πολλοὺς ἐσώρευον, καὶ τὴν Ῥωμαίων κατέθεον, μέχρι Μεσσάλας Κορουῖνος αὐτοῖς ἐπιπεμφθεὶς λιμῷ παρεστήσατο.", "st": "3.17"}, {"sp": "N", "t": "καὶ Σαλασσοὶ μὲν οὕτως ἐλήφθησαν, Ἰάποδες δὲ οἱ πέραν Ἄλπεων, ἔθνος ἰσχυρόν τε καὶ ἄγριον, δὶς μὲν ἀπεώσαντο Ῥωμαίους, ἔτεσί που ἀγχοῦ εἴκοσιν, Ἀκυληίαν δ’ ἐπέδραμον καὶ Τεργηστὸν Ῥωμαίων ἄποικον ἐσκύλευσαν. ἐπιόντος δ’ αὐτοῖς τοῦ Καίσαρος ὁδὸν ἀνάντη καὶ τραχεῖαν· οἱ δ’ ἔτι μᾶλλον αὐτὴν ἐδυσχέραινον αὐτῷ, τὰ δένδρα κόπτοντες. ὡς δ’ ἀνῆλθεν, ἐς τὴν ἄλλην ὕλην αὐτοὶ συνέφυγον καὶ προσιόντα ἐλόχων. ὁ δέ (ὑπώπτευε γὰρ ἀεί τι τοιοῦτον) ἐς τὰς ἀκρωρείας τινὰς ἔπεμπεν, οἳ ἑκατέρωθεν αὐτῷ συνέθεον προβαίνοντι διὰ τοῦ χθαμαλοῦ καὶ κόπτοντι τὴν ὕλην· οἱ δὲ Ἰάποδες ἐπεξέθεον μὲν ἐκ τῶν ἐνεδρῶν καὶ πολλοὺς ἐτίτρωσκον, ὑπὸ δὲ τῶν ἐν τοῖς ἄκροις ἐπιτρεχόντων κατεκόπτοντο οἱ πλείους. οἱ δὲ λοιποὶ πάλιν ἐς τὰ λάσια συνέφευγον, τὴν πόλιν ἐκλιπόντες, ᾗ ὄνομα Τέρπωνος. καὶ αὐτὴν ὁ Καῖσαρ ἑλὼν οὐκ ἐνέπρησεν, ἐλπίσας καὶ τούσδε ἐνδώσειν· καὶ ἐνέδωκαν.", "st": "3.18"}, {"sp": "N", "t": "ἐπὶ δ’ ἑτέραν πόλιν ἐχώρει, Μετοῦλον, ἣ τῶν Ἰαπόδων ἐστὶ κεφαλή, κεῖται δ’ ἐν ὄρει σφόδρα ὑλώδει ἐπὶ δύο λόφων, οὓς διαιρεῖ χαράδρα στενή. καὶ ἡ νεότης ἦν ἀμφὶ τοὺς τρισχιλίους μαχίμους τε καὶ σφόδρα εὐόπλους· οἳ Ῥωμαίους τὰ τείχη σφῶν περιστάντας εὐκόλως ἀπεκρούοντο. οἱ δὲ χῶμα ἤγειρον· καὶ οἱ Μετοῦλοι τό τε χῶμα νυκτὸς καὶ ἡμέρας ἐκτρέχοντες ἠνώχλουν, καὶ τοὺς ἄνδρας ἀπὸ τοῦ τείχους μηχαναῖς κατεπόνουν, ἃς ἐσχήκεσαν ἐκ τοῦ πολέμου ὃν Δέκμος Βροῦτος ἐνταῦθα ἐπολέμησεν Ἀντωνίῳ τε καὶ τῷ Σεβαστῷ. πονοῦντος δὲ κἀκείνοις ἤδη τοῦ τείχους, οἵδ’ ὑπετείχισαν ἔνδοθεν, καὶ τὸ κεκμηκὸς ἐκλιπόντες μετεπήδησαν ἐς τὸ νεότευκτον· οἱ δὲ Ῥωμαῖοι τὸ μὲν ἐκλειφθὲν λαβόντες ἐνέπρησαν, κατὰ δὲ τοῦ ἄλλου δύο χώματα ἔχουν, καὶ ἀπ’ αὐτῶν γεφύρας τέσσαρας ἐξέτεινον ἐς τὸ τεῖχος. γενομένων δὲ τούτων ὁ Καῖσαρ περιέπεμψέ τινας ἐς τὰ ὀπίσθια τῆς πόλεως, περισπᾶν τοὺς Μετούλους, τοῖς δ’ ἄλλοις προσέταξε περᾶν ἐς τὰ τείχη. διὰ τῶν γεφυρῶν. καὶ αὐτὸς ἐς ὑψηλὸν πύργον ἀναβὰς ἑώρα.", "st": "3.19"}, {"sp": "N", "t": "οἱ βάρβαροι δὲ τοῖς περῶσιν ὑπήντων τε ἐκ μετώπου κατὰ τὸ τεῖχος, καὶ ὑφεδρεύοντες ἕτεροι τὰς γεφύρας μακροῖς δόρασιν ὑπεκέντουν, μᾶλλόν τε ἐθάρρησαν μιᾶς γεφύρας καὶ δευτέρας ἐπ’ ἐκείνῃ πεσούσης. ὡς δὲ καὶ ἡ τρίτη συνέπεσε, φόβος ἤδη παντελὴς τοὺς Ῥωμαίους ἐπεῖχε, καὶ οὐδεὶς τῆς τετάρτης ἐπέβαινεν, ἕως ὁ Καῖσαρ ἐκ τοῦ πύργου καταθορὼν ὠνείδιζεν αὐτούς. ἀλλὰ καὶ ὣς οὐκ ἐρεθιζομένων, αὐτὸς ἀσπίδα λαβὼν ἐπὶ τὴν γέφυραν ἵετο δρόμῳ. συνέθεον δ’ αὐτῷ τῶν ἡγεμόνων Ἀγρίππας τε καὶ Ἱέρων καὶ ὁ σωματοφύλαξ Λοῦτος καὶ Οὐόλας, τέσσαρες οἵδε μόνοι, καὶ τῶν ὑπασπιστῶν ὀλίγοι. ἤδη δ’ αὐτοῦ τὴν γέφυραν περῶντος, ἐν αἰδοῖ γενόμενος ὁ στρατὸς ἀνεπήδησεν ἄθρους. καὶ πάλιν ἡ γέφυρα βαρηθεῖσα καταπίπτει, καὶ οἱ ἄνδρες ὑπ’ αὐτῆς ἀθρόοι κατεχώννυντο, καὶ οἱ μὲν ἀπέθανον αὐτῶν, οἱ δὲ συντριβέντες ἐφέροντο. ὁ δὲ Καῖσαρ ἐπλήγη μὲν τὸ σκέλος τὸ δεξιὸν καὶ τοὺς βραχίονας ἄμφω, ἀνέδραμε δ’ ὅμως εὐθὺς ἐπὶ τὸν πύργον μετὰ τῶν συμβόλων, καὶ ἑαυτὸν ἔδειξεν ἐρρωμένον, μή τις ὡς ἀποθανόντος γένοιτο θόρυβος. ἵνα δὲ μηδ’ οἱ πολέμιοι νομίσειαν αὐτὸν ἐνδώσειν ἀναχωρήσαντα, εὐθὺς ἑτέρας ἐπήγνυτο γεφύρας. ὃ καὶ μάλιστα κατέπληξε τοὺς Μετούλους ὡς ὑπὸ γνώμης ἀμάχου πολεμουμένους.", "st": "3.20"}, {"sp": "N", "t": "καὶ τῆς ἐπιούσης πρεσβευσάμενοι πρὸς αὐτὸν ὁμήρους τε πεντήκοντα ἔδοσαν, οὓς ὁ Καῖσαρ ἐπελέξατο, καὶ φρουρὰν ὑποσχόμενοι δέξεσθαι τὸν ὑψηλότερον λόφον τοῖς φρουροῖς ἀπέλιπον, αὐτοὶ δὲ μετεχώρουν ἐς τὸν ἕτερον. ἐπεὶ δὲ ἐσελθοῦσα ἡ φρουρὰ τὰ ὅπλα αὐτοὺς ἐκέλευεν ἀποθέσθαι, οἱ δὲ ἠγανάκτησάν τε, καὶ τὰ γύναια σφῶν καὶ τοὺς παῖδας ἐς τὸ βουλευτήριον συγκλείσαντες, καὶ φυλακὴν ἐπιστήσαντες, οἷς εἴρητο, εἴ τι ἀηδὲς γίγνοιτο περὶ αὐτούς, ἐμπρῆσαι τὸ βουλευτήριον, ἐπεχείρουν τοῖς Ῥωμαίοις αὐτοὶ μετ’ ἀπονοίας. οἷα δ’ ὑψηλοτέροις ἐπιχειροῦντες ἐκ ταπεινοῦ, συνεχώσθησαν ἀθρόοι, καὶ οἱ φύλακες τὸ βουλευτήριον κατέπησαν, πολλαί τε τῶν γυναικῶν ἑαυτάς τε καὶ τὰ τέκνα διεχρῶντο, αἱ δὲ καὶ ζῶντα ἔτι φέρουσαι ἐς τὸ πῦρ ἐνήλαντο, ὡς ἀπολέσθαι τῶν Μετούλων τήν τε νεότητα πᾶσαν ἐν τῇ μάχῃ καὶ τῶν ἀχρείων τὸ πλέον τῷ πυρί. συγκατεφλέγη δὲ αὐτοῖς καὶ ἡ πόλις, καὶ οὐδὲν ἦν ἴχνος μεγίστης ἐκεῖθι γενομένης. Μετούλου δ’ ἁλούσης οἱ λοιποὶ τῶν Ἰαπόδων καταπλαγέντες ἑαυτοὺς ἐπέτρεψαν τῷ Καίσαρι. Ἰάποδες μὲν οὖν οἱ πέραν Ἄλπεων τότε πρῶτον Ῥωμαίων ὑπήκουσαν· καὶ αὐτῶν Ποσηνοὺς ἀποχωρήσαντος τοῦ Καίσαρος ἀποστάντας ἐπιπεμφθεὶς αὐτοῖς Μᾶρκος Ἕλουιος εἷλε, καὶ τοὺς μὲν αἰτίους ἔκτεινε, τοὺς δὲ λοιποὺς ἀπέδοτο.", "st": "3.21"}, {"sp": "N", "t": "ἐς δὲ τὴν Σεγεστικὴν γῆν οἱ Ῥωμαῖοι δὶς πρότερον ἐμβαλόντες οὔτε ὅμηρον οὔτε ἄλλο τι εἰλήφεσαν· ὅθεν ἦσαν ἐπὶ φρονήματος οἱ Σεγεστανοί. ὁ δὲ Καῖσαρ αὐτοῖς ἐπῄει διὰ τῆς Παιόνων γῆς, οὔπω Ῥωμαίοις οὐδὲ τῆσδε ὑπηκόου γενομένης. ὑλώδης δ’ ἐστὶν ἡ Παιόνων, καὶ ἐπιμήκης ἐξ Ἰαπόδων ἐπὶ Δαρδάνους. καὶ οὐ πόλεις ᾤκουν οἱ Παίονες οἵδε, ἀλλ’ ἀγροὺς ἢ κώμας κατὰ συγγένειαν· οὐδ’ ἐς βουλευτήρια κοινὰ συνῄεσαν, οὐδ’ ἄρχοντες αὐτοῖς ἦσαν ἐπὶ πᾶσιν. οἱ δ’ ἐν ἡλικίᾳ μάχης ἐς δέκα μυριάδας συνετέλουν. ἀλλ’ οὐδ’ οὗτοι συνῄεσαν ἀθρόοι δι’ ἀναρχίαν. προσιόντος δ’ αὐτοῖς τοῦ Καίσαρος, ἐς τὰς ὕλας ὑποφυγόντες τοὺς ἀποσκιδναμένους τῶν στρατιωτῶν ἀνῄρουν. ὁ δὲ Καῖσαρ ἕως μὲν ἤλπιζεν αὐτοὺς ἀφίξεσθαι πρὸς αὑτόν, οὔτε τὰς κώμας οὔτε τοὺς ἀγροὺς ἐλυμαίνετο, οὐκ ἀπαντώντων δὲ πάντα ἐνεπίμπρη καὶ ἔκειρεν ἐπὶ ἡμέρας ὀκτώ, ἐς ὃ διῆλθεν ἐς τὴν Σεγεστανῶν, καὶ τήνδε Παιόνων οὖσαν, ἐπὶ τοῦ Σάου ποταμοῦ, ἐν ᾧ καὶ πόλις ἔστιν ἐχυρά, τῷ τε ποταμῷ καὶ τάφρῳ μεγίστῃ διειλημμένη, διὸ καὶ μάλιστα αὐτῆς ἔχρῃζεν ὁ Καῖσαρ, ὡς ταμιείῳ χρησόμενος ἐς τὸν Δακῶν καὶ Βαστερνῶν πόλεμον, οἳ πέραν εἰσὶ τοῦ Ἴστρου, λεγομένου μὲν ἐνταῦθα Δανουβίου, γιγνομένου δὲ μετ’ ὀλίγον Ἴστρου. ἐμβάλλει δ’ ὁ Σάος ἐς τὸν Ἴστρον· καὶ αἱ νῆες ἐν τῷ Σάῳ Καίσαρι ἐγίγνοντο, αἳ ἐς τὸν Δανούβιον αὐτῷ τὴν ἀγορὰν διοίσειν ἔμελλον.", "st": "3.22"}, {"sp": "N", "t": "διὰ μὲν δὴ ταῦτα τῆς Σεγέστης ἔχρῃζεν ὁ Καῖσαρ· προσιόντι δὲ αὐτῷ οἱ Σεγεστανοὶ προσέπεμψαν, πυνθανόμενοι τίνος χρῄζει. ὁ δὲ φρουρὰν ἐσαγαγεῖν ἔφη, καὶ ὁμήρους ἑκατὸν λαβεῖν, ἵν’ ἀσφαλῶς ταμιείῳ τῇ πόλει χρῷτο ἐπὶ Δάκας. ᾔτει δὲ καὶ σῖτον, ὅσον δύναιντο φέρειν. ταῦθ’ οἱ μὲν πρωτεύοντες ἠξίουν δοῦναι· ὁ δὲ δῆμος ἐξαγριαίνων τὰ μὲν ὅμηρα διδόμενα περιεῖδεν, ὅτι ἴσως οὐ παρὰ σφῶν ἀλλὰ τῶν πρωτευόντων παῖδες ἦσαν, προσιούσης δὲ τῆς φρουρᾶς τὴν ὄψιν οὐκ ἐνεγκόντες ὁρμῇ μανιώδει τὰς πύλας αὖθις ἀπέκλειον καὶ αὑτοὺς τοῖς τείχεσιν ἐπέστησαν. ὁ οὖν Καῖσαρ τόν τε ποταμὸν ἐγεφύρου, καὶ χάρακας καὶ τάφρους πάντοθεν ἐποιεῖτο, ἀποτειχίσας δ’ αὐτοὺς δύο χώματα ἔχου. οἷς ἐπέδραμον μὲν οἱ Σεγεστανοὶ πολλάκις, οὐ δυνηθέντες δ’ ἑλεῖν λαμπάδας καὶ πῦρ πολὺ ἄνωθεν ἐπέβαλλον. προσιούσης δ’ αὐτοῖς Παιόνων ἑτέρων βοηθείας, ὁ Καῖσαρ ὑπαντήσας ἐνήδρευσεν αὐτήν· καὶ οἱ μὲν ἀνῃρέθησαν, οἱ δ’ ἔφυγον, καὶ οὐδεὶς ἔτι Παιόνων ἐβοήθει.", "st": "3.23"}, {"sp": "N", "t": "οἱ Σεγεστανοὶ δὲ πᾶσαν πολιορκίαν ὑποστάντες ἡμέρᾳ τριακοστῇ κατὰ κράτος ἐλήφθησαν, καὶ τότε πρῶτον ἤρξαντο ἱκετεύειν. καὶ αὐτοὺς ὁ Καῖσαρ ἐπαίνῳ τε τῆς ἀρετῆς καὶ ἐλέῳ τῆς ἱκεσίας οὔτε ἔκτεινεν οὔτε ἀνέστησεν, ἀλλὰ χρήμασιν ἐζημίωσε, καὶ τῆς πόλεως μέρος διατειχίσας ἐσήγαγεν ἐς αὐτὸ φρουρὰν πέντε καὶ εἴκοσι σπειρῶν. καὶ ὁ μὲν τάδ’ ἐργασάμενος ἐς Ῥώμην ἀνέζευξεν, ὡς ἦρος ἐπανήξων ἐς τὴν Ἰλλυρίδα. φήμης δ’ ἐπιδραμούσης ὅτι τὴν φρουρὰν οἱ Σεγεστανοὶ διέφθειραν, ἐξέθορε χειμῶνος. καὶ τὸ μὲν τέλος τῆς φήμης ψευδὲς ηὗρε, τὴν δὲ αἰτίαν ἀληθῆ· ἐγεγόνεσαν γὰρ ἐν κινδύνῳ, τῶν Σεγεστανῶν αὐτοὺς ἄφνω περιστάντων, καὶ πολλοὺς τὸ αἰφνίδιον ἀπωλωλέκει, τῆς δ’ ἐπιούσης προελθόντες ἐκράτουν τῶν Σεγεστανῶν. ὁ οὖν Καῖσαρ ἐπὶ Δαλμάτας μετῄει, γένος ἕτερον Ἰλλυριῶν, Ταυλαντίοις ὅμορον.", "st": "3.24"}, {"sp": "N", "t": "οἱ Δαλμάται δ’ ἐξ οὗ τὰς ὑπὸ Γαβινίῳ πέντε τάξεις ἀνῃρήκεσαν καὶ τὰ σημεῖα εἰλήφεσαν, ἐπαρθέντες ἐπὶ τῷδε τὰ ὅπλα οὐκ ἀπετέθειντο ἔτεσιν ἤδη δέκα, ἀλλὰ καὶ τοῦ Καίσαρος ἐπιόντος αὐτοῖς συμμαχήσειν ἀλλήλοις συνετίθεντο. καὶ ἦσαν οἱ μαχιμώτατοι μυρίων καὶ δισχιλίων πλείους, ὧν στρατηγὸν Οὐέρσον αἱροῦνται. ὁ δὲ Πρωμόναν αὖθις, τὴν τῶν Λιβυρνῶν πόλιν, καταλαβὼν ὠχύρου, καὶ τἆλλα οὖσαν ἐκφυῶς ὀχυρωτάτην· ὄρειον γάρ ἐστι τὸ χωρίον, καὶ αὐτῷ περίκεινται λόφοι πάντοθεν ὀξεῖς οἷα πρίονες. ἐν μὲν δὴ τῇ πόλει τὸ πλέον ἦν, ἐν δὲ τοῖς λόφοις διέθηκεν Οὐέρσος φρούρια· καὶ πάντες ἐφεώρων τὰ Ῥωμαίων ἀφ’ ὑψηλοῦ. ὁ δὲ Καῖσαρ ἐς μὲν τὸ φανερὸν πάντας ἀπετείχιζε, λάθρᾳ δὲ τοὺς εὐτολμοτάτους ἔπεμπε ζητεῖν ἄνοδον ἐς τὸν ἀκρότατον τῶν λόφων. καὶ οἱ μέν, τῆς ὕλης αὐτοὺς ἐπικαλυπτούσης, νυκτὸς ἐμπίπτουσι τοῖς φύλαξιν εὐναζομένοις, καὶ κτείνουσιν αὐτούς, καὶ τῷ Καίσαρι κατέσεισαν ὑπὸ λύγῃ· ὁ δὲ τῆς τε πόλεως ἐς πεῖραν ᾔει τῷ πλέονι στρατῷ, καὶ ἐς τὸ εἰλημμένον ἄκρον ἑτέρους ἐφ’ ἑτέροις ἔπεμπεν, οἳ τοῖς ἄλλοις λόφοις ἐπικατῄεσαν. φόβος τε καὶ θόρυβος ἦν τοῖς βαρβάροις ὁμοῦ πᾶσιν ἐπιχειρουμένοις πάντοθεν· μάλιστα δὲ οἱ ἐν τοῖς λόφοις ἔδεισαν διὰ τὸ ἄνυδρον, μὴ τῶν διόδων ἀφαιρεθῶσιν. καὶ συμφεύγουσιν ἐς τὴν Πρωμόναν.", "st": "3.25"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ αὐτήν τε καὶ δύο λόφους, οἳ ἔτι ἐκρατοῦντο ὑπὸ τῶν πολεμίων, ὁμοῦ περιετείχιζε, τεσσαράκοντα σταδίων περίμετρον. κἀν τούτῳ Τέστιμον Δαλμάτην, στρατὸν ἕτερον ἄγοντα τοῖς ἐν Πρωμόνῃ συμμάχον, ὑπαντήσας ἐδίωκεν ἐς τὰ ὄρη, καὶ ἐφορῶντος ἔτι τοῦ Τεστίμου τὴν Πρωμόναν εἷλεν, οὔπω τῆς περιτειχίσεως τετελεσμένης. ἐκδραμόντων γὰρ τῶν ἔνδον καὶ συνελαυνομένων ὀξέως, οἱ Ῥωμαῖοι φεύγουσιν αὐτοῖς ἐς τὴν πόλιν συνεσέπεσον, καὶ τὸ τρίτον τούτων ἔνδον ἔκτειναν· οἱ λοιποὶ δ’ ἐς τὴν ἄκραν ἀνέδραμον. καὶ σπεῖρα Ῥωμαίων ἐφύλασσεν αὐτοὺς ἐπὶ τῶν πυλῶν. οἷς προσπίπτουσιν οἱ βάρβαροι νυκτὸς τετάρτης, καὶ ἐξέλιπεν ἡ σπεῖρα τὰς πύλας ὑπὸ δέους. ὁ δὲ Καῖσαρ τοὺς μὲν πολεμίους ἀνέκοψε τῆς ὁρμῆς, καὶ τῆς ἐπιούσης εἷλε παραδόντας ἑαυτούς· τὴν δὲ σπεῖραν ἣ τὸ φυλάκιον ἐξέλιπε διακληρώσας, ἐζημίωσε θανάτῳ τὸ δέκατον, καὶ λοχαγοὺς ἐπὶ τῷ δεκάτῳ δύο. καὶ τοῖς λοιποῖς ἐκέλευεν ἐκείνου τοῦ θέρους κριθὴν ἀντὶ σίτου τραφῆναι δίδοσθαι.", "st": "3.26"}, {"sp": "N", "t": "οὕτω μὲν ἑάλω Πρωμόνα, Τέστιμος δ’ ὁρῶν διεσκέδασε τὸν στρατὸν ἑαυτοῦ, φεύγειν ἄλλους ἀλλαχοῦ· ὅθεν αὐτοὺς οὐκ ἐδύναντο οἱ Ῥωμαῖοι διώκειν ἐς πολύ, τήν τε διαίρεσιν σφῶν τὴν ἐς πολλὰ δείσαντες, καὶ τὴν ἀπειρίαν τῶν ὁδῶν καὶ τὰ ἴχνη τῆς φυγῆς συγκεχυμένα. Συνόδιον δ’ αἱροῦσι πόλιν ἐν ἀρχῇ τῆς ὕλης, ἐν ᾗ τὸν Γαβινίου στρατὸν ἐνήδρευσαν οἱ Δαλμάται περὶ φάραγγι βαθείᾳ καὶ ἐπιμήκει καὶ μέσῃ δύο ὀρῶν, ἔνθα καὶ τὸν Καίσαρα ἐνήδρευον. ὁ δὲ τό τε Συνόδιον ἐνέπρησε, καὶ ἐς τὰ ὄρη περιπέμψας ἄνω στρατὸν ἑκατέρωθεν αὐτῷ συμπαρομαρτεῖν, αὐτὸς ᾔει διὰ τῆς φάραγγος, κόπτων τὴν ὕλην καὶ τὰς πόλεις αἱρῶν, καὶ πάντα ἐμπιπρὰς ὅσα κατὰ τὴν ὁδὸν ᾕρει. πολιορκουμένης δὲ πόλεως Σετουΐας, ἐπῄει τις αὐτοῖς συμμαχία βαρβάρων, ἣν ὁ Καῖσαρ ὑπαντήσας ἐκώλυσεν ἐσδραμεῖν ἐς τὴν Σετουΐαν. κἀν τῷ πόνῳ τῷδε ἐπλήγη λίθῳ τὸ γόνυ, καὶ ἐς πολλὰς ἡμέρας ἐθεραπεύετο. ῥαΐσας δὲ ἐς Ῥώμην ἐπανῆλθεν, ὑπατεύσων σὺν Οὐολκατίῳ Τύλλῳ, Στατίλιον Ταῦρον ἐς τὰ λοιπὰ τοῦ πολέμου καταλιπών.", "st": "3.27"}, {"sp": "N", "t": "νουμηνίᾳ δ’ ἔτους ἀρξάμενος ὑπατεύειν, καὶ τὴν ἀρχὴν αὐτῆς ἡμέρας παραδοὺς Αὐτρωνίῳ Παίτῳ, εὐθὺς ἐξέθορεν αὖθις ἐπὶ τοὺς Δαλμάτας, ἄρχων ἔτι τὴν τῶν τριῶν ἀρχήν· δύο γὰρ ἔλειπεν ἔτη τῇ δευτέρᾳ πενταετίᾳ τῆσδε τῆς ἀρχῆς, ἣν ἐπὶ τῇ προτέρᾳ σφίσιν αὐτοῖς ἐψηφίσαντο καὶ ὁ δῆμος ἐπεκεκυρώκει. οἱ Δαλμάται δ’ ἤδη κάμνοντες ὑπὸ λιμοῦ, τῶν ἔξωθεν ἀγορῶν ἀποκεκλεισμένοι, ἐρχομένῳ τῷ Καίσαρι ὑπήντων καὶ σφᾶς παρέδοσαν σὺν ἱκετηρίᾳ, ὅμηρά τε δόντες ἑπτακοσίους παῖδας, οὓς καὶ ὁ Καῖσαρ ᾔτει, καὶ τὰ Ῥωμαϊκὰ σημεῖα τὰ Γαβινίου· τὸν δὲ φόρον τὸν ἀπὸ Γαΐου Καίσαρος ἐκλειφθέντα ἀποδώσειν ὑποστάντες, εὐπειθεῖς ἐς τὸ ἔπειτα ἐγένοντο. τὰ σημεῖα δὲ ὁ Καῖσαρ ἀπέθηκεν ἐν τῇ στοᾷ τῇ Ὀκταουία λεγομένῃ. Δαλματῶν δ’ ἁλόντων καὶ Δερβανοὶ προσιόντα τὸν Καίσαρα συγγνώμην ᾔτουν σὺν ἱκετηρίᾳ, καὶ ὁμήρους ἔδοσαν, καὶ τοὺς ἐκλειφθέντας φόρους ὑπέστησαν ἀποδώσειν. τῶν δὲ … οἷς μὲν ὁ Καῖσαρ ἐπλησίασε, καὶ ὁμήρους ἐπὶ ταῖς συνθήκαις ἔδοσαν· ὅσοις δ’ οὐκ ἐπλησίασε διὰ νόσον, οὔτ’ ἔδοσαν οὔτε συνέθεντο. φαίνονται δὲ καὶ οἵδε ὕστερον ὑπαχθέντες.", "st": "3.28"}, {"sp": "N", "t": "οὕτω πᾶσαν ὁ Καῖσαρ τὴν Ἰλλυρίδα γῆν, ὅση τε ἀφειστήκει Ῥωμαίων, καὶ τὴν οὐ πρότερον ὑπακούσασαν αὐτοῖς, ἐκρατύνατο. καὶ αὐτῷ ἡ βουλὴ θρίαμβον Ἰλλυρικὸν ἔδωκε θριαμβεῦσαι, ὃν ἐθριάμβευσεν ὕστερον ἅμα τοῖς κατ Ἀντωνίου.", "st": "3.28"}, {"sp": "N", "t": "λοιποὶ δ’ εἰσὶ τῆς ὑπὸ Ῥωμαίων νομιζομένης Ἰλλυρίδος εἶναι πρὸ μὲν Παιόνων Ῥαιτοὶ καὶ Νωρικοί, μετὰ Παίονας δὲ Μυσοὶ ἕως ἐπὶ τὸν Εὔξεινον Πόντον. Ῥαιτοὺς μὲν οὖν καὶ Νωρικοὺς ἡγοῦμαι Γάιον Καίσαρα πολεμοῦντα Κελτοῖς ἐπιλαβεῖν, ἢ τὸν Σεβαστὸν χειρούμενον Παίονας· ἐν μέσῳ γάρ εἰσιν ἀμφοτέρων, καὶ οὐδὲν ηὗρον ἴδιον ἐς Ῥαιτοὺς ἢ Νωρικοὺς γενόμενον· ὅθεν μοι δοκοῦσι τοῖς ἑτέροις τῶν γειτόνων συναλῶναι.", "st": "3.29"}, {"sp": "N", "t": "Μυσοὺς δὲ Μᾶρκος μὲν Λεύκολλος, ὁ ἀδελφὸς Λικινίου Λευκόλλου τοῦ Μιθριδάτῃ πολεμήσαντος, κατέδραμε, καὶ ἐς τὸν ποταμὸν ἐμβαλών, ἔνθα εἰσὶν Ἑλληνίδες ἓξ πόλεις Μυσοῖς πάροικοι, Ἴστρος τε καὶ Διονυσόπολις καὶ Ὀδησσὸς καὶ Μεσημβρία, καὶ Καλλατίς, καὶ Ἀπολλωνία· ἐξ ἧς ἐς Ῥώμην μετήνεγκε τὸν μέγαν Ἀπόλλωνα τὸν ἀνακείμενον ἐν τῷ Παλατίῳ. καὶ πλεῖον οὐδὲν ηὗρον ἐπὶ τῆς Ῥωμαίων δημοκρατίας ἐς Μυσοὺς γενόμενον, οὐδ’ ἐς φόρου ὑπαχθέντας οὐδ’ ἐπὶ τοῦ Σεβαστοῦ· ὑπήχθησαν δὲ ὑπὸ Τιβέριου τοῦ μετὰ τὸν Σεβαστὸν τοῖς Ῥωμαίοις αὐτοκράτορος γενομένου. ἀλλά μοι τὰ μὲν πρὸ ἁλώσεως Αἰγύπτου πάντα ὑπὸ νεύματι τοῦ δήμου γενόμενα ἐφ’ ἑαυτῶν συγγέγραπται, ἃ δὲ μετ’ Αἴγυπτον οἱ αὐτοκράτορες οἵδε ἐκρατύναντο ἢ προσέλαβον, ὡς ἴδια αὐτῶν ἔργα, μετὰ τὰ κοινὰ εἴρηται· ἔνθα καὶ περὶ Μυσῶν ἐρῶ πλέονα. νῦν δ’, ἐπεὶ τοὺς Μυσούς τε οἱ Ῥωμαῖοι τῆς Ἰλλυρίδος ἡγοῦνται, καὶ τὸ σύγγραμμά μοι τοῦτο Ἰλλυρικόν ἐστιν, ὡς ἂν εἴη τὸ σύγγραμμα ἐντελές, ἐδόκει προειπεῖν ὅτι καὶ Μυσοὺς Λεύκολλός τε τῷ δήμῳ στρατηγῶν ἐπέδραμε καὶ Τιβέριος εἷλε κατὰ τὴν μόναρχον ἐξουσίαν.", "st": "3.30"}, {"sp": "HDR", "t": "Συριακή", "st": "4"}, {"sp": "N", "t": "Ἀντίοχος ὁ Σελεύκου τοῦ Ἀντιόχου, Σύρων καὶ Βαβυλωνίων καὶ ἑτέρων ἐθνῶν βασιλεύς, ἕκτος δὲ ἀπὸ Σελεύκου τοῦ μετ’ Ἀλέξανδρον Ἀσίας τῆς περὶ Εὐφράτην βεβασιλευκότος, ἐσβαλὼν ἐς Μηδίαν τε καὶ Παρθυηνὴν καὶ ἕτερα ἔθνη ἀφιστάμενα ἔτι πρὸ αὐτοῦ, καὶ πολλὰ καὶ μεγάλα δράσας, καὶ μέγας Ἀντίοχος ἀπὸ τοῦδε κληθείς, ἐπαιρόμενος τοῖς γεγονόσι καὶ τῇ δι’ αὐτὰ προσωνυμίᾳ, Συρίαν τε τὴν κοίλην καὶ Κιλικίας ἔστιν ἃ Πτολεμαίου τοῦ φιλοπάτορος, Αἰγύπτου βασιλέως ἔτι παιδὸς ὄντος, ἐπιδραμὼν περιέσπασε, καὶ μικρὸν οὐδὲν ἐνθυμούμενος Ἑλλησποντίους ἐπῄει καὶ Αἰολέας καὶ Ἴωνας ὡς οἷ προσήκοντας ἄρχοντι τῆς Ἀσίας, ὅτι καὶ πάλαι τῶν τῆς Ἀσίας βασιλέων ὑπήκουον. ἔς τε τὴν Εὐρώπην διαπλεύσας Θρᾴκην ὑπήγετο καὶ τὰ ἀπειθοῦντα ἐβιάζετο, Χερρόνησόν τε ὠχύρου, καὶ Λυσιμάχειαν ᾤκιζεν, ἣν Λυσίμαχος μὲν ὁ Θρᾴκης ἐπὶ Ἀλεξάνδρῳ βασιλεύσας ἔκτισεν ἐπιτείχισμα τοῖς Θρᾳξὶν εἶναι, οἱ Θρᾷκες δ’ ἀποθανόντος τοῦ Λυσιμάχου καθῃρήκεσαν. καὶ ὁ Ἀντίοχος συνῴκιζε, τούς τε φεύγοντας τῶν Λυσιμαχέων κατακαλῶν, καὶ εἴ τινες αὐτῶν αἰχμάλωτοι γεγονότες ἐδούλευον ὠνούμενος, καὶ ἑτέρους προσκαταλέγων, καὶ βοῦς καὶ πρόβατα καὶ σίδηρον ἐς γεωργίαν ἐπιδιδούς, καὶ οὐδὲν ἐλλείπων ἐς ταχεῖαν ἐπιτειχίσματος ὁρμήν· πάνυ γὰρ αὐτῷ τὸ χωρίον ἐφαίνετο λαμπρῶς ἔχειν ἐπὶ ὅλῃ Θρᾴκῃ, καὶ ταμιεῖον εὔκαιρον ἐς τὰ λοιπὰ ὧν ἐπενόει πάντων ἔσεσθαι.", "st": "4.1"}, {"sp": "N", "t": "ταῦτα δ’ αὐτῷ διαφορᾶς φανερᾶς καὶ πρὸς Ῥωμαίους ἦρξεν. ὡς γὰρ δὴ μετῄει τὰς τῇδε Ἑλληνίδας πόλεις, οἱ μὲν πλέονες αὐτῷ προσετίθεντο καὶ φρουρὰς ἐσεδέχοντο δέει τῷ τῆς ἁλώσεως, Σμυρναῖοι δὲ καὶ Λαμψακηνοὶ καὶ ἕτεροι ἔτι ἀντέχοντες ἐπρεσβεύοντο ἐς Φλαμινῖνον τὸν Ῥωμαίων στρατηγόν, ἄρτι Φιλίππου τοῦ Μακεδόνος μεγάλῃ μάχῃ περὶ Θετταλίαν κεκρατηκότα· ἐγίγνετο γὰρ δὴ καὶ τὰ Μακεδόνων καὶ τὰ Ἑλλήνων ἐπίμικτα ἀλλήλοις ἀνὰ μέρη καὶ χρόνους, ὥς μοι ἐν τῇ Ἑλληνικῇ γραφῇ δεδήλωται. καὶ γίγνονταί τινες Ἀντιόχῳ καὶ Φλαμινίνῳ διαπρεσβεύσεις τε ἐς ἀλλήλους καὶ ἀπόπειραι ἀτελεῖς. ἐκ πολλοῦ δὲ οἱ Ῥωμαῖοι καὶ ὁ Ἀντίοχος ὑπόπτως εἶχον ἀλλήλοις, οἱ μὲν οὐκ ἀτρεμήσειν ὑπολαμβάνοντες Ἀντίοχον ἐπαιρόμενον ἀρχῆς τε μεγέθει καὶ εὐπραξίας ἀκμῇ, ὁ δὲ Ῥωμαίους οἱ μόνους αὐξομένῳ μάλιστα ἐμποδὼν ἔσεσθαι, καὶ κωλύσειν ἐς τὴν Εὐρώπην περαιούμενον. οὐδενὸς δέ πω φανεροῦ γεγονότος αὐτοῖς ἐς ἔχθραν ἀφίκοντο πρέσβεις ἐς Ῥώμην παρὰ Πτολεμαίου τοῦ φιλοπάτορος, αἰτιωμένου Συρίαν τε καὶ Κιλικίαν Ἀντίοχον αὐτὸν ὑφελέσθαι. καὶ οἱ Ῥωμαῖοι τῆς ἀφορμῆς ἐπέβαινον ἄσμενοι, κατὰ καιρὸν σφίσι γενομένης, καὶ πρέσβεις ἐς τὸν Ἀντίοχον ἔστελλον, οἳ λόγῳ μὲν ἔμελλον συναλλάξειν Πτολεμαῖον Ἀντιόχῳ, ἔργῳ δὲ κατασκέψεσθαι τὴν ὁρμὴν Ἀντιόχου καὶ κωλύσειν ὅσα δύναιντο.", "st": "4.2"}, {"sp": "N", "t": "τούτων δὴ τῶν πρέσβεων Γναῖος ἡγούμενος ἠξίου τὸν Ἀντίοχον Πτολεμαίῳ μέν, ὄντι Ῥωμαίων φίλῳ, συγχωρεῖν ἄρχειν ὅσων ὁ πατὴρ αὐτῷ κατέλιπε, τὰς δ’ ἐν Ἀσίᾳ πόλεις, ὧν Φίλιππος ὁ Μακεδὼν ἦρχεν, αὐτονόμους ἐᾶν· οὐ γὰρ εἶναι δίκαιον Ἀντίοχον κρατεῖν ὧν Φίλιππον ἀφείλοντο Ῥωμαῖοι. ὅλως δ’ ἀπορεῖν ἔφη τί τοσοῦτον στόλον ὁ Ἀντίοχος καὶ τοσαύτην στρατιὰν ἄγων ἄνωθεν ἐκ Μήδων ἔλθοι τῆς Ἀσίας ἐπὶ θάλασσαν, ἔς τε τὴν Εὐρώπην ἐσβάλοι, καὶ πόλεις ἐν αὐτῇ κατασκευάζοιτο, καὶ Θρᾴκην ὑπάγοιτο, εἰ μὴ ταῦτά ἐστιν ἑτέρου πολέμου θεμέλια. ὁ δ’ ἀπεκρίνατο Θρᾴκην μέν, τῶν προγόνων αὑτοῦ γενομένην τε καὶ δι’ ἀσχολίας ἐκπεσοῦσαν, αὐτὸς ἐπὶ σχολῆς ὢν ἀναλαμβάνειν, καὶ Λυσιμάχειαν ἐγείρειν οἰκητήριον Σελεύκῳ τῷ παιδὶ εἶναι, τὰς δ’ ἐν Ἀσίᾳ πόλεις αὐτονόμους ἐάσειν, εἰ τὴν χάριν οὐ Ῥωμαίοις ἀλλ’ ἑαυτῷ μέλλοιεν ἕξειν. “Πτολεμαίῳ δ’,” ἔφη, “καὶ συγγενής εἰμι καὶ ὅσον οὔπω καὶ κηδεστὴς ἔσομαι, καὶ χάριν ὑμῖν αὐτὸν ὁμολογεῖν παρασκευάσω. ἀπορῶ δὲ κἀγὼ τίνι Ῥωμαῖοι δικαίῳ τὴν Ἀσίαν πολυπραγμονοῦσιν, ἐμοῦ τὴν Ἰταλίαν οὐ πολυπραγμονοῦντος.”", "st": "4.3"}, {"sp": "N", "t": "οὕτω μὲν ἀπ’ ἀλλήλων ἄπρακτοι διεκρίθησαν, ἀπορρηγνύντες ἤδη τὰς ἀπειλὰς ἐς τὸ φανερώτερον· λόγου δὲ καὶ δόξης ἐμπεσούσης ὅτι Πτολεμαῖος ὁ φιλοπάτωρ ἀποθάνοι, κατὰ σπουδὴν ὁ Ἀντίοχος ἀπῄει ὡς Αἴγυπτον ἔρημον ἄρχοντος ἁρπασόμενος. καὶ αὐτῷ κατὰ Ἔφεσον Ἀννίβας ὁ Καρχηδόνιος συμβάλλει, φεύγων τὴν πατρίδα δι’ ἐχθρῶν διαβολάς, οἳ Ῥωμαίοις αὐτὸν ἔφασκον εἶναι δύσερίν τε καὶ φιλοπόλεμον καὶ οὔποτε εἰρηνεύειν δυνάμενον. τότε δ’ ἦν ὅτε Καρχηδόνιοι Ῥωμαίοις ὑπήκουον ἔνσπονδοι. Ἀννίβαν μὲν δὴ διώνυμον ἐπὶ στρατηγίαις ὄντα ὁ Ἀντίοχος ὑπεδέχετο λαμπρῶς καὶ εἶχεν ἀμφ’ αὑτόν· περὶ δὲ τὴν Λυκίαν Πτολεμαῖον περιεῖναι μαθὼν Αἰγύπτου μὲν ἀπέγνω, Κύπρον δ’ ἐλπίσας αἱρήσειν ἀντὶ Αἰγύπτου διέπλει κατὰ τάχος ἐπ’ αὐτήν. χειμῶνι δ’ ἀμφὶ τὸν Σάρον ποταμὸν συμπεσών, καὶ πολλὰς τῶν νεῶν ἀποβαλών, ἐνίας δ’ αὐτοῖς ἀνδράσι καὶ φίλοις, ἐς Σελεύκειαν τῆς Συρίας κατέπλευσε, καὶ τὸν στόλον κατεσκεύαζε πεπονημένον. γάμους τε τῶν παίδων ἔθυεν, Ἀντιόχου καὶ Λαοδίκης, ἀλλήλοις συναρμόζων.", "st": "4.4"}, {"sp": "N", "t": "ἤδη δὲ τὸν πρὸς Ῥωμαίους πόλεμον ἐγνωκὼς ἀποκαλύπτειν, ἐπιγαμίαις τοὺς ἐγγὺς βασιλέας προκατελάμβανε, καὶ Πτολεμαίῳ μὲν ἐς Αἴγυπτον ἔστελλε Κλεοπάτραν τὴν Σύραν ἐπίκλησιν, προῖκα Συρίαν τὴν κοίλην ἐπιδιδούς, ἣν αὐτὸς ἀφῄρητο τοῦ Πτολεμαίου, θεραπεύων ἤδη τὸ μειράκιον, ἵν’ ἐν τῷ πολέμῳ τῷ πρὸς Ῥωμαίους ἀτρεμῇ· Ἀντιοχίδα δ’ ἔπεμπεν Ἀριαράθῃ τῷ Καππαδοκῶν βασιλεῖ, καὶ τὴν ἔτι λοιπὴν Εὐμένει τῷ Περγάμου βασιλεῖ. ὁ δέ (ἑώρα γὰρ αὐτὸν ἤδη Ῥωμαίοις τε πολεμησείοντα καὶ πρὸς τήνδε τὴν χρείαν τὸ κῆδος αὑτῷ συναπτόμενον) ἠρνήσατο, καὶ τοῖς ἀδελφοῖς Ἀττάλῳ τε καὶ Φιλεταίρῳ, θαυμάζουσιν ὅτι κῆδος βασιλέως τοσοῦδε καὶ γείτονος, αὐτοῦ τε κατάρχοντος καὶ δεομένου, παραιτοῖτο, ἐπεδείκνυ τὸν ἐσόμενον πόλεμον ἐν μὲν ἀρχῇ τι παρ’ ἀμφοῖν ἕξειν ἰσοπαλές, σὺν χρόνῳ δ’ ὑπεροίσειν τὰ Ῥωμαίων δι’ εὐψυχίαν καὶ ταλαιπωρίαν. “ἐγὼ δ’,” ἔφη, “Ῥωμαίων μὲν ἐπικρατούντων βεβαίως τῆς ἀρχῆς τῆς ἐμῆς ἄρξω, Ἀντιόχου δὲ νικῶντος ἐλπὶς μὲν ἀφαιρεθήσεσθαι πάντα πρὸς γείτονος, ἐλπὶς δὲ καὶ ἔχοντα βασιλεύσειν βασιλεύομενον ὑπ’ ἐκείνου.”", "st": "4.5"}, {"sp": "N", "t": "ὁ μὲν δὴ τοιοῖσδε λογισμοῖς τοὺς γάμους ἀπεώσατο, ὁ δ’ Ἀντίοχος αὖθις ἐφ’ Ἑλλησπόντου κατῄει, καὶ περιπλεύσας ἐς Χερρόνησον πολλὰ καὶ τότε τῆς Θρᾴκης ὑπήγετό τε καὶ κατεστρέφετο. Ἕλληνας δ’, ὅσοι τοῖς Θρᾳξὶν ὑπήκουον, ἠλευθέρου, καὶ Βυζαντίοις ἐχαρίζετο πολλὰ ὡς ἐπίκαιρον ἐπὶ τοῦ στόματος πόλιν ἔχουσιν. Γαλάτας τε δώροις καὶ καταπλήξει τῆς παρασκευῆς ἐς συμμαχίαν ὑπήγετο, ἀξιομάχους ἡγούμενος ἔσεσθαί οἱ διὰ τὰ μεγέθη τῶν σωμάτων. μετὰ δὲ τοῦτο ἐς Ἔφεσον κατῇρε, καὶ πρέσβεις ἐς Ῥώμην ἔπεμπε Λυσίαν τε καὶ Ἡγησιάνακτα καὶ Μένιππον, οἳ τῷ μὲν ἔργῳ τῆς βουλῆς ἀποπειράσειν ἔμελλον, τῷ λόγῳ δ’ ὁ Μένιππος ἔφη τὸν βασιλέα περὶ τὴν Ῥωμαίων φιλίαν ἐσπουδακότα, καὶ βουλόμενον αὐτοῖς εἶναι καὶ σύμμαχον ἂν ἀξιῶσι, θαυμάζειν ὅτι κελεύουσι τῶν ἐν Ἰωνίᾳ πόλεων ἀφίστασθαι, καὶ φόρους τισὶν ἀφιέναι, καὶ τῆς Ἀσίας ἔνια μὴ πολυπραγμονεῖν, καὶ Θρᾴκην ἐᾶν ἀεὶ τῶν προγόνων αὐτοῦ γενομένην· ἅπερ οὐ τοῖς φίλοις ἀλλὰ τοῖς ἡττημένοις τοὺς κεκρατηκότας ἐπικελεύειν. οἱ δὲ τῆς πρεσβείας συνιέντες ἐπὶ διαπείρᾳ σφῶν ἀφιγμένης, διὰ βραχέος ἀπεκρίναντο αὐτοῖς, ἐὰν Ἀντίοχος αὐτονόμους τοὺς Ἕλληνας ἐᾷ τοὺς ἐν Ἀσίᾳ καὶ τῆς Εὐρώπης ἀπέχηται, Ῥωμαίοις αὐτὸν ἔσεσθαι φίλον, ἂν ἐθέλῃ.", "st": "4.6"}, {"sp": "N", "t": "τοσάδε μὲν ἀπεκρίναντο Ῥωμαῖοι, καὶ τὰς αἰτίας ταῖς ἀποκρίσεσιν οὐκ ἐπέθεσαν· ὁ δ’ Ἀντίοχος ἐς πρώτην ἐπινοῶν τὴν Ἑλλάδα ἐσβαλεῖν, κἀκεῖθεν ἄρξασθαι τοῦ πρὸς Ῥωμαίους πολέμου, ὑπετίθετο τὴν γνώμην τῷ Καρχηδονίῳ Ἀννίβᾳ· ὁ δ’ ἔφη τὴν μὲν Ἑλλάδα ἐκ πολλοῦ τετρυμένην ἔργον εὐχείρωτον εἶναι, τοὺς δὲ πολέμους ἅπασι χαλεποὺς μὲν οἴκοι διὰ λιμὸν τὸν ἐπιγιγνόμενον, ἔξω δὲ κουφοτέρους· καὶ τὰ Ῥωμαίων οὔ ποτε Ἀντίοχον ἐν τῇ Ἑλλάδι καθαιρήσειν, ἀγορᾶς τε οἰκείας καὶ παρασκευῆς ἱκανῆς εὐπορούντων. ἐκέλευεν οὖν τι προλαβεῖν τῆς Ἰταλίας καὶ πολεμεῖν ἐκεῖθεν ὁρμώμενον, ἵνα Ῥωμαίοις ἀσθενέστερα ᾖ καὶ τὰ οἴκοι καὶ τὰ ἔξω. “ἔχω δ’ ἐμπείρως,” ἔφη, “τῆς Ἰταλίας, καὶ μυρίοις ἀνδράσι δύναμαι καταλαβεῖν αὐτῆς τὰ ἐπίκαιρα, ἔς τε Καρχηδόνα τοῖς φίλοις ἐπιστεῖλαι τὸν δῆμον ἐς ἀπόστασιν ἐγεῖραι, δυσφοροῦντα τέως ἐφ’ ἑαυτοῦ καὶ πρὸς Ῥωμαίους ἀπίστως ἔχοντα, τόλμης τε καὶ ἐλπίδος ἐμπλησόμενον, εἰ πύθοιντό με πορθοῦντᾳ τὴν Ἰταλίαν αὖθις.” ὁ δ’ ἄσμενος ἀκούσας τοῦ λόγου, καὶ μέγα, ὥσπερ ἦν, ἐς τὸν πόλεμον ἡγούμενος Καρχηδόνα προσλαβεῖν, αὐτίκα αὐτὸν ἐπιστέλλειν τοῖς φίλοις ἐκέλευεν.", "st": "4.7"}, {"sp": "N", "t": "ὁ δὲ οὐκ ἐπέστειλε μέν (οὐ γὰρ ἀσφαλὲς ἡγεῖτό πω, Ῥωμαίων τε πάντ’ ἀνερευνωμένων, καὶ τοῦ πολέμου μή πω φανεροῦ γεγονότος, καὶ πολλῶν οἱ διαφερομένων ἐν Καρχηδόνι, καὶ τῆς πολιτείας οὐδὲν βέβαιον οὐδ’ εὐσταθὲς ἐχούσης, ἃ καὶ μετ’ ὀλίγον ἀνέτρεψε τὴν Καρχηδόνα), Ἀρίστωνα δ’ ἔμπορον Τύριον ἐπὶ προφάσει τῆς ἐμπορίας ἔπεμπε πρὸς τοὺς φίλους, ἀξιῶν, ὅταν αὐτὸς ἐς τὴν Ἰταλίαν ἐμβάλῃ, τότε ἐκείνους τὴν Καρχηδόνα ἐς ἄμυναν ὧν ἐπεπόνθεσαν ἐγείρειν. καὶ ὁ μὲν Ἀρίστον οὕτως ἔπραξεν, οἱ δὲ τοῦ Ἀννίβου ἐχθροί, αἰσθόμενοι τῆς Ἀρίστωνος ἐπιδημίας, ἐθορύβουν ὡς ἐπὶ νεωτέροις ἔργοις, καὶ τὸν Ἀρίστωνα ἐζήτουν περιιόντες. ὁ δέ, ἵνα τὴν διαβολὴν μὴ ἐξαίρετον ἔχοιεν οἱ Ἀννίβου φίλοι, προύθηκε νυκτὸς λαθὼν γράμματα πρὸ τοῦ βουλευτηρίου, ὅτι πάντας ὁ Ἀννίβας τοὺς βουλευτὰς παρακαλοίη τῇ πατρίδι συνάρασθαι μετ’ Ἀντιόχου. καὶ τοῦτο πράξας ἀπέπλευσεν. ἅμα δ’ ἡμέρᾳ τὸ μὲν δέος ἐξῄρητο τῶν Ἀννίβου φίλων ἐκ τῆς Ἀρίστωνος ἐπινοίας, ὡς πρὸς ἅπασαν τὴν γερουσίαν ἀπεσταλμένου, ἡ δὲ πόλις ἐπεπλήρωτο θορύβου ποικίλου, δυσμενῶς μὲν ἔχουσα Ῥωμαίοις, λήσεσθαι δ’ οὐ προσδοκῶσα.", "st": "4.8"}, {"sp": "N", "t": "καὶ τὰ μὲν Καρχηδονίων ὧδε εἶχε, Ῥωμαίων δὲ πρέσβεις, ἕτεροί τε καὶ Σκιπίων ὁ Καρχηδονίους ἀφελόμενος τὴν ἡγεμονίαν, ἐς ὁμοίαν πεμφθέντες Ἀντιόχου τῆς τε γνώμης ἀπόπειραν καὶ τῆς παρασκευῆς κατάσκεψιν, ἐπεὶ τὸν βασιλέα ηὗρον οἰχόμενον ἐς Πισίδας, ἐν Ἐφέσῳ περιέμενον, ἔνθα συνῄεσαν θαμινὰ ἐς λόγους τῷ Ἀννίβᾳ, Καρχηδόνος τε σφίσιν ἔτι οὔσης ἐνσπόνδου καὶ οὔπω φανερῶς Ἀντιόχου πολεμίου, καταμεμφόμενοι τὸν Ἀννίβαν ὅτι τὴν πατρίδα φύγοι, Ῥωμαίων οὐδὲν οὔτε ἐς αὐτὸν οὔτε ἐς τοὺς ἄλλους Καρχηδονίους ἐπὶ ταῖς συνθήκαις ἁμαρτόντων. ἔπρασσον δὲ ταῦθ’, ὕποπτον ἐργαζόμενοι γενέσθαι τῷ βασιλεῖ τὸν Ἀννίβαν ἐκ τῆς συνεχοῦς σφῶν ὁμιλίας τε καὶ συνόδου. καὶ τοῦθ’ ὁ μὲν στρατηγικώτατος Ἀννίβας οὐχ ὑπενόησεν, ὁ δὲ βασιλεὺς πυθόμενος ὑπώπτευσε, καὶ ἀμβλύτερος ἦν τἀπὸ τοῦδε πιστεύειν ἔτι τῷ Ἀννίβᾳ· καὶ γάρ τι καὶ ζήλου προὐπῆν ἐς αὐτὸν ἤδη καὶ φθόνου, μὴ τῶν γιγνομένων τὸν ἔπαινον Ἀννίβας ἀποφέροιτο.", "st": "4.9"}, {"sp": "N", "t": "λέγεται δ’ ἐν ταῖσδε ταῖς διατριβαῖς ἐν τῷ γυμνασίῳ λεσχηνεῦσαί ποτε πρὸς ἀλλήλους Σκιπίωνα καὶ Ἀννίβαν περὶ στρατηγίας πολλῶν ἐφεστώτων, καὶ τοῦ Σκιπίωνος ἐρομένου τίς δοκοίη οἱ στρατηγὸς ἄριστος γενέσθαι, τὸν Ἀννίβαν εἰπεῖν, “ὁ Μακεδὼν Ἀλέξανδρος.” Σκιπίωνα δ’ ἡσυχάσαι μὲν ἐπὶ τῷδ’, ἐξιστάμενον ἄρα Ἀλεξανδρῳ, ἐπανερέσθαι δὲ τίς εἴη δεύτερος μετ’ Ἀλέξανδρον. καὶ τὸν φάναι, “Πύρρος ὁ Ἠπειρώτης,” τὴν ἀρετὴν ἄρα τὴν στρατηγικὴν ἐν τόλμῃ τιθέμενον· οὐ γὰρ ἔστιν εὑρεῖν μεγαλοτολμοτέρους τῶνδε τῶν βασιλέων. δακνόμενον δ’ ἤδη τὸν Σκιπίωνα ὅμως ἐπανερέσθαι ἔτι τίνι διδοίη τὰ τρίτα, ταχὺ γοῦν ἐλπίζοντα ἕξειν τὰ τρίτα. τὸν δέ, “ἐμαυτῷ,” φάναι· “νέος γὰρ ὢν ἔτι Ἰβηρίας τε ἐκράτησα, καὶ στρατῷ τὰ Ἄλπεια ὄρη μεθ’ Ἡρακλέα πρῶτος ὑπερῆλθον, ἔς τε τὴν Ἰταλίαν, ὑμῶν οὐδενός πω θαρροῦντος, ἐμβαλὼν τετρακόσια ἀνέστησα ἄστη, καὶ περὶ τῇ πόλει τὸν ἀγῶνα πολλάκις ὑμῖν ἐπέστησα, οὔτε μοι χρημάτων οὔτε στρατιᾶς ἐπιπεμπομένης ἐκ Καρχηδόνος.” ὡς δὲ αὐτὸν ὁ Σκιπίων εἶδεν ἀπομηκύνοντα τὴν σεμνολογίαν, ἔφη γελάσας, “ποῦ δ’ ἂν ἑαυτὸν ἔταττες, ὦ Ἀννίβα, μὴ νενικημένος ὑπ’ ἐμοῦ;” τὸν δέ φασιν, αἰσθανόμενον ἤδη τῆς ζηλοτυπίας, εἰπεῖν ὅτι ἔγωγε ἔταξα ἂν ἐμαυτὸν πρὸ Ἀλεξάνδρου. οὕτω μὲν ὁ Ἀννίβας ἐπέμεινέ τε τῇ σεμνολογίᾳ, καὶ τὸν Σκιπίωνα λαθὼν ἐθεράπευσεν ὡς καθελόντα τὸν ἀμεινονα Ἀλεξάνδρου·", "st": "4.10"}, {"sp": "N", "t": "διαλυομένης δὲ τῆς συνόδου Σκιπίωνα μὲν ὁ Ἀννίβας ἐπὶ ξένια ἐκάλει, Σκιπίων δὲ ἐλθεῖν ἂν ἔφη μάλα προθύμως, εἰ μὴ συνῆσθα νῦν Ἀντιόχῳ πρὸς Ῥωμαίους ὑπόπτως ἔχοντι. ὧδε μὲν ἐκεῖνοι, τῆς στρατηγίας ἀξίως, τὴν ἔχθραν ὡρίζοντο τοῖς πολέμοις, Φλαμινῖνος δ’ ἀνομοίως. ἡττηθέντος γὰρ ὕστερον Ἀντιόχου φεύγοντα τὸν Ἀννίβαν καὶ ἀλώμενον περὶ Βιθυνίαν, πρεσβεύων, ἐφ’ ἕτερα πρὸς Προυσίαν, οὔτε τι πρὸς τοῦ Ἀννίβου προπαθών, οὔτε Ῥωμαίων ἐντειλαμένων, οὔτε φοβερὸν ἔτι αὐτοῖς γενέσθαι δυνάμενον Καρχηδόνος κατεστραμμένης, ἔκτεινε διὰ τοῦ Προυσίου φαρμάκῳ, λεγόμενον μὲν ἐσχηκέναι ποτὲ χρησμὸν ὧδε ἔχοντα “Λίβυσσα κρύψει βῶλος Ἀννίβου δέμας,” καὶ οἰόμενον ἐν Λιβύῃ τεθνήξεσθαι, ποταμὸς δ’ ἔστι Λίβυσσος ἐν τῇ Βιθυνίᾳ, καὶ πεδίον ἐκ τοῦ ποταμοῦ Λίβυσσα. καὶ τάδε μὲν ἐς ὑπόμνημα τῆς Ἀννίβου καὶ Σκιπίωνος μεγαλονοίας καὶ Φλαμινίνου σμικρότητος παρεθέμην.", "st": "4.11"}, {"sp": "N", "t": "ὁ δ’ Ἀντίοχος ἐκ Πισιδῶν ἐς τὴν Ἔφεσον ἐπανῄει, καὶ χρηματίσας τοῖς Ῥωμαίων πρέσβεσι Ῥοδίους μὲν καὶ Βυζαντίους καὶ Κυζικηνούς, καὶ ὅσοι ἄλλοι περὶ τὴν Ἀσίαν εἰσὶν Ἕλληνες, αὐτονόμους ἐπηγγείλατο ἐάσειν, εἰ γίγνοιντο αὑτῷ συνθῆκαι πρὸς Ῥωμαίους, Αἰολέας δὲ καὶ Ἴωνας οὐ συνεχώρει ὡς ἐκ πολλοῦ καὶ τοῖς βαρβάροις βασιλεῦσι τῆς Ἀσίας εἰθισμένους ὑπακούειν. οἱ μὲν δὴ Ῥωμαίων πρέσβεις ἐς οὐδὲν αὐτῷ συμβαίνοντες (οὐ γὰρ ἐπ’ ἔργῳ συμβάσεων ἐληλύθεσαν ἀλλ’ ἐς ἀπόπειραν) ᾤχοντο ἐς Ῥώμην· Ἀντιόχῳ δ’ ἧκον Αἰτωλῶν πρέσβεις, ὧν Θόας ἦρχεν, αὐτοκράτορά τε στρατηγὸν Αἰτωλῶν Ἀντίοχον ἀποφαίνοντες, καὶ διαπλεῖν ἐς τὴν Ἑλλάδα ἤδη παρακαλοῦντες ὡς ἐπὶ ἔργον ἕτοιμον. οὐδὲ εἴων ἀναμένειν τὴν στρατιὰν ἀπὸ τῆς Ἀσίας τῆς ἄνω κατιοῦσαν, ἀλλὰ τὰ Αἰτωλῶν ὑπερεπαίροντες, καὶ Λακεδαιμονίους ἐπαγγελλόμενοι σφίσι καὶ Φίλιππον ἐπὶ τοῖς Λακεδαιμονίοις τὸν Μακεδόνα, Ῥωμαίοις μηνίοντα, συμμαχήσειν, ἐπέσπερχον ἐς τὴν διάβασιν. ὁ δ’ ἠρεθίζετο μάλα κουφόνως, καὶ οὐδὲ τοῦ παιδὸς αὐτῷ προσαγγελθέντος ἐν Συρίᾳ τεθνάναι τῆς ὁρμῆς τι ἐνδούς, διέπλει μετὰ μυρίων ὧν τότε εἶχε μόνων ἐς Εὔβοιαν. καὶ τήνδε μὲν αὐτὸς παρεστήσατο ἅπασαν, ἐνδοῦσαν ὑπὸ ἐκπλήξεως· Μικιθίων δέ, αὐτοῦ στρατηγός, τοῖς περὶ Δήλιον Ῥωμαίοις ἐπιπεσὼν (ἱερὸν δ’ ἐστὶ τὸ χωρίον Ἀπόλλωνος) τοὺς μὲν αὐτῶν ἔκτεινε, τοὺς δ’ ἐζώγρησεν.", "st": "4.12"}, {"sp": "N", "t": "Ἀμύνανδρός τε, ὁ Ἀθαμάνων βασιλεύς, ἐς συμμαχίαν Ἀντιόχῳ συνῆλθε διὰ τοιᾶσδε προφάσεως. τῶν τις Μακεδόνων Ἀλέξανδρος, ἐν Μεγάλῃ πόλει τραφεὶς καὶ τῆς αὐτόθι πολιτείας ἀξιωθείς, ἐτερατεύετο γένος Ἀλεξάνδρῳ τῷ Φιλίππου προσήκειν, γενομένους τέ οἱ παῖδας ὠνόμασεν, ἐς πίστιν ὧν ἐλογοποίει, Φίλιππόν τε καὶ Ἀλέξανδρον καὶ Ἀπάμαν, ἣν Ἀμυνάνδρῳ πρὸς γάμον ἠγγύησεν. ἀγαγὼν δ’ αὐτὴν Φίλιππος ὁ ἀδελφὸς ἐς τὸν γάμον, ἐπεὶ τὸν Ἀμύνανδρον εἶδεν ἀσθενῆ καὶ πραγμάτων ἄπειρον, παρέμενε, τὴν ἀρχὴν διὰ τὸ κῆδος διοικῶν. τοῦτον οὖν τὸν Φίλιππον ὁ Ἀντίοχος τότε ἐπελπίζων ἐς τὴν Μακεδόνων ἀρχὴν ὡς οἰκείαν οἱ κατάξειν, προσέλαβε τοὺς Ἀθαμᾶνας ἐς τὴν συμμαχίαν, ἐπὶ δ’ αὐτοῖς καὶ Θηβαίους, αὐτὸς ἐς Θήβας παρελθών τε καὶ δημηγορήσας.", "st": "4.13"}, {"sp": "N", "t": "ὁ μὲν δὴ Θηβαίοις τε καὶ Ἀμυνάνδρῳ καὶ Αἰτωλοῖς ἐπὶ τοσῷδε πολέμῳ μάλα ματαίως ἐθάρρει, καὶ ἐς Θεσσαλίαν ἐσκόπει πότερον εὐθὺς ἢ μετὰ χειμῶνα δέοι στρατεύειν· Ἀννίβαν δ’ ἐπὶ τῇ σκέψει τῇδε ἡσυχάζοντα ἐκέλευε γνώμην πρῶτον ἐσενεγκεῖν.", "st": "4.13"}, {"sp": "N", "t": "ὁ δ’ ἔφη, “Θεσσαλοὺς μὲν οὐ δυσχερές, εἴτε νῦν εἴτε μετὰ χειμῶνα ἐθέλοις, ὑπάγεσθαι. τὸ γὰρ ἔθνος ἐκ πολλοῦ πεπονηκὸς ἔς τε σὲ νῦν καὶ ἐς Ῥωμαίους αὖ, εἴ τι γίγνοιτο νεώτερον, μεταβαλεῖται. ἤλθομεν δ’ ἄνευ τῆς οἰκείας δυνάμεως, Αἰτωλοῖς ἐπάγουσι πεισθέντες ὅτι καὶ Λακεδαιμόνιοι καὶ Φίλιππος ἡμῖν συμμαχήσουσιν· ὧν Λακεδαιμονίους μὲν καὶ πολεμεῖν ἡμῖν ἀκούω μετ’ Ἀχαιῶν, Φίλιππον δὲ οὐχ ὁρῶ σοι παρόντα, δυνατὸν ἐν τῷδε τῷ πολέμῳ ῥοπήν, ὁποτέρωσε προσθοῖτο, ποιῆσαι. τῆς δὲ γνώμης ἔχομαι τῆς αὐτῆς, τὴν στρατιὰν ἀπὸ τῆς Ἀσίας καλεῖν ὅτι τάχιστα, καὶ μὴ ἐν Ἀμυνάνδρῳ καὶ Αἰτωλοῖς τὰς ἐλπίδας ἔχειν, ὅταν δ’ ἀφίκηται, τὴν Ἰταλίαν πορθεῖν, ἵνα τοῖς οἰκείοις κακοῖς περισπώμενοι τὰ σὰ λυπῶσιν ἥκιστα, καὶ περὶ τῶν σφετέρων δεδιότες μηδαμοῦ προΐωσιν. ὁ δὲ τρόπος οὐκέθ’ ὅμοιος ᾧ προύλεγον, ἀλλὰ χρὴ τὸ μὲν ἥμισυ τῶν νεῶν τὰ παράλια τῆς Ἰταλίας πορθεῖν, τὸ δὲ ἥμισυ ναυλοχεῖν ἐφεδρεῦον ἐς τὰ συμφερόμενα, αὐτὸν δὲ δὲ τῷ πεζῷ παντὶ προκαθήμενον τῆς Ἑλλάδος, ἀγχοῦ τῆς Ἰταλίας, δόξαν ἐμποιεῖν ἐσβολῆς, καὶ εἰ δύναιό ποτε, καὶ ἐσβαλεῖν. Φίλιππον δὲ πειρᾶσθαι μὲν προσάγεσθαι μηχανῇ πάσῃ, πλεῖστον ἐς ἑκατέρους ἐν τῷδε τῷ πολέμῳ δυνάμενον· ἢν δ’ ἀπειθῇ, τὸν σὸν υἱὸν αὐτῷ Σέλευκον ἐπιπέμπειν διὰ Θρᾴκης, ἵνα καὶ ὅδε περισπώμενος οἰκείοις κακοῖς μηδὲν ᾖ τοῖς πολεμίοις χρήσιμος.”", "st": "4.14"}, {"sp": "N", "t": "τοσάδε μὲν ὁ Ἀννίβας εἶπε, καὶ ἦν ἄριστα πάντων· ὑπὸ δὲ φθόνου τῆς τε δόξης αὐτοῦ καὶ συνέσεως οἵ τε ἄλλοι καὶ αὐτὸς οὐχ ἧσσον ὁ βασιλεύς, ἵνα μὴ δοκοίη σφῶν ὁ Ἀννίβας τῇ στρατηγίᾳ προφέρειν, μηδὲ ἡ δόξα τῶν ἐσομένων ἐκείνου γένοιτο, μεθῆκαν ἅπαντα, πλὴν ὅτι Πολυξενίδας ἐπὶ τὴν στρατιὰν ἐς τὴν Ἀσίαν ἐπέμφθη.", "st": "4.14"}, {"sp": "N", "t": "Ῥωμαῖοι δ’ ἐπεὶ τῆς ἐσβολῆς τῆς ἐς τὴν Ἑλλάδα Ἀντιόχου καὶ τῶν ἐπὶ Δηλίου Ῥωμαίων ἀναιρέσεώς τε καὶ αἰχμαλωσίας ἐπύθοντο, πολεμεῖν ἐψηφίσαντο. οὕτω μὲν ὁ Ἀντιόχου τε καὶ Ῥωμαίων πόλεμος, ἐκ πολλοῦ δι’ ὑπονοίας ἀλλήλοις γενόμενος, τότε πρῶτον ἀπερρήγνυτο ἐς ἔργον· οἷα δ’ Ἀντιόχου τῆς τε Ἀσίας τῆς ἄνω πολλῶν καὶ μεγάλων ἐθνῶν καὶ τῆς ἐπὶ θαλάσσῃ, χωρὶς ὀλίγων, ὅλης ἐπικρατοῦντος, ἔς τε τὴν Εὐρώπην διαβεβηκότος ἤδη, καὶ δόξαν ἐπίφοβον καὶ παρασκευὴν ἱκανὴν ἔχοντος, πολλά τε ἄλλα καθ’ ἑτέρων ἐξειργασμένου λαμπρά, δι’ ἃ καὶ μέγας ἦν ἐπώνυμον αὐτῷ, τὸν πόλεμον οἱ Ῥωμαῖοι χρόνιον σφίσι καὶ μέγαν ἔσεσθαι προσεδόκων. φίλιππόν τε τὸν Μακεδόνα δι’ ὑποψίας εἶχον, ἄρτι ὑπὸ σφῶν καταπεπολεμημένον, καὶ Καρχηδονίους, μὴ οὐ πιστοὶ σφίσιν ὦσιν ἐπὶ ταῖς συνθήκαις, Ἀννίβου συνόντος Ἀντιόχῳ. τούς τε ἄλλους σφῶν ὑπηκόους ὑπονοοῦντες, μὴ καὶ παρὰ τούτων τι νεώτερον ἐς τὴν Ἀντιόχου δόξαν γένοιτο, στρατιὰν ἐς ἅπαντας, ἐφεδρεύειν εἰρηνικῶς αὐτοῖς, καὶ στρατηγοὺς ἐπὶ τῇ στρατιᾷ, περιέπεμπον, οὓς αὐτοὶ καλοῦσιν ἑξαπελέκεας, ὅτι τῶν ὑπάτων δυώδεκα πελέκεσι καὶ δυώδεκα ῥάβδοις, ὥσπερ οἱ πάλαι βασιλεῖς, χρωμένων, τὸ ἥμισυ τῆς ἀξιώσεως ἔστι τοῖσδε τοῖς στρατηγοῖς καὶ τὰ ἡμίσεα παράσημα. ὡς δ’ ἐν μεγάλῳ φόβῳ, καὶ περὶ τῆς Ἰταλίας ἐδείμαινον, μὴ οὐδ’ αὐτὴ σφίσιν ᾖ πιστὴ ἢ βέβαιος ἐπ’ Ἀντιόχῳ. πεζὸν δὴ πολὺν ἐς Τάραντα διέπεμπον, ἐφεδρεύειν τοῖς ἐπιοῦσι, καὶ νεῶν στόλος τὴν παράλιον περιέπλει. τοσόσδε φόβος ἦν Ἀντιόχου τὰ πρῶτα. ὡς δὲ αὐτοῖς τὰ ἐς τὴν ἀρχὴν συνετετάχατο πάντα, ἐπ’ αὐτὸν Ἀντίοχον ἤδη κατέλεγον ἀπὸ μὲν σφῶν αὐτῶν ἐς δισμυρίους ἄνδρος, ἀπὸ δὲ τῶν συμμάχων τὸ διπλάσιον, ὡς ἅμα τῷ ἦρι τὸν Ἰόνιον διαβαλοῦντες.", "st": "4.15"}, {"sp": "N", "t": "καὶ οἱ μὲν τὸν χειμῶνα ὅλον ἐν τούτῳ παρασκευῆς ἦσαν, ὁ δ’ Ἀντίοχος ἤλαυνεν ἐπὶ Θετταλούς, καὶ γενόμενος ἐν Κυνὸς κεφαλαῖς, ἔνθα τὸ πταῖσμα τοῖς Μακεδόσιν ὑπὸ Ῥωμαίων ἐγεγένητο, τὰ λείπανα τῶν τότε πεσόντων ἄταφα ἔτι ὄντα μεγαλοπρεπῶς ἔθαπτε, δημοκοπῶν ἐς Μακεδόνας, καὶ Φίλιππον αὐτοῖς διαβάλλων οὐ θάψαντα τοὺς ὑπὲρ αὐτοῦ πεσόντας. ὧν πυθόμενος ὁ Φίλιππος, ἐνδοιάζων ἔτι καὶ περισκοπῶν ὁποτέρωσε προσθοῖτο, αὐτίκα εἵλετο τὰ Ῥωμαίων, Βαίβιόν τε στρατηγὸν αὐτῶν, ἄρχοντά τινος πλησίον στρατοῦ, καλέσας ἐλθεῖν ἔς τι χωρίον, πίστεις αὖθις ἐδίδου Ῥωμαίοις ἀδόλως συμμαχήσειν κατ’ Αντιόχου. ἐφ’ οἷς αὐτὸν ὁ Βαίβιος ἐπῄνει, καὶ θαρρήσας αὐτίκα ἔπεμπε διὰ τῆς Μακεδονίας Ἄππιον Κλαύδιον μετὰ δισχιλίων πεζῶν ἐς Θεσσαλίαν. καὶ ὁ Ἄππιος ἀπὸ τῶν Τεμπῶν Ἀντίοχον Λαρίσῃ παρακαθ ήμενον ἰδὼν πῦρ πολὺ ἤγειρεν, ἐπικρύπτων τὴν ὀλιγότητα. καὶ ὁ Ἀντίοχος, ὡς Βαιβίου καὶ Φιλίππου παρόντων διαταραχθείς, ἐξέλιπε τὴν πολιορκίαν, πρόφασιν τὸν χειμῶνα ποιούμενος, καὶ ἐς Χαλκίδα παρῆλθεν, ἔνθα κόρης εὐπρεποῦς ἔρωτι ἁλούς, ὑπὲρ ἔτη πεντήκοντα γεγονὼς καὶ τοσόνδε πόλεμον διαφέρων, ἔθυε γάμους καὶ πανηγύρεις ἦγε, καὶ τὴν δύναμιν ἐς πᾶσαν ἀργίαν καὶ τρυφὴν ἐπὶ τὸν χειμῶνα ὅλον ἀνῆκεν. ἀρχομένου δ’ ἦρος ἐμβαλὼν ἐς Ἀκαρνανίαν ᾔσθετο μὲν τῆς ἀργίας τοῦ στρατοῦ δυσέργου πρὸς ἅπαντα ὄντος, καὶ τότε τῶν γάμων αὐτῷ καὶ τῆς πανηγύρεως μετέμελεν· ὑπαγαγόμενος δ’ ὅμως τινὰ τῆς Ἀκαρνανίας, καὶ τὰ λοιπὰ πολιορκῶν, ἐπεὶ τάχιστα Ῥωμαίους ἐπύθετο περᾶν τὸν Ἰόνιον, ἐς Χαλκίδα ἀνεζεύγνυ.", "st": "4.16"}, {"sp": "N", "t": "Ῥωμαῖοι δ’ ὑπὸ σπουδῆς τοῖς τότε ἑτοίμοις ἱππεῦσι δισχιλίοις καὶ πεζοῖς δισμυρίοις καὶ ἐλέφασί τισιν, ἡγουμένου σφῶν Ἀκιλίου Μανίου Γλαβρίωνος, ἐς Ἀπολλωνίαν ἐκ Βρεντεσίου διαβαλόντες ἐπὶ Θεσσαλίας ἐβάδιζον καὶ τὰς πόλεις ἐξέλυον τῶν πολιορκιῶν, ἐν ὅσαις δ’ ἦσαν ἤδη Ἀθαμάνων φρουραί, τὰς φρουρὰς ἐξέβαλλον. καὶ τὸν Μεγαλοπολίτην Φίλιππον αἰχμάλωτον ἔλαβον, ἐλπίζοντα ἔτι τὴν Μακεδόνων ἀρχήν. εἷλον δὲ καὶ τῶν Ἀντιοχείων ἐς τρισχιλίους. ἅμα δὲ ταῦτα ὁ Μάνιος εἰργάζετο, καὶ ὁ Φίλιππος ἐς Ἀθαμανίαν ἐμβαλὼν πᾶσαν αὐτὴν ὑπήκοον ἔλαβεν, Ἀμυνάνδρου φυγόντος ἐς Ἀμβρακίαν. ὧν ὁ Ἀντίοχος αἰσθανόμενός τε, καὶ τὴν ὀξύτητα τῶν γιγνομένων καταπλαγείς, ἔδεισεν ὡς ἐπὶ αἰφνιδίῳ καὶ ταχείᾳ μεταβολῇ, καὶ τῆς εὐβουλίας Ἀννίβου τότε ᾔσθετο, ἔς τε τὴν Ἀσίαν ἄλλους ἐπ’ ἄλλοις ἔπεμπεν ἐπισπέρχειν Πολυξενίδαν ἐς τὴν διάβασιν, αὐτὸς δ’ ὅσους εἶχε, πανταχόθεν συνεκάλει. γενομένων δ’ αὐτῷ τῶν μὲν οἰκείων πεζῶν μυρίων καὶ ἱππέων πεντακοσίων, ἐπὶ δὲ τούτοις καὶ τινῶν συμμάχων, Θερμοπύλας κατέλαβεν ὡς τὴν δυσχωρίαν προβαλούμενος τοῖς πολεμίοις καὶ τὸν στρατὸν ἐκ τῆς Ἀσίας ἀναμενῶν. δίοδος δ’ ἐστὶν αἱ Θερμοπύλαι στενὴ καὶ ἐπιμήκης, καὶ αὐτὴν περιέχει τῇ μὲν θάλασσα τραχεῖα καὶ ἀλίμενος, τῇ δὲ ἕλος ἄβατόν τε καὶ βαραθρῶδες. κορυφαί τε εἰσὶν ἐν αὐτῇ δύο ὀρῶν ἀπόκρημνοι, καὶ τούτων μὲν Τειχιοῦντα καλοῦσι τὴν δὲ Καλλίδρομον. ἔχει δὲ ὁ τόπος θερμῶν ὑδάτων πηγάς, καὶ Θερμοπύλαι ἀπὸ τοῦδ’ ἐπικλῄζονται.", "st": "4.17"}, {"sp": "N", "t": "τεῖχος οὖν ἐνταῦθα διπλοῦν ὁ Ἀντίοχος ᾠκοδομήσατο, καὶ τὰς μηχανὰς ἐπὶ τὸ τεῖχος ἐπέθηκεν. ἔς τε τὰς κορυφὰς τῶν ὀρῶν Αἰτωλοὺς ἀνέπεμψε, μή τις λάθοι κατὰ τὴν λεγομένην ἀτραπὸν περιελθών, ᾗ δὴ καὶ Λακεδαιμονίοις τοῖς ἀμφὶ Λεωνίδαν Ξέρξης ἐπέθετο, ἀφυλάκτων τότε τῶν ὀρῶν ὄντων. Αἰτωλοὶ δὲ χιλίους μὲν ἑκατέρῳ τῶνδε τῶν ἄκρων ἐπέστησαν, τοῖς δὲ λοιποῖς ἐστρατοπέδευον ἐφ’ ἑαυτῶν περὶ πόλιν Ἡράκλειαν. ὁ δὲ Μάνιος ἐπεὶ κατεῖδε τὴν τῶν πολεμίων παρασκευήν, σημεῖον ἔδωκεν ἐς ἕω μάχης· καὶ δύο τῶν χιλιάρχων, Μᾶρκον Κάτωνα καὶ Λεύκιον Οὐαλέριον, ἐκέλευσε νυκτός, ἐπιλεξαμένους ἑκάτερον ὁπόσους ἐθέλοι, τὰ ὄρη περιελθεῖν καὶ τοὺς Αἰτωλοὺς ἀπὸ τῶν ἄκρων, ὅπῃ δύναιντο, βιάσασθαι. τούτων ὁ μὲν Λεύκιος ἀπεκρούσθη τοῦ Τειχιοῦντος, ἀγαθῶν ἐνταῦθα τῶν Αἰτωλῶν γενομένων· ὁ δὲ Κάτων τῷ Καλλιδρόμῳ παραστρατοπεδεύσας, κοιμωμένοις ἔτι τοῖς ἐχθροῖς ἐπέπεσε περὶ ἐσχάτην φυλακήν, καὶ πολὺς ἀμφ’ αὐτὸν ἐγίγνετο ἀγών, βιαζόμενον ἐς ὑψηλὰ καὶ ἀπόκρημνα κωλυόντων τῶν πολεμίων. ἤδη δὲ καὶ Μάνιος ἐπῆγε τὴν στρατιὰν Ἀντιόχῳ κατὰ μέτωπον, ἐς λόχους ὀρθίους διῃρημένην· ὧδε γὰρ μόνως ἐν στενοῖς ἐδύνατο. καὶ ὁ βασιλεὺς τοὺς μὲν ψιλοὺς καὶ πελταστὰς προμάχεσθαι τῆς φάλαγγος ἐκέλευσεν, αὐτὴν δ’ ἔστησε πρὸ τοῦ στρατοπέδου, ἐπὶ δεξιὰ δ’ αὐτῆς τοὺς σφενδονήτας καὶ τοξότας ἐπὶ τῶν ὑπωρειῶν, τοὺς δ’ ἐλέφαντας ἐν ἀριστερᾷ, καὶ τὸ στῖφος ὃ μετ’ αὐτῶν ἀεὶ συνετάσσετο, παρὰ τῇ θαλάσσῃ.", "st": "4.18"}, {"sp": "N", "t": "γενομένης δ’ ἐν χερσὶ τῆς μάχης, τὰ μὲν πρῶτα τὸν Μάνιον οἱ ψιλοὶ πανταχόθεν περιτρέχοντες ἐλύπουν· ἐπεὶ δὲ αὐτοὺς φιλοπόνως δεχόμενός τε καὶ ἀναχωρῶν καὶ αὖθις ἐπιὼν ἐτρέψατο, τοὺς μὲν ψιλοὺς ἡ φάλαγξ ἡ τῶν Μακεδόνων διαστᾶσα ἐς αὑτὴν ἐδέξατο καὶ συνελθοῦσα ἐκάλυψε, καὶ τὰς σαρίσσας ἐν τάξει πυκνὰς προὐβάλοντο, ᾧ δὴ μάλιστα οἱ Μακεδόνες ἐξ Ἀλεξάνδρου καὶ Φιλίππου κατεπλήσσοντο τοὺς πολεμίους, ἀντίοις δόρασι πολλοῖς καὶ μακροῖς οὐ τολμῶντας πελάζειν. αἰφνίδιον δ’ ὤφθη τῶν Αἰτωλῶν ἐκ τοῦ Καλλιδρόμου φυγὴ καὶ βοή, καθαλλομένων ἐς τὸ Ἀντιόχου στρατόπεδον. τὸ μὲν δὴ πρῶτον ἑκατέροις ἄγνοιά τε τοῦ γιγνομένου καὶ θόρυβος ἦν ὡς ἐν ἀγνοίᾳ· ὡς δὲ ὁ Κάτων ἐπεφαίνετο διώκων αὐτοὺς μετὰ πολλῆς βοῆς, καὶ ὑπὲρ τὸ στρατόπεδον ἐγίγνετο ἤδη τὸ Ἀντιόχου, ἔδεισαν οἱ τοῦ βασιλέως, περί τε τῆς Ῥωμαίων μάχης ἐπιφόβως ἐκ πολλοῦ πυνθανόμενοι, καὶ σφᾶς εἰδότες ὑπὸ ἀργίας καὶ τρυφῆς δι’ ὅλου τοῦ χειμῶνος ἐς δυσεργίαν διεφθαρμένους. τούς τε σὺν τῷ Κάτωνι σαφῶς μὲν οὐ καθορῶντες ὁπόσοι τινὲς εἶεν ὑπὸ δὲ τοῦ φόβου πλείους νομίζοντες εἶναι, καὶ περὶ τῷ στρατοπέδῳ δείσαντες, ἀκόσμως ἐς αὐτὸ κατέφυγον ὡς ἀπ’ αὐτοῦ τοὺς πολεμίους ἀμυνούμενοι. Ῥωμαῖοι δ’ αὐτοῖς παραθέοντες συνεσέπεσον ἐς τὸ στρατόπεδον, καὶ ἦν ἄλλη φυγὴ τῶν Ἀντιοχείων ἐκεῖθεν ἄκοσμος. ὁ δὲ Μάνιος μέχρι μὲν ἐπὶ Σκάρφειαν ἐδίωκαν αὐτοὺς κτείνων τε καὶ ζωγρῶν, ἀπὸ δὲ τῆς Σκαρφείας ἐπανιὼν διήρπαζε τὸ στρατόπεδον τοῦ βασιλέως καὶ τοὺς Αἰτωλοὺς ἐπιδραμόντας τῷ Ῥωμαίων χάρακι παρὰ τὴν ἀπουσίαν αὐτῶν ἐξήλασεν ἐπιφανείς.", "st": "4.19"}, {"sp": "N", "t": "ἀπέθανον δ’ ἐν τῇ μάχῃ καὶ τῇ διώξει Ῥωμαίων μὲν ἀμφὶ τοὺς διακοσίους, Ἀντιόχου δέ, σὺν τοῖς ληφθεῖσιν, ἀμφὶ τοὺς μυρίους. αὐτὸς δ’ ὁ βασιλεὺς ἀπὸ μὲν τῆς πρώτης τροπῆς μετὰ πεντακοσίων ἱππέων ἐς Ἐλάτειαν ἀμεταστρεπτὶ διέδραμεν, ἀπὸ δ’ Ἐλατείας ἐς Χαλκίδα καὶ ἐς Ἔφεσον μετ’ Εὐβοίας τῆς νεογάμου (τοῦτο γὰρ αὐτὴν ὠνόμαζεν) ἐπὶ τῶν νεῶν ἔφυγεν, οὐδὲ τούτων ἁπασῶν· ἀγορὰν γάρ τινας αὐτῶν διαφερούσας ὁ Ῥωμαίων ναύαρχος ἐπαναχθεὶς διεφθάρκει. οἱ δ’ ἐν ἄστει Ῥωμαῖοι τῆς νίκης πυθόμενοι, ταχείας τε οὕτω σφίσι καὶ εὐχεροῦς φανείσης, ἔθυον, ἐκ φοβερᾶς τῆς Ἀντιόχου δόξης τὴν πρώτην πεῖραν ἀσπασάμενοι. φίλιππόν τε τῆς συμμαχίας ἀμειβόμενοι, τὸν υἱὸν αὐτῷ Δημήτριον, ὁμηρεύοντα ἔτι παρὰ σφίσιν, ἔπεμψαν.", "st": "4.20"}, {"sp": "N", "t": "καὶ τάδε μὲν ἦν ἐν ἄστει, Μάνιος δὲ Φωκέας μὲν καὶ Χαλκιδέας, καὶ ὅσοι ἄλλοι τῷ Ἀντιόχῳ συνεπεπράχεσαν, δεομένους ἀπέλυσε τοῦ δέους, τὴν δ’ Αἰτωλίαν αὐτός τε καὶ Φίλιππος ἐδῄουν, καὶ τὰς πόλεις ἐπολιόρκουν. Δαμόκριτόν τε τὸν στρατηγὸν τῶν Αἰτωλῶν ἐνταῦθα ὁ Μάνιος ἔλαβε κρυπτόμενον, ὃς Φλαμινίνῳ παρὰ τὸν Τίβεριν ἠπείλει στρατοπεδεύσειν. ὁ μὲν δὴ Μάνιος ἐπὶ Καλλιπόλεως διώδευε τὸ ὄρος ὃ καλοῦσι Κόρακα, ὑψηλότατόν τε ὀρῶν καὶ δυσόδευτον καὶ ἀπόκρημνον, μετὰ στρατοῦ βαρυτάτου τε καὶ λαφύρων καταγόμου· πολλοὶ δ’ ἐξέπιπτον ὑπὸ τῆς δυσοδίας ἐς τὰ ἀπόκρημνα, καὶ σκεύεσιν αὐτοῖς καὶ ὅπλοις κατεφέροντο. καὶ αὐτοὺς δυνηθέντες ἂν οἱ Αἰτωλοὶ συνταράξαι οὐδὲ ὤφθησαν, ἀλλ’ ἐς Ῥώμην περὶ εἰρήνης ἐπρέσβευον. Ἀντίοχος δὲ τὴν στρατιὰν ἀπὸ τῶν ἄνω σατραπειῶν κατὰ σπουδὴν ἐπὶ θάλασσαν ἐκάλει, καὶ τὰς ναῦς ἐπεσκεύαζε, ναυαρχοῦντος αὐτῷ Πολυξενίδου Ῥοδίου φυγάδος. ἔς τε Χερρόνησον διαπλεύσας πάλιν αὐτὴν ὠχύρου, καὶ Σηστὸν καὶ Ἄβυδον ἐκρατύνετο, δι’ ὧν ἔδει τὴν φάλαγγα τὴν Ῥωμαίων ἐς τὴν Ἀσίαν ὁδεῦσαί τε καὶ περᾶσαι. Λυσιμάχειαν δὲ ταμιεῖον τῷδε τῷ πολέμῳ ποιούμενος, ὅπλα καὶ σῖτον πολὺν ἐς αὐτὴν συνέφερεν, ἡγούμενος αὐτίκα οἱ Ῥωμαίους πεζῷ τε πολλῷ καὶ ναυσὶν ἐπιθήσεσθαι. οἱ δὲ Μανίῳ μὲν αἱροῦνται διάδοχον ἐπὶ τὴν στρατηγίαν Λεύκιον Σκιπίωνα, ὃς τότε αὐτοῖς ὕπατος ἦν, ἀπράκτῳ δ’ ὄντι καὶ ἀπειροπολέμῳ σύμβουλον αἱροῦνται τὸν ἀδελφὸν Πόπλιον Σκιπίωνα τὸν Καρχηδονίους ἀφελόμενον τὴν ἡγεμονίαν καὶ πρῶτον ὀνομασθέντα Ἀφρικανόν.", "st": "4.21"}, {"sp": "N", "t": "καὶ οἱ μὲν Σκιπίωνες ἔτι ἦσαν ἐν παρασκευῇ, Λίουιος δ’ ὁ φύλαξ τῆς Ἰταλίας, ἐπὶ τὴν ναυαρχίαν αἱρεθεὶς Ἀτιλίῳ διάδοχος, αὐτίκα ταῖς τε ἰδίαις ναυσίν, αἷς τὴν Ἰταλίαν περιέπλει, καὶ παρὰ Καρχηδονίων αὐτῷ τισὶ δοθείσαις καὶ συμμαχίσιν ἄλλαις ἐς Πειραιᾶ κατήχθη, καὶ τὸν ὑπ’ Ἀτιλίῳ στόλον παραλαβὼν ἔπλει καταφράκτοις ὀγδοήκοντα καὶ μιᾷ, ἑπομένου καὶ Εὐμένους πεντήκοντα ἰδίαις· καὶ ἦν κατάφρακτον καὶ τῶνδε τὸ ἥμισυ. ἔς τε Φώκαιαν ὑπήκοον μὲν Ἀντιόχου, ὑπὸ δ’ ἐκπλήξεως αὐτοὺς δελομένην κατήγοντο, καὶ τῆς ἐπιούσης ἐς ναυμαχίαν ἀνέπλεον. ἀντανήγετο δ’ αὐτοῖς ὁ ναύαρχος ὁ Ἀντιόχου Πολυξενίδας διακοσίαις ναυσί, κουφοτέραις τῶν πολεμίων παρὰ πολύ· ᾧ δὴ καὶ μάλιστα προύλαβε τοῦ πελάγους ἔτι Ῥωμαίων ἀναπειρωμένων. καὶ δύο τῶν Καρχηδονίων ναῦς ἰδὼν προπλεούσας, τρεὶς τῶν ἰδίων ἐπιπέμψας εἷλε τὰς δύο κενάς, ἐξαλομένων τῶν Λιβύων ἐς τὸ πέλαγος. Λίουιος δ’ ἐπὶ τὰς τρεῖς ἐφέρετο πρῶτος ὑπ’ ὀργῆς τῇ στρατηγίδι νηί, πολὺ προύχων τοῦ στόλου. αἱ δ’, ὡς μιᾷ, σὺν καταφρονήσει χεῖράς τε σιδηρᾶς ἐπέβαλον, καὶ συνεστηκότων τῶν σκαφῶν ὁ ἀγὼν ἦν ὥσπερ ἐν γῇ. πολὺ δὲ κρείσσους ὄντες οἱ Ῥωμαῖοι ταῖς εὐτολμίαις, ἐπιβάντες ἐς τὰς ἀλλοτρίας ἐκράτουν, καὶ μιᾷ νηὶ δύο ὁμοῦ φέροντες ἐπανῄεσαν. καὶ τόδε μὲν τῆς ναυμαχίας προαγώνισμα ἦν· ἐπεὶ δὲ οἱ στόλοι συνέπεσον ἀλλήλοις, ἰσχύι μὲν καὶ προθυμίᾳ τὰ Ῥωμαίων ἐπεκράτει, διὰ δὲ βαρύτητα τῶν σκαφῶν τοὺς ἐχθροὺς οὐκ ἐδύναντο καταλαμβάνειν κούφαις ναυσὶν ὑποφεύγοντας, ἕως οἳ μὲν ἐς τὴν Ἔφεσον ὀξέως κατέφυγον, οἳ δ’ ἐς Χίον ἀπῇραν, ἔνθα αὐτοῖς Ῥοδίων νῆες συμμαχίδες ἦλθον ἑπτὰ καὶ εἴκοσιν. Ἀντίοχος δὲ περὶ τῆσδε τῆς ναυμαχίας πυθόμενος, Ἀννίβαν ἔστελλεν ἐπὶ Συρίας ἐς νεῶν ἄλλων ἐκ τε Φοινίκης καὶ Κιλικίας παρασκευήν.", "st": "4.22"}, {"sp": "N", "t": "καὶ τόνδε μὲν ἐπανιόντα Ῥόδιοι κατέκλεισαν ἐς Παμφυλίαν, καί τινας αὐτοῦ τῶν νεῶν εἷλον, καὶ τὰς λοιπὰς ἐφεδρεύοντες ἐφύλασσον·", "st": "4.22"}, {"sp": "N", "t": "Πόπλιος δὲ Σκιπίων ἀφικόμενος ἐς Αἰτωλίαν μετὰ τοῦ ὑπάτου, καὶ τὸν Μανίου στρατὸν παραλαβών, τὰς μὲν ἐν Αἰτωλίᾳ πολιορκίας ὑπερεῖδεν ὡς μικρὸν ἔργον, καὶ τοῖς Αἰτωλοῖς δεομένοις ἐπέτρεψεν αὖθις ἐς Ῥώμην πρεσβεῦσαι περὶ σφῶν, ἐπὶ δὲ τὸν Ἀντίοχον ἠπείγετο πρὶν ἐκβῆναι τῷ ἀδελφῷ τὴν στρατηγίαν. διὰ δὲ Μακεδόνων ὥδευε καὶ Θρᾳκῶν ἐπὶ τὸν Ἑλλήσποντον, δυσχερῆ καὶ χαλεπὴν ὁδὸν αὐτῷ γενομένην ἄν, εἰ μὴ Φίλιππος ὁ Μακεδὼν ὡδοποίει καὶ ὑπεδέχετο καὶ παρέπεμπεν ἐζευγμένοις τε ποταμοῖς ἐκ πολλοῦ καὶ ἀγοραῖς ἑτοίμοις· ἐφ’ οἷς αὐτὸν οἱ Σκιπίωνες αὐτίκα τῶν ὑπολοίπων χρημάτων ἀπέλυσαν, ἐπιτετραμμένοι τοῦθ’ ὑπὸ τῆς βουλῆς, εἰ πρόθυμον εὕροιεν. ἐπέστελλον δὲ καὶ ἐς Προυσίαν τὸν Βιθυνῶν βασιλέα, καταλέγοντες ὅσοις βασιλεῦσι Ῥωμαῖοι συμμαχήσασι τὰς ἀρχὰς ἐπηύξησαν· Φίλιππον δέ, φασί, τὸν Μακεδόνα καὶ πολέμῳ κρατήσαντες ἄρχειν ἐῶσι, καὶ τὸν παῖδα αὐτῷ τῆς ὁμηρείας ἀπελύσαμεν, καὶ τὸ ἔτι ὄφλημα τῶν χρημάτων. οἷς ὁ Προυσίας ἡσθεὶς συνέθετο συμμαχήσειν ἐπ’ Ἀντίοχον.", "st": "4.23"}, {"sp": "N", "t": "Λίουιος δ’ ὁ ναύαρχος ἐπεὶ τῆς ὁδοιπορίας τῶν Σκιπιώνων ἐπύθετο, Παυσίμαχον μὲν τὸν Ῥόδιον μετὰ τῶν Ῥοδίων νεῶν ἐν τῇ Αἰολίδι κατέλιπε, καὶ μέρος τι τοῦ ἰδίου στόλου, ταῖς δὲ πλείοσιν ἐς τὸν Ἑλλήσποντον ἔπλει τὸν στρατὸν ὑποδεξόμενος. καὶ Σηστὸς μὲν αὐτῷ καὶ Ῥοίτειον καὶ ὁ Ἀχαιῶν λιμὴν καί τινα ἄλλα προσέθετο, Ἀβυδον δὲ ἀπειθοῦσαν ἐπολιόρκει.", "st": "4.23"}, {"sp": "N", "t": "Παυσίμαχος δ’ οἰχομένου Λιουίου πείρας τε πυκνὰς καὶ μελέτας τῶν ἰδίων ἐποιεῖτο, καὶ μηχανὰς ποικίλας συνεπήγνυτο, πυρφόρα τε ἀγγεῖα σιδηρᾶ ἐξῆπτε κοντῶν μακρῶν, αἰωρεῖσθαι τὸ πῦρ ἐς τὸ πέλαγος, ἵνα τῶν μὲν ἰδίων σκαφῶν πολὺ προύχῃ, τοῖς δὲ πολεμίοις προσιοῦσιν ἐμπίπτῃ. καὶ αὐτὸν τάδε φιλοπονούμενον Πολυξενίδας ὁ Ἀντιόχου ναύαρχος, Ῥόδιός τε ὢν καὶ ὅδε καί τισιν αἰτίαις ἐκπεσὼν τῆς πατρίδος, ἐνήδρευεν, ὑπισχνούμενος τὸν Ἀντιόχου στόλον ἐγχειριεῖν, εἰ συνθοῖτο συμπράξειν ἐς κάθοδον αὑτῷ. ὁ δὲ ὑπώπτευε μὲν ἐπίκλοπον ἄνδρα καὶ πανοῦργον, καὶ ἐς πολὺ καλῶς ἐφυλάσσετο· γράψαντος δ’ αὐτῷ τοῦ Πολυξενίδου περὶ τῆς προδοσίας ἐπιστολὴν αὐτόγραφον, καὶ ἐπ’ αὐτῇ καὶ ἀναζεύξαντος ἀπὸ τῆς Ἐφέσου, καὶ τὴν στρατιὰν ὑποκριθέντος ἐς χορτολογίαν περιπέμπειν, ὁ Παυσίμαχος τήν τε ἀνάζευξιν ὁρῶν, καὶ οὐκ ἐλπίσας ἄν τινα περὶ προδοσίας ἐπιστολὴν αὐτόγραφον οὐκ ἀληθεύοντα πέμψαι, πάγχυ πιστεύσας ἐξέλυσε τὰς φυλακὰς καὶ ἐς σιτολογίαν καὶ αὐτὸς περιέπεμπεν. ὁ δὲ Πολυξενίδας ἐπεὶ κατεῖδεν αὐτὸν ἐνηδρευμένον, αὐτίκα τὴν παρασκευὴν συνῆγε, καὶ Νίκανδρον τὸν πειρατὴν σὺν ὀλίγοις ἐς τὴν Σάμον περιέπεμπε, κατὰ τὴν γῆν ὄπισθεν τοῦ Παυσιμάχου θορυβοποιεῖν. ἐκ δὲ μέσων νυκτῶν αὐτὸς ἐπέπλει, καὶ περὶ τὴν ἑωθινὴν φυλακὴν ἐπέπιπτεν ἔτι κοιμωμένῳ. ὁ δὲ ἐν αἰφνιδίῳ κακῷ καὶ ἀδοκήτῳ τοὺς στρατιώτας ἐκέλευε, τὰς ναῦς ἐκλιπόντας, ἀπὸ τῆς γῆς ἀμύνεσθαι τοὺς πολεμίους. προσπεσόντος δ’ ὄπισθεν αὐτῷ τοῦ Νικάνδρου, νομίσας καὶ τὴν γῆν προειλῆφθαι οὐχ ὑπὸ τῶν ἑωραμένων μόνων ἀλλ’, ὡς ἐν νυκτί, πολὺ πλειόνων, πάλιν ἐς τὰς ναῦς ἐνέβαινε θορυβούμενος, πρῶτός τε ἐς μάχην ἀνήγετο, καὶ πρῶτος ἔπιπτε λαμπρῶς ἀγωνιζόμενος. τῶν δ’ ἄλλων οἱ μὲν ἐλήφθησαν οἱ δ’ ἀπώλοντο. καὶ τῶν νεῶν ἑπτὰ μέν αἳ τὸ πῦρ ἔφερον, οὐδενὸς αὐταῖς διὰ τὴν φλόγα προσιόντος ἔφυγον, τὰς δὲ λοιπὰς εἴκοσιν ὁ Πολυξενίδας ἀναδησάμενος ἐς τὴν Ἔφεσον κατήχθη.", "st": "4.24"}, {"sp": "N", "t": "καὶ ἐπὶ τῇδε τῇ νίκῃ Φώκαια αὖθις καὶ Σάμος καὶ Κύμη πρὸς Ἀντίοχον μετετίθεντο. δείσας δ’ ὁ Λίουιος περὶ τῶν σφετέρων νεῶν, ἃς ἐν τῇ Αἰολίδι κατελελοίπει, κατὰ σπουδὴν ἐς αὐτὰς ἐπανῄει. καὶ Εὐμένης πρὸς αὐτὸν ἠπείγετο, Ῥόδιοί τε Ῥωμαίοις ναῦς ἑτέρας εἴκοσιν ἔπεμπον. μικρὸν δὲ διαλιπόντες ἅπαντες ἀνεθάρρησαν, καὶ ἐπὶ τὴν Ἔφεσον ἔπλεον ἐς ναυμαχίαν ἐσκευασμένοι. οὐδενὸς δ’ αὐτοῖς ἀντεπιπλέοντος, τὸ μὲν ἥμισυ τῶν νεῶν ἐς ἐπίδειξιν ἔστησαν ἐν μέσῃ τῇ θαλάσσῃ μέχρι πολλοῦ, ταῖς δ’ ὑπολοίποις ἐς τὴν πολεμίαν καταχθέντες ἐπόρθουν, μέχρι Νίκανδρος αὐτοῖς ἐκ τῆς μεσογείας ἐπιπεσὼν τήν τε λείαν ἀφείλετο καὶ ἐς τὰς ναῦς κατεδίωξεν.", "st": "4.25"}, {"sp": "N", "t": "οἱ μὲν δὴ πάλιν ἐς Σάμον ἀνήγοντο, καὶ ὁ χρόνος ἔληγε Λιουίῳ τῆς ναυαρχίας· τοῦ δ’ αὐτοῦ χρόνου Σέλευκος ὁ Ἀντιόχου τὴν Εὐμένους γῆν ἐδῄου καὶ Περγάμῳ παρεκάθητο, τοὺς ἄνδρας ἐς τὴν πόλιν κατακλείσας. ὅθεν ὁ Εὐμένης ἐς Ἐλαίαν, τὸ τῆς ἀρχῆς ἐπίνειον, διέπλει κατὰ σπουδήν, καὶ σὺν αὐτῷ Λεύκιος Αἰμίλιος Ῥηγίλλος ὁ Λιουίου τὴν ναυαρχίαν παραδεδεγμένος. ἧκον δὲ καὶ παρὰ τῶν Ἀχαιῶν Εὐμένει σύμμαχοι χίλιοι πεζοὶ καὶ ἱππεῖς ἑκατὸν ἐπίλεκτοι, ὧν Διοφάνης ὁ στρατηγὸς ἀπὸ τοῦ τείχους ἰδὼν τοὺς Σελευκείους παίζοντάς τε καὶ μεθύοντας ἐκ καταφρονήσεως, ἔπειθε τοὺς Περγαμηνοὺς ἑαυτῷ συνεκδραμεῖν ἐπὶ τοὺς πολεμίους. οὐχ ὑφισταμένων δ’ ἐκείνων, ὥπλισε τοὺς ἰδίους χιλίους καὶ τοὺς ἑκατὸν ἱππέας. καὶ προαγαγὼν ὑπὸ τὸ τεῖχος ἔστησεν ἀτρεμεῖν, ὑπερορώντων αὐτοὺς ἐς πολὺ τῶν πολεμίων ὡς ὀλίγους τε καὶ οὐ τολμῶντας ἐς χεῖρας ἐλθεῖν. ὁ δ’ ἀριστοποιουμένοις ἐπιδραμὼν ἐθορύβησέ τε καὶ ἐτρέψατο τοὺς προφύλακας, τῶν δ’ ἄλλων ἐπὶ τὰ ὅπλα ἀναπηδώντων, καὶ τοὺς ἵππους περιχαλινούντων ἢ φεύγοντας διωκόντων ἢ δυσχερῶς ἀναβαινόντων οὐκ εὐσταθοῦντας, ἐκράτει πάνυ λαμπρῶς, ἐπιβοώντων ἄνωθεν ἀπὸ τοῦ τείχους τῶν Περγαμηνῶν, καὶ οὐδὲ τότε προελθεῖν ὑφισταμένων. κτείνας δ’ ὅσους ἐδύνατο ὡς ἐν ἐπιδείξει ταχείᾳ, καί τινας αἰχμαλώτους ἑλὼν ἄνδρας τε καὶ ἵππους, ἐπανῄει κατὰ σπουδήν. καὶ τῆς ἐπιούσης αὖθις ἵστη τοὺς Ἀχαιοὺς ὑπὸ τὸ τεῖχος, οὐδὲ τότε τῶν Περγαμηνῶν αὐτῷ συνεξιόντων. Σέλευκος δ’ ἱππεῦσι πολλοῖς αὐτῷ προσεπέλαζε προκαλούμενος. ὁ δὲ τότε μὲν οὐκ ἐπεξῄει, παρ’ αὐτὸ τὸ τεῖχος ἑστώς, ἀλλ’ ἐφυλάσσετο· ἐπεὶ δ’ ὁ Σέλευκος παραμείνας ἐς μεσημβρίαν, καμνόντων οἱ ἤδη τῶν ἱππέων ἐπέστρεφε καὶ ἐπανῄει, τοῖς τελευταίοις αὐτοῦ ὁ Διοφάνης ἐπιθέμενος καὶ θορυβοποιήσας, καὶ βλάψας ὅσα καὶ τότε δυνατὸς ἦν, εὐθὺς ἐπανῄει πάλιν ὑπὸ τὸ τεῖχος. καὶ τόνδε τὸν τρόπον συνεχῶς ἔν τε χορτολογίαις καὶ ξυλείαις ἐνεδρεύων καὶ ἀεί τι ἐνοχλῶν ἀπό τε Περγάμου τὸν Σέλευκον ἀνέστησε καὶ ἀπὸ τῆς ἄλλης Εὐμένους χώρας ἐξήλασεν.", "st": "4.26"}, {"sp": "N", "t": "Πολυξενίδᾳ δὲ καὶ Ῥωμαίοις μετ’ οὐ πολὺ γίγνεται ναυμαχία περὶ Μυόννησον, ἐς ἣν συνῄεσαν Πολυξενίδας μὲν ναυσὶν ἐνενήκοντα καταφράκτοις, Λεύκιος δ’ ὁ Ῥωμαίων ναύαρχος ὀγδοήκοντα τρισί· τούτων ἦσαν ἐκ Ῥόδου πέντε καὶ εἴκοσιν. ὧν ὁ στρατηγὸς Εὔδωρος ἐτέτακτο μὲν ἐπὶ τοῦ λαιοῦ κέρως, ἰδὼν δὲ ἐπὶ θάτερα Πολυξενίδαν πολὺ προύχοντα Ῥωμαίων, ἔδεισέ τε μὴ κυκλωθεῖεν, καὶ περιπλεύσας ὀξέως ἅτε κούφαις ναυσὶ καὶ ἐρέταις ἐμπείροις θαλάσσης, τὰς ναῦς τὰς πυρφόρους τῷ Πολυξενίδᾳ πρώτας ἐπῆγε, λαμπομένας τῷ πυρὶ πάντοθεν. οἱ δ’ ἐμβαλεῖν μὲν αὐταῖς οὐκ ἐτόλμων διὰ τὸ πῦρ, κύκλῳ δ’ αὐτὰς περιπλέοντες ἐνέκλινόν τε καὶ θαλάσσης ἐπίμπλαντο καὶ ἐς τὰς ἐπωτίδας ἐτύπτοντο, μέχρι Ῥοδίας νεὼς ἐς Σιδονίαν ἐμβαλούσης, καὶ τῆς πληγῆς εὐτόνου γενομένης, ἄγκυρα ἐκπίπτουσα τῆς Σιδονίας ἐς τὴν Ῥοδίαν ἐπάγη τε καὶ συνέδησεν ἄμφω πρὸς ἀλλήλας, ὅθεν ἦν ὁ ἀγὼν ἀτρεμούντων τῶν σκαφῶν τοῖς ἐπιβάταις ὥσπερ ἐν γῇ. καὶ προσιουσῶν ἄλλων ἐς ἐπικουρίαν ἑκατέρᾳ πολλῶν, φιλονεικία τε παρ’ ἀμφοῖν ἐγίγνετο λαμπρά, καὶ τὸ μέσον τῶν Ἀντιόχου νεῶν ἔρημον ἐκ τούτου γενόμενον αἱ Ῥωμαίων νῆες διέπλεον, καὶ τοὺς πολεμίους ἔτι ἀγνοοῦντας ἐκύκλουν, ὡς δ’ ἔμαθόν ποτε, ἐγίγνετο φυγὴ καὶ τροπή, καὶ διεφθάρησαν Ἀντιόχου νῆες μιᾶς δέουσαι τριάκοντα, ὧν τρισκαίδεκα αὐτοῖς ἀνδράσιν ἐλήφθησαν. Ῥωμαίων δ’ ἀπώλοντο μόναι δύο. καὶ ὁ Πολυξενίδας τὴν Ῥοδίαν ναῦν ἐπαγόμενος ἐς τὴν Ἔφεσον κατήχθη.", "st": "4.27"}, {"sp": "N", "t": "τοῦτο μὲν δὴ τῇ ναυμαχίᾳ τῇ περὶ τὴν Μυόννησον ἦν τέλος· οὔπω δ’ αὐτῆς ὁ Ἀντίοχος αἰσθόμενος Χερρόνησόν τε καὶ Λυσιμάχειαν ἐπιμελῶς ὠχύρου, μέγα, ὥσπερ ἦν, τὸ ἔργον ἡγούμενος ἐπὶ Ῥωμαίοις, ὅπου γε καὶ τὴν ἄλλην Θρᾴκην διελθεῖν στρατοπέδῳ δυσόδευτον αὐτοῖς ἂν ἐγένετο καὶ δύσβατον, εἰ μὴ Φίλιππος διέφερεν. ἀλλ’ ὁ Ἀντίοχος ὢν καὶ τὰ ἄλλα κουφόνους ἀεὶ καὶ ταχὺς ἐς μεταβολήν, ἐπεὶ τῆς ἥσσης ἐπύθετο τῆς περὶ Μυόννησον, πάμπαν ἐξεπλάγη, νομίσας αὑτῷ τὸ δαιμόνιον ἐπιβουλεύειν· παρὰ γὰρ λόγον ἕκαστα χωρεῖν, Ῥωμαίων μὲν ἐν τῇ θαλάσσῃ κρατούντων, ἐν ᾗ πολὺ προύχειν αὐτὸς ἐνόμιζε, Ῥοδίων δ’ Ἀννίβαν ἐς Παμφυλίαν κατακεκλεικότων, Φιλίππου δὲ Ῥωμαίους παραπέμποντος ἀβάτους ὁδούς, ὃν μάλιστα μνησικακήσειν αὐτοῖς ὧν ἔπαθεν ὑπελάμβανεν. ὑπὸ δὴ τῶνδε πάντων ἐκταρασσόμενός τε, καὶ θεοῦ βλάπτοντος ἤδη τοὺς λογισμούς, ὅπερ ἅπασι προσιόντων ἀτυχημάτων ἐπιγίγνεται, Χερρόνησον ἐξέλιπεν ἀλογίστως, πρὶν καὶ ἐς ὄψιν ἐλθεῖν τοῖς πολεμίοις, οὔτε μετενεγκὼν ὅσος ἦν ἐν αὐτῇ σῖτος σεσωρευμένος πολὺς ἢ ὅπλα ἢ χρήματα ἢ μηχαναί, οὔτε ἐμπρήσας, ἀλλ’ ὑγιεῖς ἀφορμὰς τοσάσδε τοῖς πολεμίοις καταλιπών. Λυσιμαχέας τε αὐτῷ καθάπερ ἐκ πολιορκίας συμφεύγοντας μετ’ οἰμωγῆς, ἅμα γυναιξὶ καὶ παιδίοις, ὑπερεώρα, μόνου τοῦ διάπλου τοῦ περὶ Ἄβυδον εἶρξαι τοὺς πολεμίους ἐπινοῶν, καὶ τὴν λοιπὴν ἔτι ἐλπίδα τοῦ πολέμου πᾶσαν ἐν τούτῳ τιθέμενος. οὐ μὴν οὔτε τὸν διάπλουν ἐφύλαξεν ὑπὸ θεοβλαβείας, ἀλλ’ ἐς τὸ μεσόγειον ἠπείχθη ἐπανελθεῖν, φθάνων τοὺς πολεμίους, οὐδέ τινα φυλακὴν ἐν τῷ διάπλῳ κατέλιπεν.", "st": "4.28"}, {"sp": "N", "t": "οἱ δὲ Σκιπίωνες ἐπεὶ τὴς ἀναχωρήσεως αὐτοῦ ἐπύθοντο, Λυσιμάχειάν τε δρόμῳ κατέλαβον, καὶ τῶν ἐν Χερρονήσῳ θησαυρῶν τε καὶ ὅπλων κρατήσαντες τὸν Ἑλλήσποντον ἔρημον ὄντα φυλακῆς εὐθὺς ἐπέρων μετὰ σπουδῆς, ἔφθασάν τε Ἀντίοχον ἔτι ἀγνοοῦντα ἐν Σάρδεσι γενόμενοι. ὁ δ’ ἐκπλαγεὶς ἐβαρυθύμει, καὶ τὰ ἴδια αὑτοῦ ἁμαρτήματα ἐς τὸ δαιμόνιον ἀνατιθεὶς Ἡρακλείδην τὸν Βυζάντιον ἔπεμπεν ἐς τοὺς Σκιπίωνας ἐπὶ διαλύσεσι τοῦ πολέμου, Σμύρναν τε καὶ Ἀλεξάνδρειαν αὐτοῖς διδοὺς τὴν ἐπὶ Γρανίκῳ καὶ Λάμψακον, δι’ ἃς ἦρξεν αὐτοῖς ὁ πόλεμος, καὶ τὸ ἥμισυ τῆς δαπάνης τοῦδε τοῦ πολέμου. ἐνετέλλετο δέ, εἰ δέοι, καὶ τῶν Ἰάδων πόλεων δοῦναι καὶ τῶν Αἰολίδων ὅσαι τὰ Ῥωμαίων ἐν τῷδε τῷ ἀγῶνι εἵλοντο, καὶ εἴ τι ἄλλο αἰτοῖεν οἱ Σκιπίωνες. ταῦτα μὲν εἶχεν ἐς τὸ φανερὸν λέγειν ὁ Ἡρακλείδης, ἰδίᾳ δὲ πρὸς Πόπλιον Σκιπίωνα ἔφερε παρ’ Ἀντιόχου χρημάτων τε πολλῶν ὑποσχέσεις καὶ τοῦ παιδὸς ἀφέσεις. ᾑρήκει γὰρ αὐτὸν ἐν τῇ Ἑλλάδι ὁ Ἀντίοχος, ἐς Δηματριάδα ἐκ Χαλκίδος διαπλέοντα· καὶ ἦν ὁ παῖς Σκιπίων ὁ Καρχηδόνα ὕστερον ἑλών τε καὶ κατασκάψας, καὶ δεύτερος ἐπὶ τῷδε τῷ Σκιπίωνι Ἀφρικανὸς ὀνομασθείς, Παύλου μὲν υἱὸς ὢν τοῦ Περσέα τὸν Μακεδόνα ἑλόντος, Σκιπίωνος δὲ τῷ γένει θυγατριδοῦς καὶ θέσει παῖς. κοινῇ μὲν οὖν οἱ Σκιπίωνες τῷ Ἡρακλείδῃ τήνδε ἔδοσαν τὴν ἀπόκρισιν, ἐὰν ὁ Ἀντίοχος εἰρήνης δέηται, μὴ τῶν Ἰάδων μηδὲ τῶν Αἰολίδων αὐτὸν ἐκστῆναι πόλεων, ἀλλὰ πάσης τῆς ἐπὶ τάδε Ταύρου, καὶ τὴν δαπάνην τοῦ πολέμου πᾶσαν ἐσενεγκεῖν, δι’ αὐτὸν γενομένου. ἰδιᾳ δὲ ὁ Πόπλιος ἔφη τῷ Ἡρακλείδῃ Ῥωμαίους, εἰ μὲν ἔτι Χερρονήσου καὶ Λυσιμαχείας κρατῶν ὁ Ἀντίοχος ταῦτα προύτεινεν, ἀσμένως ἂν λαβεῖν· τάχα δ’ εἰ καὶ μόνον ἔτι τοῦ Ἑλλησπόντου τὸν διάπλουν ἐφύλασσε· νῦν δ’ αὐτοὺς ἤδη περάσαντάς τε καὶ ἐν ἀσφαλεῖ γενομένους, καὶ τὸν χαλινόν, φασίν, ἐνθέντας, καὶ ἐπὶ τῷ χαλινῷ τὸν ἵππον ἀναβάντας, οὐκ ἀνέξεσθαι διαλύσεων ἐπ’ ὀλίγοις. αὐτὸς δὲ χάριν εἰδέναι τῷ βασιλεῖ τῆς προαιρέσεως, καὶ μᾶλλον εἴσεσθαι λαβὼν τὸν υἱόν· ἀμείβεσθαι δ’ αὐτὸν ἤδη, καὶ συμβουλεύειν δέχεσθαι τὰ προτεινόμενα πρὶν ἐς πεῖραν ἐλθεῖν μειζόνων ἐπιταγμάτων.", "st": "4.29"}, {"sp": "N", "t": "ὁ μὲν δὴ Πόπλιος ταῦτα εἰπὼν ἐς Ἐλαίαν νοσηλευόμενος ὑπεχώρει, σύμβουλον τῷ ἀδελφῷ Γναῖον Δομίτιον καταλιπών· ὁ δ’ Ἀντίοχος, οἷόν τι καὶ Φίλιππος ὁ Μακέδων, οἰηθεὶς τῶνδε τῶν ἐπιταγμάτων πλέον οὐδὲν αὑτοῦ τὸν πόλεμον ἀφαιρήσεσθαι, συνέτασσε ἀπὸ τῶν πολεμίων, καὶ Σκιπίωνι τὸν υἱὸν ἀπέπεμπεν ἐς Ἐλαίαν. ὁ δὲ τοῖς ἄγουσι συνεβούλευε μὴ μάχεσθαι τὸν Ἀντίοχον ἕως αὐτὸς ἐπανέλθοι. καὶ τῷδε πεισθεὶς ὁ Ἀντίοχος μετεστρατοπέδευσεν ἀμφὶ τὸ ὄρος τὸ Σίπυλον, τεῖχός τε καρτερὸν τῷ στρατοπέδῳ περιετείχιζε, καὶ τὸν Φρύγιον ποταμὸν ἐν προβολῇ τοῖς πολεμίοις ἐτίθετο, ἵνα μηδ’ ἄκων ἀναγκάζοιτο πολεμεῖν. Δομίτιος δὲ φιλοτιμούμενος τὸν πόλεμον ἐφ’ ἑαυτοῦ κριθῆναι, τὸν ποταμὸν ἐπέρα μάλα θρασέως, καὶ σταδίους εἴκοσιν ἀπ’ Ἀντιόχου διασχὼν ἐστρατοπέδευσεν. τέσσαρσί τε ἡμέραις ἐφεξῆς ἐξέτασσον ἑκάτεροι παρὰ τὸν χάρακα τὸν ἑαυτῶν, καὶ μάχης οὐ κατῆρχον. τῇ πέμπτῃ δὲ ὁ Δομίτιος ἐξέτασσεν αὖθις καὶ ἐπέβαινε σοβαρῶς. οὐκ ἀντεπιόντος δὲ τοῦ Ἀντιόχου, τότε μὲν ἐγγυτέρω μετεστρατοπέδευσε, μίαν δὲ ἄλλην διαλιπὼν ἐκήρυσσεν ἐς ἐπήκοον τῶν πολεμίων ἐς αὔριον Ἀντιόχῳ καὶ ἄκοντι πολεμήσειν. ὁ δὲ συνταραχθεὶς αὖθις μεθίει τὰ δόξαντα, καὶ δυνηθεὶς ἂν ἑστάναι μόνον ὑπὸ τὸ τεῖχος ἢ καλῶς αὐτὸν ἀπὸ τοῦ τείχους ἀπομάχεσθαι μέχρι ῥαΐσειεν ὁ Πόπλιος, αἰσχρὸν ἡγεῖτο μετὰ πλειόνων φυγομαχεῖν· ὅθεν ἐς μάχην παρέτασσεν.", "st": "4.30"}, {"sp": "N", "t": "καὶ ἐξῆγον ἔτι νυκτὸς ἄμφω περὶ ἐσχάτην φυλακήν, διεκόσμει δ’ αὐτῶν ἑκάτερος ὧδε. τὸ μὲν λαιὸν εἶχον ὁπλῖται Ῥωμαίων μύριοι, παρὰ τὸν ποταμὸν αὐτόν· καὶ μετ’ ἐκείνους ἦσαν Ἰταλῶν ἕτεροι μύριοι, τρεῖς ἑκατέρων τάξεις ἐπὶ βάθος. ἐπὶ δὲ τοῖς Ἰταλοῖς ὁ Εὐμένους στρατὸς ἐτάσσετο, καὶ Ἀχαιῶν πελτασταὶ περὶ τρισχιλίους. ὧδε μὲν εἶχε τὸ λαιόν, τὸ δεξιὸν δ’ ἦν ἱππεῖς, οἵ τε Ῥωμαίων καὶ Ἰταλῶν καὶ Εὐμένους, οὐ πλείους οὐδ’ οὗτοι τρισχιλίων. ἀνεμεμίχατο δ’ ἅπασι ψιλοί τε καὶ τοξόται πολλοί, καὶ ἀμφὶ τὸν Δομίτιον αὐτὸν ἦσαν ἱππέων ἶλαι τέσσαρες. οὕτω μὲν ἐγίγνοντο πάντες ἐς τρισμυρίους, ἐπεστάτει δὲ τοῦ μὲν δεξιοῦ Δομίτιος αὐτός, καὶ ἐς τὸ μέσον αὐτὸν ἵστη τὸν ὕπατον, τὸ δὲ λαιὸν ἔδωκεν Εὐμένει. τῶν δ’ ἐλεφάντων, οὓς εἶχεν ἐκ Λιβύης, οὐδένα νομίζων ἔσεσθαι χρήσιμον ὀλιγωτέρων τε ὄντων καὶ βραχυτέρων οἷα Λιβύων (δεδίασι δ’ οἱ σμικρότεροι τοὺς μείζονας), ἔστησεν ὀπίσω πάντας.", "st": "4.31"}, {"sp": "N", "t": "ὧδε μὲν δὴ διετετάχατο Ῥωμαῖοι, Ἀντιόχῳ δ’ ἦν μὲν ὁ στρατὸς ἅπας ἑπτακισμύριοι, καὶ τούτων τὸ κράτιστον ἦν ἡ φάλαγξ ἡ Μακεδόνων, ἄνδρες ἑξακισχίλιοι καὶ μύριοι, ἐς τὸν Ἀλεξάνδρου καὶ Φιλίππου τρόπον ἔτι κοσμούμενοι· ἵστη δ’ αὐτοὺς ἐν μέσῳ, διελὼν ἀνὰ χιλίους καὶ ἑξακοσίους ἐς δέκα μέρη, καὶ τούτων ἑκάστου μέρους ἦσαν ἐπὶ μὲν τοῦ μετώπου πεντήκοντα ἄνδρες, ἐς δὲ τὸ βάθος δύο καὶ τριάκοντα, ἐς δὲ τὰ πλευρὰ ἑκάστου μέρους ἐλέφαντες δύο καὶ εἴκοσιν. ἡ δ’ ὄψις ἦν τῆς μὲν φάλαγγος οἷα τείχους, τῶν δ’ ἐλεφάντων οἷον πύργων. τοιοῦτον μὲν ἦν τὸ πεζὸν Ἀντιόχῳ, ἱππεῖς δ’ ἑκατέρωθεν αὐτοῦ παρετετάχατο Γαλάται τε κατάφρακτοι καὶ τὸ λεγόμενον ἄγημα τῶν Μακεδόνων. εἰσὶ δὲ καὶ οἵδε ἱππεῖς ἐπίλεκτοι, καὶ παρ’ αὐτὸ ἄγημα λέγεται. τάδε μὲν ἔξ ἴσου τῆς φάλαγγος ἦν ἑκατέρωθεν· ἐπὶ δ’ αὐτοῖς τὰ κέρατα κατεῖχον ἐν μὲν δεξιᾷ ψιλοί τέ τινες καὶ ἕτεροι ἱππεῖς ἀργυράσπιδες καὶ ἱπποτοξόται διακόσιοι, τὸ δὲ λαιὸν Γαλατῶν τ’ ἔθνη, Τεκτοσάγαι τε καὶ Τρόκμοι καὶ Τολιστόβοιοι, καὶ Καππαδόκαι τινὲς οὓς ἔπεμψεν Ἀριαράθης, καὶ μιγάδες ἄλλοι ξένοι, κατάφρακτός τε ἵππος ἐπὶ τοῖσδε ἑτέρα, καὶ ἣν ἐκάλουν ἵππον ἑταιρικήν, ὡπλισμένη κούφως. ὧδε μὲν καὶ ὁ Ἀντίοχος ἐξέτασσεν. καὶ δοκεῖ τὴν ἐλπίδα λαβεῖν ἐν τοῖς ἱππεῦσιν, οὓς πολλοὺς ἔστησεν ἐπὶ τοῦ μετώπου, τὴν δὲ φάλαγγα πυκνὴν ἐς ὀλίγον συναγαγεῖν ἀπειροπολέμως, ᾗ δὴ καὶ μάλιστα ἔδει θαρρεῖν πάνυ ἠσκημένῃ. πολὺ δὲ καὶ ἄλλο πλῆθος ἦν λιθοβόλων τε καὶ τοξοτῶν καὶ ἀκοντιστῶν καὶ πελταστῶν, Φρυγῶν τε καὶ Λυκίων καὶ Παμφύλων καὶ Πισιδῶν Κρητῶν τε καὶ Τραλλιανῶν καὶ Κιλίκων ἐς τὸν Κρητῶν τρόπον ἐσκευασμένων. ἱπποτοξόται τε ἐπὶ τοῖσδε ἕτεροι, Δᾶαι καὶ Μυσοὶ καὶ Ἐλυμαῖοι καὶ Ἄραβες, οἳ καμήλους ὀξυτάτας ἐπικαθήμενοι τοξεύουσί τε εὐμαρῶς ἀφ’ ὑψηλοῦ, καὶ μαχαίραις, ὅτε πλησιάζοιεν, ἐπιμήκεσι καὶ στεναῖς χρῶνται. δρεπανηφόρα τε ἅρματα ἐν τῷ μεταιχμίῳ, προπολεμεῖν τοῦ μετώπου, ἐτετάχατο· καὶ εἴρητο αὐτοῖς μετὰ τὴν πρώτην πεῖραν ὑποχωρεῖν.", "st": "4.32"}, {"sp": "N", "t": "ὄψις τε ἦν ὥσπερ δύο στρατῶν, τοῦ μὲν ἀρχομένου πολεμεῖν, τοῦ δ’ ἐφεδρεύοντος· ἑκάτερος δ’ αὐτῶν ἐς κατάπληξιν ἐσκεύαστο δεινῶς πλήθει τε καὶ κόσμῳ. ἐφειστήκει δὲ τοῖς μὲν δεξιοῖς ἱππεῦσιν Ἀντίοχος αὐτός, τοῖς δ’ ἐπὶ θάτερα Σέλευκος ὁ υἱὸς Ἀντιόχου, τῇ δὲ φάλαγγι Φίλιππος ὁ ἐλεφαντάρχης καὶ τοῖς προμάχοις Μύνδις τε καὶ Ζεῦξις. ἀχλυώδους δὲ καὶ ζοφερᾶς τῆς ἡμέρας γενομένης, ἥ τε ὄψις ἔσβεστο τῆς ἐπιδείξεως, καὶ τὰ τοξεύματα πάντα ἀμβλύτερα ἦν ὡς ἐν ἀέρι ὑγρῷ καὶ σκοτεινῷ. ὅπερ ἐπεὶ κατεῖδεν Εὐμένης, τῶν μὲν ἄλλων κατεφρόνησε, τὴν δὲ ῥύμην τῶν ἁρμάτων τεταγμένων ἐφ’ ἑαυτὸν μάλιστα δείσας, ὅσοι ἦσαν αὐτῷ σφενδονῆται καὶ ἀκοντισταὶ καὶ ἕτεροι κοῦφοι, συναγαγὼν προσέταξε, τὰ ἅρματα περιθέοντας, ἐς τοὺς ἵππους ἀκοντίζειν ἀντὶ τῶν ἐπιβατῶν· ἵππου γὰρ ἐν ἅρματι ζυγομαχοῦντος ἀχρεῖον τὸ λοιπὸν ἅρμα γίγνεται, καὶ πολλὰ καὶ τῆς ἄλλης εὐταξίας παραλύεται, τὰ δρέπανα τῶν φιλίων δεδιότων. ὃ καὶ τότε συνηνέχθη γενέσθαι· πληγέντων γὰρ τῶν ἵππων ἀθρόως, καὶ τὰ ἅρματα ἐς τοὺς φίλους περιφερόντων, αἵ τε κάμηλοι πρῶται τῆς ἀταξίας ᾐσθάνοντο, πλησίον τοῖς ἅρμασι παρατεταγμέναι, καὶ μετὰ ταύτας ἡ κατάφρακτος ἵππος, οὐ ῥᾳδίως ὑπὸ τοῦ βάρους τὰ δρέπανα ἐκφεύγειν δυναμένη. θόρυβός τε ἦν ἤδη πολὺς καὶ τάραχος ποικίλος, ἀρξάμενος μὲν ἀπὸ τῶνδε μάλιστα, χωρῶν δὲ ἐπὶ ὅλον τὸ μεταίχμιον, καὶ μείζων ὑπόνοια τοῦ ἀκριβοῦς· ὡς γὰρ ἐν διαστήματι μακρῷ καὶ πλήθει πυκνῷ καὶ βοῇ ποικίλῃ καὶ φόβῳ πολλῷ, τὸ μὲν ἀκριβὲς οὐδὲ τοῖς ἀγχοῦ τῶν πασχόντων καταληπτὸν ἦν, τὴν δὲ ὑπόνοιαν μειζόνως ἐς τοὺς ἑξῆς ἕκαστοι μετέφερον.", "st": "4.33"}, {"sp": "N", "t": "ὁ δ’ Εὐμένης, ἐπεὶ τὰ πρῶτα καλῶς ἐπέπρακτο αὐτῷ, καὶ τὸ μεταίχμιον, ὅσον αἵ τε κάμηλοι καὶ τὰ ἅρματα ἐπεῖχεν, ἐγεγύμνωτο, τοὺς ἰδίους ἱππέας, καὶ ὅσοι Ῥωμαίων αὐτῷ καὶ Ἰταλῶν παρετετάχατο, ἐπῆγεν ἐπὶ τοὺς ἀντικρὺ Γαλάτας τε καὶ Καππαδόκας καὶ τὴν ἄλλην σύνοδον τῶν ξένων, μέγα κεκραγὼς καὶ παρακαλῶν ἐπὶ ἄνδρας ἀπείρους τε μάχης καὶ γεγυμνωμένους τῶν προπολεμούντων. οἱ δ’ ἐπείθοντο, καὶ βαρείας σφῶν τῆς ἐμβολῆς γενομένης τρέπονται τούτους τε καὶ τοὺς παρεζευγμένους αὐτοῖς ἱππέας τε καὶ καταφράκτους, ἐκ πολλοῦ ταρασσομένους διὰ τὰ ἅρματα· οὓς δὴ καὶ μάλιστα, διὰ τὸ βάρος ὑποφεύγειν ἢ ἀναστρέφειν εὐμαρῶς οὐ δυναμένους, κατελάμβανόν τε καὶ συνέκοπτον. καὶ τάδε μὲν ἦν περὶ τὸ λαιὸν τῆς φάλαγγος τῶν Μακεδόνων· ἐν δεξιᾷ δέ, ᾗπερ αὐτὸς ὁ Ἀντίοχος ἐτέτακτο, διακόψας τὸ σύνταγμα τῆς Ρ̓ωμαίων φάλαγγος ἀπέσπασεν ἐπὶ πολὺ διώκων.", "st": "4.34"}, {"sp": "N", "t": "καὶ ἡ φάλαγξ ἡ τῶν Μακεδόνων, τεταγμένη μέν, ὡς μεθ’ ἱππέων, ἐπὶ στενοῦ τε καὶ τετραγώνου, γεγυμνωμένη δὲ τῶν ἱππέων ἑκατέρωθεν, τοὺς μὲν ψιλοὺς τοὺς ἐπὶ τοῦ μετώπου σφῶν ἔτι προπολεμοῦντας διαστᾶσα ἐς αὑτὴν ἐδέξατο καὶ πάλιν συνῄει, Δομιτίου δ’ αὐτὴν ἱππεῦσι πολλοῖς καὶ ψιλοῖς εὐμαρῶς, οἷα πλινθίον πυκνόν, κυκλώσαντος, οὔτ’ ἐκδραμεῖν ἔτι ἔχουσα οὔτ’ ἐξελίξαι βάθος οὕτω πολύ, μάλα καρτερῶς ἐκακοπάθει. καὶ ἠγανάκτουν αὐτοὶ μὲν ταῖς ἐμπειρίαις οὐδὲν ἔχοντες ἔτι χρῆσθαι, τοῖς δὲ πολεμίοις εὔβλητοι καὶ ἐπιτυχεῖς πανταχόθεν ὄντες. ὅμως δὲ τὰς σαρίσσας ἐκ τετραγώνου προβαλλόμενοι πυκνὰς προὐκαλοῦντο Ῥωμαίους ἐς χεῖρας ἐλθεῖν, καὶ δόξαν ἐπιβαινόντων ἀεὶ παρεῖχον. οὐ μήν τι προεπήδων, πεζοί τε καὶ βαρεῖς ὄντες ὑπὸ τῶν ὅπλων, καὶ τοὺς πολεμίους ἐπὶ ἵππων ὁρῶντες, μάλιστα δὲ ἵνα μὴ τὸ τῆς τάξεως πυκνὸν ἐκλύσειαν· μετατάξασθαι γὰρ ἑτέρως οὐκ ἔφθανον. Ῥωμαῖοι δ’ αὐτοῖς οὐ προσεπέλαζον μέν, οὐδ’ ἐς χεῖρας ᾔεσαν, δεδιότες ἀνδρῶν ἠσκημένων ἐμπειρίαν τε καὶ πυκνότητα καὶ ἀπόγνωσιν, περιθέοντες δὲ ἐσηκόντιζόν τε καὶ ἐσετόξευον. καὶ οὐδὲν ἦν ἀχρεῖον ὡς ἐν ὀλίγῳ πολλῶν συνεστώτων. οὐ γὰρ εἶχον οὔτε ἐκκλῖναι τὰ βαλλόμενα οὔτε φερομένοις διαστῆναι. ὅθεν ἤδη πολλὰ κάμνοντες ἐνεδίδοσαν ὑπὸ τῆς ἀπορίας, καὶ βάδην ὑπεχώρουν σὺν ἀπειλῇ, πάνυ εὐσταθῶς καὶ Ῥωμαίοις ἐπιφόβως· οὐδὲ γὰρ τότε προσπελάζειν αὐτοῖς ἐτόλμων, ἀλλὰ περιθέοντες ἔβλαπτον, μέχρι, τῶν ἐλεφάντων ἐν τῇ Μακεδόνων φάλαγγι συνταραχθέντων τε καὶ οὐχ ὑπακουόντων ἔτι τοῖς ἐπιβάταις, ὁ κόσμος ὁ τῆς φυγῆς συνεχεῖτο.", "st": "4.35"}, {"sp": "N", "t": "καὶ ταύτῃ μὲν ὁ Δομίτιος ἐκράτει, καὶ ἐπὶ τὸ στρατόπεδον τοῦ Ἀντιόχου φθάσας ἐβιάζετο τοὺς ἐν αὐτῷ φυλάσσοντας· ὁ δὲ Ἀντίοχος ἐς πολὺ διώκων παρ’ οὓς ἐκ τῆς Ῥωμαϊκῆς φάλαγγος ἐτέτακτο, οὐδενὸς οὐδ’ ἐκείνοις ἱππέων ἢ ψιλοῦ παρόντος ἐς ἐπικουρίαν (οὐ γὰρ παρετετάχει Δομίτιος, ἡγούμενος οὐ δεήσεσθαι διὰ τὸν ποταμόν), μέχρι τοῦ Ῥωμαίων χάρακος ἦλθεν. ἐπεὶ δὲ αὐτὸν ὅ τε χιλίαρχος ὁ τοῦ χάρακος φύλαξ, ἀκμῆσι τοῖς φύλαξιν ὑπαντιάσας, ἐπέσχε τῆς ὁρμῆς καὶ οἱ φεύγοντες τοῖς ἀναμιχθεῖσι θαρροῦντες ἐπεστρέφοντο, ἐπανῄει σοβαρὸς ὁ Ἀντίοχος ὡς ἐπὶ νίκῃ, οὐδενὸς τῶν ἐπὶ θάτερα πεπυσμένος. Ἄτταλος δ’ αὐτόν, ὁ Εὐμένους ἀδελφός, ἱππεῦσι πολλοῖς ὑπαντιάζει. καὶ τούσδε μὲν εὐμαρῶς ὁ Ἀντίοχος διακόψας διέδραμε, καὶ παρατρεχόντων ἔτι καὶ μικρὰ λυπούντων οὐκ ἐφρόντιζεν· ὡς δὲ κατεῖδε τὴν ἧτταν καὶ τὸ πεδίον ἅπαν νεκρῶν ἰδίων πλῆρες, ἀνδρῶν τε καὶ ἵππων καὶ ἐλεφάντων, τό τε στρατόπεδον εἰλημμένον ἤδη κατὰ κράτος, τότε δὴ καὶ ὁ Ἀντίοχος ἔφυγεν ἀμεταστρεπτί, καὶ μέχρι μέσων νυκτῶν ἐς Σάρδεις παρῆλθεν. παρῆλθε δὲ καὶ ἀπὸ Σάρδεων ἐς Κελαινάς, ἣν Ἀπάμειαν καλοῦσιν, οἷ τὸν υἱὸν ἐπυνθάνετο συμφυγεῖν. τῆς δ’ ἐπιούσης ἐς Συρίαν ἐκ Κελαινῶν ἀνεζεύγνυ, τοὺς στρατηγοὺς ἐν Κελαιναῖς καταλιπὼν ὑποδέχεσθαί τε καὶ ἀθροίζειν τοὺς διαφυγόντας. περι τε καταλύσεως τοῦ πολέμου πρέσβεις ἔπεμπε πρὸς τὸν ὕπατον. ὁ δὲ τὰ οἰκεῖα ἔθαπτε, καὶ ἐσκύλευε τοὺς πολεμίους, καὶ τὰ αἰχμάλωτα συνῆγεν. ἐφάνησαν δὲ νεκροὶ Ῥωμαίων μὲν τῶν ἐξ ἄστεος ἱππεῖς εἴκοσι καὶ τέσσαρες καὶ πεζοὶ τριακόσιοι μάλιστα, οὓς ὁ Ἀντίοχος ἔκτεινεν, Εὐμένους δὲ πεντεκαίδεκα ἱππεῖς μόνοι. Ἀντιόχου δέ, σὺν τοῖς αἰχμαλώτοις εἰκάζοντο ἀπολέσθαι περὶ πεντακισμυρίους· οὐ γὰρ εὐμαρὲς ἦν ἀριθμῆσαι διὰ τὸ πλῆθος. καὶ τῶν ἐλεφάντων οἱ μὲν ἀνῄρηντο, πεντεκαίδεκα δ’ αἰχμάλωτοι ἐγεγένητο.", "st": "4.36"}, {"sp": "N", "t": "ὡς δ’ ἐπὶ νίκῃ λαμπροτάτῃ καὶ παραλόγως τισὶ δοκούσῃ γενέσθαι (οὐ γὰρ εἰκὸς ἐνόμιζον ὀλιγωτέρους πολὺ πλειόνων ἐν ἀλλοτρίᾳ γῇ παρὰ τοσόνδε κρατῆσαι, καὶ μάλιστα φάλαγγος Μακεδόνων, εὖ γεγυμνασμένης καὶ εὐανδρούσης τότε μάλιστα, καὶ δόξαν ἄμαχόν τε καὶ φοβερὰν ἐχούσης), οἱ μὲν Ἀντιόχου φίλοι τὴν προπέτειαν αὐτοῦ τῆς ἐς Ῥωμαίους διαφορᾶς καὶ τὴν ἐξ ἀρχῆς ἀπειρίαν τε καὶ ἀβουλίαν ἐπεμέμφοντο, Χερρόνησόν τε καὶ Λυσιμάχειαν αὐτοῖς ὅπλοις καὶ τοσῇδε παρασκευῇ μεθέντος ἐκ χειρῶν πρὶν καὶ ἐς πεῖραν ἐλθεῖν τοῖς πολεμίοις, καὶ τὴν τοῦ Ἑλλησπόντου φυλακὴν ἐκλιπόντος, Ῥωμαίων οὐκ ἂν εὐμαρῶς ἐλπισάντων βιάσασθαι τὴν διάβασιν. κατεμέμφοντο δ’ αὐτοῦ καὶ τὴν τελευταίαν ἀφροσύνην, ἀχρεῖον ἐν στενῷ τὸ κράτιστον τοῦ στρατοῦ πεποιηκότος, καὶ τὴν ἐλπίδα θεμένου ἐν πλήθει συγκλύδων ἀνδρῶν ἀρτιπολέμων μᾶλλον ἢ ἐν ἀνδράσι διὰ μελέτην καὶ χρόνον ἐργάταις τε οὖσι πολέμου καὶ ἐκ τοσῶνδε πολέμων τὸ φρόνημα ἐς εὐτολμίαν καὶ θάρσος ηὐξημένοις. τοιαῦτα μὲν ἦν τὰ περὶ Ἀντιόχου λογοποιούμενα, Ῥωμαίοις δ’ ἐπῇρτο τὰ φρονήματα, καὶ οὐδὲν ἔτι σφίσιν ἡγοῦντο εἶναι δυσεργὲς ὑπό τε ἀρετῆς καὶ θεῶν ἐπικουρίας· καὶ γὰρ δὴ καὶ ἐς δόξαν εὐτυχίας ἔφερεν ὅτι οὕτω γε ὀλίγοι τε πολλῶν καὶ ἐξ ἐφόδου καὶ ἐν πρώτῃ μάχῃ καὶ ἐν ἀλλοτρίᾳ γῇ τοσῶνδε ἐθνῶν καὶ παρασκευῆς βασιλικῆς, καὶ μισθοφόρων ἀρετῆς, καὶ δόξης Μακεδόνων, καὶ βασιλέως αὐτοῦ μεγίστην τε ἀρχὴν κεκτημένου καὶ ἐπίκλησιν μεγάλου, κεκρατηκότες ἦσαν ἡμέρᾳ μιᾷ. πολύ τε σφίσιν ἦν τὸ ἔπος ἐν τοῖς λόγοις, “ἦν βασιλεὺς Ἀντίοχος ὁ μέγας.”", "st": "4.37"}, {"sp": "N", "t": "τοιάδε μὲν δὴ καὶ Ῥωμαῖοι περὶ σφῶν ἐμεγαλαύχουν· ὁ δὲ ὕπατος, ἐπεὶ αὐτῷ ῥαΐσας ὁ ἀδελφὸς Πόπλιος ἦλθεν ἀπὸ τὴς Ἐλαίας, ἐχρημάτιζε τοῖς Ἀντιόχου πρέσβεσιν. οἱ μὲν δὴ μαθεῖν ἠξίουν ὅ τι ποιῶν ὁ βασιλεὺς Ἀντίοχος ἔσται Ῥωμαίοις φίλος· ὁ δὲ Πόπλιος αὐτοῖς ὧδε ἀπεκρίνατο· “αἴτιος μὲν αὑτῷ διὰ πλεονεξίαν Ἀντίοχος καὶ τῶν νῦν καὶ τῶν πρότερον γεγονότων, ὃς ἀρχὴν μεγίστην ἔχων τε, καὶ Ῥωμαίων αὐτὸν ἐώντων ἔχειν, Πτολεμαίου συγγενοῦς ἰδίου καὶ Ῥωμαίοις φίλου Συρίαν τὴν κοίλην ἀφείλετο, καὶ ἐς τὴν Εὐρώπην οὐδὲν αὐτῷ προσήκουσαν ἐμβαλὼν Θρᾴκην κατεστρέφετο καὶ Χερρόνησον ὠχύρου καὶ Λυσιμάχειαν ἤγειρεν, ἔς τε τὴν Ἑλλάδα διελθὼν ἐδουλοῦτο τοὺς Ἕλληνας ὑπὸ Ῥωμαίων ἄρτι αὐτονόμους ἀφειμένους, μέχρι περὶ Θερμοπύλας ἡττήθη μάχῃ. καὶ φυγὼν οὐδ’ ὣς ἔληξε τῆς πλεονεξίας, ἀλλὰ κἀν τῇ θαλάττῃ πολλάκις ἐλαττωθεὶς σπονδῶν μέν, ἄρτι τὸν Ἑλλήσποντον ἡμῶν πεπερακότων, ἐδεήθη, διὰ δὲ ὑπεροψίαν τὰ προτεινόμενα ὑπερεῖδε, καὶ στράτευμα αὖθις πολὺ καὶ παρασκευὴν ἄπειρον ἐφ’ ἡμᾶς συναγαγὼν ἐπολέμει, βιαζόμενος ἐς πεῖραν ἐλθεῖν τοῖς ἀμείνοσι, μέχρι συνηνέχθη μεγάλῳ κακῷ. ἡμᾶς δὲ εἰκὸς μὲν ἦν αὐτῷ μείζονα τὴν ζημίαν ἐπιθεῖναι, βιασαμένῳ πολλάκις Ῥωμαίοις ἐς χεῖρας ἐλθεῖν· ἀλλ’ οὐχ ὑβρίζομεν ταῖς εὐπραξίαις, οὐδ’ ἐπιβαροῦμεν τοῖς ἑτέρων ἀτυχήμασιν. δίδομεν δὲ ὅσα καὶ πρότερον αὐτῷ προὐτείνομεν, μικρὰ ἄττα προσθέντες, ὅσα καὶ ἡμῖν ἔσται χρήσιμα καὶ αὐτῷ λυσιτελῆ πρὸς τὸ μέλλον ἐς ἀσφάλειαν, ἀπέχεσθαι μὲν αὐτὸν τῆς Εὐρώπης ὅλης καὶ Ἀσίας τῶν ἐπὶ τάδε τοῦ Ταύρου (καὶ τούτοις ὅροι τεθήσονται), παραδοῦναι δ’ ἐλέφαντας ὅσους ἔχει καὶ ναῦς ὅσας ἂν ἐπιτάξωμεν, ἔς τε λοιπὸν ἐλέφαντας μὲν οὐκ ἔχειν, ναῦς δὲ ὅσας ἂν ὁρίσωμεν, δοῦναι δὲ καὶ εἴκοσιν ὅμηρα, ἃ ἂν ὁ στρατηγὸς ἐπιγράψῃ, καὶ χρήματα ἐς τὴν τοῦδε τοῦ πολέμου δαπάνην, δι’ αὐτὸν γενομένου, τάλαντα Εὐβοϊκὰ αὐτίκα μὲν ἤδη πεντακόσια, καὶ ὅταν τάσδε τὰς σπονδὰς ἡ σύγκλητος ἐπιψηφίσῃ, δισχίλια καὶ πεντακόσια, δώδεκα δ’ ἔτεσιν ἄλλοις ἕτερα μύρια καὶ δισχίλια, τὸ μέρος ἑκάστου ἔτους ἀναφέροντα ἐς Ῥώμην· ἀποδοῦναι δ’ ἡμῖν αἰχμάλωτα καὶ αὐτόμολα πάντα, καὶ Εὐμένει ὅσα λοιπὰ τῆς πρὸς Ἄτταλον τὸν Εὐμένους πατέρα συνθήκης ἔχει. ταῦτα Ἀντιόχῳ πράττοντι ἀδόλως δίδομεν εἰρήνην τε καὶ φιλίαν, ὅταν ἡ σύγκλητος ἐπιψηφίσῃ.”", "st": "4.38"}, {"sp": "N", "t": "τοσάδε προύτεινεν ὁ Σκιπίων, καὶ πάντα ἐδέχοντο οἱ πρέσβεις. το τε μέρος αὐτίκα τῶν χρημάτων καὶ τὰ εἴκοσιν ὅμηρα ἐκομίζετο, καὶ ἦν αὐτῶν Ἀντίοχος ο νεώτερος υἱὸς Ἀντιόχου. ἐς δὲ τὴν Ῥώμην οἵ τε Σκιπίωνες καὶ ὁ Ἀντίοχος πρέσβεις ἔπεμπον, καὶ ἡ βουλὴ τοῖς ἐγνωσμένοις συνετίθεντο. καὶ ἐγράφοντο συνθῆκαι τοὺς Σκιπίωνος λόγους βεβαιοῦσαί τε καὶ περὶ τῶν ἀορίστων ἐπιλέγουσαι, καὶ βραχέα ἄττα προσεπιλαμβάνουσαι, ὅρον μὲν Ἀντιόχῳ τῆς ἀρχῆς εἶναι δύο ἄκρας, Καλύκαδνόν τε καὶ Σαρπηδόνιον, καὶ τάσδε μὴ παραπλεῖν Ἀντίοχον ἐπὶ πολέμῳ, ναῦς δὲ καταφράκτους ἔχειν δώδεκα μόνας, αἷς ἐς τοὺς ὑπηκόους πολέμου κατάρχειν· πολεμούμενον δὲ καὶ πλέοσι χρῆσθαι· μηδένα δ’ ἐκ τῆς Ῥωμαίων ξενολογεῖν, μηδὲ φυγάδας ἐξ αὐτῆς ὑποδέχεσθαι, καὶ τὰ ὅμηρα διὰ τριετίας ἐναλλάσσειν, χωρίς γε τοῦ παιδὸς Ἀντιόχου. ταῦτα συγγραψάμενοί τε καὶ ἐς τὸ Καπιτώλιον ἐς δέλτους χαλκᾶς ἀναθέντες, οὗ καὶ τὰς ἄλλας συνθήκας ἀνατιθέασιν, ἔπεμπον ἀντίγραφα Μαλλίῳ Οὐούλσωνι τῷ διαδεδεγμένῳ τὴν Σκιπίωνος στρατηγίαν. ὁ δ’ ὤμνυ τοῖς Ἀντιόχου πρέσβεσι περὶ Ἀπάμειαν τῆς Φρυγίας, καὶ ὁ Ἀντίοχος ἐπὶ τοῦτο πεμφθέντι Θέρμῳ χιλιάρχῳ. τοῦτο μὲν δὴ Ἀντιόχῳ μεγάλῳ τοῦ πρὸς Ῥωμαίους πολέμου τέλος ἦν. καὶ ἐδόκει μέχρι τοῦδε προελθεῖν μόνου διὰ χάριν τὴν ἐς τὸν παῖδα τὸν Σκιπίωνος Ἀντιόχῳ γενομένην·", "st": "4.39"}, {"sp": "N", "t": "καί τινες τὸν Σκιπίωνα ἐπανελθόντα διέβαλλον ἐπὶ τῷδε, καὶ δήμαρχοι δύο δωροδοκίας αὐτὸν ἐγράψαντο καὶ προδοσίας. ὁ δὲ ἀδοξῶν καὶ ὑπερορῶν τοῦ ἐγκλήματος, ἐπεὶ συνῆλθε τὸ δικαστήριον ἧς ἡμέρας ποτὲ Καρχηδόνα παρεστήσατο, θυσίαν προύπεμψεν ἐς τὸ Καπιτώλιον, καὶ ἐς τὸ δικαστήριον αὐτὸς παρῆλθεν ἐπὶ λαμπροῦ σχήματος ἀντὶ οἰκτροῦ καὶ ταπεινοῦ τῶν ὑπευθύνων, ὡς εὐθὺς ἐπὶ τῷδε πάντας ἐκπλῆξαί τε καὶ ἐς εὔνοιαν, ὡς ἐπὶ χρηστῷ δὴ συνειδότι μεγαλοφρονούμενον, προσαγαγέσθαι. λέγειν δὲ ἀρξάμενος τῆς μὲν κατηγορίας οὐδ’ ἐπεμνήσθη, τὸν δὲ βίον ἑαυτοῦ καὶ ἐπιτηδεύματα καὶ ἔργα πάντα ἐπεξῄει, καὶ πολέμους ὅσους ἐπολέμησεν ὑπὲρ τῆς πατρίδος, καὶ ἕκαστον αὐτῶν ὡς ἐπολέμησεν, ὁσάκις τε ἐνίκησεν, ὡς ἐγγενέσθαι τοῖς ἀκροωμένοις τι καὶ ἡδονῆς διὰ τὴν ἱστορίαν τῆς σεμνολογίας. ἐπεὶ δέ ποτε προῆλθεν ἐπὶ Καρχηδόνα, ἐξάρας ἐς φαντασίαν τάδε μάλιστα, καὶ ὁρμῆς αὐτός τε ἐμπλησθεὶς καὶ τὸ πλῆθος ἐμπλήσας, εἶπεν ὅτι τῆσδε τῆς ἡμέρας ἐγὼ τάδε ἐνίκων καὶ Καρχηδόνα ὑμῖν, ὦ πολῖται, περιεποίουν, τὴν τέως ὑμῖν ἐπιφοβωτάτην. ἄπειμι δὴ θύσων τῆς ἡμέρας ἐς τὸ Καπιτώλιον· καὶ ὑμῶν ὅσοι φιλοπόλιδες, τῆς θυσίας μοι, γιγνομένης ὑπὲρ ὑμῶν συνάψασθε. ταῦτα ἔφη, καὶ ἐς τὸ Καπιτώλιον ἔθει, μηδὲν τῆς δίκης φροντίσας. εἵπετο δ’ αὐτῷ τὸ πλῆθος καὶ οἱ πλέονες τῶν δικαστῶν σὺν εὐφήμῳ βοῇ, καὶ θύοντι ὅμοια ἐπεφώνουν. οἱ κατήγοροι δὲ ἠποροῦντο, καὶ οὔτε αὐτῷ τὴν δίκην αὖθις ὡς ἀτέλεστον ἐτόλμησαν ἐπιγράψαι, οὔτε μέμψασθαι δημοκοπίας, δυνατώτερον αὐτοῦ τὸν βίον εἰδότες ὑπονοίας τε καὶ διαβολῆς.", "st": "4.40"}, {"sp": "N", "t": "ὁ μὲν δὴ Σκιπίων ὧδε ἐγκλήματος ἀναξίου τῶν βεβιωμένων οἱ κατεφρόνησε, σοφώτερον, ἐμοὶ δοκεῖν, Ἀριστείδου περὶ κλοπῆς καὶ Σωκράτους περὶ ὧν ἐνεκαλεῖτο οὐδὲν εἰπόντων ὑπ’ ἀδοξίας ὁμοίας, ἢ Σωκράτους εἰπόντος ἃ δοκεῖ Πλάτωνι, μεγαλοφρονέστερον δὲ ἄρα καὶ Ἐπαμεινώνδου, ὃς ἐβοιωτάρχει μὲν ἅμα Πελοπίδᾳ καὶ ἑτέρῳ, ἐξέπεμψαν δὲ αὐτοὺς οἱ Θηβαῖοι, στρατὸν ἑκάστῳ δόντες, ἐπικουρεῖν Ἀρκάσι καὶ Μεσσηνίοις πολεμουμένοις ὑπὸ Λακώνων, οὔπω δ’ ὅσα ἐπενόοουν ἐργασαμένους ἐπὶ διαβολῇ μετεκάλουν. οἱ δὲ τοῖς διαδόχοις σφῶν τὴν ἀρχὴν ἐπὶ μῆνας ἓξ οὐ μεθῆκαν, ἕως τὰ Λακεδαιμονίων φρούρια καθεῖλον καὶ ἐπέστησαν αὖθις ἕτερα τῶν Ἀρκάδων, Ἐπαμεινώνδου τοὺς συστρατήγους ἐς τοῦτο ἀναγκάζοντός τε, καὶ ὑποδεχομένου τὸ ἔργον αὐτοῖς ἀζήμιον ἔσεσθαι. ἐπεὶ δὲ αὐτοῖς ἐπανελθοῦσιν οἱ κατήγοροι, καθ’ ἕνα διώκοντες, ἐτιμῶντο θανάτου (θανάτῳ γὰρ ὁ νόμος ἐζημίου τὸν ἐκ βίας ἀρχὴν ἄρξαντα ἀλλοτρίαν), οἱ μὲν ἕτεροι διέφυγον οἴκτῳ τε χρώμενοι καὶ λόγοις πλείοσι, καὶ τὴν αἰτίαν ἐς τὸν Ἐπαμεινώνδαν ἀναφέροντες, αὐτὸν οὕτω λέγειν ὑποθέμενον αὐτοῖς καὶ λέγουσιν ἐπιμαρτυροῦντα· ὁ δὲ κρινόμενος τελευταῖος “ὁμολογῶ,” ἔφη, “παρανόμως ἄρξαι τόνδε τὸν χρόνον, καὶ οὓς ἀπελύσατε νῦν, ἐγὼ συναναγκάσαι. καὶ οὐ παραιτοῦμαι τὸν θάνατον παρανομήσας. αἰτῶ δ’ ὑμᾶς ἀντὶ τῶν προβεβιωμένων μοι κατὰ τὸν τάφον ἐπιγράψαι· “οὗτός ἐστιν ὁ περὶ Λεῦκτρα νικήσας καὶ τὴν πατρίδα, τοὺς ἐχθροὺς οὐχ ὑπομένουσαν, οὐδ’ εἴ τις ξένος ἔχοι Λακωνικὸν πῖλον, ἐπὶ τὴν Σπάρτην αὐτὴν προαγαγών. οὗτος ὑπὸ τῆς πατρίδος ἀνῄρηται, παρανομήσας ἐπὶ συμφέροντι τῆς πατρίδος.”” ταῦτ’ εἰπὼν κατέβη τε τοῦ βήματος, καὶ παρεδίδου τὸ σῶμα τοῖς ἐθέλουσιν ἀπαγαγεῖν. οἱ δικασταὶ δὲ τῷ τε ὀνείδει τοῦ λόγου καὶ θαύματι τῆς ἀπολογίας καὶ αἰδοῖ τοῦ ἀνδρὸς ἀπολογουμένου, τὰς ψήφους οὐχ ὑποστάντες λαβεῖν, ἐξέδραμον ἐκ τοῦ δικαστηρίου.", "st": "4.41"}, {"sp": "N", "t": "τάδε μὲν δή τις, ὡς ἐθέλοι, συγκρίνειν ἔχει· Μάλλιος δὲ ὁ τοῦ Σκιπίωνος διάδοχος τὴν ἀφαιρεθεῖσαν Ἀντιόχου γῆν ἐπιὼν καθίστατο, καὶ Γαλατῶν τῶν Ἀντιόχῳ συμμαχησάντων Τολιστοβοίους, ἀναφυγόντας ἐς τὸν Μύσιον Ὄλυμπον, ἐπιμόχθως τοῦ ὄρους ἐπιβὰς ἐτρέπετο φεύγοντας, ἕως ἔκτεινε καὶ κατεκρήμνισεν ὅσους ἀριθμήσασθαι διὰ τὸ πλῆθος οὐκ ἐγένετο, αἰχμαλώτους δ’ ἔλαβεν ἐς τετρακισμυρίους, ὧν τὰ μὲν ὅπλα κατέκαυσε, τὰ δὲ σώματα, οὐ δυνάμενος τοσόνδε πλῆθος ἐν πολέμοις περιάγεσθαι, τοῖς ἐγγὺς βαρβάροις ἀπέδοτο. ἐν δὲ Τεκτοσάγαις τε καὶ Τρόκμοις ἐκινδύνευσε μὲν ἐξ ἐνέδρας, καὶ ἔφυγεν· ἐπανελθὼν δὲ ἐς αὐλιζομένους τε καὶ βεβυσμένους ὑπὸ πλήθους περιέστησε τοὺς ψιλοὺς αὐτοῖς, καὶ περιτρέχων ἐκέλευεν ἐσακοντίζειν μήτε προσπλεκομένους μήτε πλησιάζοντας. οὐδενὸς δὲ βέλους ἀτυχοῦντος διὰ τὴν πυκνότητα τῶν πολεμίων, ἔκτεινεν ἐς ὀκτακισχιλίους, καὶ ἐδίωξε τοὺς λοιποὺς ὑπὲρ Ἅλυν ποταμόν. Ἀριαράθου δὲ τοῦ Καππαδοκῶν βασιλέως, καὶ τοῦδε συμμάχους πέμψαντος Ἀντιόχῳ, δεδιότος τε καὶ δεομένου καὶ διακόσια τάλαντα πέμψαντος ἐπὶ τῇ δεήσει τὴν χώραν οὐκ ἐπέδραμεν, ἀλλ’ ἐς τὸν Ἑλλήσποντον ἐπανῆλθε σὺν γάζῃ τε πολλῇ καὶ χρήμασιν ἀπείροις καὶ λείᾳ βαρυτάτῃ καὶ στρατῷ καταγόμῳ.", "st": "4.42"}, {"sp": "N", "t": "τάδε μὲν καλῶς ἐπέπρακτο τῷ Μαλλίῳ· τὸ δ’ ἐντεῦθεν ἀλόγως πάμπαν ὥρᾳ θέρους πλεῦσαι μὲν ὑπερεῖδεν, οὔτε τὸ βάρος ὧν ἐπήγετο ποιησάμενος ἐνθύμιον, οὔτ’ ἐπειγόμενος διαπονεῖν ἢ γυμνάζειν ὁδοιπορίαις ἔτι στρατὸν οὐκ ἐς πόλεμον ὁρμῶντα ἀλλ’ ἐς οἰκείαν μετὰ λαφύρων ἐπανιόντα, διὰ δὲ Θρᾴκης ὥδευε, στενὴν καὶ μακρὰν καὶ δύσβατον ὁδόν, πνίγους ὥρᾳ, οὔτ’ ἐς Μακεδονίαν Φιλίππῳ προεπιστείλας ἀπαντᾶν, ἵνα παραπέμψειεν αὐτόν, οὔτε τὸν στρατὸν ἐς μέρη πολλὰ διελών, ἵνα κουφότερον βαδίζοι καὶ τὰ χρήσιμα εὐμαρέστερα ἔχοι, οὔτε τὰ σκευοφόρα συντάξας ἐς λόχους ὀρθίους, ἵν’ εὐφυλακτότερα ᾖ. ἀλλ’ ἀθρόως ἦγεν ἅπαντας ἐπὶ μῆκος πολύ, καὶ τὰ σκευοφόρα εἶχεν ἐν μέσῳ, μήτε τῶν πρόσθεν αὐτοῖς δυναμένων ἐπικουρεῖν μήτε τῶν ὄπισθεν ὀξέως διὰ μῆκος ὁμοῦ καὶ στενότητα τῆς ὁδοῦ. ὅθεν αὐτῷ πανταχόθεν ἐς τὰ πλάγια τῶν Θρᾳκῶν ἐπικειμένων, πολὺ μέρος ἀπώλεσε τῆς τε λείας καὶ τῶν δημοσίων χρημάτων καὶ αὐτοῦ δὴ τοῦ στρατοῦ. μετὰ δὲ τῶν ὑπολοίπων ἐς Μακεδονίαν διεσώθη. ᾧ δὴ καὶ μάλιστα ἐγένετο καταφανὲς ὅσον ὤνησε παραπέμπων τοὺς Σκιπίωνας ὁ Φίλιππος, καὶ ὅσον ἥμαρτεν Ἀντίοχος ἐκλιπὼν τὴν Χερρόνησον. ὁ δὲ Μάλλιος ἔκ τε Μακεδονίας Θεσσαλίαν διελθὼν καὶ ἐκ Θεσσαλίας Ἤπειρον ἐς Βρεντέσιον ἐπέρα, καὶ τὴν λοιπὴν στρατιὰν ἐς τὰ οἰκεῖα διαφεὶς ἐπανῆλθεν ἐς Ῥώμην.", "st": "4.43"}, {"sp": "N", "t": "Ῥόδιοι δὲ καὶ Εὐμένης ὁ Περγάμου βασιλεὺς μέγα φρονοῦντες ἐπὶ τῇ κατ’ Ἀντιόχου συμμαχίᾳ, Εὐμένης μὲν αὐτὸς ἐς Ῥώμην ἐστέλλετο, Ῥόδιοι δὲ πρέσβεις ἔπεμπον. ἡ βουλὴ δὲ Ῥοδίοις μὲν ἔδωκε Λυκίους τε καὶ Κᾶρας, οὓς οὐ πολὺ ὕστερον ἀπέστησεν αὐτῶν ὡς Περσεῖ τῷ Μακεδόνι μᾶλλον ἢ σφίσι πολεμοῦσι τῷ Περσεῖ προθυμοτέρων γενομένων, Εὐμένει δὲ παρέσχον ὅσα λοιπὰ ἀφῄρηντο Ἀντίοχον, χωρὶς Ἑλλήνων τῶν ἐν αὐτοῖς. τούτων δὲ ὅσοι μὲν Ἀττάλῳ τῷ πατρὶ Εὐμένους ἐτέλουν φόρους, ἐκέλευσαν Εὐμένει συμφέρειν, ὅσοι δ’ Ἀντιόχῳ πρῶτον ἐτέλουν, ἀπέλυσαν τῶν φόρων καὶ αὐτονόμους ἀφῆκαν.", "st": "4.44"}, {"sp": "N", "t": "ὧδε μὲν Ρωμαῖοι διέθεντο τὰ δορίκτητα, Ἀντιόχου δ’ ὕστερον τοῦ μεγάλου βασιλέως τελευτήσαντος γίγνεται Σέλευκος ὁ υἱὸς διάδοχος· καὶ τὸν ἀδελφὸν ὅδε Ἀντίοχον ἐξέλυσε τῆς ὑπὸ Ῥωμαίοις ὁμηρείας, ἀντιδοὺς τὸν ἑαυτοῦ παῖδα Δημήτριον. Ἀντιόχου δ’ ἐπανιόντος ἐκ τῆς ὁμηρείας καὶ ὄντος ἔτι περὶ Ἀθήνας, ὁ μὲν Σέλευκος ἐξ ἐπιβουλῆς Ἡλιοδώρου τινὸς τῶν περὶ τὴν αὐλὴν ἀποθνήσκει, τὸν δ’ Ἡλιόδωρον Εὐμένης καὶ Ἄτταλος ἐς τὴν ἀρχὴν βιαζόμενον ἐκβάλλουσι, καὶ τὸν Ἀντίοχον ἐς αὐτὴν κατάγουσιν, ἑταιριζόμενοι τὸν ἄνδρα· ἀπὸ γὰρ τινῶν προσκρουμάτων ἤδη καὶ οἵδε Ῥωμαίους ὑπεβλέποντο. οὕτω μὲν Ἀντίοχος ὁ Αντιόχου τοῦ μεγάλου Συρίας ἐπεκράτησεν· ὅτῳ παρὰ τῶν Σύρων ἐπώνυμον ἦν ἐπιφανής, ὅτι τῆς ἀρχῆς ἁρπαζομένης ὑπὸ ἀλλοτρίων βασιλεὺς οἰκεῖος ὤφθη. συνθέμενος δὲ φιλίαν καὶ συμμαχίαν Εὐμένει, Συρίας καὶ τῶν περὶ αὐτὴν ἐθνῶν ἐγκρατῶς ἦρχε, σατράπην μὲν ἔχων ἐν Βαβυλῶνι Τίμαρχον, ἐπὶ δὲ ταῖς προσόδοις Ἡρακλείδην, ἀδελφὼ μὲν ἀλλήλοιν, ἄμφω δὲ αὐτοῦ γενομένω παιδικά. ἐστράτευσε δὲ καὶ ἐπὶ Ἀρταξίαν τὸν Ἀρμενίων βασιλέα.", "st": "4.45"}, {"sp": "N", "t": "καὶ αὐτὸν ἑλὼν ἐτελεύτησεν, ἐνναετὲς παιδίον ἀπολιπών, Ἀντίοχον, ᾧ προσέθηκαν ὄνομα εὐπάτωρ οἱ Σύροι διὰ τὴν τοῦ πατρὸς ἀρετήν. καὶ τὸ παιδίον ἔτρεφε Λυσίας. ἡ δὲ σύγκλητος ἥσθη φανέντος ἐν ὀλίγῳ τοῦ Ἀντιόχου γεννικοῦ καὶ ταχέως ἀποθανόντος. Δημήτριόν τε τὸν Σελεύκου μὲν υἱὸν Ἀντιόχου δὲ τοῦ ἐπιφανοῦς ἀδελφιδοῦν, υἱωνὸν δὲ τοῦ μεγάλου Ἀντιόχου, ἀνεψιὸν ὄντα τῷδε τῷ παιδίῳ, ὁμηρεύοντα ἔτι ἐν Ῥώμῃ καὶ ἔτος ἄγοντα τρίτον ἐπὶ τοῖς εἴκοσιν, ἐς τὴν βασιλείαν καταχθῆναι παρακαλοῦντα ὡς αὑτῷ μᾶλλον προσήκουσαν, οὐ κατῆγον, οὐ συμφέρειν σφίσιν ἡγούμενοι τελειότερον ἄρχειν Σύρων ἀντὶ παιδὸς ἀτελοῦς. πυνθανόμενοι δ’ ἐν Συρίᾳ στρατόν τ’ ἐλεφάντων εἶναι καὶ ναῦς πλείονας τῶν ὡρισμένων Ἀντιόχῳ, πρέσβεις ἔπεμπον, οἳ τοὺς ἐλέφαντας συγκόψειν ἔμελλον καὶ τὰς ναῦς διαπρήσειν. οἰκτρὰ δὲ ἡ ὄψις ἦν ἀναιρουμένων θηρίων ἡμέρων τε καὶ σπανίων, καὶ νεῶν ἐμπιπραμένων· καί τις ἐν Λαοδικείᾳ Λεπτίνης τὴν ὄψιν οὐκ ἐνεγκών, Γναῖον Ὀκτάουιον τὸν τῶνδε τῶν πρέσβεων ἡγεμόνα, ἀλειφόμενον ἐν τῷ γυμνασίῳ, διεχρήσατο.", "st": "4.46"}, {"sp": "N", "t": "καὶ τὸν μὲν Ὀκτάουιον ἔθαπτεν ὁ Λυσίας,", "st": "4.46"}, {"sp": "N", "t": "Δημήτριος δὲ αὖθις ἐς τὴν σύγκλητον ἐσελθὼν ἐδεῖτο τῆς γοῦν ὁμηρείας μόνης ἀπολυθῆναι, ὡς Ἀντιόχου μὲν ἀντιδοθείς, Ἀντιόχου δ’ ἀποθανόντος. ἐπεὶ δ’ οὐκ ἐτύγχανεν οὐδὲ τοῦδε, λαθὼν ἐξέπλευσε, καὶ δεξαμένων αὐτὸν ἀσμένως τῶν Σύρων ἦρχε, τόν τε Λυσίαν καὶ τὸ παιδίον ἐπ’ αὐτῷ διαφθείρας, καὶ Ἡρακλείδην ἐκβαλών, καὶ Τίμαρχον ἐπανιστάμενον ἀνελών, καὶ τἆλλα πονηρῶς τῆς Βαβυλῶνος ἡγούμενον· ἐφ’ ᾧ καὶ σωτήρ, ἀρξαμένων τῶν Βαβυλωνίων, ὠνομάσθη. κρατυνάμενος δὲ τὴν ἀρχὴν ὁ Δημήτριος στέφανόν τε Ῥωμαίοις ἀπὸ χρυσῶν μυρίων, χαριστήριον τῆς ποτὲ παρ’ αὐτοῖς ὁμηρείας, καὶ Λεπτίνην τὸν ἀνδροφόνον Ὀκταουίου. οἱ δὲ τὸν μὲν στέφανον ἐδέχοντο, Λεπτίνην δὲ οὐκ ἔλαβον, ὡς δή τι τοῦτ’ ἔγκλημα τοῖς Σύροις ταμιευόμενοι. Δημήτριος δὲ καὶ ἐκ τῆς Καππαδοκῶν ἀρχῆς Ἀριαράθην ἐκβαλών, Ὀλοφέρνην ἐπὶ χιλίοις ταλάντοις ἀντ’ αὐτοῦ κατήγαγεν, ἀδελφὸν εἶναι δοκοῦντα Ἀριαράθου. καὶ Ῥωμαίοις ἐδόκει μέν, ὡς ἀδελφούς, Ἀριαράθην καὶ Ὀλοφέρνην βασιλεύειν ὁμοῦ.", "st": "4.47"}, {"sp": "N", "t": "ἐκπεσόντων δὲ καὶ τῶνδε καὶ Ἀριοβαρζάνου μετ’ αὐτοὺς οὐ πολὺ ὕστερον ὑπὸ Μιθριδάτου τοῦ Ποντικοῦ βασιλέως, ὁ Μιθριδάτειος πόλεμος ἐπὶ τῷδε καὶ ἐφ’ ἑτέροις ἤρξατο συνίστασθαι, μέγιστός τε καὶ πολυτροπώτατος ἔθνεσι πολλοῖς γενόμενος, καὶ παρατείνας ἐς ἔτη μάλιστα τεσσαράκοντα, ἐν οἷς πολλαὶ μὲν ἀρχαὶ Σύροις ἐκ τοῦ βασιλείου γένους ὀλιγοχρόνιοι πάμπαν ἐγένοντο, πολλαὶ δὲ τροπαὶ καὶ ἐπαναστάσεις ἐπὶ τὰ βασίλεια. Παρθυαῖοί τε προαποστάντες ἀπὸ τῆς τῶν Σελευκιδῶν ἀρχῆς Μεσοποταμίαν ἐς ἑαυτοὺς περιέσπασαν, ἣ τοῖς Σελευκίδαις ὑπήκουεν. καὶ βασιλεὺς Ἀρμενίας Τιγράνης ὁ Τιγράνους ἔθνη πολλὰ τῶν περιοίκων ἰδίοις δυνάσταις χρώμενα ἑλών, βασιλεὺς ἀπὸ τοῦδε βασιλέων ἡγεῖτο εἶναι, καὶ τοῖς Σελευκίδαις ἐπεστράτευεν οὐκ ἐθέλουσιν ὑπακούειν. οὐχ ὑποστάντος δ’ αὐτὸν Ἀντιόχου τοῦ εὐσεβοῦς, ὁ Τιγράνης ἦρχε Συρίας τῆς μετ’ Εὐφράτην, ὅσα γένη Σύρων μέχρι Αἰγύπτου. ἦρχε δὲ ὁμοῦ καὶ Κιλικίας (καὶ γὰρ ἥδε τοῖς Σελευκίδαις ὑπήκουε), Μαγαδάτην στρατηγὸν ἐπιτάξας ἅπασιν, ἐπὶ ἔτη τεσσαρεσκαίδεκα.", "st": "4.48"}, {"sp": "N", "t": "Λευκόλλου δὲ τοῦ Ῥωμαίων στρατηγοῦ Μιθριδάτην διώκοντος ἐς τὸν Τιγράνην ὑποφεύγοντα, ὁ Μαγαδάτης ᾔει μετὰ τοῦ στρατοῦ Τιγράνῃ βοηθήσων, καὶ ἐν τῷδε παραδὺς ἐς τὴν Συρίαν Ἀντίοχος ὁ Ἀντιόχου τοῦ εὐσεβοῦς ἦρχε τῶν Σύρων ἑκόντων. καὶ αὐτῷ Λεύκολλος μέν, ὁ Τιγράνῃ πρῶτός τε πολεμήσας καὶ τῆς ἐπικτήτου γῆς αὐτὸν ἐξελάσας, οὐκ ἐφθόνησεν ἀρχῆς πατρῴας· Πομπήιος δέ, ὁ ἐπὶ Λευκόλλῳ Μιθριδάτην ἐξελών, Τιγράνῃ μὲν Ἀρμενίας συνεχώρησεν ἄρχειν, Ἀντίοχον δὲ ἐξέβαλε τῆς Σύρων ἀρχῆς, οὐδὲν ἐς Ῥωμαίους ἁμαρτόντα, ἔργῳ μὲν ὅτι ἦν εὔκολον αὐτῷ, στρατιὰν ἔχοντι, πολλὴν ἀρχὴν ἄνοπλον ἀφελέσθαι, λόγῳ δὲ ὅτι τοὺς Σελευκίδας, ὑπὸ Τιγράνους ἐκπεσόντας, οὐκ εἰκὸς ἦν ἔτι Συρίας ἄρχειν μᾶλλον ἢ Ῥωμαίους Τιγράνην νενικηκότας.", "st": "4.49"}, {"sp": "N", "t": "οὕτω μὲν δὴ Κιλικίας τε καὶ Συρίας τῆς τε μεσογείου καὶ κοίλης καὶ Φοινίκης καὶ Παλαιστίνης, καὶ ὅσα ἄλλα Συρίας ἀπὸ Εὐφράτου μέχρι Αἰγύπτου καὶ μέχρι θαλάσσης ὀνόματα, ἀμαχὶ Ῥωμαῖοι κατέσχον. ἓν δὲ γένος ἔτι τὸ Ἰουδαίων ἐνιστάμενον ὁ Πομπήιος ἐξεῖλε κατὰ κράτος, καὶ τὸν βασιλέα Ἀριστόβουλον ἔπεμψεν ἐς Ῥώμην, καὶ τὴν μεγίστην πόλιν Ἱεροσόλυμα καὶ ἁγιωτάτην αὐτοῖς κατέσκαψεν, ἣν δὴ καὶ Πτολεμαῖος ὁ πρῶτος Αἰγύπτου βασιλεὺς καθῃρήκει, καὶ Οὐεσπασιανὸς αὖθις οἰκισθεῖσαν κατέσκαψε, καὶ Ἀδριανὸς αὖθις ἐπ’ ἐμοῦ. καὶ διὰ ταῦτ’ ἐστὶν Ἰουδαίοις ἅπασιν ὁ φόρος τῶν σωμάτων βαρύτερος τῆς ἄλλης περιοικίας. ἔστι δὲ καὶ Σύροις καὶ Κίλιξιν ἐτήσιος, ἑκατοστὴ τοῦ τιμήματος ἑκάστῳ. Πομπήιος μὲν οὖν τῶνδε τῶν ὑπὸ τοῖς Σελευκίδαις γενομένων ἐθνῶν τοῖς μὲν … ἐπέστησεν οἰκείους βασιλέας ἢ δυνάστας, καθὰ καὶ Γαλατῶν τῶν ἐν Ἀσίᾳ τοῖς τέσσαρσι δυνάσταις ἐβεβαίωσε τὰς τετραδαρχίας, συμμαχήσασίν οἱ κατὰ Μιθριδάτου. καὶ οὐ πολὺ ὕστερον καὶ τάδε περιῆλθεν ἐς Ῥωμαίους, ἐπὶ Καίσαρος μάλιστα τοῦ Σεβαστοῦ, κατὰ μέρη.", "st": "4.50"}, {"sp": "N", "t": "Συρίας δ’ εὐθὺς ὁ Πομπήιος Σκαῦρον τὸν ἐν τοῖς πολέμοις ἑαυτῷ γενόμενον ταμίαν ἔταξεν ἡγεῖσθαι, καὶ ἡ βουλὴ Φίλιππον ἐπὶ Σκαύρῳ τὸν Μάρκιον, καὶ Μαρκελλῖνον Λέντλον ἐπὶ τῷ Φιλίππῳ, ἄμφω στρατηγικοὺς κατ’ ἀξίωσιν. ἀλλὰ τῶνδε μὲν ἑκατέρῳ διετὴς ἐτρίφθη χρόνος, τοὺς γειτονας ἐνοχλοῦντας Ἄραβας ἀμυνομένῳ. καὶ τοῦδε χάριν ἐς τὸ ἔπειτα ἐγένοντο Συρίας στρατηγοὶ τῶν τὰ ἐπώνυμα ἀρξάντων ἐν ἄστει, ἵνα ἔχοιεν ἐξουσίαν καταλόγου τε στρατιᾶς καὶ πολέμου οἷα ὕπατοι. καὶ πρῶτος ἐκ τῶνδε ἐπέμφθη Γαβίνιος μετὰ στρατιᾶς. καὶ πολεμεῖν αὐτὸν ὁρμῶντα Μιθριδάτης μὲν ὁ Παρθυαίων βασιλεύς, ἐξελαυνόμενος τῆς ἀρχῆς ὑπ’ Ὀρώδου τοῦ ἀδελφοῦ, μετῆγεν ἐξ Ἀράβων ἐπὶ Παρθυαίους, Πτολεμαῖος δὲ αὐτόν, ὁ ἑνδέκατος Αἰγύπτου βασιλεύς, ἐκπεσὼν καὶ ὅδε τῆς ἀρχῆς, μετέπεισε χρήμασι πολλοῖς ἀντὶ Παρθυαίων ἐπὶ Ἀλεξανδρέας ὁρμῆσαι. καὶ κατήγαγε μὲν τὸν Πτολεμαῖον ἐπὶ τὴν ἀρχὴν ὁ Γαβίνιος, Ἀλεξανδρεῦσι πολεμήσας, ὑπὸ δὲ τῆς Ῥωμαίων βουλῆς ἔφυγεν ἐπὶ τῷ ἄνευ ψηφίσματος ἐς Αἴγυπτον ἐμβαλεῖν, ἐπὶ πολέμῳ Ῥωμαίοις ἀπαισίῳ νομιζομένῳ· ἦν γάρ τι Σιβύλλειον αὐτοῖς ἀπαγορεῦον. ἐπὶ δὲ Γαβινίῳ μοι δοκεῖ Κράσσος ἄρξαι Σύρων, ὅτῳ πολεμούντι Παρθυαίοις ἡ μεγάλη συμφορὰ γίγνεται. καὶ ἐπὶ Λευκίου Βύβλου μετὰ Κράσσον στρατηγοῦντος Συρίας ἐς τὴν Συρίαν ἐσέβαλον οἱ Παρθυαῖοι. Σάξα δὲ μετὰ Βύβλον ἡγουμένου καὶ τὰ μέχρι Ἰωνίας ἐπέδραμον, ἀσχολουμένων Ῥωμαίων ἐς τὰ ἐπ’ ἀλλήλους ἐμφύλια.", "st": "4.51"}, {"sp": "N", "t": "ἀλλὰ τάδε μὲν ἐντελῶς ἐν τῇ Παρθικῇ συγγραφῇ λέξω· τῆς δὲ βίβλου τῆσδε οὔσης Συριακῆς, ὅπως μὲν ἔσχον Συρίαν Ῥωμαῖοι καὶ συνέστησαν ἐς τὰ νῦν ὄντα, εἴρηται, οὐκ ἀπεικὸς δὲ τὰ Μακεδόνων ἐπιδραμεῖν. οἳ πρὸ Ῥωμαίων Συρίας ἐβασίλευον.", "st": "4.52"}, {"sp": "N", "t": "Ἀλέξανδρος μὲν δὴ βασιλεὺς ἦν ἐπὶ Πέρσαις Σύρων, ὁ καὶ πάντων βασιλεὺς ὅσων εἶδεν· Ἀλεξάνδρου δ’ ἀποθανόντος ἐπὶ παισὶ τῷ μὲν βραχεῖ πάνυ τῷ δὲ ἔτι κυϊσκομένῳ, οἱ μὲν Μακεδόνες, πόθῳ τοῦ Φιλιππείου γένους, εἵλοντο σφῶν βασιλεύειν Ἀριδαῖον τὸν ἀδελφὸν Ἀλεξάνδρου, καίπερ οὐκ ἔμφρονα νομιζόμενον εἶναι, μετονομάσαντες δὴ Φίλιππον ἀντὶ Ἀριδαίου, τρεφομένων ἔτι τῶν παίδων Ἀλεξάνδρου ἐφύλαξαν γὰρ δὴ καὶ τὴν κύουσαν), οἱ φίλοι δ’ ἐς σατραπείας ἐνείμαντο τὰ ἔθνη, Περδίκκου διανέμοντος αὐτοῖς ὑπὸ τῷ βασιλεῖ Φιλίππῳ. καὶ οὐ πολὺ ὕστερον τῶν βασιλέων ἀποθανόντων βασιλεῖς ἐγένοντο οἱ σατράπαι. Σύρων δὴ πρῶτος γίγνεται σατράπης Λαομέδων ὁ Μιτυληναῖος ἔκ τε Περδίκκου καὶ ἐξ Ἀντιπάτρου τοῦ μετὰ τὸν Περδίκκαν προστατεύσαντος τῶν βασιλέων. Λαομέδοντα δ’ ἐπιπλεύσας Πτολεμαῖος ὁ τῆς Αἰγύπτου σατράπης ἔπειθε πολλοῖς χρήμασιν ἐγχειρίσαι οἱ τὴν Συρίαν, προβολήν τε οὖσαν Αἰγύπτου καὶ ἐπιχείρημα κατὰ Κύπρου. καὶ οὐ πειθόμενον συλλαμβάνει· ὁ δὲ τοὺς φύλακας διαφθείρας πρὸς Ἀλκέταν ἔφυγεν ἐς Καρίαν. καί τινα χρόνον ὁ Πτολεμαῖος ἦρχε Συρίας, καὶ φρουρὰς ἐν ταῖς πόλεσι καταλιπὼν ἐς Αἴγυπτον ἀπέπλει.", "st": "4.52"}, {"sp": "N", "t": "Ἀντίγονος δ’ ἦν Φρυγίας μὲν καὶ Λυκίας καὶ Παμφυλίας σατράπης, ἐπίσκοπος δ’ εἶναι τῆς ὅλης Ἀσίας ἐξ Ἀντιπάτρου περῶντος ἐς τὴν Εὐρώπην ἀπολελειμμένος Εὐμένη τὸν Καππαδοκίας σατράπήν, ψηφισαμένων εἶναι πολέμιον τῶν Μακεδόνων, ἐπολιόρκει. ὁ δὲ αὐτὸν ἐκφεύγει, καὶ τὴν Μηδικὴν ἐκρατύνετο ἑαυτῷ. ἀλλ’ Εὐμένη μὲν κτείνει καταλαβὼν ὁ Ἀντίγονος, καὶ ἐπανιὼν ὑπεδέχθη λαμπρῶς ὑπὸ Σελεύκου σατραπεύοντος ἐν Βαβυλῶνι. ὑβρίσαντος δέ τινα τῶν ἡγεμόνων τοῦ Σελεύκου, καὶ οὐ κοινώσαντος Ἀντιγόνῳ παρόντι, χαλεπήνας ὁ Ἀντίγονος ᾔτει λογισμοὺς χρημάτων τε καὶ κτημάτων. ὁ δὲ ἀσθενέστερος ὢν Ἀντίγονου πρὸς Πτολεμαῖον ἐς Αἴγυπτον ὑπεχώρει. καὶ ὁ Ἀντίγονος εὐθὺς ἐπὶ τῇ φυγῇ τοῦ Σελεύκου Βλίτορά τε, Μεσοποταμίας ἡγούμενον, παρέλυσε τῆς ἀρχῆς, ὅτι Σέλευκον μεθῆκεν ἀπιόντα, καὶ τὴν Βαβυλωνίαν καὶ τὴν Μεσοποταμίαν καὶ ὅσα ἄλλα ἐκ Μήδων ἐπὶ τὸν Ἑλλήσποντον ἔθνη, καθίστατο ἑαυτῷ, ἤδη καὶ Ἀντιπάτρου τεθνεῶτος. ἐπίφθονός τε εὐθὺς ἐκ τῶνδε τοῖς ἄλλοῖς σατράπαις ἐγίγνετο, γῆς ἄρχων τοσῆσδε. διὸ καὶ μάλιστα τῷ Σελεύκῳ παρακαλοῦντι συνέθεντο Πτολεμαῖός τε καὶ Λυσίμαχος ὁ Θρᾴκης σατράπης καὶ Κάσσανδρος ὁ Ἀντιπάτρου, Μακεδόνων ἐπὶ τῷ πατρὶ ἡγούμενος· καὶ ὁμοῦ πρεσβευσάμενοι τὸν Ἀντίγονον ἠξίουν τὴν ἐπίκτητον αὐτῷ γενομένην γῆν τε καὶ χρήματα πρός τε σφᾶς νείμασθαι καὶ πρὸς ἑτέρους Μακεδόνας, οἳ τῶν σατραπειῶν ἐξεπεπτώκεσαν. ἐπιχλευάσαντος δὲ αὐτοὺς τοῦ Ἀντιγόνου οἱ μὲν ἐς πόλεμον καθίσταντο κοινόν, ὁ δὲ ἀντιπαρεσκευάζετο, καὶ ἐξέβαλλε τὰς φρουρὰς ὅσαι ἔτι ἦσαν ἐν τῇ Συρίᾳ Πτολεμαίου, καὶ Φοινίκης τε καὶ τῆς λεγομένης κοίλης τὰ ἔτι ὑπήκοα τοῦ Πτολεμαίου πρὸς ἑαυτὸν ἀθρόως περιέσπα.", "st": "4.53"}, {"sp": "N", "t": "χωρῶν δ’ ὑπὲρ τὰς Κιλικίους πύλας, Δημήτριον τὸν υἱόν, ἀμφὶ δύο καὶ εἴκοσιν ἔτη γεγονότα, ἐν Γάζῃ μετὰ τοῦ στρατοῦ καταλείπει πρὸς τὰς ὁρμὰς Πτολεμαίου τὰς ἀπ’ Αἰγύπτου. τοῦτον ὁ Πτολεμαῖος ἐνίκα περὶ τὴν Γάζαν μάχῃ λαμπρῶς, καὶ τὸ μειράκιον ἐς τὸν πατέρα ἐχώρει. Πτολεμαῖος δ’ αὐτίκα τὸν Σέλευκον ἐς τῆν Βαβυλῶνα πέμπει, τὴν ἀρχὴν ἀναληψόμενον· καὶ πεζοὺς ἐς τοῦτο ἔδωκεν αὐτῷ χιλίους, καὶ τριακοσίους ἱππέας. καὶ σὺν οὕτως ὀλίγοις ὁ Σέλευκος τήν τε Βαβυλωνίαν, προθύμως αὐτὸν ἅμα τῶν ἀνδρῶν ἐκδεχομένων, ἀνέλαβε, καὶ τὴν ἀρχὴν μετ’ οὐ πολὺ ἐς μέγα προήγαγεν. ὁ δ’ Ἀντίγονος Πτολεμαῖον ἠμύνετο, καὶ ναυμαχίᾳ περὶ Κύπρον ἐνίκα περιφανεῖ, Δημητρίου τοῦ παιδὸς στρατηγοῦντος· ἐφ’ ὅτῳ λαμπροτάτῳ γενομένῳ ὁ στρατὸς ἀνεῖπεν ἄμφω βασιλέας, Ἀντίγονόν τε καὶ Δημήτριον, ἤδη καὶ τῶν βασιλέων τεθνεώτων, Ἀριδαίου τε τοῦ Φιλίππου καὶ Ὀλυμπιάδος καὶ τῶν υἱῶν Ἀλεξάνδρου. ἀνεῖπε δὲ καὶ Πτολεμαῖον ὁ οἰκεῖος αὐτοῦ στρατὸς βασιλέα, ὡς μή τι διὰ τὴν ἧσσαν μειονεκτοίη τῶν νενικηκότων. τοῖσδε μὲν δὴ τυχεῖν ὁμοίων συνηνέχθη κατ’ ἐναντίας αἰτίας, εἵποντο δ’ εὐθὺς αὐτοῖς οἱ λοιποί, καὶ βασιλεῖς ἅπαντες ἐκ σατραπῶν ἐγίγνοντο.", "st": "4.54"}, {"sp": "N", "t": "οὕτω δὴ καὶ ὁ Σέλευκος ἐβασίλευσε τῆς Βαβυλωνίας. ἐβασίλευσε δὲ καὶ Μηδίας, Νικάτορα κτείνας αὐτὸς ἐν τῇ μάχῃ, τὸν ὑπ’ Ἀντιγόνου Μηδίας σατραπεύειν ἀπολελειμμένον. πολέμους δ’ ἐπολέμησε πολλοὺς Μακεδόσι καὶ βαρβάροις, καὶ τούτων Μακεδόσι μὲν δύο μεγίστους, τὸν μὲν ὕστερον Λυσιμάχῳ βασιλεύοντι Θρᾴκης, τὸν δὲ πρότερον Ἀντιγόνῳ περὶ Ἴψον τῆς Φρυγίας, αὐτῷ στρατηγοῦντι καὶ αὐτῷ μαχομένῳ, καίπερ ὑπὲρ ὀγδοήκοντα ἔτη γεγονότι. πεσόντος δ’ Ἀντιγόνου κατὰ τὴν μάχην, ὅσοι βασιλεῖς τὸν Ἀντίγονον ἅμα τῷ Σελεύκῳ καθῃρήκεσαν, τὴν Ἀντιγόνου γῆν διενέμοντο. καὶ ὁ Σέλευκος τότε τῆς μετ’ Εὐφράτην Συρίας ἐπὶ θαλάσσῃ καὶ Φρυγίας τῆς ἀνὰ τὸ μεσόγειον ἄρχειν διέλαχεν. ἐφεδρεύων δὲ ἀεὶ τοῖς ἐγγὺς ἔθνεσι, καὶ δυνατὸς ὢν βιάσασθαι καὶ πιθανὸς προσαγαγέσθαι, ἦρξε Μεσοποταμίας καὶ Ἀρμενίας καὶ Καππαδοκίας τῆς Σελευκίδος λεγομένης καὶ Περσῶν καὶ Παρθυαίων καὶ Βακτρίων καὶ Ἀράβων καὶ Ταπύρων καὶ τῆς Σογδιανῆς καὶ Ἀραχωσίας καὶ Ὑρκανίας, καὶ ὅσα ἄλλα ὅμορα ἔθνη μέχρι Ἰνδοῦ ποταμοῦ Ἀλεξάνδρῳ ἐγεγένητο δορίληπτα, ὡς ὡρίσθαι τῷδε μάλιστα μετ’ Ἀλέξανδρον τῆς Ἀσίας τὸ πλέον· ἀπὸ γὰρ Φρυγίας ἐπὶ ποταμὸν Ἰνδὸν ἄνω πάντα Σελεύκῳ κατήκουεν. καὶ τὸν Ἰνδὸν περάσας ἐπολέμησεν Ἀνδροκόττῳ βασιλεῖ τῶν περὶ αὐτὸν Ἰνδῶν, μέχρι φιλίαν αὐτῷ καὶ κῆδος συνέθετο. καὶ τῶνδε τὰ μὲν πρὸ τῆς Ἀντιγόνου τελευτῆς, τὰ δὲ μετ’ Ἀντίγονον ἐποίησεν.", "st": "4.55"}, {"sp": "N", "t": "λέγεται δ’ αὐτῷ, στρατιώτῃ τοῦ βασιλέως ἔτι ὄντι καὶ ἐπὶ Πέρσας ἑπομένῳ, χρησμὸν ἐν Διδυμέως γενέσθαι πυνθανομένῳ περὶ τῆς ἐς Μακεδονίαν ἐπανόδου, “μὴ σπεῦδ’ Εὐρώπηνδ’. Ἀσίη τοι πολλὸν ἀμείνων.” καὶ ἐν Μακεδονίᾳ τὴν ἑστίαν αὐτῷ τὴν πατρῴαν, οὐδενὸς ἅψαντος, ἐκλάμψαι πῦρ μέγα. καὶ ὄναρ αὐτοῦ τὴν μητέρα ἰδεῖν, ὃν ἂν εὕροι δακτύλιον, δοῦναι φόρημα Σελεύκῳ, τὸν δὲ βασιλεύσειν ἔνθα ἂν ὁ δακτύλιος ἐκπέσῃ. καὶ ἡ μὲν ηὗρεν ἄγκυραν ἐν σιδήρῳ κεχαραγμένην, ὁ δὲ τὴν σφραγῖδα τήνδε ἀπώλεσε κατὰ τὸν Εὐφράτην. λέγεται καὶ ἐς τὴν Βαβυλωνίαν ἀπιόντα ὕστερον προσκόψαι λίθῳ, καὶ τὸν λίθον ἀνασκαφέντα ἄγκυραν ὀφθῆναι. θορυβουμένων δὲ τῶν μάντεων ὡς ἐπὶ συμβόλῳ κατοχῆς, Πτολεμαῖον τὸν Λάγου παραπέμποντα εἰπεῖν ἀσφαλείας τὴν ἄγκυραν, οὐ κατοχῆς εἶναι σύμβολον. καὶ Σελεύκῳ μὲν διὰ τοῦτο ἄρα καὶ βασιλεύσαντι ἡ σφραγὶς ἄγκυρα ἦν, δοκεῖ δέ τισι καὶ περιόντος ἔτι Ἀλεξάνδρου καὶ ἐφορῶντος ἕτερον τῷ Σελεύκῳ σημεῖον περὶ τῆς ἀρχῆς τοιόνδε γενέσθαι. Ἀλεξάνδρῳ γὰρ ἐξ Ἰνδῶν ἐς Βαβυλῶνα ἐπανελθόντι, καὶ τὰς ἐν αὐτῇ τῇ Βαβυλωνίᾳ λίμνας ἐπὶ χρείᾳ τοῦ τὸν Εὐφράτην τὴν Ἀσσυρίδα γῆν ἀρδεύειν περιπλέοντι, ἄνεμος ἐμπεσὼν ἥρπασε τὸ διάδημα, καὶ φερόμενον ἐκρεμάσθη δόνακος ἐν τάφῳ τινὸς ἀρχαίου βασιλέως. καὶ ἐσήμαινε μὲν ἐς τὴν τελευτὴν τοῦ βασιλέως καὶ τόδε, ναύτην δέ φασιν ἐκκολυμβήσαντα περιθέσθαι τῇ κεφαλῇ τὸ διάδημα καὶ ἐνεγκεῖν ἄβροχον Ἀλεξάνδρῳ, καὶ λαβεῖν τῆς προθυμίας αὐτίκα δωρεὰν παρὰ τοῦ βασιλέως τάλαντον ἀργυρίου· τῶν δὲ μάντεων αὐτὸν ἀναιρεῖν κελευόντων οἱ μὲν πεισθῆναι τὸν Ἀλέξανδρον αὐτοῖς, οἱ δὲ ἀντειπεῖν. εἰσὶ δὲ οἳ τάδε πάντα ὑπερελθόντες, οὐ ναύτην ὅλως φασὶν ἀλλὰ Σέλευκον ἐπὶ τὸ διάδημα τοῦ βασιλέως ἐκκολυμβῆσαι, καὶ περιθέσθαι Σέλευκον αὐτὸ τῇ κεφαλῇ, ἵν’ ἄβροχον εἴη. καὶ τὰ σημεῖα ἐς τέλος ἀμφοῖν ἀπαντῆσαι. Ἀλέξανδρόν τε γὰρ ἐν Βαβυλῶνι μεταστῆναι τοῦ βίου, καὶ Σέλευκον τῆς Ἀλεξάνδρου γῆς, ὅτι πλείστης μάλιστα τόνδε τῶν Ἀλεξάνδρου διαδόχων, βασιλεῦσαι.", "st": "4.56"}, {"sp": "N", "t": "τοσαῦτα μὲν δὴ περὶ τῶν Σελεύκῳ προμαντευθέντων ἐπυθόμην· γίγνεται δ’ εὐθὺς Ἀλεξάνδρου μεταστάντος ἡγεμὼν τῆς ἵππου τῆς ἑταιρικῆς ἧς δὴ καὶ Ἡφαιστίων ἡγήσατο Ἀλεξάνδρῳ καὶ ἐπὶ Ἡφαιστίωνι Περδίκκας, μετὰ δὲ τὴν ἵππον σατράπης τε τῆς Βαβυλωνίας καὶ βασιλεὺς ἐπὶ τῇ σατραπείᾳ. γενομένῳ δὲ αὐτῷ τὰ ἐς πολέμους ἐπιτυχεστάτῳ Νικάτωρ ἐπώνυμον γίγνεται· τῷδε γὰρ ἀρέσκομαι μᾶλλον τοῦ Νικάτορα κτεῖναι. καὶ τὸ σῶμα ὄντι εὐρώστῳ τε καὶ μεγάλῳ, καὶ ταῦρον ἄγριον ἐν Ἀλεξάνδρου θυσίᾳ ποτὲ ἐκθορόντα τῶν δεσμῶν ὑποστάντι μόνῳ καὶ ταῖς χερσὶ μόναις κατειργασμένῳ, προστιθέασιν ἐς τοὺς ἀνδριάντας ἐπὶ τῷδε κέρατα. πόλεις δὲ ᾤκισεν ἐπὶ τὸ μῆκος τῆς ἀρχῆς ὅλης ἑκκαίδεκα μὲν Ἀντιοχείας ἐπὶ τῷ πατρί, πέντε δὲ ἐπὶ τῇ μητρὶ Λαοδικείας, ἐννέα δ’ ἐπωνύμους ἑαυτοῦ, τέσσαρας δ’ ἐπὶ ταῖς γυναιξί, τρεῖς Ἀπαμείας καὶ Στρατονίκειαν μίαν. καὶ εἰσὶν αὐτῶν ἐπιφανέσταται καὶ νῦν Σελεύκειαι μὲν ἥ τε ἐπὶ τῇ θαλάσσῃ καὶ ἡ ἐπὶ τοῦ Τίγρητος ποταμοῦ, Λαοδίκεια δὲ ἡ ἐν τῇ Φοινίκῃ καὶ Ἀντιόχεια ἡ ὑπὸ τῷ Λιβάνῳ ὄρει καὶ ἡ τῆς Συρίας Ἀπάμεια. τὰς δὲ ἄλλας ἐκ τῆς Ἑλλάδος ἢ Μακεδονίας ὠνόμαζεν, ἢ ἐπὶ ἔργοις ἑαυτοῦ τισιν, ἢ ἐς τιμὴν Ἀλεξάνδρου τοῦ βασιλέως· ὅθεν ἔστιν ἐν τῇ Συρίᾳ καὶ τοῖς ὑπὲρ αὐτὴν ἄνω βαρβάροις πολλὰ μὲν Ἑλληνικῶν πολλὰ δὲ Μακεδονικῶν πολισμάτων ὀνόματα, Βέρροια, Ἔδεσσα, Πέρινθος, Μαρώνεια, Καλλίπολις, Ἀχαΐα, Πέλλα, Ὠρωπός, Ἀμφίπολις, Ἀρέθουσα, Ἀστακός, Τεγέα, Χαλκίς, Λάρισα, Ἥραια, Ἀπολλωνία, ἐν δὲ τῇ Παρθυηνῇ Σώτειρα, Καλλιόπη, Χάρις, Ἑκατόμπυλος, Ἀχαΐα, ἐν δ’ Ἰνδοῖς Ἀλεξανδρόπολις, ἐν δὲ Σκύθαις Ἀλεξανδρέσχατα. καὶ ἐπὶ ταῖς αὐτοῦ Σελεύκου νίκαις ἔστι Νικηφόριόν τε ἐν τῇ Μεσοποταμίᾳ καὶ Νικόπολις ἐν Ἀρμενίᾳ τῇ ἀγχοτάτω μάλιστα Καππαδοκίας.", "st": "4.57"}, {"sp": "N", "t": "φασὶ δὲ αὐτῷ τὰς Σελευκείας οἰκίζοντι, τὴν μὲν ἐπὶ τῇ θαλάσσῃ, διοσημίαν ἡγήσασθαι κεραυνοῦ, καὶ διὰ τοῦτο θεὸν αὐτοῖς κεραυνὸν ἔθετο, καὶ θρησκεύουσι καὶ ὑμνοῦσι καὶ νῦν κεραυνόν· ἐς δὲ τὴν ἐπὶ τοῦ Τίγρητος ἡμέραν ἐπιλέξασθαι τοὺς μάγους κελευομένους, καὶ τῆς ἡμέρας ὥραν, ᾗ τῶν θεμελίων ἄρξασθαι τῆς ὀρυχῆς ἔδει, ψεύσασθαι τὴν ὥραν τοὺς μάγους, οὐκ ἐθέλοντας ἐπιτείχισμα τοιόνδε σφίσι γενέσθαι. καὶ Σέλευκος μὲν ἐν τῇ σκηνῇ τὴν δεδομένην ὥραν ἀνέμενεν, ὁ δὲ στρατὸς ἐς τὸ ἔργον ἕτοιμος, ἀτρεμῶν ἔστε σημήνειεν ὁ Σέλευκος, ἄφνω κατὰ τὴν αἰσιωτέραν ὥραν δόξαντές τινα κελεύειν ἐπὶ τὸ ἔργον ἀνεπήδησαν, ὡς μηδὲ τῶν κηρύκων ἐρυκόντων ἔτι ἀνασχέσθαι. τὸ μὲν δὴ ἔργον ἐξετετέλεστο, Σελεύκῳ δὲ ἀθύμως ἔχοντι, καὶ τοὺς μάγους αὖθις ἀνακρίνοντι περὶ τῆς πόλεως, ἄδειαν αἰτήσαντες ἔλεγον οἱ μάγοι· “τὴν πεπρωμένην ὦ βασιλεῦ μοῖραν, χείρονά τε καὶ κρείσσονα, οὐκ ἔστιν οὔτε ἀνδρὸς οὔτε πόλεως ἐναλλάξαι. μοῖρα δέ τις καὶ πόλεών ἐστιν ὥσπερ ἀνδρῶν. καὶ τήνδε χρονιωτάτην μὲν ἐδόκει τοῖς θεοῖς γενέσθαι, ἀρχομένην ἐκ τῆσδε τῆς ὥρας ἧς ἐγένετο· δειμαίνοντες δ’ ἡμεῖς ὡς ἐπιτείχισμα ἡμῖν ἐσομένην, παρεφέρομεν τὸ πεπρωμένον. τὸ δὲ κρεῖσσον ἦν καὶ μάγων πανουργούντων καὶ βασιλέως ἀγνοοῦντος αὐτό. τοιγάρτοι τὸ δαιμόνιον τὰ αἰσιώτερα τῷ στρατῷ προσέταξεν. καὶ τοῦτο ἔνι σοι καταμαθεῖν ὧδε, ἵνα μή τι καὶ νῦν ἡμᾶς ἔτι τεχνάζειν ὑπονοῇς. αὐτός τε γὰρ ὁ βασιλεὺς σὺ τῷ στρατῷ παρεκάθησο, καὶ τὸ κέλευσμα αὐτὸς ἐδεδώκεις ἀναμένειν· καὶ ὁ εὐπειθέστατος ὤν σοι πρὸς κινδύνους καὶ πόνους οὐκ ἠνέσχετο νῦν οὐδὲ ἀναπαύσεως ἐπιτάγματος, ἀλλ’ ἀνέθορεν, οὐδὲ ἀνὰ μέρος ἀλλ’ ἀθρόως, ἐπιστάταις αὐτοῖς, καὶ ἐνόμιζε κεκελεῦσθαι. καὶ ἐκεκέλευστο δή· διόπερ οὐδὲ σοῦ κατερύκοντος αὐτοὺς ἔτι ἐπείθοντο. τί ἂν οὖν βασιλέως ἐν ἀνθρώποις εἴη καρτερώτερον ἄλλο θεοῦ; ὃς τῆς σῆς γνώμης ἐπεκράτησε, καὶ ἡγεμόνευσέ σοι τῆς πόλεως ἀντὶ ἡμῶν, δυσμεναίνων ἡμῖν τε καὶ γένει παντὶ τῷ περιοίκῳ. ποῦ γὰρ ἔτι τὰ ἡμέτερα ἰσχύσει, δυνατωτέρου γένους παρῳκισμένου; ἡ μὲν δὴ πόλις σοι γέγονε σὺν τύχῃ καὶ μεγιστεύσει καὶ χρόνιος ἔσται· σὺ δὲ ἡμῖν, ἐξαμαρτοῦσιν ὑπὸ δέους οἰκείων ἀγαθῶν ἀφαιρέσεως, τὴν συγγνώμην βεβαίου.” ταῦτα τῶν μάγων εἰπόντων ὁ βασιλεὺς ἥσθη καὶ συνέγνω.", "st": "4.58"}, {"sp": "N", "t": "τοιάδε μὲν ἐπυθόμην περὶ Σελευκείας· ὁ δὲ Σέλευκος τὸν υἱὸν Ἀντίοχον, περιὼν ἔτι, τῆς ἄνω γῆς βασιλεύειν ἀπέφηνεν ἀνθ’ ἑαυτοῦ. καὶ εἴ τῳ μεγαλόφρον εἶναι τόδε φαίνεται καὶ βασιλικόν, μεγαλοφρονέστερον ἔτι καὶ σοφώτερον ἤνεγκε τὸν ἔρωτα τοῦ παιδὸς καὶ τὴν ἐς τὸ πάθος αὐτοῦ σωφροσύνην. ἤρα μὲν γὰρ ὀ Ἀντίοχος Στρατονίκης τῆς αὐτοῦ Σελεύκου γυναικός, μητρυιᾶς οἱ γενομένης καὶ παῖδα ἤδη τῷ Σελεύκῳ πεποιημένης, συγγιγνώσκων δὲ τὴν ἀθεμιστίαν τοῦ πάθους οὔτε ἐπεχείρει τῷ κακῷ οὔτε προύφερεν, ἀλλ’ ἐνόσει καὶ παρεῖτο καὶ ἑκὼν ἐς τὸν θάνατον συνήργει. οὐδ’ ὁ περιώνυμος ἰατρὸς Ἐρασίστρατος, ἐπὶ μεγίσταις συντάξεσι Σελεύκῳ συνών, εἶχε τεκμήρασθαι τοῦ πάθους, μέχρι φυλάξας καθαρὸν ἐκ πάντων τὸ σῶμα, εἴκασεν εἶναι τῆς ψυχῆς τὴν νόσον, ᾗ δὴ καὶ ἐρρωμένῃ καὶ νοσούσῃ τὸ σῶμα συναίσθεται. λύπας μὲν οὖν καὶ ὀργὰς καὶ ἐπιθυμίας ἄλλας ὁμολογεῖσθαι, ἔρωτα δ’ ἐπικρύπτεσθαι πρὸς τῶν σωφρόνων. οὐδὲν δὲ οὐδ’ ὣς τοῦ Ἀντιόχου φράζοντος αὐτῷ λιπαροῦντι μαθεῖν ἐν ἀπορρήτῳ, παρεκαθέζετο καὶ ἐφύλασσε τὰς τοῦ σώματος μεταβολάς, ὅπως ἔχοι πρὸς ἕκαστον τῶν ἐσιόντων. ὡς δὲ ηὗρεν ἐπὶ μὲν τῶν ἄλλων σβεννύμενον ἀεὶ τὸ σῶμα καὶ μαραινόμενον ὁμαλῶς, ὅτε δὲ ἡ Στρατονίκη παρίοι πρὸς αὐτὸν ἐπισκεψομένη, τὴν μὲν γνώμην ὑπ’ αἰδοῦς καὶ συνειδότος τότε μάλιστα αὐτὸν ἐνοχλούμενον καὶ σιωπῶντα, τὸ δὲ σῶμα καὶ ἄκοντος αὐτοῦ θαλερώτερόν τε γιγνόμενον αὐτῷ καὶ ζωτικώτερον, καὶ αὖθις ἀπιούσης ἀσθενέστερον, ἔφη τῷ Σελεύκῳ τὸν υἱὸν ἀνιάτως ἔχειν αὐτῷ. ὑπεραλγήσαντος δὲ τοῦ βασιλέως καὶ ἐκβοήσαντος εἶπεν· “ἔρως ἔστὶ τὸ πάθος, καὶ ἔρως γυναικός, ἀλλ’ ἀδύνατος.”", "st": "4.59"}, {"sp": "N", "t": "Σελεύκου δὲ θαυμάσαντος εἴ τινα μὴ δύναιτο πεῖσαι Σέλευκος ὁ τῆς Ἀσίας βασιλεύς, ἐπὶ γάμῳ τοιοῦδε παιδός, ἱκεσίᾳ τε καὶ χρήμασι καὶ δωρεαῖς καὶ ὅλῃ τῇ τοσῇδε βασιλείᾳ, περιιούσῃ μὲν ἐς τόνδε τὸν κάμνοντα βασιλέα, δοθησομένῃ δὲ καὶ νῦν ἀντὶ τῆς σωτηρίας εἰ ἤδη τις ἐθέλοι, καὶ μόνον ἀξιοῦντος μαθεῖν τίς ἔστι τὸ γύναιον, ὁ Ἐρασίστρατος ἔφη· “τῆς ἐμῆς γυναικὸς ἐρᾷ.” καὶ ὁ Σέλευκος, “εἶτ’ ὦ?̓γαθέ,” ἔφη, “φιλίας μὲν οὕτω καὶ χαρίτων ἔχων ἐφ’ ἡμῖν, ἀρετῆς δὲ καὶ σοφίας ἐν ὀλίγοις, οὐ σώσεις μοι νέον ἄνδρα καὶ βασιλικόν, φίλου καὶ βασιλέως υἱόν, ἀτυχοῦντα καὶ σωφρονοῦντα καὶ τὸ κακὸν ἐπικρύπτοντα καὶ προτιμώμενον αὑτῷ θανάτου, ἀλλ’ ὑπερόψει μὲν οὕτως Ἀντιόχον, ὑπερόψει δ’ ἐπ’ αὐτῷ καὶ Σέλευκον;” ὁ δ’ ἀπομαχόμενος εἶπε λόγον ὡς ἄφυκτον, ὅτι μηδ’ ἂν σύ, καίπερ ὢν πατήρ, τῆς σῆς Ἀντιόχος εἰ ἤρα γυναικός, μεθῆκας ἂν αὐτῷ τὴν γυναῖκα. ἔνθα δὴ πάντας ὤμνυ τοὺς βασιλείους θεοὺς ὁ Σέλευκος, ἦ μὴν ἑκὼν ἂν καὶ χαίρων μεθεῖναι καὶ διήγημα γενέσθαι καλὸν εὐνοίας ἀγαθοῦ πατρὸς ἐς παῖδα σώφρονα καὶ ἐγκρατῆ τοῦ κακοῦ καὶ ἀνάξιον τῆς συμφορᾶς. πολλά τε ὅμοια ἐπενεγκών, ἤρξατο ἄχθεσθαι ὅτι μὴ αὐτὸς αὐτῷ γίγνοιτο ἰατρὸς ἀτυχοῦντι, ἀλλὰ καὶ ἐς ταῦτα δέοιτο Ἐρασιστράτου.", "st": "4.60"}, {"sp": "N", "t": "ὁ δ’ ἐπεὶ κατεῖδε τὴν ὁρμὴν τοῦ βασιλέως ἔργον ὑποφαίνουσαν, οὐχ ὑπόκρισιν, ἀνεκάλυπτε τὸ πάθος, καὶ ὅπως αὐτὸ εὕροι κρυπτόμενον διηγεῖτο. Σελεύκῳ δὲ ἡσθέντι ἔργον μὲν ἐγένετο πεῖσαι τὸν υἱόν, ἔργον δ’ ἐπ’ ἐκείνῳ τὴν γυναῖκα· ὡς δ’ ἔπεισε, τὴν στρατιὰν συναγαγών, αἰσθομένην ἴσως ἤδη τι τούτων, κατελογίζετο μὲν αὐτοῖς τὰ ἔργα τὰ ἑαυτοῦ καὶ τὴν ἀρχήν, ὅτι δὴ μάλιστα τῶν Ἀλεξάνδρου διαδόχων ἐπὶ μήκιστον προαγάγοι· διὸ καὶ γηρῶντι ἤδη δυσκράτητον εἶναι διὰ τὸ μέγεθος. “ἐθέλω δέ,” ἔφη, “διελεῖν τὸ μέγεθος ἐς τὴν ὑμετέραν τοῦ μέλλοντος ἀμεριμνίαν, καὶ τὸ μέρος ἤδη δοῦναι τοῖς ἐμοῖς φιλτάτοις. δίκαιοι δ’ ἐστέ μοι πάντες ἐς πάντα συνεργεῖν, οἳ ἐς τοσοῦτον ἀρχῆς καὶ δυνάμεως ηὐξήθητε ὑπ’ ἐμοῦ μετ’ Ἀλέξανδρον. φίλτατοι δ’ εἰσί μοι καὶ ἀρχῆς ἄξιοι τῶν τε παίδων ὁ τέλειος ἤδη καὶ ἡ γυνή. ἤδη δ’ αὐτοῖς καὶ παῖδες, ὡς νέοις, γένοιντο ταχέως, καὶ πλέονες φύλακες ὑμῖν τῆς ἡγεμονίας εἶεν. ἁρμόζω σφίσιν ἀλλήλους ἐφ’ ὑμῶν, καὶ πέμπω βασιλέας εἶναι τῶν ἐθνῶν ἤδη τῶν ἄνω. καὶ οὐ Περσῶν ὑμῖν ἔθη καὶ ἑτέρων ἐθνῶν μᾶλλον ἢ τόνδε τὸν κοινὸν ἅπασιν ἐπιθήσω νόμον, ἀεὶ δίκαιον εἶναι τὸ πρὸς βασιλέως ὁριζόμενον.” ὁ μὲν δὴ οὕτως εἶπεν, ἡ στρατιὰ δὲ ὡς βασιλέα τε τῶν ἐπὶ Ἀλεξάνδρῳ μέγιστον καὶ πατέρα ἄριστον ηὐφήμει καὶ ὁ Σέλευκος Στρατονίκῃ καὶ τῷ παιδὶ τὰ αὐτὰ προστάξας ἐζεύγνυ τὸν γάμον καὶ ἐπὶ τὴν βασιλείαν ἐξέπεμψεν, ἔργον ἀοίδιμον τόδε καὶ δυνατώτερον τῶν ἐν πολέμοις αὐτῷ γενομένων ἐργασάμενος.", "st": "4.61"}, {"sp": "N", "t": "Σατραπεῖαι δὲ ἦσαν ὑπ’ αὐτῷ δύο καὶ ἑβδομήκοντα· τοσαύτης ἐβασίλευε γῆς. καὶ τὴν πλείονα τῷ παιδὶ παραδούς, ἦρχε τῶν ἀπὸ θαλάσσης ἐπὶ Εὐφράτην μόνων. καὶ πόλεμον τελευταῖον Λυσιμάχῳ περὶ Φρυγίαν τὴν ἐφ’ Ἑλλησπόντῳ πολεμῶν, Λυσιμάχου μὲν ἐκράτει πεσόντος ἐν τῇ μάχῃ, αὐτὸς δὲ τὸν Ἑλλήσποντον ἐπέρα. καὶ ἐς Λυσιμάχειαν ἀναβαίνων κτείνεται. Πτολεμαῖος δ’ αὐτὸν ἑπόμενος ἔκτεινεν, ὅτῳ κεραυνὸς ἐπίκλησις. υἱὸς δ’ ἦν ὁ κεραυνος ὅδε Πτολεμαίου τοῦ σωτῆρος καὶ Εὐρυδίκης τῆς Ἀντιπάτρου· καὶ αὐτὸν ἐκπεσόντα Αἰγύπτου διὰ δέος, ὅτι νεωτάτῳ παιδὶ ὁ Πτολεμαῖος τὴν ἀρχὴν ἐπενόει δοῦναι, ὁ Σέλευκος οἷα φίλου παῖδα ἀτυχοῦντα ὑπεδέξατο, καὶ ἔφερβε καὶ ἐπήγετο πάντῃ φονέα ἑαυτοῦ.", "st": "4.62"}, {"sp": "N", "t": "καὶ Σέλευκος μὲν οὕτω τελευτᾷ, τρία καὶ ἑβδομήκοντα ἔτη βιώσας, καὶ βασιλεύσας αὐτῶν δύο καὶ τεσσαράκοντα. καὶ μοι δοκεῖ καὶ ἐς τοῦτο αὐτῷ συνενεχθῆναι τὸ αὐτὸ λόγιον, “μὴ σπεῦδ’ Εὐρώπηνδ’· Ἀσίη τοι πολλὸν ἀμείνων.” ἡ γὰρ Λυσιμάχεια τῆς Εὐρώπης ἐστί, καὶ τότε πρῶτον ἀπὸ τῆς Ἀλεξάνδρου στρατείας ἐς τὴν Εὐρώπην διεπέρα. λέγεται δὲ καὶ περὶ αὐτοῦ τοῦ θανάτου ποτὲ αὐτῷ χρωμένῳ λόγιον προαγορευθῆναι “Ἄργος ἀλευόμενος τὸ πεπρωμένον εἰς ἔτος ἥξεις· εἰ δ’ Ἄργει πελάσαις, τότε κεν παρὰ μοῖραν ὄλοιο.” ὁ μὲν δὴ Ἄργος τὸ Πελοποννήσιον καὶ Ἄργος τὸ Ἀμφιλοχικὸν καὶ Ἄργος τὸ ἐν Ὀρεστείᾳ (ὅθεν οἱ Ἀργεάδαι Μακεδόνες) καὶ τὸ ἐν τῷ Ἰονίῳ λεγόμενον οἰκίσαι Διομήδην ἀλώμενον, καὶ εἴ τί που γῆς ἄλλο Ἄργος ἐκαλεῖτο, πάντα ἀνεζήτει καὶ ἐφυλάσσετο· ἀναβαίνοντι δ’ ἐς τὴν Λυσιμάχειαν αὐτῷ ἀπὸ τοῦ Ἑλλησπόντου βωμὸς ἦν ἐν ὄψει μέγας τε καὶ περιφανής, καὶ πυθόμενος αὐτὸν ἢ τοὺς Ἀργοναύτας στήσασθαι παραπλέοντας ἐς Κόλχους ἢ τοὺς Ἀχαιοὺς ἐπὶ Ἴλιον στρατεύοντας, καὶ διὰ τοῦτο ἔτι τὸν βωμὸν τοὺς περιχώρους Ἄργος καλεῖν, ἢ διὰ τὴν ναῦν διαφθείροντας τὸ ὄνομα ἢ διὰ τὴν πατρίδα τῶν Ἀτρειδῶν, κτείνεται, ταῦτα ἔτι μανθάνων, ὑπὸ τοῦ Πτολεμαίου προσπεσόντος ὄπισθεν. καὶ Σέλευκον μὲν ἔκαιε Φιλέταιρος ὁ Περγάμου δυναστεύσας, πολλῶν χρημάτων τὸ σῶμα τὸν κεραυνὸν αἰτήσας, καὶ τὰ λείψανα ἔπεμπεν Ἀντιόχῳ τῷ παιδὶ αὐτοῦ. ὁ δ’ ἐν Σελευκείᾳ τῇ πρὸς θαλάσσῃ ἀπέθετο, καὶ νεὼν αὐτῷ ἐπέστησε καὶ τέμενος περιέθηκε· καὶ τὸ τέμενος Νικατόρειον ἐπικλῄζεται.", "st": "4.63"}, {"sp": "N", "t": "Λυσίμαχον δὲ πυνθάνομαι, τῶν ὑπασπιστῶν ὄντα τῶν Ἀλεξάνδρου, παρατροχάσαι ποτὲ ἐπὶ πλεῖστον αὐτῷ, καὶ καμόντα, τῆς οὐρᾶς τοῦ βασιλέως ἵππου λαβόμενον, ἔτι συντρέχειν, πληγέντα δὲ ἐς τὸ μέτωπον ἐπὶ τὴν φλέβα τῷ τέλει τοῦ βασιλείου δόρατος αἱμορροεῖν· τὸν δὲ Ἀλέξανδρον, ἀπορίᾳ τελαμῶνος, τῷ διαδήματι αὐτοῦ τὸ τραῦμα περιδῆσαι, καὶ ἐμπλησθῆναι μὲν αἵματος τὸ διάδημα, τὸν δὲ Ἀλεξάνδρου μάντιν Ἀρίστανδρον φερομένῳ τῷ Λυσιμάχῳ καὶ ὧδε ἔχοντι ἐπειπεῖν ὅτι βασιλεύσει μὲν οὗτος ὁ ἀνήρ, βασιλεύσει δ’ ἐπιπόνως. ὁ μὲν δὴ καὶ ἐβασίλευσε τεσσαράκοντα ἔτη μάλιστα σὺν οἷς ἐσατράπευσε, καὶ ἐπιπόνως ἐβασίλευσε, καὶ ἑβδομηκοντούτης ὢν στρατευόμενος καὶ μαχόμενος ἔπεσεν. εὐθὺς δ’ ἐπαναιρεθέντος αὐτῷ τοῦ Σελεύκου, κείμενον τὸ σῶμα τοῦ Λυσιμάχου κύων οἰκεῖος, ἐς πολὺ ὑπερμαχῶν, ἀλύμαντον ἐξ ὀρνέων καὶ θηρίων διεφύλασσε, μέχρι Θώραξ ὁ Φαρσάλιος εὑρὼν ἔθαψεν. οἱ δὲ Ἀλέξανδρόν φασι θάψαι, τὸν αὐτοῦ Λυσιμάχου παῖδα, φυγόντα μὲν ὑπὸ δέους πρὸς Σέλευκον ὅτε Λυσίμαχος Ἀγαθοκλέα τὸν ἕτερον αὐτοῦ παῖδα ἀνεῖλεν, ἐρευνησάμενον δὲ ἐν τῷ τότε τὸ σῶμα, καὶ ἐκ τοῦ κυνὸς μάλιστα ἀνευρόντα ἤδη διεφθαρμένον. τὰ δὲ ὀστᾶ τοὺς Λυσιμαχέας ἐνθέσθαι τῷ σφετέρῳ ἱερῷ, καὶ τὸ ἱερὸν Λυσιμάχείον προσαγορεῦσαι.", "st": "4.64"}, {"sp": "N", "t": "τοιόνδε μὲν δὴ τέλος ἑκατέρῳ τῶνδε τῶν βασιλέων συνηνέχθη, ἀνδρειοτάτων τε καὶ τὰ σώματα μεγίστων γενομένων, τοῦ μὲν ἐς ἑβδομήκοντα ἔτη, τοῦ δὲ ἐς πλέονα τούτων ἔτι ἄλλα τρία, μεμαχημένων ἐκ χειρὸς οἰκείας ἀεὶ μέχρι τοῦ θανάτου.", "st": "4.64"}, {"sp": "N", "t": "Σελεύκου δ’ ἀποθανόντος διάδοχοι, παῖς παρὰ πατρὸς ἐκδεχόμενοι τὴν Σύρων ἀρχήν, ἐγένοντο οἵδε, Ἀντίοχος μὲν πρῶτος ὅδε ὁ τῆς μητρυιᾶς ἐρασθείς, ὃς καὶ σωτὴρ ἐπεκλήθη Γαλάτας ἐκ τῆς Εὐρώπης ἐς τὴν Ἀσίαν ἐσβαλόντας, ἐξελάσας, δεύτερος δὲ Ἀντίοχος ἕτερος, ἐκ τῶνδε τῶν γάμων γενόμενος, ὅτῳ θεὸς ἐπώνυμον ὑπὸ Μιλησίων γίγνεται πρῶτον, ὅτι αὐτοῖς Τίμαρχον τύραννον καθεῖλεν. ἀλλὰ τόνδε μὲν τὸν θεὸν ἔκτεινεν ἡ γυνὴ φαρμάκῳ. δύο δὲ εἶχε, Λαοδίκην καὶ Βερενίκην, ἐξ ἔρωτός τε καὶ ἐγγύης, … Πτολεμαίου τοῦ φιλαδέλφου θυγατέρα· καὶ αὐτὸν ἔκτεινε Λαοδίκη, καὶ ἐπ’ ἐκείνῳ Βερενίκην τε καὶ τὸ Βερενίκης βρέφος. καὶ Πτολεμαῖος ὁ τοῦ φιλαδέλφου, ταῦτα τινύμενος, Λαοδίκην τε ἔκτεινε καὶ ἐς Συρίαν ἐνέβαλε καὶ ἐς Βαβυλῶνα ἤλασεν. καὶ Παρθυαῖοι τῆς ἀποστάσεως τότε ἦρξαν ὡς τεταραγμένης τῆς τῶν Σελευκιδῶν ἀρχῆς.", "st": "4.65"}, {"sp": "N", "t": "ἐπὶ δὲ τῷ θεῷ βασιλεὺς γίγνεται Συρίας Σέλευκος, υἱὸς τοῦ θεοῦ τε καὶ Λαοδίκης, ᾧ καλλίνικος ἐπώνυμον. ἐπὶ δὲ Σελεύκῳ δύο παῖδες αὐτοῦ Σελεύκου, καθ’ ἡλικίαν ἑκάτερος αὐτῶν, Σέλευκός τε καὶ Ἀντίοχος. Σελεύκῳ μὲν δὴ ἀσθενεῖ τε ὄντι καὶ πενομένῳ καὶ δυσπειθῆ τὸν στρατὸν ἔχοντι ἐπεβούλευσαν οἱ φίλοι διὰ φαρμάκων, καὶ ἐς ἔτη δύο μόνα ἐβασίλευσεν· ὁ δὲ Ἀντίοχος ὅδε ἐστὶν ὁ μέγας ἐπίκλην, περὶ οὗ μοι πάλαι εἴρηται, Ῥωμαίοις πεπολεμηκότος. ἐβασίλευσε δὲ ἔτη ἑπτὰ καὶ τριάκοντα. καὶ αὐτοῦ περὶ τοῖν παίδοιν προεῖπον ἀμφοῖν βεβασιλευκότοιν, Σελεύκου τε καὶ Ἀντιόχου, Σελεύκου μὲν ἔτεσι δώδεκα, ἀπράκτως ἅμα καὶ ἀσθενῶς διὰ τὴν τοῦ πατρὸς συμφοράν, Ἀντιόχου δὲ δώδεκα οὐ πλήρεσιν, ἐν οἷς Ἀρταξίαν τὸν Ἀρμένιον εἷλε, καὶ ἐς Αἴγυπτον ἐστράτευσεν ἐπὶ ἕκτον Πτολεμαῖον, ὀρφανευόμενον μετ’ ἀδελφοῦ. καὶ αὐτῷ στρατοπεδεύοντι περὶ τὴν Ἀλεξάνδρειαν Ποπίλιος παρὰ Ῥωμαίων πρεσβευτὴς ἧκε, φέρων δέλτον ἐν ᾗ τάδε ἐγέγραπτο, μὴ πολεμεῖν Πτολεμαίοις Ἀντίοχον. ἀναγνόντι δὲ αὐτῷ, καὶ λέγοντι βουλεύσεσθαι, κύκλον τῇ ῥάβδῳ περιέγραψεν ὁ Ποπίλιος, καὶ εἶπεν· “ἐνταῦθα βουλεύου.” ὁ μὲν δὴ καταπλαγεὶς ἀνέζευξε, καὶ τὸ τῆς Ἐλυμαίας Ἀφροδίτης ἱερὸν ἐσύλησε, καὶ φθίνων ἐτελεύτησε, παιδίον ἐνναετὲς ἀπολιπών, Ἀντίοχον τὸν εὐπάτορα, ὥς μοι καὶ περὶ τοῦδε εἴρηται.", "st": "4.66"}, {"sp": "N", "t": "εἴρηται δὲ καὶ περὶ Δημητρίου τοῦ μετ’ αὐτόν, ὃς ὡμήρευεν ἐν Ῥώμῃ καὶ τῆς ὁμηρείας ἐκφυγὼν ἐβασίλευσε, σωτὴρ καὶ ὅδε πρὸς τῶν Σύρων, δεύτερος ἐπὶ τῷ Σελεύκου τοῦ νικάτορος παιδὶ ὀνομασθείς. ἐπανίσταται δὲ αὐτῷ τις Ἀλέξανδρος, ψευδόμενος εἶναι τοῦ Σελευκείου γένους· καὶ Πτολεμαῖος ὁ τῆς Αἰγύπτου βασιλεὺς κατὰ μῖσος Δημητρίου συνελάμβανεν Ἀλεξάνδρῳ. καὶ Δημήτριος μὲν διὰ Πτολεμαῖον ἐξέπεσε τῆς ἀρχῆς καὶ ἐτελεύτησε· τὸν δὲ Ἀλέξανδρον ἐξέβαλε Δημήτριος ὁ Δημητρίου τοῦδε τοῦ σωτῆρος υἱός, καὶ ἐπὶ τῷδε, ὡς νόθον τοῦ γένους ἄνδρα νικήσας, νικάτωρ ὑπὸ τῶν Σύρων ὠνομάσθη, δεύτερος καὶ ὅδε μετὰ Σέλευκον. ἐπί τε Παρθυαίους καὶ ὅδε μετὰ Σέλευκον ἐστράτευσε, καὶ γενόμενος αἰχμάλωτος δίαιταν εἶχεν ἐν Φραάτου βασιλέως, καὶ Ῥοδογούνην ἔζευξεν αὐτῷ τὴν ἀδελφὴν ὁ βασιλεύς.", "st": "4.67"}, {"sp": "N", "t": "παρὰ δὲ τὴν ἀναρχίαν τήνδε δοῦλος τῶν βασιλέων Διόδοτος παιδίον Ἀλέξανδρον, ἐξ Ἀλεξάνδρου τοῦ νόθου καὶ τῆς Πτολεμαίου θυγατρός, ἐπὶ τὴν βασιλείαν ἤγαγεν. καὶ τὸ παιδίον κτείνας αὐτὸς ἐπετόλμησε τῇ ἀρχῇ, Τρύφων ἀφ’ ἑαυτοῦ μετονομασθείς. ἀλλ’ αὐτὸν Ἀντίοχος ὁ ἀδελφὸς Δημητρίου τοῦ αἰχμαλώτου, πυθόμενος ἐν Ῥόδῳ περὶ τῆς αἰχμαλωσίας, κτείνει κατιὼν ἐς τὰ πατρῷα σὺν πόνῳ πολλῷ. καὶ στρατεύει καὶ ὅδε ἐπὶ τὸν Φραάτην, τὸν ἀδελφὸν αἰτῶν. ὁ μὲν δὴ Φραάτης αὐτὸν ἔδεισε καὶ τὸν Δημήτριον ἐξέπεμψεν· ὁ δ’ Ἀντίοχος καὶ ὣς συνέβαλέ τε τοῖς Παρθυαίοις, καὶ ἡσσώμενος ἑαυτὸν ἔκτεινεν. ἔκτεινε δὲ καὶ Δημήτριον ἐς τὴν βασιλείαν ἐπανελθόντα ἡ γυνὴ Κλεοπάτρα, δολοφονήσασα διὰ ζῆλον τοῦ γάμου Ῥοδογούνης, δι’ ὃν δὴ καὶ Ἀντιόχῳ τῷ ἀδελφῷ τοῦ Δημητρίου προὐγεγάμητο. καὶ παῖδες ἦσαν αὐτῇ δύο μὲν ἐκ Δημητρίου, Σέλευκός τε καὶ Ἀντίοχος, ὅτῳ γρυπὸς ἐπίκλησις, ἐκ δὲ Ἀντιόχου Ἀντίοχος, ὅτῳ Κυζικηνὸς ἐπώνυμον. τούτων τὸν μὲν γρυπὸν ἐς Ἀθήνας, τὸν δὲ Κυζικηνὸν ἐς Κύζικον ἐπεπόμφει τρέφεσθαι.", "st": "4.68"}, {"sp": "N", "t": "Σέλευκον δ’ εὐθὺς ἐπὶ τῷ πατρὶ Δημητρίῳ τὸ διάδημα ἐπιθέμενον ἐπιτοξεύσασα ἔκτεινεν, εἴτε δείσασα περὶ τῆς τοῦ πατρὸς δολοφονήσεως, εἴτε καὶ μανιώδει πρὸς πάντας μίσει. μετὰ δὲ Σέλευκον ὁ γρυπὸς ἐγένετο βασιλεύς, καὶ τὴν μητέρα οἱ φάρμακον κεράσασαν πιεῖν ἠνάγκασεν. ἡ μὲν δὴ δίκην ποτὲ ἔδωκεν, ἄξιος δὲ ἄρα τῆς μητρὸς ἦν καὶ ὁ γρυπός· ἐπεβούλευε γὰρ τῷ Κυζικηνῷ καίπερ ὄντι ὁμομητρίῳ. ὁ δὲ μαθὼν ἐπολέμησέ τε αὐτῷ καὶ τῆς ἀρχῆς αὐτόν ἐξήλασε, καὶ βασιλεὺς ἀντ’ ἐκείνου τοῖς Σύροις ἐγένετο. ἀλλὰ καὶ τόνδε Σέλευκος ὁ Ἀντιόχου τοῦ γρυποῦ παῖς, ἐπιστρατεύσας ὄντι περ θείῳ, παρείλετο τὴν ἀρχήν. βίαιος δὲ καὶ τυραννικώτατος ὢν ἐν Ἑστίᾳ Μόψου τῆς Κιλικίας κατεπρήσθη κατὰ τὸ γυμνάσιον. καὶ αὐτὸν διεδέξατο Ἀντίοχος ὁ υἱὸς τοῦ Κυζικηνοῦ· ὃν ἐπιβουλευόμενον ὑπὸ Σελεύκου τοῦ ἀνεψιοῦ οἱ μὲν Σύροι νομίζουσι περισωθῆναι δι’ εὐσέβειαν, καὶ διὰ τοῦτο εὐσεβῆ παρωνόμασαν (ἑταίρα δ’ αὐτὸν ἔσωσεν, ἐρασθεῖσα τοῦ κάλλους), ἐμοὶ δὲ δοκοῦσιν ἐπὶ γέλωτι αὐτῷ ποιήσασθαι τὸ ὄνομα οἱ Σύροι· ἔγημε γὰρ οὗτος ὁ εὐσεβὴς Σελήνην, ἣ καὶ τῷ πατρὶ αὐτοῦ ἐγεγάμητο τῷ Κυζικηνῷ καὶ τῷ γρυπῷ θείῳ γενομένῳ. τοιγάρτοι αὐτὸν θεοῦ μετιόντος ἐξήλασε τῆς ἀρχῆς Τιγράνης.", "st": "4.69"}, {"sp": "N", "t": "καὶ τὸν υἱὸν ἐκείνου τὸν ἐκ τῆς Σελήνης αὐτῷ γενόμενον, ἐν Ἀσίᾳ τε τραφέντα καὶ ἀπὸ τοῦδε Ἀσιατικὸν ἐπίκλην, Πομπήιος ἀφείλετο τὴν Σύρων ἀρχήν, ὥς μοι λέλεκται, ὄντα μὲν ἑπτακαιδέκατον ἐκ Σελεύκου Σύρων βασιλέα (ἐξαίρω γὰρ Ἀλέξανδρόν τε καὶ τὸν Ἀλεξάνδρου παῖδα ὡς νόθους, καὶ τὸν δοῦλον αὐτῶν Διόδοτον), βασιλεύσαντα δ’ ἐν ταῖς ἀσχολίαις ταῖς Πομπηίου ἐπὶ ἓν μόνον ἔτος. ἡ δὲ ἀρχὴ τῶν Σελευκιδῶν ἐς τριάκοντα ἐπὶ διακοσίοις ἐνιαυτοὺς διίκετο· καὶ εἴ τις ἐπισκοποίη τὸν ἐς Ῥωμαίους χρόνον ἀπ’ Ἀλεξάνδρου, προσθετέον ἐπὶ τοῖς διακοσίοις τριάκοντα ἔτεσι τὰ Τιγράνους τεσσαρεσκαίδεκα.", "st": "4.70"}, {"sp": "N", "t": "τοσάδε μὲν δὴ καὶ περὶ Μακεδόνων τῶν Συρίας βεβασιλευκότων εἶχον εἰπεῖν ὡς ἐν ἀλλοτρίᾳ συγγραφῇ.", "st": "4.70"}, {"sp": "HDR", "t": "Μιθριδάτειος", "st": "5"}, {"sp": "N", "t": "Θρᾷκας Ἕλληνες ἡγοῦνται, τοὺς ἐς Ἴλιον μετὰ Ῥήσου στρατεύσαντας, Ῥήσου νυκτὸς ὑπὸ Διομήδους ἀναιρεθέντος ὃν τρόπον Ὅμηρος ἐν τοῖς ἔπεσι φράζει, φεύγοντας ἐπὶ τοῦ Πόντου τὸ στόμα, ᾗ στενώτατός ἐστιν ἐς Θρᾴκην ὁ διάπλους, οἱ μὲν οὐκ ἐπιτυχόντας πλοίων τῇδε καταμεῖναι καὶ τῆς γῆς κρατῆσαι Βεβρυκίας λεγομένης, οἱ δὲ περάσαντας ὑπὲρ τὸ Βυζάντιον ἐς τὴν Θρᾳκῶν τῶν Βιθυνῶν λεγομένων παρὰ Βιθύαν ποταμὸν οἰκῆσαι, καὶ λιμῷ πιεσθέντας ἐς Βεβρυκίαν αὖθις ἐπανελθεῖν, καὶ Βιθυνίαν ἀντὶ Βεβρυκίας, ἀπὸ τοῦ ποταμοῦ παρ’ ὃν ᾤκουν, ὀνομάσαι, ἢ καὶ τὸ ὄνομα αὐτοῖς ἀλόγως σὺν χρόνῳ παρατραπῆναι, οὐκ ἐς πολὺ τῆς Βιθυνίας παρὰ τὴν Βεβρυκίαν διαφερούσης. ὧδε μὲν ἔνιοι νομίζουσιν, ἕτεροι δὲ Βίθυν ἄρξαι πρῶτον αὐτῶν, παῖδα Διός τε καὶ Θρᾴκης, οὓς ἐπωνύμους ἑκατέρᾳ γῇ γενέσθαι.", "st": "5.1"}, {"sp": "N", "t": "τάδε μὲν οὖν μοι προλελέχθω περὶ Βιθυνίας· τῶν δὲ πρὸ Ῥωμαίων αὐτῆς βασιλέων, ἐννέα καὶ τεσσαράκοντα ἐφεξῆς γενομένων, ὅτου μοι μάλιστα μνημονεῦσαι προσήκει τὰ Ῥωμαίων συγγράφοντι, Προυσίας ἦν ὁ κυνηγὸς ἐπίκλησιν, ᾧ Περσεὺς ὁ Μακεδόνων βασιλεὺς τὴν ἀδελφὴν ἠγγύησεν. καὶ οὐ πολὺ ὕστερον Περσέως καὶ Ῥωμαίων ἐς χεῖρας ἐπ’ ἀλλήλους ἰόντων, ὁ Προυσίας οὐδετέροις συνεμάχει. Περσέως δ’ ἁλόντος ἀπήντησε τοῖς Ῥωμαίων στρατηγοῖς εἷμά τε Ῥωμαϊκὸν ἀμπεχόμενος, ὃ καλοῦσι τήβεννον, καὶ ὑποδήματα ἔχων Ἰταλικά, τὴν κεφαλὴν ἐξυρημένος καὶ πῖλον ἐπικείμενος, ᾧ τρόπῳ τινὲς προΐασι τῶν ἐν διαθήκαις ἐλευθερωθέντων, αἰσχρὸς ὢν καὶ τἆλλα ὀφθῆναι καὶ βραχύς. ἐντυχὼν δ’ αὐτοῖς ἔφη ῥωμαϊστὶ τῷ ῥήματι “Ῥωμαίων εἰμὶ λίβερτος,” ὅπερ ἐστὶν ἀπελεύθερος. γέλωτα δὲ παρασχὼν ἐς Ῥώμην ἐπέμφθη, καὶ φανεὶς κἀνταῦθα γελοῖος ἔτυχε συγγνώμης.", "st": "5.2"}, {"sp": "N", "t": "χρόνῳ δ’ ὕστερον Ἀττάλῳ τι χαλεπήνας, τῷ Βασιλεῖ τῆς Ἀσίας τῆς περὶ τὸ Πέργαμον, τὴν γῆν ἐδῄου τὴν Ἀσιάδα. μαθοῦσα δ’ ἡ Ῥωμαίων βουλὴ προσέπεμπε τῷ Προυσίᾳ μὴ πολεμεῖν Ἀττάλῳ, φίλῳ Ῥωμαίων ὄντι καὶ συμμάχῳ. καὶ δυσπειθῶς ἔτι ἔχοντι οἱ πρέσβεις μετ’ ἀνατάσεως προσέτασσον πείθεσθαι τοῖς ὑπὸ τῆς συγκλήτου λεγομένοις, καὶ ἥκειν μετὰ χιλίων ἱππέων ἔς τι μεθόριον ἐπὶ συνθήκαις, ἔνθα καὶ τὸν Ἄτταλον ἔφασαν περιμένειν μετὰ τοσῶνδε ἑτέρων. ὁ δ’ ὡς ὀλίγων τῶν σὺν Ἀττάλῳ καταφρονήσας, καὶ ἐλπίσας αὐτὸν ἐνεδρεύσειν, προύπεμπε τοὺς πρέσβεις ὡς μετὰ χιλίων ἑπόμενος, πάντα δ’ ἀναστήσας τὸν στρατὸν ἦγεν ὡς ἐς μάχην. Ἀττάλου δὲ καὶ τῶν πρέσβεων αἰσθομένων τε καὶ διαφυγόντων ᾗ δυνατὸς αὐτῶν ἐγίγνετο ἕκαστος, ὁ δὲ καὶ τῶν σκευοφόρων τῶν Ῥωμαϊκῶν ὑπολειφθέντων ἥπτετο, καὶ χωρίον τι Νικηφόριον ἐξελὼν κατέσκαπτε, καὶ τοὺς ἐν αὐτῷ νεὼς ἐνεπίμπρη, Ἄτταλόν τε ἐς τὸ Πέργαμον συμφυγόντα ἐπολιόρκει, μέχρι καὶ τῶνδε οἱ Ῥωμαῖοι πυθόμενοι πρέσβεις ἑτέρους ἔπεμπον, οἳ τὸν Προυσίαν ἐκέλευον Ἀττάλῳ τὰς βλάβας ἀποτῖσαι. τότε οὖν καταπλαγεὶς ὁ Προυσίας ὑπήκουσε καὶ ἀνεχώρει. ποινὴν δὲ τῶν πρέσβεων ὁρισάντων αὐτὸν ἐσενεγκεῖν Ἀττάλῳ ναῦς καταφράκτους εἴκοσιν αὐτίκα καὶ ἀργυρίου σὺν χρόνῳ τάλαντα πεντακόσια, τάς τε ναῦς ἔδωκε καὶ τὰ χρήματα ἐν τῷ χρόνῳ συνέφερεν.", "st": "5.3"}, {"sp": "N", "t": "ὄντι δ’ αὐτῷ διὰ μίσους τοῖς ὑπηκόοις ἐπὶ ὠμότητι χαλεπῇ, Νικομήδης υἱὸς ἦν, πάνυ τοῖς Βιθυνοῖς ἀρέσκων· ὅπερ ὁ Προυσίας ὑφορώμενος ἐς Ῥώμην αὐτὸν βιοῦν μετεστήσατο. καὶ μαθὼν εὐδοκιμοῦντα κἀκεῖ, προσέταξε τῆς βουλῆς δεηθῆναι τῶν ἔτι ὀφειλομένων Ἀττάλῳ χρημάτων αὐτὸν ἀπολῦσαι. Μηνᾶν τε αὐτῷ συμπρεσβεύσοντα ἔπεμπε· καὶ εἴρητο τῷ Μηνᾷ, εἰ μὲν ἐπιτύχοι τῆς ἀφέσεως τῶν χρημάτων, ἔτι φείδεσθαι τοῦ Νικομήδους, εἰ δὲ ἀποτύχοι, κτείνειν αὐτὸν ἐν Ῥώμῃ. κερκούρους τέ τινας ἐς τοῦτο συνέπεμψεν αὐτῷ, καὶ δισχιλίους στρατιώτας. ὁ δὲ τῆς μὲν ζημίας οὐκ ἀφεθείσης τῷ Προυσίᾳ Ἀ̔νδρόνικος γὰρ ἐπιπεμφθεὶς ἐς ἀντιλογίαν ὑπὸ Ἀττάλου τὴν ζημίαν ἀπέφαινεν ἐλάττονα τῆς ἁρπαγῆς̓, τὸν δὲ Νικομήδη λόγου καὶ σπουδῆς ἄξιον ὁρῶν, ἠπόρητο, καὶ οὔτε κτείνειν αὐτὸν ὑφίστατο οὔτε αὐτὸς ἐς Βιθυνίαν ἐπανιέναι διὰ δέος. ὅμως δ’ αὐτῷ βραδύνοντι συνεὶς ὁ νεανίσκος ἐς λόγους ἦλθεν, ἐθέλοντι κἀκείνῳ. συνθέμενοι δ’ ἐπιβουλεῦσαι τῷ Προυσίᾳ, τὸν Ἀττάλου πρεσβευτὴν Ἀνδρόνικον ἐς τὸ ἔργον προσέλαβον, ἵνα τὸν Ἄτταλον πείσειε τὸν Νικομήδη καταγαγεῖν ἐς Βιθυνίαν. ἀναμείναντες δ’ ἀλλήλους ἐν τῇ Βερνίκῃ, πολισματίῳ τινὶ τῆς Ἠπείρου, νυκτὸς ἐσβάντες ἐς ναῦν ἅ τε δέοι ποιεῖν συνετίθεντο, καὶ διελύθησαν ἔτι νυκτός.", "st": "5.4"}, {"sp": "N", "t": "ἅμα δ’ ἡμέρᾳ Νικομήδης μὲν ἐξέβαινε τῆς νεὼς πορφύραν τε βασιλικὴν ἠμφιεσμένος καὶ διάδημα ἐπικείμενος, Ἀνδρόνικος δ’ αὐτὸν ὑπαντιάσας τε καὶ βασιλέα προσειπὼν παρέπεμπε μετὰ στρατιωτῶν ὧν εἶχε πεντακοσίων. Μηνᾶς δὲ ὑποκρινόμενος τότε πρῶτον ᾐσθῆσθαι Νικομήδους παρόντος, ἐς τοὺς δισχιλίους διαδραμὼν ἐδυσφόρει. προϊὼν δὲ τῷ λόγῳ, “δύο,” ἔφη, “βασιλέοιν, τοῦ μὲν ὄντος ἐν τῇ χώρᾳ τοῦ δ’ ἐπιόντος, ἀναγκαῖον ἡμῖν τὸ σφέτερον εὖ διατίθεσθαι καὶ τοῦ γενησομένου καλῶς τεκμαίρεσθαι, ὡς ἐν τῷδε τῆς ἡμετέρας σωτηρίας βεβαιουμένης, ἢν καλῶς προϊδώμεθα πότερος αὐτῶν ἐπικρατήσει. ὁ μὲν δὴ γέρων ἐστίν, ὁ δὲ νέος· καὶ Βιθυνοὶ τὸν μὲν ἀποστρέφονται, τὸν δὲ αἱροῦνται. Ῥωμαίων τε οἱ δυνατοὶ τὸν νεανίαν ἀγαπῶσι· καὶ Ἀνδρόνικος αὐτὸν ἤδη δορυφορῶν ὑποδείκνυσι τὴν Ἀττάλου συμμαχίαν, ἀρχήν τε μεγάλην ἔχοντος καὶ Βιθυνοῖς γειτονεύοντος καὶ ἐκ πολλοῦ τῷ Προυσίᾳ πεπολεμωμένου.” λέγων δὲ ταῦθ’ ἅμα καὶ τὴν ὠμότητα τοῦ Προυσίου παρεγύμνου, καὶ ὅσα πονηρὰ πράξειεν ἐς ἅπαντας, καὶ τὸ κοινὸν ἐπὶ τοῖσδε Βιθυνῶν ἐς αὐτὸν ἔχθος. ὡς δὲ κἀκείνους εἶδε τὴν Προυσίου μοχθηρίαν ἀποστρεφομένους, ἦγεν αὐτοὺς ἐς τὸν Νικομήδην αὐτίκα, καὶ προσειπὼν καὶ ὅδε βασιλέα δεύτερος ἐπὶ Ἀνδρονίκῳ μετὰ τῶν δισχιλίων ἐδορυφόρει.", "st": "5.5"}, {"sp": "N", "t": "Ἄτταλός τε τὸν νεανίαν προθύμως ὑπεδέχετο, καὶ τὸν Προυσίαν ἐκέλευσε τῷ παιδὶ πόλεις τέ τινας ἐς ἐνοίκησιν καὶ χώραν ἐς ἐφόδια δοῦναι. ὁ δ’ αὐτίκα δώσειν ἔφη τὴν Ἀττάλου βασιλείαν ἅπασαν, ἣν δὴ καὶ πρότερον Νικομήδει περιποιῶν ἐς Ἀσίαν ἐσβαλεῖν. ταῦτα δ’ εἰπὼν ἔπεμπεν ἐς Ῥώμην τοὺς Νικομήδους καὶ Ἀττάλου κατηγορήσοντάς τε καὶ προκαλεσομένους ἐς κρίσιν. οἱ δ’ ἀμφὶ τὸν Ἄτταλον εὐθὺς ἐχώρουν ἐς τὴν Βιθυνίαν, καὶ προσιοῦσιν αὐτοῖς οἱ Βιθυνοὶ κατ’ ὀλίγους προσετίθεντο. Προυσίας δ’ ἅπασιν ἀπιστῶν, καὶ Ῥωμαίους ἐλπίζων αὑτὸν ἐξαιρήσεσθαι τῆς ἐπιβουλῆς, Διήγυλιν τὸν Θρᾷκα, κηδεστὴν ὄντα οἱ, πεντακοσίους Θρᾷκας αἰτήσας καὶ λαβὼν τοῖσδε μόνοις τὸ σῶμα ἐπέτρεψεν, ἐς τὴν ἀκρόπολιν τὴν ἐν Νικαίᾳ καταφυγών· ὁ δὲ Ῥωμαίων στρατηγὸς ἐν ἄστει οὔτε αὐτίκα ἐπῆγεν ἐπὶ τὴν βουλὴν τοὺς τοῦ Προυσίου πρέσβεις, χαριζόμενος Ἀττάλῳ· ἐπαγαγών τέ ποτε, ψηφισαμένης τῆς βουλῆς τὸν στρατηγὸν αὐτὸν ἑλέσθαι τε καὶ πέμψαι πρέσβεις οἳ διαλύσουσι τὸν πόλεμον, εἵλετο τρεῖς ἄνδρας, ὧν ὁ μὲν τὴν κεφαλήν ποτε λίθῳ πληγεὶς ἀσχήμονας ἐπέκειτο ὠτειλάς, ὁ δὲ τοὺς πόδας διέφθαρτο ὑπὸ ῥεύματος, ὁ δ’ ἠλιθιώτατος ἐνομίζετο εἶναι, ὥστε Κάτωνα τὴν πρεσβείαν ἐπισκώπτοντα εἰπεῖν τὴν πρεσβείαν ταύτην μήτε νοῦν ἔχειν μήτε πόδας μήτε κεφαλήν.", "st": "5.6"}, {"sp": "N", "t": "οἱ μὲν δὴ πρέσβεις ἐς Βιθυνίαν ἀφίκοντο, καὶ προσέτασσον αὐτοῖς τὸν πόλεμον ἐκλῦσαι, Νικομήδους δὲ καὶ Ἀττάλου συγχωρεῖν ὑποκρινομένων οἱ Βιθυνοὶ διδαχθέντες ἔλεγον οὐκ εἶναι δυνατοὶ φέρειν ἔτι τὴν ὠμότητα τὴν Προυσίου, φανεροὶ μάλιστα αὐτῷ γενόμενοι δυσχεραίνοντες. οἱ μὲν δὴ πρέσβεις, ὡς οὔπω Ῥωμαίων τάδε πυθομένων, ἐπανῄεσαν ἄπρακτοι· Προυσίας δ’ ἐπεὶ καὶ τὰ Ῥωμαίων ἀπέγνω, οἷς μάλιστα πιστεύων οὐδενὸς ἐς ἄμυναν ἐπεφροντίκει, μετῆλθεν ἐς Νικομήδειαν ὡς κρατυνούμενος τὴν πόλιν καὶ τοῖς ἐπιοῦσι πολεμήσων. οἱ δὲ προδιδόντες αὐτὸν τὰς πύλας ἀνέῳξαν, καὶ ὁ μὲν Νικομήδης ἐσῄει μετὰ τοῦ στρατοῦ, τὸν δὲ Προυσίαν ἐς ἱερὸν Διὸς καταφυγόντα συνεκέντησάν τινες ἐπιπεμφθέντες ἐκ τοῦ Νικομήδους. οὕτω Νικομήδης ἀντὶ Προυσίου Βιθυνῶν ἐβασίλευε, καὶ αὐτὸν χρόνῳ τελευτήσαντα Νικομήδης ὁ υἱός, ᾧ φιλοπάτωρ ἐπίκλησις ἦν, διεδέξατο, Ῥωμαίων αὐτῷ τὴν ἀρχὴν ὡς πατρῴαν ψηφισαμένων.", "st": "5.7"}, {"sp": "N", "t": "τὰ μὲν δὴ Βιθυνῶν ὧδε εἶχε· καὶ εἴ τῳ σπουδὴ πάντα προμαθεῖν, υἱωνὸς τοῦδε ἕτερος Νικομήδης Ῥωμαίοις τὴν ἀρχὴν ἐν διαθήκαις ἀπέλιπεν.", "st": "5.7"}, {"sp": "N", "t": "Καππαδοκίας δὲ πρὸ μὲν Μακεδόνων οἵτινες ἦρχον, οὐκ ἔχω σαφῶς εἰπεῖν, εἴτε ἰδίαν ἀρχήν, εἴτε Δαρείου κατήκουον· Ἀλέξανδρος δέ μοι δοκεῖ τοὺς ἄρχοντας τῶνδε τῶν ἐθνῶν ἐπὶ φόρῳ καταλιπεῖν, ἐπειγόμενος ἐπὶ Δαρεῖον. φαίνεται γὰρ καὶ Ἀμισόν, ἐν Πόντῳ πόλιν Ἀττικοῦ γένους, ἐπὶ δημοκρατίαν ὡς πάτριόν σφισι πολιτείαν ἀναγαγών. Ἱερώνυμος δὲ οὐδ’ ἐπιψαῦσαι τῶν ἐθνῶν ὅλως, ἀλλ’ ἀνὰ τὴν παράλιον τῆς Παμφυλίας καὶ Κιλικίας ἑτέραν ὁδὸν ἐπὶ τὸν Δαρεῖον τραπέσθαι. Περδίκκας δέ, ὃς ἐπὶ Ἀλεξάνδρῳ τῆς Μακεδόνων ἦρχεν, Ἀριαράθην Καππαδοκίας ἡγούμενον, εἴτε ἀφιστάμενον εἴτε τὴν ἀρχὴν αὐτοῦ περιποιούμενος Μακεδόσιν, εἷλε καὶ ἐκρέμασε, καὶ ἐπέστησε τοῖς ἔθνεσιν Εὐμένη τὸν Καρδιανόν. Εὐμένους δὲ ἀναιρεθέντος ὅτε αὐτὸν οἱ Μακεδόνες εἵλοντο εἶναι πολέμιον, Ἀντίπατρος ἐπὶ τῷ Περδίκκᾳ τῆς ὑπὸ Ἀλεξάνδρῳ γενομένης γῆς ἐπιτροπεύων, Νικάνορα ἔπεμψε Καππαδοκῶν σατραπεύειν.", "st": "5.8"}, {"sp": "N", "t": "Μακεδόνων δὲ οὐ πολὺ ὕστερον ἐς ἀλλήλους στασιασάντων, Ἀντίγονος μὲν ἦρχε Συρίας Λαομέδοντα ἐκβαλών, Μιθριδάτης δ’ αὐτῷ συνῆν, ἀνὴρ γένους βασιλείου Περσικοῦ. καὶ ὁ Ἀντίγονος ἐνύπνιον ἔδοξε πεδίον σπεῖραι χρυσίῳ, καὶ τὸ χρυσίον ἐκθερίσαντα τὸν Μιθριδάτην ἐς τὸν Πόντον οἴχεσθαι. καὶ ὁ μὲν αὐτὸν ἐπὶ τῷδε συλλαβὼν ἐβούλετο ἀποκτεῖναι, ὁ δ’ ἐξέφυγε σὺν ἱππεῦσιν ἕξ, καὶ φραξάμενός τι χωρίον τῆς Καππαδοκίας, πολλῶν οἱ προσιόντων ἐν τῇδε τῇ Μακεδόνων ἀσχολίᾳ, Καππαδοκίας τε αὐτῆς καὶ τῶν ὁμόρων περὶ τὸν Πόντον ἐθνῶν κατέσχεν, ἐπί τε μέγα τὴν ἀρχὴν προαγαγὼν παισὶ παρέδωκεν. οἱ δ’ ἦρχον, ἕτερος μεθ’ ἕτερον, ἕως ἐπὶ τὸν ἕκτον ἀπὸ τοῦ πρώτου Μιθριδάτην, ὃς Ῥωμαίοις ἐπολέμησεν. τούτου δὲ τοῦ γένους ὄντες οἱ Καππαδοκίας τε καὶ Πόντου βασιλεῖς ἔσθ’ ὅτε μοι δοκοῦσι διελεῖν τὴν ἀρχήν, καί οἱ μὲν τοῦ Πόντου κατασχεῖν οἱ δὲ Καππαδοκίας.", "st": "5.9"}, {"sp": "N", "t": "ὅ γέ τοι Ῥωμαίοις πρῶτος ἐν φιλίᾳ γενόμενος καὶ ναῦς τινὰς ἐπὶ Καρχηδονίους καὶ συμμαχίαν ὀλίγην παρασχών, βασιλεὺς Πόντου, Μιθριδάτης ὁ εὐεργέτης ἐπίκλησιν, ὡς ἀλλοτρίαν τὴν Καππαδοκίαν ἐπέδραμεν. καὶ διαδέχεται Μιθριδάτης υἱός, ᾧ Διόνυσος καὶ εὐπάτωρ ἐπώνυμα ἦν. Ῥωμαῖοι δ’ αὐτὸν ἐκστῆναι Καππαδοκίας ἐκέλευσαν Ἀριοβαρζάνῃ, καταφυγόντι τε ἐς αὐτοὺς καὶ δόξαντι ἄρα γνησιωτέρῳ τοῦ Μιθριδάτου πρὸς τὴν Καππαδοκῶν ἀρχήν, ἢ καὶ τὸ μέγεθος τῆς ἀρχῆς τοῦ Μιθριδάτου πολλῆς οὔσης ὑφορώμενοί τε καὶ ἐς πλέονα διαιροῦντες ἀφανῶς. ὁ δὲ τοῦτο μὲν ἤνεγκε, Νικομήδει δὲ τῷ Νικομήδους τοῦ Προυσίου, Βιθυνίας ὡς πατρῴας ὑπὸ Ῥωμαίων ἀποδειχθέντι βασιλεύειν, Σωκράτη τὸν ἀδελφὸν αὐτοῦ Νικομήδους, ὅτῳ χρηστὸς ἐπώνυμον ἦν, μετὰ στρατιᾶς ἐπέμψε· καὶ τὴν Βιθυνῶν ἀρχὴν ὁ Σωκράτης ἐς αὑτὸν περιέσπασεν. τοῦ δ’ αὐτοῦ χρόνου Μιθράας καὶ Βαγώας Ἀριοβαρζάνη τόνδε τὸν ὑπὸ Ῥωμαίων κατηγμένον ἐς τὴν Καππαδοκίαν ἐκβαλόντες, Ἀριαράθην κατήγαγον ἐς αὐτήν.", "st": "5.10"}, {"sp": "N", "t": "Ῥωμαῖοι δὲ Νικομήδην ὁμοῦ καὶ Ἀριοβαρζάνην ἐπανῆγον ἐς τὴν οἰκείαν ἑκάτερον, πρέσβεις τέ τινας αὐτοῖς ἐς τοῦτο συνέπεμψαν, ὧν Μάνιος Ἀκύλιος ἡγεῖτο· καὶ συλλαβεῖν ἐς τὴν κάθοδον ἐπέστειλαν Λευκίῳ τε Κασσίῳ, τῆς περὶ τὸ Πέργαμον Ἀσίας ἡγουμένῳ, στρατιὰν ἔχοντι ὀλίγην, καὶ τῷδε τῷ εὐπάτορι Μιθριδάτῃ. ἀλλ’ ὁ μὲν αὐτῆς τε Καππαδοκίας ἕνεκα Ῥωμαίοις ἐπιμεμφόμενος, καὶ Φρυγίαν ἔναγχος ὑπ’ αὐτῶν ἀφῃρημένος, ὡς διὰ τῆς Ἑλληνικῆς γραφῆς δεδήλωται, οὐ συνέπραττε· Κάσσιος δὲ καὶ Μάνιος τῷ τε Κασσίου στρατῷ, καὶ πολὺν ἄλλον ἀγείραντες Γαλατῶν καὶ Φρυγῶν, Νικομήδη τε κατήγαγον ἐς Βιθυνίαν καὶ Ἀριοβαρζάνην ἐς Καππαδοκίαν. εὐθύς τε ἀνέπειθον ἄμφω, γείτονας ὄντας Μιθριδάτου, τὴν γῆν τὴν Μιθριδάτου κατατρέχειν καὶ ἐς πόλεμον ἐρεθίζειν, ὡς Ῥωμαίων αὐτοῖς πολεμοῦσι συμμαχησόντων. οἱ δὲ ὤκνουν μὲν ὁμοίως ἑκάτερος γείτονος πολέμου τοσοῦδε κατάρξαι, τὴν Μιθριδάτου δύναμιν δεδιότες· ἐγκειμένων δὲ τῶν πρέσβεων, ὁ Νικομήδης πολλὰ μὲν ὑπὲρ τῆς ἐπικουρίας τοῖς στρατηγοῖς καὶ τοῖς πρέσβεσιν ὡμολογηκὼς χρήματα δώσειν καὶ ἔτι ὀφείλων, πολλὰ δ’ ἄλλα παρὰ τῶν ἑπομένων Ῥωμαίων δεδανεισμένος καὶ ὀχλούμενος, ἄκων ἐσέβαλεν ἐς τὴν Μιθριδάτου γῆν καὶ ἐλεηλάτησεν ἐπὶ πόλιν Ἄμαστριν, οὐδενὸς οὔτε κωλύοντος αὐτὸν οὔτε ἀπαντῶντος. ὁ γάρ τοι Μιθριδάτης ἑτοίμην ἔχων δύναμιν ὅμως ὑπεχώρει, πολλὰ καὶ δίκαια διδοὺς ἐγκλήματα τῷ πολέμῳ γενέσθαι.", "st": "5.11"}, {"sp": "N", "t": "ἀναζεύξαντος δὲ τοῦ Νικομήδους μετὰ πολλῶν λαφύρων, Πελοπίδαν ὁ Μιθριδάτης ἔπεμπεν ἐς τοὺς Ῥωμαίων στρατηγούς τε καὶ πρέσβεις, οὐκ ἀγνοῶν μὲν αὐτοὺς πολεμησείοντας αὑτῷ καὶ τῆσδε τῆς ἐσβολῆς αἰτίους γεγονότας, ὑποκρινόμενος δέ, καὶ πλείονας ὁμοῦ καὶ εὐπρεπεστέρας αἰτίας τοῦ γενησομένου πολέμου πορίζων, ἀνεμίμνησκε φιλίας καὶ συμμαχίας ἰδίας τε καὶ πατρῴας. ἀνθ’ ὧν αὐτὸν ὁ Πελοπίδας ἔφη Φρυγίαν ἀφῃρῆσθαι καὶ Καππαδοκίαν, τὴν μὲν ἀεὶ τῶν προγόνων αὐτοῦ γενομένην καὶ ὑπὸ τοῦ πατρὸς ἀναληφθεῖσαν, Φρυγίαν δὲ ἐπινίκιον ἐπὶ Ἀριστονίκῳ παρὰ τοῦ ὑμετέρου στρατηγοῦ δοθεῖσάν τε καὶ οὐχ ἧσσον παρὰ τοῦ αὐτοῦ στρατηγοῦ πολλῶν χρημάτων ἐωνημένην. “νῦν δ’,” ἔφη, “καὶ Νικομήδη τὸ στόμα τοῦ Πόντου διακλείοντα περιορᾶτε, καὶ τὴν γῆν μέχρι Ἀμάστριδος ἐπιτρέχοντα, καὶ λείαν ἄγοντα ὅσην ἴστε ἀκριβῶς, οὐκ ἀσθενῶς οὐδὲ ἀνετοίμως ἔχοντος πρὸς ἄμυναν τοῦ ἐμοῦ βασιλέως, ἀλλ’ ἀναμένοντος ὑμᾶς ἐν ὄψει μάρτυρας τῶν γιγνομένων γενέσθαι. ἐπειδὴ δὲ ἐγένεσθέ τε καὶ εἴδετε, παρακαλεῖ Μιθριδάτης, φίλος ὢν ὑμῖν καὶ σύμμαχος, φίλους ὄντας ὑμᾶς καὶ συμμάχους (ὧδε γὰρ αἱ συνθῆκαι λέγουσιν), ἐπικουρεῖν ἡμῖν ἀδικουμένοις ὑπὸ Νικομήδους, ἢ κωλύειν αὐτὸν ἀδικοῦντα.”", "st": "5.12"}, {"sp": "N", "t": "ὁ μὲν τοιαῦτα εἶπε, Νικομήδους δὲ πρέσβεις ἐς ἀντιλογίαν αὐτῷ παρόντες ἔφασαν· “Νικομήδει μὲν ἐκ πολλοῦ Μιθριδάτης ἐπιβουλεύων Σωκράτη μετὰ στρατιᾶς ἐπὶ τὴν βασιλείαν ἐπῆγεν, ἡσυχάζοντα καὶ δικαιοῦντα τὸν πρεσβύτερον ἄρχειν. καὶ ὧδε Μιθριδάτης ἐς Νικομήδην ἔπραξεν, ὃν ὑμεῖς, ὦ Ῥωμαῖοι, Βιθυνῶν ἐστήσασθε βασιλεύειν· ὃ καὶ δῆλόν ἐστιν οὐκ ἐς ἡμᾶς μᾶλλον ἢ ἐς ὑμᾶς γεγονέναι. τῷ δ’ αὐτῷ λόγῳ κεκελευκότων ὑμῶν τοῖς ἐν Ἀσίᾳ βασιλεῦσι τῆς Εὐρώπης μηδὲ ἐπιβαίνειν, τὰ πολλὰ Χερρονήσου περιέσπασεν. καὶ τάδε μὲν ἔστω τῆς ἐς ὑμᾶς ὕβρεώς τε καὶ δυσμενείας αὐτοῦ καὶ ἀπειθείας ἔργα· ἡ παρασκευὴ δὲ ὅση, καὶ πᾶσα ἕτοιμος ὡς ἐπὶ μέγαν δὴ καὶ ἐγνωσμένον πόλεμον ἤδη, τοῦ τε ἰδίου στρατοῦ καὶ συμμάχων Θρᾳκῶν καὶ Σκυθῶν, ὅσα τε ἄλλα πλησίον ἔθνη. ἐς δὲ τὸν Ἀρμένιον αὐτῷ καὶ ἐπιγαμία γέγονε, καὶ ἐς Αἴγυπτον καὶ Συρίαν περιπέμπει προσεταιριζόμενος τοὺς βασιλέας. νῆές τε εἰσὶν αὐτῷ κατάφρακτοι τριακόσιαι, καὶ ἑτέρας προσαπεργάζεται· ἐπί τε πρῳρέας καὶ κυβερνήτας ἐς Φοινίκην καὶ ἐς Αἴγυπτον περιέπεμψεν. ἅπερ οὐκ ἐπὶ Νικομήδει που, τοσάδε ὄντα, ἀλλ’ ἐφ’ ὑμῖν, ὦ Ῥωμαῖοι, Μιθριδάτης, ἐργάζεται, δυσμεναίνων μὲν ἐξ οὗ Φρυγίαν αὐτὸν πανούργως πριάμενον, καὶ δεκάσαντα τῶν ὑμετέρων τινὰ στρατηγῶν, ἀποθέσθαι προσετάξατε, τῆς οὐ δικαίας κτήσεως καταγνόντες, χαλεπαίνων δ’ ἐπὶ Καππαδοκία, δεδομένῃ καὶ τῇδε πρὸς ὑμῶν Ἀριοβαρζάνῃ, δεδιὼς δ’ αὐξομένους ὑμᾶς, καὶ παρασκευαζόμενος ἐν τῇ καθ’ ἡμᾶς προφάσει καὶ ὑμῖν, εἰ δύναιτο, ἐπιθέσθαι. σωφρόνων δ’ ἐστὶ μὴ περιμένειν ὅτε πολεμεῖν ὑμῖν ὁμολογήσει, ἀλλ’ ἐς τὰ ἔργα αὐτοῦ μᾶλλον ἢ τοὺς λόγους ἀφορᾶν μηδὲ φιλίας ὄνομα ἐπίπλαστον ὑποκρινομένῳ τοὺς ἀληθεῖς καὶ βεβαίους ἐκδοῦναι φίλους, μηδὲ τὴν σφετέραν περὶ τῆς ἡμετέρας βασιλείας κρίσιν ὑπεριδεῖν ἀκυρουμένην ὑπ’ ἀνδρὸς ὁμοίως ἡμῖν τε καὶ ὑμῖν ἐχθροῦ.”", "st": "5.13"}, {"sp": "N", "t": "ὧδε μὲν καὶ οἱ Νικομήδους ἔλεξαν· ἐπελθὼν δὲ αὖθις ὁ Πελοπίδας ἐς τὸ τῶν Ῥωμαίων συνέδριον περὶ μὲν τῶν πάλαι γεγονότων, εἴ τι Νικομήδης ἐπιμέμφοιτο, δικάσαι Ῥωμαίους ἠξίου, τὰ δὲ νῦν (ἐν ὄψει γὰρ ὑμῶν γέγονε, τῆς τε γῆς τῆς Μιθριδάτου δῃουμένης καὶ τῆς θαλάττης ἀποκεκλεισμένης καὶ λείας τοσῆσδε ἐλαυνομένης) οὐ λόγων ἔφη χρῄζειν οὐδὲ κρίσεως, “ἀλλ’ αὖθις ὑμᾶς παρακαλοῦμεν ἢ κωλύειν τὰ γιγνόμενα ἢ Μιθριδάτῃ συμμαχεῖν ἀδικουμένῳ, ἢ τελευταῖον, ὦ ἄνδρες Ῥωμαῖοι, μηδὲ κωλύειν ἀμυνόμενον, ἀλλ’ ἀμφοῖν ἐκστῆναι τοῦ πόνοῦ.” τοσαῦτα τοῦ Πελοπίδου παλιλλογήσαντος, ἔγνωστο μὲν ἐκ πολλοῦ τοῖς Ῥωμαίων στρατηγοῖς ἐπικουρεῖν Νικομήδει, καὶ ἐς ὑπόκρισιν τῆς ἀντιλογίας ἠκροῶντο· τὰ δὲ εἰρημένα ὅμως ὑπὸ τοῦ Πελοπίδου, καὶ τὴν τοῦ Μιθριδάτου φιλίαν ἐνσύνθηκον ἔτι οὖσαν, αἰδούμενοι ἠπόρουν ἀποκρίσεως ἐπὶ πολύ, μέχρι ἐπιστήσαντες μετὰ σοφίας ὧδε ἀπεκρίναντο. “οὔτε Μιθριδάτην ἄν τι βουλοίμεθα πάσχειν ἄχαρι πρὸς Νικομήδους, οὔτε Νικομήδους ἀνεξόμεθα πολεμουμένου· οὐ γὰρ ἡγούμεθα Ῥωμαίοις συμφέρειν βλάπτεσθαι Νικομήδη.” ταῦτα δ’ εἰπόντες τὸν Πελοπίδαν, βουλόμενον διελέγχειν τῆς ἀποκρίσεως τὴν ἀπορίαν, ἀπέπεμψαν ἐκ τοῦ συνεδρίου.", "st": "5.14"}, {"sp": "N", "t": "Μιθριδάτης μὲν οὖν, ὡς ἐμφανῶς ἤδη πρὸς Ῥωμαίων ἀδικούμενος, ἔπεμπε σὺν πολλῇ χειρὶ τὸν υἱὸν Ἀριαράθην βασιλεύειν Καππαδοκίας. καὶ εὐθὺς ἦρχεν αὐτῆς ὁ Ἀριαράθης, Ἀριοβαρζάνην ἐκβαλών. Πελοπίδας δὲ ἐς τοὺς Ῥωμαίων στρατηγοὺς αὖθις ἐλθὼν ἔλεγεν ὧδε. “ἃ μὲν ἠδικημένος πρὸς ὑμῶν, ὦ Ῥωμαῖοι, βασιλεὺς Μιθριδάτης ἔφερε, Φρυγίαν τε καὶ Καππαδοκίαν ἀφῃρημένος ἔναγχος, ἠκούσατε· ἃ δὲ Νικομήδης αὐτὸν ἔβλαπτεν, ὁρῶντες ὑπερείδετε. φιλίαν τε καὶ συμμαχίαν ἡμῖν προφέρουσιν, ὥσπερ οὐκ ἐγκαλοῦσιν ἀλλ’ ἐγκαλουμένοις ἀπεκρίνασθε μὴ νομίζειν συμφέρειν τοῖς Ῥωμαίων πράγμασι βλάπτεσθαι Νικομήδη οἷάπερ αὐτὸν ἀδικούμενον. ὑμεῖς οὖν αἴτιοι τῷ κοινῷ Ῥωμαίων τοῦδε τοῦ περὶ Καππαδοκίαν γεγονότος· διὰ γὰρ ὑμᾶς, ὧδε μὲν ἡμᾶς ὑπερορῶντας ὧδε δὲ σοφίζοντας ἐν ταῖς ἀποκρίσεσιν, οὕτως ἔπραξεν ὁ Μιθριδάτης. καὶ πρεσβεύσεται καθ’ ὑμῶν ἐς τὴν ὑμετέραν βουλήν, ἐφ’ ἣν ὑμῖν ἀπολογησομένοις ἐπαγγέλλει παρεῖναι, φθάνειν δὲ μηδέν, μηδ’ ἐξάρχειν ἄνευ τοῦ κοινοῦ τῶν Ῥωμαίων τοσοῦδε πολέμου, ἐνθυμουμένους ὅτι Μιθριδάτης βασιλεύει μὲν τῆς πατρῴας ἀρχῆς, ἣ δισμυρίων ἐστὶ σταδίων τὸ μῆκος, προσκέκτηται δὲ πολλὰ περίχωρα, καὶ Κόλχους, ἔθνος ἀρειμανές, Ἑλλήνων τε τοὺς ἐπὶ τοῦ Πόντου κατῳκισμένους, καὶ βαρβάρων τοὺς ὄντας ὑπὲρ αὐτούς. φίλοις δ’ ἐς πᾶν τὸ κελευόμενον ἑτοίμοις χρῆται Σκύθαις τε καὶ Ταύροις καὶ Βαστέρναις καὶ Θρᾳξὶ καὶ Σαρμάταις καὶ πᾶσι τοῖς ἀμφὶ Τάναΐν τε καὶ Ἴστρον καὶ τὴν λίμνην ἔτι τὴν Μαιώτιδα. Τιγράνης δ’ ὁ Ἀρμένιος αὐτῷ κηδεστής ἐστι, καὶ Ἀρσάκης ὁ Παρθυαῖος φίλος. νεῶν τε πλῆθος ἔχει, τὸ μὲν ἕτοιμον τὸ δὲ γιγνόμενον ἔτι, καὶ παρασκευὴν ἐς πάντα ἀξιόλογον.", "st": "5.15"}, {"sp": "N", "t": "“οὐκ ἐψεύσαντο δ’ ὑμῖν ἔναγχος οἱ Βιθυνοὶ καὶ περὶ τῶν ἐν Αἰγύπτῳ καὶ Συρίᾳ βασιλέων· οὓς οὐ μόνον εἰκός ἐστιν ἡμῖν, εἰ πόλεμος γένοιτο, προσθήσεσθαι, ἀλλὰ καὶ τὴν νεόκτητον ὑμῖν Ἀσίαν καὶ Ἑλλάδα καὶ Λιβύην καὶ πολλὰ καὶ αὐτῆς Ἰταλίας, ὅσα τὴν ὑμετέραν πλεονεξίαν οὐ φέροντα πολεμεῖ νῦν ὑμῖν πόλεμον ἄσπειστον. ὃν οὔπω διαθέσθαι δυνηθέντες ἐπιχειρεῖτε Μιθριδάτῃ, Νικομήδην αὐτῷ καὶ Ἀριοβαρζάνην παρὰ μέρος ἐπιπέμποντες· καὶ φατὲ μὲν εἶναι φίλοι καὶ σύμμαχοι, καὶ ὑποκρίνεσθε οὕτω, χρῆσθε δὲ ὡς πολεμίῳ. φέρετε οὖν, καὶ νῦν, εἴ τι πρὸς τῶν γεγονότων ἐς μετάνοιαν ἠρέθισθε, ἢ Νικομήδη κωλύσατε τοὺς ὑμετέρους ἀδικεῖν φίλους (καὶ τάδε πράξασιν ὑμῖν ὑπέχομαι συμμαχήσειν ἐπὶ τοὺς Ἰταλοὺς βασιλέα Μιθριδάτην), ἢ τὴν δοκοῦσαν ἐς ἡμᾶς φιλίαν λύσατε, ἢ ἐς Ῥώμην ἐπὶ κρίσιν ἴωμεν.”", "st": "5.16"}, {"sp": "N", "t": "ὁ μὲν δὴ Πελοπίδας ὧδε ἔλεξεν, οἱ δὲ φορτικώτερον αὐτὸν εἰπεῖν ἡγούμενοι, Μιθριδάτην μὲν ἐκέλευον ἀπέχεσθαι Νικομήδους καὶ Καππαδοκίας (αὐτοὶ γὰρ αὖθις Ἀριοβαρζάνην ἐς αὐτὴν κατάξειν), Πελοπίδαν δ’ εὐθὺς ἐξιεναι τοῦ στρατοπέδου, καὶ μηκέτι πρεσβεύειν ἐς αὑτους, εἰ μὴ τοῖς κελευομένοις ὁ βασιλεὺς ἐμμένοι. οὕτω μὲν ἀπεκρίναντο, καὶ ἀπιόντι φυλακὴν συνέπεμψαν, ἵνα μή τινας ἐπιτρίψειε παροδεύων.", "st": "5.16"}, {"sp": "N", "t": "ταῦτα δὲ εἰπόντες, οὐκ ἀναμείναντες περὶ τοσοῦδε πολέμου τὴν βουλὴν ἢ τὸν δῆμον ἐπιγνώμονα γενέσθαι, στρατιὰν ἤγειρον ἔκ τε Βιθυνίας καὶ Καππαδοκίας καὶ Παφλαγονίας καὶ Γαλατῶν τῶν ἐν Ἀσίᾳ. ὡς δὲ αὐτοῖς ὅ τε ἴδιος στρατός, ὅσον εἶχε Λεύκιος Κάσσιος ὁ τῆς Ἀσίας ἡγούμενος, ἕτοιμος ἦν ἤδη, καὶ τὰ συμμαχικὰ πάντα συνεληλύθει, διελόμενοι τὸ πλῆθος ἐστρατοπέδευον, Κάσσιος μὲν ἐν μέσῳ Βιθυνίας τε καὶ Γαλατίας, Μάνιος δὲ ᾗ διαβατὸν ἦν ἐς Βιθυνίαν τῷ Μιθριδάτῃ, Ὄππιος δὲ ἔτερος στρατηγὸς ἐπὶ τῶν ὀρῶν τῶν Καππαδοκίας, ἱππέας ἔχων ἕκαστος αὐτῶν καὶ πεζοὺς ἀμφὶ τοὺς τετρακισμυρίους. ἦν δὲ καὶ νεῶν στόλος αὐτοῖς, οὗ περὶ Βυζάντιον Μινούκιός τε Ῥοῦφος καὶ Γάιος Ποπίλιος ἡγοῦντο, τὸ στόμα τοῦ Πόντου φυλάσσοντες. παρῆν δὲ αὐτοῖς καὶ Νικομήδης, ἄρχων ἑτέρων πεντακισμυρίων πεζῶν καὶ ἱππέων ἑξακισχιλίων. τοσόσδε μὲν αὐτοῖς ἀθρόως στρατὸς ἀγήγερτο· Μιθριδάτῃ δὲ τὸ μὲν οἰκεῖον ἦν μυριάδες πεζῶν πέντε καὶ εἴκοσι καὶ ἱππεῖς τετρακισμύριοι, καὶ νῆες κατάφρακτοι τριακόσιαι, δίκροτα δὲ ἑκατόν, καὶ ἡ ἄλλη παρασκευὴ τούτων κατὰ λόγον, στρατηγοὶ δὲ Νεοπτόλεμός τε καὶ Ἀρχέλαος, ἀλλήλων ἀδελφώ, καὶ τοῖς πλείστοις αὐτὸς παρεγίγνετο. συμμαχικὰ δὲ ἦγον αὐτῷ Ἀρκαθίας μέν, αὐτοῦ Μιθριδάτου παῖς, ἐκ τῆς βραχυτέρας Ἀρμενίας μυρίους ἱππέας, καὶ Δορύλαος … ἐν φάλαγγι ταττομένους, Κρατερὸς δ’ ἑκατὸν καὶ τριάκοντα ἅρματα. τοσαύτη μὲν ἦν ἑκατέροις ἡ παρασκευή, ὅτε πρῶτον ᾔεσαν ἐς ἀλλήλους Ῥωμαῖοί τε καὶ Μιθριδάτης, ἀμφὶ τὰς ἑκατὸν καὶ ἑβδομήκοντα τρεῖς ὀλυμπιάδας.", "st": "5.17"}, {"sp": "N", "t": "ἐν δὲ πεδιῳ πλατεῖ παρὰ τὸν Αμνειον ποταμὸν κατιδόντες ἀλλήλους ὅ τε Νικομήδης καὶ οἱ τοῦ Μιθριδάτου στρατηγοὶ παρέταττον ἐς μάχην, Νικομήδης μὲν ἅπαντας τοὺς ἑαυτοῦ, Νεοπτόλεμος δὲ καὶ Ἀρχέλαος τοὺς εὐζώνους μόνους, καὶ οὓς Ἀρκαθίας εἶχεν ἱππέας καί τινα τῶν ἁρμάτων· ἡ γὰρ φάλαγξ ἔτι προσῄει. ἐς δέ τινα γήλοφον τοῦ πεδίου πετρώδη προλαβόντες ἀνέπεμψαν ὀλίγους, ἵνα μὴ κυκλωθεῖεν ὑπὸ τῶν Βιθυνῶν πολὺ πλειόνων ὄντων. ὡς δὲ ἐξωθουμένους εἶδον αὐτοὺς ἐκ τοῦ γηλόφου, δείσας ὁ Νεοπτόλεμος περὶ τῇ κυκλώσει προσεβοήθει μετὰ σπουδῆς, καλῶν ἅμα καὶ τὸν Ἀρκαθίαν. Νικομήδης δ’ ὁρῶν ἀντιπαρῄει· καὶ γίγνεται πολὺς ἐνταῦθα ἀγὼν καὶ φόνος. βιασαμένου δὲ τοῦ Νικομηδους ἔφευγον οἱ Μιθριδάτειοι, ἕως ὁ Ἀρχέλαος ἀπὸ τοῦ δεξιοῦ μετελθὼν ἐνέβαλεν ἐς τοὺς διώκοντας. οἱ δ’ ἐς αὐτὸν ἐπεστράφησαν. ὁ δ’ ὑπεχώρει κατ’ ὀλίγον, ἵν’ ἔχοιεν ἐκ τῆς φυγῆς ἐπανελθεῖν οἱ περὶ Νεοπτόλεμον. ὡς δὲ εἴκασεν αὐτάρκως ἔχειν, ἐπέστρεφε, καὶ τοῖς Βιθυνοῖς τὰ δρεπανηφόρα ἅρματα ἐμπίπτοντα μετὰ ῥύμης διέκοπτε καὶ διέτεμνε τοὺς μὲν ἀθρόως ἐς δύο τοὺς δ’ ἐς μέρη πολλά. τό τε γιγνόμενον ἐξέπληττε τὴν στρατιὰν τοῦ Νικομήδους, ὅτε ἴδοιεν ἡμιτόμους ἄνδρας ἔτι ἔμπνους, ἢ ἐς πολλὰ διερριμμένους, ἢ τῶν δρεπάνων ἀπηρτημένους. ἀηδίᾳ τε μᾶλλον ὄψεως ἢ μάχης ἥσσῃ τὴν τάξιν ὑπὸ φόβου συνέχεαν. ταραχθεῖσι δ’ αὐτοῖς ὁ μὲν Ἀρχέλαος ἐκ τοῦ μετώπου, Νεοπτόλεμος δὲ καὶ Ἀρκαθίας ἐκ τῆς φυγῆς ἀναστρέφοντες ἐπέκειντο ὄπισθεν. οἱ δ’ ἐπὶ πολὺ μὲν ἠμύνοντο, ἐς ἑκατέρους ἐπιστρεφόμενοι· ὡς δὲ τὸ πλεῖστον ἐπεπτώκει, Νικομήδης μὲν ἔφευγε μετὰ τῶν ὑπολοίπων ἐς Παφλαγονίαν, οὐδ’ ἐς χεῖρας ἐλθούσης πω τῆς Μιθριδατείου φάλαγγος, ἑάλω δ’ αὐτοῦ τὸ χαράκωμα καὶ τὰ χρήματα πολλὰ ὄντα καὶ πλῆθος αἰχμαλώτων. οὓς πάντας ὁ Μιθριδάτης φιλανθρωπευσάμενός τε καὶ ἐφόδια δοὺς ἀπέλυσεν ἐς τὰ οἰκεῖα ἀπιέναι, δόξαν ἐμποιῶν τοῖς πολεμίοις φιλανθρωπίας.", "st": "5.18"}, {"sp": "N", "t": "ἔργον δὴ τόδε πρῶτον τοῦ Μιθριδατείου πολέμου καὶ οἱ στρατηγοὶ τῶν Ῥωμαίων κατεπεπλήγεσαν, ὡς οὐκ εὐβουλίᾳ μᾶλλον ἢ προπετῶς, ἄνευ τοῦ κοινοῦ, τοσόνδε πόλεμον ἅψαντες. ὀλίγοι τε γὰρ πολὺ πλειόνων ἐκεκρατήκεσαν, καὶ οὐδεμιᾷ συντυχίᾳ χωρίων ἢ πολεμίου σφάλματος, ἀλλ’ ἀρετῇ στρατηγῶν καὶ ἀνδρείᾳ στρατοῦ. Νικομήδης μὲν οὖν Μανίῳ παρεστρατοπέδευε, Μιθριδάτης δ’ ἐπὶ τὸ Σκορόβαν ὄρος ἀνῄει, ὃ τέλος ἐστὶ Βιθυνῶν καὶ τῆς Ποντικῆς χώρας. πρόδρομοί τε αὐτοῦ, Σαυροματῶν ἑκατὸν ἱππεῖς, ὀκτακοσίοις ἱππεῦσι τοῦ Νικομήδους ἐντυχόντες αἱροῦσι καὶ τούτων τινάς· οὓς πάλιν ὁ Μιθριδάτης σὺν ἐφοδίοις μεθῆκεν ἐς τὰς πατρίδας ἀπιέναι. Μάνιον δ’ ὑποφεύγοντα Νεοπτόλεμός τε καὶ Νεμάνης ὁ Ἀρμένιος ἀμφὶ τὸ πρῶτον Πάχιον χωρίον ἑβδόμης ὥρας καταλαβόντες, οἰχομένου πρὸς Κάσσιον Νικομήδους, ἠνάγκασαν ἐς μάχην ἱππέας ἔχοντα τετρακισχιλίους καὶ πεζοὺς ἔτι τούτων δεκαπλασίονας. κτείναντες δ’ αὐτοῦ περὶ μυρίους, ἐζώγρησαν ἐς τριακοσίους· οὓς ὁμοίως ὁ Μιθριδάτης ἐς αὐτὸν ἀναχθέντας ἀπέλυσε, καταδημοκοπῶν τοὺς πολεμίους. Μανίου δ’ ἐλήφθη καὶ τὸ στρατόπεδον, καὶ φεύγων αὐτὸς ἐπὶ τὸν Σαγγάριον ποταμὸν νυκτὸς γενομένης ἐπέρασέ τε καὶ ἐς Πέργαμον ἐσώθη. Κάσσιος δὲ καὶ Νικομήδης, καὶ ὅσοι ἄλλοι Ῥωμαίων πρέσβεις παρῆσαν, ἐς Λεόντων κεφαλήν, ὃ τῆς Φρυγίας ἐστὶν ὀχυρώτατον χωρίον, μετεστρατοπέδευον· καὶ τὸ πλῆθος ὅσον εἶχον, οὐ πάλαι συνειλεγμένον, χειροτεχνῶν ἢ γεωργῶν ἢ ἰδιωτῶν, ἐγύμναζον, καὶ τοὺς Φρύγας αὐτοῖς προσκατέλεγον. ὀκνούντων δὲ ἑκατέρων ἀπέγνωσαν πολεμεῖν ἀνδράσιν ἀπολέμοις, καὶ διαλύσαντες αὐτοὺς ἀνεχώρουν, Κάσσιος μὲν ἐς Ἀπάμειαν σὺν τῷ ἑαυτοῦ στρατῷ, Νικομήδης δὲ ἐς Πέργαμον, Μάνιος δὲ ἐπὶ Ῥόδου. ὧν, ὅσοι τὸ στόμα τοῦ Πόντου κατεῖχον, πυθόμενοι διελύθησαν, καὶ τάς τε κλεῖς τοῦ Πόντου, καὶ ναῦς ὅσας εἶχον, τῷ Μιθριδάτῃ παρέδοσαν.", "st": "5.19"}, {"sp": "N", "t": "ὁ δὲ ὁρμῇ τῇδε μιᾷ τὴν ἀρχὴν ὅλην τοῦ Νικομήδους ὑπολαβὼν ἐπῄει, καὶ καθίστατο τὰς πόλεις. ἐμβαλὼν δὲ καὶ ἐς Φρυγίαν, ἐς τὸ τοῦ Ἀλεξάνδρου πανδοκεῖον κατέλυσεν, αἰσιούμενος ἄρα, ἔνθαπερ Ἀλέξανδρος ἀνεπαύσατο, καὶ Μιθριδάτην σταθμεῦσαι. ὁ μὲν δὴ καὶ Φρυγίας τὰ λοιπὰ καὶ Μυσίαν καὶ Ἀσίαν, ἃ Ῥωμαίοις νεόκτητα ἦν, ἐπέτρεχε, καὶ ἐς τὰ περίοικα περιπέμπων ὑπηγάγετο Λυκίαν τε καὶ Παμφυλίαν καὶ τὰ μέχρι Ἰωνίας. Λαοδικεῦσι δὲ ἔτι ἀντέχουσι, τοῖς περὶ τὸν Λύκον ποταμόν Ῥωμαίων γάρ τις στρατηγὸς Κόιντος Ὄππιος, ἱππέας ἔχων καὶ μισθοφόρους τινάς, ἐς τὴν πόλιν ἐσδραμὼν ἐφύλαττεν αὐτήν̓, κήρυκα ἐπιπέμψας ἐπὶ τὰ τείχη λέγειν ἐκέλευσεν ὅτι βασιλεὺς Μιθριδάτης ὑπέχεται Λαοδικεῦσιν ἄδειαν, εἰ τὸν Ὄππιον αὐτῷ προσαγάγοιεν. οἱ δ’ ἐπὶ τῷ κηρύγματι τοὺς μὲν μισθοφόρους Ὀππίου μεθῆκαν ἀπαθεῖς ἀπιέναι, αὐτὸν δ’ ἤγαγον τῷ Μιθριδάτῃ τὸν Ὄππιον, ἡγουμένων αὐτῷ τῶν ῥαβδοφόρων ἐπὶ γέλωτι. καὶ αὐτὸν ὁ Μιθριδάτης οὐδὲν διαθεὶς ἐπήγετο πανταχοῦ λελυμένον, ἐπιδεικνύμενος ἄρα Ῥωμαίων αἰχμάλωτον στρατηγόν.", "st": "5.20"}, {"sp": "N", "t": "μετ’ οὐ πολὺ δὲ καὶ Μάνιον Ἀκύλιον, τὸν τῆσδε τῆς πρεσβείας καὶ τοῦδε τοῦ πολέμου μάλιστα αἴτιον, ἑλὼν δεδεμένον ἐπὶ ὄνου περιήγετο, κηρύσσοντα τοῖς ὁρῶσιν ὅτι Μάνιος εἴη, μέχρι ἐν Περγάμῳ τοῦ στόματος αὐτοῦ κατεχώνευσε χρυσίον, δωροδοκίαν ἄρα Ῥωμαίοις ὀνειδίζων. σατράπας δὲ τοῖς ἔθνεσιν ἐπιστήσας, ἐς Μαγνησίαν καὶ Ἔφεσον καὶ Μιτυλήνην παρῆλθεν, ἀσμένως αὐτὸν ἁπάντων δεχομένων, Ἐφεσίων δὲ καὶ τὰς Ῥωμαίων εἰκόνας τὰς παρὰ σφίσι καθαιρούντων, ἐφ’ ᾧ δίκην ἔδοσαν οὐ πολὺ ὕστερον. ἐπανιὼν δὲ ἐκ τῆς Ἰωνίας Στρατονίκειαν εἷλε καὶ ἐζημίωσε χρήμασι, καὶ φρουρὰν ἐς τὴν πόλιν ἐσήγαγεν. παρθένον τε εὔμορφον ἰδὼν ἐς τὰς γυναῖκας ἀνεδέξατο· καὶ εἴ τῳ σπουδὴ καὶ τὸ ὄνομα πυθέσθαι, Μονίμη Φιλοποίμενος ἦν. Μάγνησι δὲ καὶ Παφλαγόσι καὶ Λυκίοις ἔτι ἀντέχουσι διὰ τῶν στρατηγῶν ἐπολέμει.", "st": "5.21"}, {"sp": "N", "t": "καὶ τάδε μὲν ἦν ἀμφὶ τὸν Μιθριδάτην· Ῥωμαῖοι δ’ ἐξ οὗ τῆς πρώτης αὐτοῦ ὁρμῆς τε καὶ ἐς τὴν Ἀσίαν ἐσβολῆς ἐπύθοντο, στρατεύειν ἐπ’ αὐτὸν ἐψηφίσαντο, καίπερ ἀσχολούμενοι στάσεσιν ἀτρύτοις ἐν τῇ πόλει καὶ οἰκείῳ πολέμῳ χαλεπῷ, τῆς Ἰταλίας ἀφισταμένης σχεδὸν ἁπάσης ἀνὰ μέρος. κληρουμένων δὲ τῶν ὑπάτων, ἔλαχε μὲν Κορνήλιος Σύλλας ἄρχειν τῆς Ἀσίας καὶ πολεμεῖν τῷ Μιθριδάτῃ, χρήματα δ’ οὐκ ἔχοντες αὐτῷ ἐσενεγκεῖν, ἐψηφίσαντο πραθῆναι ὅσα Νουμᾶς Πομπίλιος βασιλεὺς ἐς θυσίας θεῶν διετέτακτο. τοσήδε μὲν ἦν τότε πάντων ἀπορία καὶ ἐς πάντα φιλοτιμία. καὶ τινα αὐτῶν ἔφθασε πραθῆναι καὶ συνενεγκεῖν χρυσίου λίτρας ἐνακισχιλίας, ἃς μόνας ἐς τηλικοῦτον πόλεμον ἔδοσαν.", "st": "5.22"}, {"sp": "N", "t": "Σύλλαν μὲν οὖν ἐς πολὺ αἱ στάσεις κατέσχον, ὡς ἐν τοῖς ἐμφυλίοις συγγέγραπται· ἐν τούτῳ δ’ ὁ Μιθριδάτης ἐπί τε Ῥοδίους ναῦς πλείονας συνεπήγνυτο, καὶ σατράπαις ἅπασι καὶ πόλεων ἄρχουσι δι’ ἀπορρήτων ἔγραφε, τριακοστὴν ἡμέραν φυλάξαντας ὁμοῦ πάντας ἐπιθέσθαι τοῖς παρὰ σφίσι Ῥωμαίοις καὶ Ἰταλοῖς, αὐτοῖς τε καὶ γυναιξὶν αὐτῶν καὶ παισὶ καὶ ἀπελευθέροις ὅσοι γένους Ἰταλικοῦ, κτείναντάς τε ἀτάφους ἀπορρῖψαι, καὶ τὰ ὄντα αὐτοῖς μερίσασθαι πρὸς βασιλέα Μιθριδάτην. ἐπεκήρυξε δὲ καὶ ζημίαν τοῖς καταθάπτουσιν αὐτοὺς ἢ ἐπικρύπτουσι, καὶ μήνυτρα τοῖς ἐλέγχουσιν ἢ τοὺς κρυπτομένους ἀναιροῦσι, θεράπουσι μὲν ἐπὶ δεσπότας ἐλευθερίαν, χρήσταις δ’ ἐπὶ δανειστὰς ἥμισυ τοῦ χρέους. τάδε μὲν δὴ δι’ ἀπορρήτων ὁ Μιθριδάτης ἐπέστελλεν ἅπασιν ὁμοῦ, καὶ τῆς ἡμέρας ἐπελθούσης συμφορῶν ἰδέαι ποικίλαι κατὰ τὴν Ἀσίαν ἦσαν, ὧν ἔνια τοιάδε ἦν.", "st": "5.22"}, {"sp": "N", "t": "Ἐφέσιοι τοὺς ἐς τὸ Αρτεμίσιον καταφυγόντας, συμπλεκομένους τοῖς ἀγάλμασιν, ἐξέλκοντες ἔκτεινον. Περγαμηνοὶ τοὺς ἐς τὸ Ἀσκληπιεῖον συμφυγόντας, οὐκ ἀφισταμένους, ἐτόξευον τοῖς ξοάνοις συμπλεκομένους. Ἀδραμυττηνοὶ τοὺς ἐκνέοντας ἐσβαίνοντες ἐς τὴν θάλασσαν ἀνῄρουν, καὶ τὰ βρέφη κατεπόντουν. Καύνιοι Ῥοδίοις ὑποτελεῖς ἐπὶ τῷ Ἀντιόχου πολέμῳ γενόμενοι, καὶ ὑπὸ Ῥωμαίων ἀφεθέντες οὐ πρὸ πολλοῦ, τοὺς Ἰταλοὺς ἐς τὴν βουλαίαν Ἑστίαν καταφυγόντας ἕλκοντες ἀπὸ τῆς Ἑστίας, τὰ βρέφη σφῶν πρῶτα ἔκτεινον ἐν ὄψει τῶν μητέρων, αὐτὰς δὲ καὶ τοὺς ἄνδρας ἐπ’ ἐκείνοις. Τραλλιανοὶ δ’ αὐθένται τοῦ κακοῦ φυλαξάμενοι γενέσθαι, Παφλαγόνα Θεόφιλον, ἄγριον ἄνδρα, ἐς τὸ ἔργον ἐμισθώσαντο, καὶ ὁ Θεόφιλος αὐτοὺς συναγαγὼν ἐπὶ τὸν τῆς ὁμονοίας νεὼν ἥπτετο τοῦ φόνου, καὶ τινῶν τοῖς ἀγάλμασι συμπλεκομένων τὰς χεῖρας ἀπέκοπτεν. τοιαύταις μὲν τύχαις οἱ περὶ τὴν Ἀσίαν ὄντες Ἰταλοὶ καὶ Ῥωμαῖοι συνεφέροντο, ἄνδρες τε ὁμοῦ καὶ βρέφη καὶ γυναῖκες, καὶ ἐξελεύθεροι καὶ θεράποντες αὐτῶν, ὅσοι γένους Ἰταλικοῦ. ᾧ καὶ μάλιστα δῆλον ἐγένετο τὴν Ἀσίαν οὐ φόβῳ Μιθριδάτου μᾶλλον ἢ μίσει Ῥωμαίων τοιάδε ἐς αὐτοὺς ἐργάσασθαι. ἀλλ’ οὗτοι μὲν δίκην ἔδοσαν διπλῆν, αὐτοῦ τε Μιθριδάτου μετ’ ὀλίγον ἀπίστως ἐξυβρίσαντος ἐς αὐτούς, καὶ ὕστερον Κορνηλίῳ Σύλλᾳ· Μιθριδάτης δὲ ἐς μὲν Κῶ κατέπλευσε, Κῴων αὐτὸν ἀσμένως δεχομένων, καὶ τὸν Ἀλεξάνδρου παῖδα τοῦ βασιλεύοντος Αἰγύπτου, σὺν χρήμασι πολλοῖς ὑπὸ τῆς μάμμης Κλεοπάτρας ἐν Κῷ καταλελειμμένον, παραλαβὼν ἔτρεφε βασιλικῶς, ἔκ τε τῶν Κλεοπάτρας θησαυρῶν γάζαν πολλὴν καὶ τέχνην καὶ λίθους καὶ κόσμους γυναικείους καὶ χρήματα πολλὰ ἐς τὸν Πόντον ἔπεμψεν.", "st": "5.23"}, {"sp": "N", "t": "ἐν δὲ τούτῳ Ῥόδιοι τά τε τειχη σφῶν καὶ τοὺς λιμένας ἐκρατύναντο, καὶ μηχανὰς ἅπασιν ἐφίστανον· καί τινες αὐτοῖς Τελμισέων τε καὶ Λυκίων συνέμαχουν. ὅσοι τε ἐξ Ἀσίας Ἰταλοὶ διεπεφεύγεσαν, ἐς Ῥόδον ἅπαντες ἐχώρουν, καὶ σὺν αὐτοῖς Λεύκιος Κάσσιος ὁ τῆς Ἀσίας ἀνθύπατος. ἐπιπλέοντος δὲ τοῦ Μιθριδάτου τὰ προάστεια καθῄρουν, ἵνα μηδὲν εἴη χρήσιμα τοῖς πολεμίοις, καὶ ἐπὶ ναυμαχίαν ἀνήγοντο, ταῖς μὲν ἐκ μετώπου ταῖς δὲ πλαγίοις. ὁ δὲ βασιλεὺς ἐπὶ πεντήρους περιπλέων ἐκέλευε τοὺς ἰδίους ἐς τὸ πέλαγος ἀνάγειν ἐπὶ κέρως, καὶ τὴν εἰρεσίαν ἐπιταχύναντας περικυκλοῦσθαι τοὺς πολεμίους ὀλιγωτέρους ὄντας, μέχρι δείσαντες οἱ Ῥόδιοι περὶ τῇ κυκλώσει ὑπεχώρουν κατ’ ὀλίγον· εἶτ’ ἐπιστρέψαντες ἐς τὸν λιμένα κατέφυγον, καὶ κλείθροις αὐτὸν διαλαβόντες ἀπὸ τῶν τειχῶν τὸν Μιθριδάτην ἀπεμάχοντο. ὁ δὲ τῇ πόλει παραστρατοπεδεύων καὶ συνεχῶς τῶν λιμένων πειρώμενος καὶ ἀποτυγχάνων, ἀνέμενε τὸ πεζὸν ἐκ τῆς Ἀσίας οἱ παραγενέσθαι. κἀν τούτῳ βραχεῖαι καὶ συνεχεῖς ἐγίγνοντο ἁψιμαχίαι τῶν ἐφεδρευόντων τοῖς τείχεσιν, ἐν αἷς οἱ Ῥόδιοι πλεονεκτοῦντες ἀνεθάρσουν κατ’ ὀλίγον, καὶ τὰς ναῦς διὰ χειρὸς εἶχον ὡς, εἴ πῃ καιρὸν εὕροιεν, ἐπιθησόμενοι τοῖς πολεμίοις.", "st": "5.24"}, {"sp": "N", "t": "ὁλκάδος δὲ βασιλικῆς ἱστίῳ παραπλεούσης, Ῥοδία δίκροτος ἐπ’ αὐτὴν ἀνήχθη· καὶ ταῖσδε κατὰ σπουδὴν ἑκατέρων ἐπιβοηθούντων ναυμαχία γίγνεται καρτερά, Μιθριδάτου μὲν ἐπιβαρύνοντος ὀργῇ καὶ πλήθεσι νεῶν, Ῥοδίων δ’ αὐτοῦ τὰ σκάφη σὺν ἐμπειρίᾳ περιπλεόντων τε καὶ ἀνατιτρώντων, ὥστε καὶ τριήρη αὐτοῖς ἀνδράσιν ἀναδησάμενοι καὶ ἀκροστόλια πολλὰ καὶ σκῦλα ἐς τὸν λιμένα φέροντες ἐπανελθεῖν. πεντήρους δὲ σφῶν εἰλημμένης ὑπὸ τῶν πολεμίων, ἀγνοοῦντες οἱ Ῥόδιοι ἐπὶ ζήτησιν αὐτῆς ἓξ ταῖς μάλιστα ταχυναυτούσαις ἀνέπλεον, καὶ Δαμαγόρας ἐπ’ αὐτῶν ὁ ναύαρχος ἐπέπλει. πέντε δ’ αὐτῷ καὶ εἴκοσιν ἐπιπέμψαντος τοῦ Μιθριδάτου, μέχρι μὲν ἐς δύσιν ὁ Δαμαγόρας ὑπεχώρει, συσκοτάζοντος δ’ ἤδη ταῖς βασιλικαῖς ἐς ἀπόπλουν ἐπιστρεφομέναις ἐμβαλὼν δύο κατεπόντωσε, δύο δ’ ἄλλας ἐς Λυκίαν συνεδίωξε, καὶ τὴν νύκτα πελαγίσας ἐπανῆλθεν. τοῦτο Ῥοδίοις καὶ Μιθριδάτῃ τέλος ἦν τῆς ναυμαχίας, παρὰ δόξαν Ῥοδίοις τε διὰ τὴν ὀλιγότητα καὶ Μιθριδάτῃ διὰ τὸ πλῆθος γενόμενον. ἐν δὲ τῷ ἔργῳ περιπλέοντι τῷ βασιλεῖ, καὶ τοὺς οἰκείους ἐπισπέρχοντι, Χία συμμαχὶς ἐμβαλοῦσα ἐκ θορύβου κατέσεισε· καὶ ὁ βασιλεύς, οὐδὲν τότε φροντίζειν ὑποκρινάμενος, τὸν κυβερνήτην ὕστερον ἐκόλασε καὶ τὸν πρῳρέα, καὶ Χίοις ἐμήνισε πᾶσιν.", "st": "5.25"}, {"sp": "N", "t": "τῶν δ’ αὐτῶν ἡμερῶν τοῦ πεζοῦ τῷ Μιθριδάτῃ παραπλέοντος ἐπὶ ὁλκάδων καὶ τριήρων, πνεῦμα Καυνικὸν ἐμπεσὸν ἐς αὐτὰς ἐς Ῥόδον παρήνεγκε· καὶ οἱ Ῥόδιοι τάχιστα ἐπαναχθέντες, ἐνοχλουμέναις ὑπὸ τοῦ κλύδωνος ἔτι καὶ διεσπαρμέναις ἐμβαλόντες, ἀνεδήσαντό τινας καὶ διέτρησαν ἑτέρας καὶ ἐνέπρησαν ἄλλας, καὶ ἄνδρας αἰχμαλώτους εἷλον ἐς τετρακοσίους. ἐφ’ οἷς ὁ Μιθριδάτης ἐς ἑτέραν ναυμαχίαν ὁμοῦ καὶ πολιορκίαν ἡτοιμάζετο, σαμβύκην δέ τινα, μηχάνημα μέγιστον, ἐπὶ δύο νεῶν φερόμενον ἐποίει. αὐτομόλων δ’ αὐτῷ λόφον ὑποδειξάντων ἐπιβατόν, ᾗ Ἀταβυρίου Διὸς ἱερὸν ἦν καὶ κολοβὸν τειχίον ἐπ’ αὐτοῦ, τὴν στρατιὰν ἐς τὰς ναῦς νυκτὸς ἐπέβησε, καὶ ἑτέροις ἀναδοὺς κλίμακας ἐκέλευσε χωρεῖν ἑκατέρους μετὰ σιωπῆς, μέχρι τινὲς αὐτοῖς πυρσεύσειαν ἐκ τοῦ Ἀταβυρίου, καὶ τότε ἀθρόως, μετὰ βοῆς ὅτι μάλιστα μεγάλης, τοὺς μὲν τοῖς λιμέσιν ἐμπίπτειν, τοὺς δὲ τὰ τείχη βιάζεσθαι. οἱ μὲν δὴ μετὰ σιγῆς βαθείας προσεπέλαζον, Ῥοδίων δ’ οἱ προφύλακες αἰσθόμενοι τῶν γιγνομένων ἐπύρσευσαν, καὶ ἡ στρατιὰ τοῦ Μιθριδάτου, νομίσασα τοῦτο εἶναι τὸν ἐκ τοῦ Ἀταβυρίου πυρσόν, ἐκ βαθείας σιωπῆς ἠλάλαξαν ὁμοῦ πάντες, οἵ τε κλιμακοφόροι καὶ ὁ στόλος ὁ νηίτης. Ῥοδίων δ’ αὐτοῖς ἀκαταπλήκτως ἀντανακραγόντων, καὶ ἀθρόως ἀναδραμόντων ἐς τὰ τείχη, οἱ βασιλικοὶ νυκτὸς μὲν οὐδ’ ἐπεχείρουν, ἡμέρας δ’ ἀπεκρούσθησαν.", "st": "5.26"}, {"sp": "N", "t": "ἡ σαμβύκη δ’ ἐπαχθεῖσα τοῦ τείχους ᾗ τὸ τῆς Ἴσιδος ἱερόν ἐστιν, ἐφόβει μάλιστα, βέλη τε πολλὰ ὁμοῦ καὶ κριοὺς καὶ ἀκόντια ἀφιεῖσα. στρατιῶταί τε σκάφεσι πολλοῖς αὐτῇ μετὰ κλιμάκων παρέθεον ὡς ἀναβησόμενοι δι’ αὐτῆς ἐπὶ τὰ τείχη. οἱ δὲ Ῥόδιοι καὶ τάδε εὐσταθῶς ὑπέμενον, ἕως τό τε μηχάνημα ὑπὸ βάρους ἐνεδίδου, καὶ φάσμα τῆς Ἴσιδος ἔδοξε πῦρ ἀφιέναι πολὺ κατ’ αὐτοῦ. καὶ ὁ Μιθριδάτης ἀπογνοὺς καὶ τῆσδε τῆς πείρας ἀνεζεύγνυεν ἐκ τῆς Ῥόδου, Πατάροις δὲ τὴν στρατιὰν περιστήσας ἔκοπτε Λητοῦς ἄλσος ἱερὸν ἐς μηχανάς, μέχρι φοβήσαντος αὐτὸν ἐνυπνίου τῆς τε ὕλης ἐφείσατο, καὶ Πελοπίδαν Λυκίοις πολεμεῖν ἐπιστήσας, Ἀρχέλαον ἐς τὴν Ἑλλάδα ἔπεμπε, προσεταιριούμενον ἢ βιασόμενον αὐτῆς ὅσα δύναιτο. αὐτὸς δ’ ἀπὸ τοῦδε τοῖς στρατηγοῖς τὰ πολλὰ μεθεὶς ἐστρατολόγει καὶ ὡπλοποίει, καὶ τῇ Στρατονικίδι γυναικὶ διετέρπετο, καὶ δίκας ἐδίκαζε τοῖς ἐπιβουλεύειν ἐς τὸ σῶμα αὐτοῦ λεγομένοις ἢ νεωτερίζουσιν ἢ ὅλως ῥωμαΐζουσιν.", "st": "5.27"}, {"sp": "N", "t": "καὶ ὁ μὲν ἐπὶ τοῖσδε ἦν, κατὰ δὲ τὴν Ἑλλάδα τοιάδε ἐγίγνετο. Ἀρχέλαος ἐπιπλεύσας καὶ σίτῳ καὶ στόλῳ πολλῷ, Δῆλόν τε ἀφισταμένην ἀπὸ Ἀθηναίων καὶ ἄλλα χωρία ἐχειρώσατο βίᾳ καὶ κράτει. κτείνας δ’ ἐν αὐτοῖς δισμυρίους ἄνδρας, ὧν οἱ πλέονες ἦσαν Ἰταλοί, τὰ χωρία προσεποιεῖτο τοῖς Ἀθηναίοις· καὶ ἀπὸ τοῦδε αὐτούς, καὶ τὰ ἄλλα κομπάζων περὶ τοῦ Μιθριδάτου καὶ ἐς μέγα ἐπαίρων, ἐς φιλίαν ὑπηγάγετο· τά τε χρήματα αὐτοῖς τὰ ἱερὰ ἔπεμπεν ἐκ Δήλου δι’ Ἀριστίωνος ἀνδρὸς Ἀθηναίου, συμπέμψας φυλακὴν τῶν χρημάτων ἐς δισχιλίους ἄνδρας, οἷς ὁ Ἀριστίων συγχρώμενος ἐτυράννησε τῆς πατρίδος, καὶ τῶν Ἀθηναίων τοὺς μὲν εὐθὺς ἔκτεινεν ὡς ῥωμαΐζοντας, τοὺς δ’ ἀνέπεμψεν ἐς Μιθριδάτην, καὶ ταῦτα μέντοι σοφίαν τὴν Ἐπικούρειον ἠσκηκώς. ἀλλὰ γὰρ οὐχ ὅδε μόνος Ἀθήνησιν, οὐδὲ Κριτίας ἔτι πρὸ τούτου, καὶ ὅσοι τῷ Κριτίᾳ συμφιλοσοφοῦντες ἐτυράννησαν, ἀλλὰ καὶ ἐν Ἰταλίᾳ τῶν πυθαγορισάντων καὶ ἐν τῇ ἄλλῃ Ἑλλάδι τῶν ἑπτὰ σοφῶν λεγομένων ὅσοι πραγμάτων ἐλάβοντο, ἐδυνάστευσάν τε καὶ ἐτυράννησαν ὠμότερον τῶν ἰδιωτικῶν τυράννων, ὥστε καὶ περὶ τῶν ἄλλων φιλοσόφων ἄπορον ποιῆσαι καὶ ὕποπτον, εἴτε δι’ ἀρετήν, εἴτε πενίας καὶ ἀπραξίας τὴν σοφίαν ἔθεντο παραμύθιον, ὧν γε καὶ νῦν πολλοὶ ἰδιωτεύοντες καὶ πενόμενοι, καὶ τὴν ἀναγκαίαν ἐκ τῶνδε σοφίαν περικείμενοι, τοῖς πλουτοῦσιν ἢ ἄρχουσι λοιδοροῦνται πικρῶς, οὐχ ὑπεροψίας πλούτου καὶ ἀρχῆς δόξαν σφίσι μᾶλλον ἢ ζηλοτυπίας ἐς αὐτὰ προφέροντες. ὑπερορῶσι δ’ αὐτῶν οἱ βλασφημούμενοι πολὺ σοφώτερον. ταῦτα μὲν οὖν ἡγήσαιτο ἄν τις ἐς Ἀριστίωνα τὸν φιλόσοφον εἰρημένα, αὐτὸν αἴτιον τῆς ἐκβολῆς τῷ λόγῳ γενόμενον·", "st": "5.28"}, {"sp": "N", "t": "Ἀρχελάῳ δ’ Ἀχαιοὶ καὶ Λάκωνες προσετίθεντο, καὶ Βοιωτία πᾶσα χωρίς γε Θεσπιέων, οὓς περικαθήμενος ἐπολιόρκει. τοῦ δ’ αὐτοῦ χρόνου Μητροφάνης ἐπιπεμφθεὶς ὑπὸ Μιθριδάτου μεθ’ ἑτέρας στρατιᾶς Εὔβοιαν καὶ Δημητριάδα καὶ Μαγνησίαν, οὐκ ἐνδεχομένας τὰ Μιθριδάτεια, ἐλεηλάτει. καὶ Βρύττιος ἐκ Μακεδονίας ἐπελθὼν σὺν ὀλίγῳ στρατῷ διεναυμάχησέ τε αὐτῷ, καὶ καταποντώσας τι πλοῖον καὶ ἡμιολίαν ἔκτεινε πάντας τοὺς ἐν αὐτοῖς, ἐφορῶντος τοῦ Μητροφάνους. ὁ δὲ καταπλαγεὶς ἔφευγεν. καὶ αὐτὸν αἰσίῳ ἀνέμῳ χρώμενον ὁ Βρέττιος οὐ καταλαβὼν Σκίαθον ἐξεῖλεν, ἣ τῆς λείας τοῖς βαρβάροις ταμιεῖον ἦν, καὶ δούλους τινὰς αὐτῶν ἐκρέμασε, καὶ ἐλευθέρων ἀπέτεμε τὰς χεῖρας. ἐπί τε Βοιωτίαν τραπείς, ἑτέρων οἱ χιλίων ἱππέων καὶ πεζῶν ἐκ Μακεδονίας ἐπελθόντων, ἀμφὶ Χαιρώνειαν Ἀρχελάῳ καὶ Ἀριστίωνι τρισὶν ἡμέραις συνεπλέκετο, ἴσου καὶ ἀγχωμάλου παρ’ ὅλον τὸν ἀγῶνα τοῦ ἔργου γιγνομένου. Λακώνων δὲ καὶ Ἀχαιῶν ἐς συμμαχίαν Ἀρχελάῳ καὶ Ἀριστίωνι προσιόντων, ὁ Βρύττιος ἅπασιν ὁμοῦ γενομένοις οὐχ ἡγούμενος ἀξιόμαχος ἔτι ἔσεσθαι ἀνεζεύγνυεν ἐς τὸν Πειραιᾶ, μέχρι καὶ τοῦδε Ἀρχέλαος ἐπιπλεύσας κατέσχεν.", "st": "5.29"}, {"sp": "N", "t": "Σύλλας δ’ ὁ τοῦ Μιθριδατείου πολέμου στρατηγὸς ὑπὸ Ῥωμαίων αἱρεθεὶς εἶναι, τότε πρῶτον ἐξ Ἰταλίας σὺν τέλεσι πέντε καὶ σπείραις τισὶ καὶ ἴλαις ἐς τὴν Ἑλλάδα περαιωθεὶς χρήματα μὲν αὐτίκα καὶ συμμάχους καὶ ἀγορὰν ἔκ τε Αἰτωλίας καὶ Θεσσαλίας συνέλεγεν, ὡς δ’ ἀποχρώντως ἔχειν ἐδόκει, διέβαινεν ἐς τὴν Ἀττικὴν ἐπὶ τὸν Ἀρχέλαον. παροδεύοντι δ’ αὐτῷ Βοιωτία τε ἀθρόως μετεχώρει, χωρὶς ὀλίγων, καὶ τὸ μέγα ἄστυ αἱ Θῆβαι, μάλα κουφόνως ἀντὶ Ῥωμαίων ἑλόμενοι τὰ Μιθριδάτεια, ὀξύτερον ἔτι, πρὶν ἐς πεῖραν ἐλθεῖν, ἀπὸ Ἀρχελάου πρὸς Σύλλαν μετετίθεντο. ὁ δ’ ἐπὶ τὴν Ἀττικὴν ἐχώρει, καὶ μέρος τι στρατοῦ ἐς τὸ ἄστυ περιπέμψας Ἀριστίωνα πολιορκεῖν, αὐτός, ἔνθαπερ ἦν Ἀρχέλαος, ἐπὶ τὸν Πειραιᾶ κατῆλθε, κατακεκλεισμένων ἐς τὰ τείχη τῶν πολεμίων. ὕψος δ’ ἦν τὰ τείχη πήχεων τεσσαράκοντα μάλιστα, καὶ εἴργαστο ἐκ λίθου μεγάλου τε καὶ τετραγώνου, Περίκλειον ἔργον, ὅτε τοῖς Ἀθηναίοις ἐπὶ Πελοποννησίους στρατηγῶν, καὶ τὴν ἐλπίδα τῆς νίκης ἐν τῷ Πειραιεῖ τιθέμενος, μᾶλλον αὐτὸν ἐκρατύνατο. Σύλλας δὲ καὶ τοιοῖσδε οὖσι τοῖς τείχεσιν εὐθὺς ἐπῆγε τὰς κλίμακας, καὶ πολλὰ μὲν ἔδρα πολλὰ δ’ ἀντέπασχεν, ἰσχυρῶς τῶν Καππαδοκῶν αὐτὸν ἀμυνομένων, ἔστε κάμνων ἐς Ἐλευσῖνα καὶ Μέγαρα ἀνεχώρει, καὶ μηχανὰς ἐπὶ τὸν Πειραιᾶ συνεπήγνυτο, καὶ χῶμα αὐτῷ προσχοῦν ἐπενόει. τέχναι μὲν δὴ καὶ παρασκευὴ πᾶσα αὐτῷ καὶ σίδηρος καὶ καταπέλται, καὶ εἴ τι τοιουτότροπον ἄλλο, ἐκ Θηβῶν ἐκομίζετο, ὕλην δὲ τῆς Ἀκαδημείας ἔκοπτε, καὶ μηχανὰς εἰργάζετο μεγίστας. τά τε μακρὰ σκέλη καθῄρει, λίθους καὶ ξύλα καὶ γῆν ἐς τὸ χῶμα μεταβάλλων.", "st": "5.30"}, {"sp": "N", "t": "δύο δ’ ἐκ τοῦ Πειραιῶς Ἀττικοὶ θεράποντες, αἱρούμενοι τὰ Ῥωμαίων, ἢ σφίσιν αὐτοῖς καταφυγήν, εἴ τι γίγνοιτο, προορώμενοι, πεσσοῖς ἐκ μολύβδου πεποιημένοις ἐγγράφοντες ἀεὶ τὸ γιγνόμενον ἐς τοὺς Ῥωμαίους ἠφίεσαν ἀπὸ σφενδόνης. καὶ τοῦδε γιγνομένου τε συνεχῶς καὶ ἐς γνῶσιν ἐλθόντος, Σύλλας τοῖς ἐσφενδονημένοις προσέχων ηὗρε γεγραμμένον ὅτι τῆς ἐπιούσης ἐκ μετώπου πεζοὶ κατὰ τοὺς ἐργαζομένους ἐκδραμοῦνται καὶ ἱππεῖς ἑκατέρωθεν ἐς τὰ πλάγια Ῥωμαίων ἐμβαλοῦσιν. κρύψας οὖν τινὰ στρατιὰν ἀποχρῶσαν, ὡς ἐγένετο τῶν πολεμίων ἡ ἐκδρομή, δόξασα δὴ μάλιστα αἰφνίδιος εἶναι, ὁ δὲ αἰφνιδιώτερον αὐτοῖς τοὺς κεκρυμμένους ἐπαφεὶς ἔκτεινε πολλοὺς καὶ ἐς τὴν θάλασσαν ἑτέρους περιέωσεν. καὶ τοῦτο μὲν τῆς πείρας ἐκείνης τέλος ἦν· αἰρομένοις δὲ ἐπὶ μέγα ἄνω τοῖς χώμασι πύργους ὁ Ἀρχέλαος ἀντεμηχανᾶτο, καὶ πλεῖστα ἐπ’ αὐτοῖς ὄργανα ἐτίθει, τάς τε δυνάμεις ἐκ Χαλκίδος καὶ τῶν ἄλλων νήσων μετεπέμπετο, καὶ τοὺς ἐρέτας καθώπλιζεν, ὡς ὄντος οἱ τοῦ κινδύνου περὶ τῶν ὅλων. ἐγίγνετο μὲν δὴ πλείων οὖσα τῆς Σύλλα στρατιᾶς ἡ Ἀρχελάου καὶ ἐκ τῶνδε πολὺ πλείων, νυκτὸς δὲ μέσης ὁ μὲν Ἀρχέλαος ἐκθορὼν μετὰ λαμπτήρων ἐνέπρησε τὴν ἑτέραν τῶν χελωνῶν καὶ τὰ ἐπ’ αὐτῇ μηχανήματα, ἡμέραις δὲ δέκα μάλιστα ἄλλα ὁ Σύλλας ἐργασάμενος ἐπέστησεν αὖθις ἔνθα καὶ τὰ πρότερα ἦν. καὶ τούτοις ὁ Ἀρχέλαος πύργον ἀνθίστη κατὰ τὸ τεῖχος.", "st": "5.31"}, {"sp": "N", "t": "Καταπλευσάσης δ’ αὐτῷ παρὰ Μιθριδάτου στρατιᾶς ἑτέρας, ἧς ἡγεῖτο Δρομιχαίτης, ἐξῆγεν ἅπαντας ἐς μάχην. ἀναμίξας δ’ αὐτοῖς σφενδονήτας καὶ τοξότας ὑπὸ τὸ τεῖχος αὐτὸ παρέταττεν, ἵνα καὶ οἱ τειχοφύλακες ἐφικνοῖντο τῶν πολεμίων· ἕτεροι δ’ ὑπὸ ταῖς πύλαις αὐτῷ πυρφόροι καιρὸν ἐκδρομῆς ἐπετήρουν. ἀγχωμάλου δ’ ἐς πολὺ τῆς μάχης οὔσης ἐνέκλινον ἑκατεροι παρὰ μέρος, πρῶτον μὲν οἱ βάρβαροι, μέχρι Ἀρχέλαος αὐτοὺς ἐπισχὼν ἐπανήγαγεν ἐς τὴν μάχην. ᾧ δὴ καὶ μάλιστα καταπλαγέντες οἱ Ῥωμαῖοι μετ’ αὐτοὺς ἔφευγον, ἔστε καὶ τούσδε Μουρήνας ὑπαντήσας ἐπέστρεφεν. ἄλλο δ’ ἀπὸ ξυλείας τέλος ἐπανιόν, καὶ σὺν αὐτοῖς οἱ ἄτιμοι, σπουδῇ τὸν ἀγῶνα εὑρόντες ἐπέπιπτον τοῖς Μιθριδατείοις πάνυ καρτερῶς, μέχρι κτεῖναι μὲν αὐτῶν ἐς δισχιλίους, τοὺς δὲ λοιποὺς ἐς τὰ τείχη συνελάσαι. Ἀρχέλαος δ’ αὐτοὺς ἐπιστρέφων αὖθις, καὶ τῷ ἀγῶνι διὰ τὴν προθυμίαν ἐς πολὺ παραμένων, καὶ ἀποκλεισθεὶς ἀνιμήθη διὰ καλῳδίων. ὁ δὲ Σύλλας τοὺς μὲν ἀτίμους περιφανῶς ἀγωνισαμένους ἐξέλυσε τῆς ἀτιμίας, τοὺς δ’ ἄλλους ἐδωρήσατο πολλοῖς.", "st": "5.32"}, {"sp": "N", "t": "καὶ χειμῶνος ἐπιόντος ἤδη στρατόπεδον ἐν Ἐλευσῖνι θέμενος, τάφρον ἄνωθεν ἐπὶ θάλατταν ἔτεμνε βαθεῖαν τοῦ μὴ τοὺς πολεμίους ἱππέας εὐμαρῶς ἐπιτρέχειν οἱ. καὶ τάδε αὐτῷ πονουμένῳ καθ’ ἑκάστην ἡμέραν ἐγίγνοντό τινες ἀγῶνες, οἱ μὲν ἀμφὶ τὴν τάφρον οἱ δὲ παρὰ τοῖς τείχεσιν, ἐπεξιόντων θαμινὰ τῶν πολεμίων, καὶ λίθοις καὶ βέλεσι καὶ μολυβδαίναις χρωμένων. ὁ δὲ Σύλλας νεῶν δεόμενος μετεπέμψατο μὲν ἐκ Ῥόδου. καὶ Ῥοδίων οὐ δυνηθέντων διαπλεῦσαι θαλασσοκρατοῦντος τοῦ Μιθριδάτου, Αεύκολλον, ἄνδρα Ῥωμαῖον περιφανῆ καὶ τοῦδε τοῦ πολέμου στρατηγὸν ἐπὶ Σύλλᾳ γενόμενον, ἐκέλευεν ἐς Ἀλεξάνδρειαν καὶ Συρίαν λαθόντα διαπλεῦσαι, παρά τε τῶν βασιλέων καὶ πόλεων, ὅσαι ναυτικαί, στόλον τινὰ ἀγείραντα τὸ Ῥοδίων ναυτικὸν παραπέμψαι. ὁ μὲν δὴ πολεμίας οὔσης τῆς θαλάσσης, οὐδὲν ἐνδοιάσας, ἐς κελήτιον ἐνέβη, καὶ ναῦν ἐκ νεώς, ἵνα λάθοι, διαμείβων ἐπ’ Ἀλεξανδρείας ἐφέρετο·", "st": "5.33"}, {"sp": "N", "t": "οἱ δὲ προδιδόντες ἀπὸ τῶν τειχῶν, πεσσοῖς πάλιν ἐγγράψαντες ὅτι πέμψοι τῆσδε τῆς νυκτὸς Ἀρχέλαος ἐς τὸ τῶν Ἀθηναίων ἄστυ λιμῷ πιεζόμενον πυροὺς ὑπὸ στρατιωτῶν φερομένους, ἐσφενδόνησαν, καὶ ὁ Σύλλας ἐνεδρεύσας ἐκράτησε τοῦ τε σίτου καὶ τῶν φερόντων. τῆς δ’ αὐτῆς ἡμέρας αὐτῷ καὶ Μουνάτιος περὶ Χαλκίδα Νεοπτόλεμον ἕτερον στρατηγὸν κατατρώσας, ἔκτεινε μὲν ἐς χιλίους καὶ πεντακοσίους, ἔλαβε δὲ αἰχμαλώτους ἔτι πλείονας. οὐ πολὺ δὲ ὕστερον τῷ Πειραιεῖ νυκτός, ἔτι κοιμωμένων τῶν φυλάκων, Ῥωμαῖοι διὰ τῶν ἐγγὺς μηχανῶν κλίμακας ἐπενεγκόντες ἐπὶ τὸ τεῖχος ἐπέβησαν, καὶ τοὺς φύλακας τοὺς ἐγγὺς ἔκτειναν. ἐφ’ ᾧ τῶν βαρβάρων οἱ μὲν εὐθὺς ἀπεπήδων ἐς τὸν Πειραιᾶ, τὸ τεῖχος καταλιπόντες ὡς εἰλημμένον ἅπαν, οἱ δ’ ἐς ἀλκὴν τραπέντες ἔκτεινάν τε τὸν ἡγεμόνα τῶν ἐπιβάντων καὶ τοὺς λοιποὺς ἔξω κατεκρήμνισαν. οἱ δὲ καὶ διὰ τῶν πυλῶν ἐκδραμόντες ὀλίγου τὸν ἕτερον τῶν Ῥωμαϊκῶν πύργων ἐνέπρησαν, εἰ μὴ Σύλλας ἐπιδραμὼν ἀπὸ τοῦ στρατοπέδου, νυκτός τε ὅλης καὶ δι’ ἡμέρας ἐπιπόνως ἀγωνισάμενος, περιέσωσεν. καὶ τότε μὲν ὑπεχώρουν οἱ βάρβαροι, τοῦ δ’ Ἀρχελάου πύργον ἕτερον μέγαν ἐπὶ τὸ τεῖχος ἄντικρυς τοῦ Ῥωμαϊκοῦ πύργου στήσαντος ἐπυργομάχουν ἐς ἀλλήλους, ἑκατέρωθεν πυκνὰ καὶ θαμινὰ πάντα ἀφιέντες, ἕως ὁ Σύλλας ἐκ καταπελτῶν, ἀνὰ εἴκοσιν ὁμοῦ μολυβδαίνας βαρυτάτας ἀφιέντων, ἔκτεινέ τε πολλούς, καὶ τὸν πύργον Ἀρχελάου κατέσεισε καὶ δυσάρμοστον ἐποίησεν, ὡς εὐθὺς αὐτὸν ὑπὸ Ἀρχελάου διὰ δέος ὀπίσω κατὰ τάχος ὑπαχθῆναι.", "st": "5.34"}, {"sp": "N", "t": "πιεζομένων δ’ ἔτι μᾶλλον ὑπὸ τοῦ λιμοῦ τῶν ἐν ἄστει, πεσσοὶ πάλιν ἐμήνυον ὅτι πέμψοι νυκτὸς ἐς τὸ ἄστυ τροφάς. καὶ ὁ Ἀρχέλαος ὑπονοῶν τι περὶ τὸν σῖτον γίγνεσθαι μήνυμα καὶ προδοσίαν, ἅμα τὸν σῖτον ἔπεμπε, καί τινας ἐφίστη ταῖς πύλαις μετὰ πυρὸς ἐς τοὺς Ῥωμαίους ἐκδραμουμένους, εἰ Σύλλας γίγνοιτο περὶ τὸν σῖτον. καὶ συνέπεσεν ἄμφω, Σύλλᾳ μὲν ἑλεῖν τοὺς σιταγωγοῦντας, Ἀρχελάῳ δ’ ἐμπρῆσαί τινα τῶν μηχανημάτων. τοῦ δ’ αὐτοῦ χρόνου καὶ Ἀρκαθίας ὁ Μιθριδάτου υἱός, μεθ’ ἑτέρας στρατιᾶς ἐς Μακεδονίαν ἐμβαλών, οὐ δυσχερῶς ὀλίγων ὄντων τῶν ἐκεῖ Ῥωμαίων ἐκράτησε, καὶ Μακεδονίαν πᾶσαν ὑπηγάγετο, καὶ σατράπαις ἐπιτρέψας αὐτὸς ἐπὶ τὸν Σύλλαν ἐχώρει, μέχρι νοσήσας περὶ τὸ Τίσαιον ἐτελεύτησεν. ἐν δὲ τῇ Ἀττικῇ τῷ μὲν ἄστει πονουμένῳ σφόδρα ὑπὸ λιμοῦ πολλὰ ὁ Σύλλας ἐπετείχιζε φρούρια, τοῦ μὴ διαδιδράσκειν ἀλλ’ ἐμμένοντας ὑπὸ τοῦ πλήθους μᾶλλον ἐνοχλεῖσθαι·", "st": "5.35"}, {"sp": "N", "t": "τῷ δὲ Πειραιεῖ, τὸ χῶμα ἐς ὕψος ἐγείρας, τὰ μηχανήματα ἐπῆγεν. Ἀρχελάου δὲ τὸ χῶμα ὑπορύττοντος καὶ τὴν γῆν ὑποφέροντός τε καὶ ἐς πολὺ διαλανθάνοντος, τὸ χῶμα ὑφίζανεν ἄφνω· καὶ ταχείας αἰσθήσεως γενομένης οἱ Ῥωμαῖοι τὰ μηχανήματα ὑφεῖλκον καὶ τὸ χῶμα ἀνεπλήρουν. τῷ δ’ αὐτῷ τρόπῳ καὶ αὐτοὶ τὴν γῆν ἐς τὰ τείχη τεκμαιρόμενοι διώρυττον· ἀλλήλοις τε συμπίπτοντες κάτω ξίφεσι καὶ δόρασιν ἐκ χειρός, ὡς δυνατὸν ἦν ἐν σκότῳ, διεμάχοντο. ὁμοῦ δὲ ταῦτα ἐγίγνετο, καὶ ὁ Σύλλας ἀπὸ τῶν χωμάτων μηχανήμασι πολλοῖς τὸ τεῖχος ἐκριοκόπει, μέχρι μέρος αὐτοῦ καταβαλών, καὶ τὸν πλησιάζοντα πύργον ἐπειγόμενος ἐμπρῆσαι, πολλὰ μὲν ἠφίει πυρφόρα τοξεύματα ἐς αὐτόν, τοὺς δὲ εὐτολμοτάτους ἀνέπεμπεν ἐπὶ κλιμάκων. σπουδῆς δὲ πολλῆς γιγνομένης ἑκατέρωθεν ὅ τε πύργος ἐνεπίμπρατο, καὶ μέρος τι τοῦ τείχους ὀλίγον ὁ Σύλλας καταβαλὼν εὐθὺς ἐπέστησε φυλακεῖον· τά τε ὑπορωρυγμένα τοῦ τείχους θεμέλια, ξύλοις ἀνηρτημένα καὶ θείου καὶ στυππίου καὶ πίσσης γέμοντα, αὐτίκα πάντα ἐνεπίμπρη. τῶν δ’ ἄλλο παρ’ ἄλλο κατεπιπτε καὶ τοὺς ἐφεστῶτας αὐτοῖς συγκατέφερεν. ὅ τε θόρυβος οὗτος δὴ μάλιστα αἰφνίδιος καὶ πολὺς ὢν πάντῃ τοὺς τειχοφύλακας ἐτάραττεν, ὡς καὶ τὸ ὑπὸ σφίσιν αὐτίκα πεσούμενον· ὅθεν ἐς πάντα συνεχῶς ἐπιστρεφόμενοι τήν τε γνώμην ὕποπτον εἶχον ὑπὸ τοῦ δέους καὶ ἀσθενῶς τοὺς πολεμίους ἀπεμάχοντο.", "st": "5.36"}, {"sp": "N", "t": "καὶ ὁ Σύλλας αὐτοῖς ὧδε ἔχουσιν ἐπικείμενος ἀπαύστως, καὶ τῶν ἰδίων τὸ ἀεὶ πονοῦν ἐναλλάσσων, ἑτέρους ἐφ’ ἑτέροις ἀκμῆτας ἐπῆγε σὺν κλίμαξι καὶ βοῇ καὶ παρακελεύσει, προτρέπων ἅμα καὶ ἀπειλῶν καὶ παρακαλῶν ὡς ἐν τῷδε τῷ βραχεῖ τοῦ παντὸς αὐτοῖς κριθησομένου. ἀντεπῆγε δὲ καὶ ὁ Ἀρχέλαος ἑτέρους ἀντὶ τῶν τεθορυβημένων, ἀνακαινίζων καὶ ὅδε τὸ ἔργον ἀεί, καὶ παρακαλῶν ἅμα καὶ ἐποτρύνων ἅπαντας ὡς ἐν ὀλίγῳ σφίσιν ἔτι τῆς σωτηρίας οὔσης. πολλῆς δὲ σπουδῆς καὶ προθυμίας ἑκατέρωθεν αὖθις ἅπασιν ἐγγενομένης φερεπονώτατος ἦν· καὶ ὁ φόνος ἴσος καὶ ὅμοιος ἐξ ἑκατέρων, ἕως ὁ Σύλλας ἔξωθεν ἐπιών, καὶ μᾶλλόν τι κάμνων, ἀνεκάλει τῇ σάλπιγγι τὴν στρατιάν, καὶ θαυμάσας πολλοὺς ἀπῆγεν. ὁ δ’ Ἀρχέλαος αὐτίκα νυκτὸς τὰ πεπτωκότα τοῦ τείχους ᾠκοδόμει, μηνοειδῆ αὐτοῖς πολλὰ περιθεὶς ἔνδοθεν. οἷς ἔτι νεοδμήτοις ὁ Σύλλας αὖθις ἐπεχείρει παντὶ τῷ στρατῷ, νομίσας ἀσθενῆ καὶ ὑγρὰ ἔτι ὄντα ῥᾳδίως κατερείψειν. κάμνων δὲ ὡς ἐν στενῷ, καὶ βαλλόμενος ἄνωθεν ἔκ τε μετώπου καὶ τῶν κεραιῶν ὡς ἐν μηνοειδέσι χωρίοις, τοῦ μὲν ἐπιχειρεῖν ἔτι τῷ Πειραιεῖ πάμπαν ἀπεῖχε τῇ γνώμῃ, καὶ ἐς πολιορκίαν, ὡς λιμῷ παραστησόμενος αὐτούς, καθίστατο·", "st": "5.37"}, {"sp": "N", "t": "αἰσθόμενος δὲ τοὺς ἐν ἄστει μᾶλλόν τι πεπιεσμένους, καὶ κτήνη πάντα καταθύσαντας, δέρματά τε καὶ βύρσας ἕψοντας καὶ λιχμωμένους τὸ γιγνόμενον ἐξ αὐτῶν, τινὰς δὲ καὶ τῶν ἀποθνησκόντων ἁπτομένους, ἐκέλευσε τῷ στρατῷ τὴν πόλιν περιταφρεύειν, ἵνα μηδὲ καθ’ ἕνα τις ἐκφεύγοι λανθάνων. ὡς δὲ καὶ τοῦτο ἐξείργαστο αὐτῷ, κλίμακας ἐπῆγεν ὁμοῦ καὶ τὸ τεῖχος διώρυττεν. τροπῆς δ’ ὡς ἐν ἀσθενέσιν ἀνδράσιν αὐτίκα γενομένης, ἐσέπεσεν ἐς τὴν πόλιν, καὶ εὐθὺς ἐν Ἀθήναις σφαγὴ πολλὴ ἦν καὶ ἀνηλεής· οὔτε γὰρ ὑποφεύγειν ἐδύναντο δι’ ἀτροφίαν, οὔτε παιδίων ἢ γυναικῶν ἔλεος ἦν, τοῦ Σύλλα τὸν ἐν ποσὶν ἀναιρεῖν κελεύοντος ὑπ’ ὀργῆς ὡς ἐπὶ ταχείᾳ δὴ καὶ ἐς βαρβάρους ἀλόγῳ μεταβολῇ καὶ πρὸς αὑτὸν ἀκράτῳ φιλονεικίᾳ. ὅθεν οἱ πλέονες, αἰσθανόμενοι τοῦ κηρύγματος, ἑαυτοὺς τοῖς σφαγεῦσιν ὑπερρίπτουν ἐς τὸ ἔργον. ὀλίγων δ’ ἦν ἀσθενὴς ἐς τὴν ἀκρόπολιν δρόμος· καὶ Ἀριστίων αὐτοῖς συνέφυγεν, ἐμπρήσας τὸ ᾠδεῖον, ἵνα μὴ ἑτοίμοις ξύλοις αὐτίκα ὁ Σύλλας ἔχοι τὴν ἀκρόπολιν ἐνοχλεῖν. ὁ δ’ ἐμπιπράναι μὲν τὴν πόλιν ἀπεῖπε, διαρπάσαι δὲ ἔδωκε τῷ στρατῷ· καὶ ἕτοιμοι σάρκες ἀνθρώπων ἐς τροφὴν ἐν πολλοῖς οἰκήμασιν ηὑρέθησαν. τῇ δὲ ἑξῆς ὁ Σύλλας τοὺς μὲν δούλους ἀπέδοτο, τοῖς δ’ ἐλευθέροις, ὅσοι νυκτὸς ἐπιλαβούσης οὐκ ἔφθασαν ἀναιρεθῆναι, πάμπαν οὖσιν ὀλίγοις, τὴν μὲν ἐλευθερίαν ἔφη διδόναι, ψῆφον δὲ καὶ χειροτονίαν τῶνδε μὲν ὡς οἱ πεπολεμηκότων ἀφαιρεῖσθαι, τοῖς δ’ ἐκγόνοις καὶ ταῦτα διδόναι.", "st": "5.38"}, {"sp": "N", "t": "ὧδε μὲν ἄδην εἶχον αἱ Ἀθῆναι κακῶν· ὁ δὲ Σύλλας τῇ μὲν ἀκροπόλει φρουρὰν ἐπέστησεν, ᾗ τὸν Ἀριστίωνα καὶ τοὺς συμπεφευγότας λιμῷ καὶ δίψει πιεσθέντας ἐξεῖλεν οὐ μετὰ πολύ. καὶ αὐτῶν ὁ Σύλλας Ἀριστίωνα μὲν καὶ τοὺς ἐκείνῳ δορυφορήσαντας ἢ ἀρχήν τινα ἄρξαντας, ἢ ὁτιοῦν ἄλλο πράξαντας παρ’ ἃ πρότερον ἁλούσης τῆς Ἑλλάδος ὑπὸ Ῥωμαίων αὐτοῖς διετέτακτο, ἐκόλασε θανάτῳ, τοῖς δὲ ἄλλοις συνέγνω, καὶ νόμους ἔθηκεν ἅπασιν ἀγχοῦ τῶν πρόσθεν αὐτοῖς ὑπὸ Ῥωμαίων ὁρισθέντων. συνηνέχθη δ’ ἐκ τῆς ἀκροπόλεως χρυσίου μὲν ἐς τεσσαράκοντα λίτρας μάλιστα, ἀργύρου δ’ ἐς ἑξακοσίας. καὶ τάδε μὲν ἀμφὶ τὴν ἀκρόπολιν ὀλίγον ὕστερον ἐγένετο·", "st": "5.39"}, {"sp": "N", "t": "ὁ δὲ Σύλλας αὐτίκα τοῦ ἄστεος ληφθέντος, οὐ περιμένων ἔτι τὸν Πειραιᾶ διὰ πολιορκίας ἐξελεῖν, κριοὺς ὁμοῦ καὶ βέλη καὶ ἀκόντια ἐπῆγεν, ἄνδρας τε πολλοὺς οἳ διώρυσσον ὑπὸ χελώναις τὰ τείχη, καὶ σπείρας αἳ τοὺς ἐπὶ τῶν τειχῶν ἀκοντίζουσαί τε καὶ τοξεύουσαι θαμινὰ ἀνέκοπτον. καὶ κατήρειψέ τι τοῦ μηνοειδοῦς, ὑγροτέρου καὶ ἀσθενεστέρου ἔτι ὄντος ἅτε νεοδμήτου. ὑπιδομένου δὲ τοῦτο ἔτι πρότερον Ἀρχελάου, καὶ προοικοδομήσαντος ἔνδοθεν ὅμοια πολλά, τὸ μὲν ἔργον ἦν τῷ Σύλλᾳ διηνεκὲς ἐμπίπτοντι ἐς ἕτερον ὅμοιον ἐξ ἑτέρου, ὁρμῇ δ’ ἀπαύστῳ καὶ στρατοῦ μεταβολῇ πυκνῇ χρώμενος, καὶ περιθέων αὐτούς, καὶ παρακαλῶν ἐπὶ τὸ ἔργον ὡς ἐν τῷδε ἔτι λοιπῷ τῆς ὅλης ἐλπίδος καὶ κέρδους τῶν προπεπονημένων ὄντος· οἱ δὲ καὶ αὐτοὶ τῷ ὄντι τοῦτο σφίσιν ἡγούμενοι τέλος εἶναι πόνων, καὶ ἐς τὸ ἔργον αὐτὸ ὡς μέγα δὴ καὶ λαμπρόν, τοιῶνδε τειχῶν κρατῆσαι, φιλοτιμούμενοι, προσέκειντο βιαίως, μέχρι καταπλαγεὶς αὐτῶν τὴν ὁρμὴν ὁ Ἀρχέλαος ὡς μανιώδη καὶ ἄλογον ἐξέλιπεν αὐτοῖς τὰ τείχη, ἐς δέ τι τοῦ Πειραιῶς ἀνέδραμεν ὀχυρώτατόν τε καὶ θαλάσσῃ περίκλυστον, ᾧ ναῦς οὐκ ἔχων ὁ Σύλλας οὐδ’ ἐπιχειρεῖν ἐδύνατο.", "st": "5.40"}, {"sp": "N", "t": "ἐντεῦθεν ὁ μὲν Ἀρχέλαος ἐπὶ Θεσσαλίαν διὰ Βοιωτῶν ἀνεζεύγνυ, καὶ συνῆγεν ἐς Θερμοπύλας τὰ λοιπὰ τοῦ τε ἰδίου στρατοῦ παντός, ὃν ἔχων ἦλθε, καὶ τοῦ σὺν Δρομιχαίτῃ παραγεγονότος. συνῆγε δὲ καὶ τὸ σὺν Ἀρκαθίᾳ τῷ παιδὶ τοῦ βασιλέως ἐς Μακεδονίαν ἐμβαλόν, ἀκραιφνέστατον δὴ καὶ πλῆρες ὂν τόδε μάλιστα, καὶ οὓς αὐτίκα ἄλλους ὁ Μιθριδάτης ἀπέστειλεν· οὐ γὰρ διέλιπεν ἐπιπέμπων. ὁ μὲν δὴ ταῦτα σὺν ἐπείξει συνῆγεν, ὁ δὲ Σύλλας τὸν Πειραιᾶ τοῦ ἄστεος μᾶλλον ἐνοχλήσαντά οἱ κατεπίμπρη, φειδόμενος οὔτε τῆς ὁπλοθήκης οὔτε τῶν νεωσοίκων οὔτε τινὸς ἄλλου τῶν ἀοιδίμων. καὶ μετὰ τοῦτ’ ἐπὶ τὸν Ἀρχέλαον ᾔει διὰ τῆς Βοιωτίας καὶ ὅδε. ὡς δ’ ἐπλησίασαν ἀλλήλοις, οἱ μὲν ἐκ Θερμοπυλῶν ἄρτι μετεχώρουν ἐς τὴν Φωκίδα, Θρᾷκές τε ὄντες καὶ ἀπὸ τοῦ Πόντου καὶ Σκύθαι καὶ Καππαδόκαι Βιθυνοί τε καὶ Γαλάται καὶ Φρύγες, καὶ ὅσα ἄλλα τῷ Μιθριδάτῃ νεόκτητα γένοιτο, πάντες ἐς δώδεκα μυριάδας ἀνδρῶν· καὶ στρατηγοὶ αὐτῶν ἦσαν μὲν καὶ κατὰ μέρος ἑκάστῳ, αὐτοκράτωρ δ’ Ἀρχέλαος ἐπὶ πᾶσιν. Σύλλας δ’ ἦγεν Ἰταλιώτας, καὶ Ἑλλήνων ἢ Μακεδόνων ὅσοι ἄρτι πρὸς αὐτὸν ἀπὸ Ἀρχελάου μετετίθεντο, ἢ εἴ τι ἄλλο περίοικον, οὐδ’ ἐς τριτημόριον τὰ πάντα τῶν πολεμίων.", "st": "5.41"}, {"sp": "N", "t": "Ἀντικαταστάντες δ’ ἀλλήλοις, ὁ μὲν Ἀρχελαος ἐξέταττεν ἐς μάχην ἀεὶ προκαλούμενος, ὁ δὲ Σύλλας ἐβράδυνε, τὰ χωρία καὶ τὸ πλῆθος τῶν ἐχθρῶν περισκοπούμενος. ἀναχωροῦντι δ’ ἐς Χαλκίδα τῷ Ἀρχελάῳ παρακολουθῶν καιρὸν ἐπετήρει καὶ τόπον. ὡς δὲ αὐτὸν εἶδε περὶ Χαιρώνειαν ἐν ἀποκρημνοις στρατοπεδευόμενον, ἔνθα μὴ κρατοῦσιν ἀποχώρησις οὐδεμία ἦν, πεδίον αὐτὸς εὐρὺ πλησίον καταλαβὼν εὐθὺς ἐπῆγεν ὡς καὶ ἄκοντα βιασόμενος ἐς μάχην Ἀρχέλαον· ἐν ᾧ σφίσι μὲν ὕπτιον καὶ εὐπετὲς ἐς δίωξιν καὶ ἀναχώρησιν ἦν πεδίον, Ἀρχελάῳ δὲ κρημνοὶ περιέκειντο, οἳ τὸ ἔργον οὐκ εἴων ἐν οὐδενὶ κοινὸν ὅλου τοῦ στρατοῦ γενέσθαι, συστῆναι διὰ τὴν ἀνωμαλίαν οὐκ ἔχοντος· τραπεῖσί τε αὐτοῖς ἄπορος διὰ τῶν κρημνῶν ἐγίγνετο ἡ φυγή. ὁ μὲν δὴ τοιοῖσδε λογισμοῖς τῇ δυσχωρίᾳ μάλιστα πιστεύων, ἐπῄει ὡς οὐδὲν ἐσομένου χρησίμου τοῦ πλήθους Ἀρχελάῳ· ὁ δ’ οὐκ ἐγνώκει μὲν αὐτῷ τότε συμπλέκεσθαι, διὸ καὶ ἀμελῶς ἐστρατοπέδευσεν, ἐπιόντος δὲ ἤδη τῆς δυσχωρίας ὀψὲ καὶ μόγις ᾐσθάνετο, καὶ προύπεμπέ τινας ἱππέας ἐς κώλυσιν αὐτοῦ. τραπέντων δ’ ἐκείνων καὶ ἐς τοὺς κρημνοὺς καταρριφθέντων, ἑξήκοντα αὖθις ἔπεμψεν ἅρματα, εἰ δύναιτο μετὰ ῥύμης κόψαι καὶ διαρρῆξαι τὴν φάλαγγα τῶν πολεμίων. διαστάντων δὲ τῶν Ῥωμαίων, τὰ μὲν ἅρματα ὑπὸ τῆς φορᾶς ἐς τοὺς ὀπίσω παρενεχθέντα τε καὶ δυσεπίστροφα ὄντα πρὸς τῶν ὑστάτων περιστάντων αὐτὰ καὶ ἐσακοντιζόντων διεφθείρετο·", "st": "5.42"}, {"sp": "N", "t": "ὁ δ’ Ἀρχέλαος δυνηθεὶς ἂν καὶ ὣς ἀπὸ τοῦ χάρακος εὐσταθῶς ἀπομάχεσθαι, τάχα οἱ καὶ τῶν κρημνῶν ἐς τοῦτο συλλαμβανόντων, ἐξῆγε σὺν ἐπείξει καὶ διέτασσε μετὰ σπουδῆς τοσόνδε πλῆθος οὐ προεγνωκότων ἀνδρῶν, ἐν στενωτάτῳ μάλιστα γεγονὼς διὰ τὸν Σύλλαν ἤδη πλησιάζοντα. τοὺς δ’ ἱππέας πρώτους ἐπαγαγὼν μετὰ δρόμου πολλοῦ, διέτεμε τὴν φάλαγγα Ῥωμαίων ἐς δύο, καὶ εὐμαρῶς ἑκατέρους ἐκυκλοῦτο διὰ τὴν ὀλιγότητα. οἱ δ’ ἀπεμάχοντο μὲν ἐγκρατῶς, ἐς πάντας ἐπιστρεφόμενοι, μάλιστα δ’ ἐπόνουν οἱ περὶ Γάλβαν τε καὶ Ὁρτήσιον, καθ’ οὓς αὐτὸς ὁ Ἀρχέλαος ἐτέτακτο, τῶν βαρβάρων ὡς ἐν ὄψει στρατηγοῦ σὺν προθυμίᾳ σφοδρᾷ ἐπικειμένων, μέχρι τοῦ Σύλλα μεταχωροῦντος ἐς αὐτοὺς σὺν ἱππεῦσι πολλοῖς, ὁ Ἀρχέλαος ἀπὸ τῶν σημείων στρατηγικῶν ὄντων καὶ τοῦ κονιορτοῦ πλείονος αἰρομένου τεκμηράμενος εἶναι Σύλλαν τὸν ἐπιόντα, λύσας τὴν κύκλωσιν ἐς τάξιν ἀνεχώρει. ὁ δὲ τῶν τε ἱππέων τὸ ἄριστον ἄγων, καὶ δύο νεαλεῖς σπείρας ἐν τῇ παρόδῳ προσλαβών, αἳ ἐτετάχατο ἐφεδρεύειν, οὔπω τὸν κύκλον τοῖς πολεμίοις ἐξελίξασιν, οὐδ’ ἐς μέτωπον εὐσταθῶς διατεταγμένοις, ἐνέβαλε, καὶ θορυβήσας ἔκοψέ τε καὶ ἐς φυγὴν τραπέντας ἐδίωκεν. ἀρξαμένης δ’ ἐνταῦθα τῆς νίκης, οὐδὲ Μουρήνας ἠλίνυεν ἐπὶ τοῦ λαιοῦ τεταγμένος, ἀλλ’ ὀνειδίσας τοῖς ἀμφ’ αὑτὸν καὶ γενναίως ἐμπεσὼν ἐδίωκε κἀκεῖνος.", "st": "5.43"}, {"sp": "N", "t": "τρεπομένων δ’ ἤδη τῶν Ἀρχελάου κερῶν, οὐδ’ οἱ μέσοι τὴν τάξιν ἐφύλασσον, ἀλλ’ ἀθρόα πάντων ἐγίγνετο φυγή. ἔνθα δὴ πάντα ὅσα εἴκασεν ὁ Σύλλας, ἐνέπιπτε τοῖς πολεμίοις· οὐ γὰρ ἔχοντες ἀναστροφὴν εὐρύχωρον οὐδὲ πεδίον ἐς φυγήν, ἐπὶ τοὺς κρημνοὺς ὑπὸ τῶν διωκόντων ἐωθοῦντο, καὶ αὐτῶν οἱ μὲν ἐξέπιπτον πρὸς αὐτόν, οἱ δ’ εὐβουλότερον ἐς τὸ στρατόπεδον ἐφέροντο. Ἀρχέλαος δ’ αὐτοὺς προλαβών, ἀπειρότατα δὴ τότε μάλιστα συμφορῶν πολεμικῶν, ἀπέκλειε, καὶ ἐπιστρέφειν ἐς τοὺς πολεμίους ἐκέλευεν. οἱ δ’ ἀνέστρεφον μὲν ἐκ προθυμίας, οὔτε δὲ στρατηγῶν ἢ ἐπιστατῶν ἐς διάταξιν ἔτι σφίσι παρόντων, οὔτε τὰ σημεῖα ἕκαστοι τὰ ἑαυτῶν ἐπιγιγνώσκοντες ὡς ἐν ἀκόσμῳ τροπῇ διερριμμένοι, χωρίου τε καὶ ἐς φυγὴν καὶ ἐς μάχην ἀποροῦντες, στενωτάτου τότε μάλιστα αὐτοῖς διὰ τὴν δίωξιν γενομένου, ἐκτείνοντο μετ’ ἀργίας, οἱ μὲν ὑπὸ τῶν πολεμίων, οὐδὲν ἀντιδρᾶσαι φθάνοντες, οἱ δὲ ὑπὸ σφῶν αὐτῶν ὡς ἐν πλήθει καὶ στενοχωρίᾳ θορυβούμενοι. πάλιν τε κατέφυγον ἐπὶ τὰς πύλας, καὶ εἰλοῦντο περὶ αὐτὰς ἐπιμεμφόμενοι τοῖς ἀποκλείουσιν. θεούς τε πατρίους αὐτοῖς καὶ τὴν ἄλλην οἰκειότητα σὺν ὀνείδει προύφερον, ὡς οὐχ ὑπὸ τῶν ἐχθρῶν μᾶλλον ἢ τῶνδε ὑπερορώντων αὑτοὺς ἀναιρούμενοι, ἔστε μόλις αὐτοῖς ὁ Ἀρχέλαος, ὀψὲ τῆς χρείας, ἀνεῴγνυ τὰς πύλας καὶ ὑπεδέχετο μετ’ ἀταξίας ἐστρέχοντας. οἱ δὲ Ῥωμαῖοι ταῦτα συνιδόντες, καὶ παρακαλέσαντες τότε μάλιστα ἀλλήλους, δρόμῳ τοῖς φεύγουσι συνεσέπιπτον ἐς τὸ στρατόπεδον, καὶ τὴν νίκην ἐς τέλος ἐξειργάσαντο.", "st": "5.44"}, {"sp": "N", "t": "Ἀρχέλαος δὲ καὶ ὅσοι ἄλλοι κατὰ μέρος ἐξέφυγον, ἐς Χαλκίδα συνελέγοντο, οὐ πολὺ πλείους μυρίων ἐκ δώδεκα μυριάδων γενόμενοι. Ῥωμαίων δὲ ἔδοξαν μὲν ἀποθανεῖν πεντεκαίδεκα ἄνδρες, δύο δ’ αὐτῶν ἐπανῆλθον. τοῦτο μὲν δὴ Σύλλᾳ καὶ Ἀρχελάῳ τῷ Μιθριδάτου στρατηγῷ τῆς περὶ Χαιρώνειαν μάχης τέλος ἦν, δι’ εὐβουλίαν δὴ μάλιστα Σύλλα καὶ δι’ ἀφροσύνην Ἀρχελάου τοιόνδε ἑκατέρῳ γενόμενον. Σύλλας δὲ πολλῶν μὲν αἰχμαλώτων πολλῶν δ’ ὅπλων καὶ λείας κρατῶν, τὰ μὲν ἀχρεῖα σωρευθέντα, διαζωσάμενος ὡς ἔθος ἐστὶ Ῥωμαίοις, αὐτὸς ἐνέπρησε τοῖς ἐνυαλίοις θεοῖς, ἀναπαύσας δὲ τὴν στρατιὰν ἐπ’ ὀλίγον, ἐς τὸν Εὔριπον σὺν εὐζώνοις ἐπὶ τὸν Ἀρχέλαον ἠπείγετο. Ῥωμαίων δὲ ναῦς οὐκ ἐχόντων, ἀδεῶς τὰς νήσους περιέπλει τὰ παράλια πορθῶν. Ζακύνθῳ δ’ ἐκβὰς παρεστρατοπέδευσεν. καὶ τινῶν Ῥωμαίων, οἳ ἐπεδήμουν, νυκτὸς ἐπιθεμένων αὐτῷ, κατὰ τάχος ἐσβὰς αὖθις ἀνήγετο ἐς Χαλκίδα, λῃστεύοντι μᾶλλον ἢ πολεμοῦντι ἐοικώς.", "st": "5.45"}, {"sp": "N", "t": "Μιθριδάτης δ’ ἐπεὶ τοσῆσδε ἥττης ἐπύθετο, κατεπλάγη μὲν αὐτίκα καὶ ἔδεισεν ὡς ἐπὶ ἔργῳ τοσούτῳ, στρατιὰν δ’ ὅμως ἄλλην ἀπὸ τῶν ὑπ’ αὐτὸν ἐθνῶν ἁπάντων κατὰ σπουδὴν συνέλεγεν. νομίσας δ’ ἄν τινας αὑτῷ διὰ τὴν ἧτταν ἢ νῦν, ἢ εἴ τινα καιρὸν ἄλλον εὕροιεν, ἐπιθήσεσθαι, τοὺς ὑπόπτους οἱ πάντας πρὶν ὀξύτερον γενέσθαι τὸν πόλεμον, ἀνελέγετο. καὶ πρῶτα μὲν τοὺς Γαλατῶν τετράρχας, ὅσοι τε αὐτῷ συνῆσαν ὡς φίλοι καὶ ὅσοι μὴ κατήκουον αὐτοῦ, πάντας ἔκτεινε μετὰ παίδων καὶ γυναικῶν χωρὶς τριῶν τῶν διαφυγόντων, τοῖς μὲν ἐνέδρας ἐπιπέμψας, τοὺς δ’ ἐπὶ διαίτῃ μιᾶς νυκτός, οὐχ ἡγούμενος αὐτῶν οὐδένα οἱ βέβαιον, εἰ πλησιάσοι Σύλλας, ἔσεσθαι. σφετερισάμενος δ’ αὐτῶν τὰς περιουσίας, φρουρὰς ἐσῆγεν ἐς τὰς πόλεις, καὶ σατράπην ἐς τὸ ἔθνος Εὔμαχον ἔπεμψεν· ὃν αὐτίκα τῶν τετραρχῶν οἱ διαφυγόντες, στρατιὰν ἀγείραντες ἀπὸ τῶν ἀγρῶν, ἐξέβαλον αὐταῖς φρουραῖς διώκοντες ἐκ Γαλατίας. καὶ Μιθριδάτῃ περιῆν Γαλατῶν ἔχειν τὰ χρήματα μόνα. Χίοις δὲ μηνίων ἐξ οὗ τις αὐτῶν ναῦς ἐς τὴν βασιλικὴν ἐν τῇ περὶ Ῥόδον ναυμαχίᾳ λαθοῦσα ἐνέβαλε, πρῶτα μὲν ἐδήμευσε τὰ ὄντα Χίοις τοῖς ἐς Σύλλαν φυγοῦσιν, ἑξῆς δ’ ἔπεμπε τοὺς τὰ Ῥωμαίων ἐρευνησομένους ἐν Χίῳ. καὶ τρίτον Ζηνόβιος στρατιὰν ἄγων ὡς ἐς τὴν Ἑλλάδα διαβαλῶν, τὰ τείχη τῶν Χίων, καὶ ὅσα ἄλλα ἐρυμνὰ χωρία, τῆς νυκτὸς κατέλαβε, καὶ ταῖς πύλαις φρουρὰν ἐπιστήσας ἐκήρυσσε τοὺς μὲν ξένους ἀτρεμεῖν, Χίους δὲ ἐς ἐκκλησίαν συνελθεῖν, ὡς διαλεξόμενος αὐτοῖς τι παρὰ τοῦ βασιλέως. ἐπεὶ δὲ συνῆλθον, ἔλεξεν ὅτι βασιλεὺς ὕποπτον ἔχει τὴν πόλιν διὰ τοὺς ῥωμαΐζοντας, παύσεται δὲ ἐὰν τά τε ὅπλα παραδῶτε καὶ ὅμηρα τῶν παίδων τοὺς ἀρίστους. οἱ μὲν δὴ κατειλημμένην σφῶν τὴν πόλιν ὁρῶντες ἔδοσαν ἄμφω, καὶ Ζηνόβιος αὐτὰ ἐς Ἐρυθρὰς ἐξέπεμψεν ὡς αὐτίκα τοῖς Χίοις γράψοντος τοῦ βασιλέως·", "st": "5.46"}, {"sp": "N", "t": "ἐπιστολὴ δὲ ἧκε Μιθριδάτου τάδε λέγουσα· “εὖνοι καὶ νῦν ἐστὲ Ῥωμαίοις, ὧν ἔτι πολλοὶ παρ’ ἐκείνοις εἰσί, καὶ τὰ ἐγκτήματα Ῥωμαίων καρποῦσθε, ἡμῖν οὐκ ἀναφέροντες. ἔς τε τὴν ἐμὴν ναῦν ἐν τῇ περὶ Ῥόδον ναυμαχίᾳ τριήρης ὑμετέρα ἐνέβαλέ τε καὶ κατέσεισεν. ὃ ἐγὼ περιέφερον ἑκὼν ἐς μόνους τοὺς κυβερνήτας, εἰ δύναισθε σώζεσθαι καὶ ἀγαπᾶν. λανθάνοντες δὲ καὶ νῦν τοὺς ἀρίστους ὑμῶν ἐς Σύλλαν διεπέμψατε, καὶ οὐδένα αὐτῶν ὡς οὐκ ἀπὸ τοῦ κοινοῦ ταῦτα πράττοντα ἐνεδείξατε οὐδ’ ἐμηνύσατε, ὃ τῶν οὐ συμπεπραχότων ἔργον ἦν. τοὺς οὖν ἐπιβουλεύοντας μὲν τῇ ἐμῇ ἀρχῇ, ἐπιβουλεύσαντας δὲ καὶ τῷ σώματι, οἱ μὲν ἐμοὶ φίλοι ἐδικαίουν ἀποθανεῖν, ἐγὼ δ’ ὑμῖν τιμῶμαι δισχιλίων ταλάντων.” τοσαῦτα μὲν ἡ ἐπιστολὴ περιεῖχεν, οἱ δ’ ἐβούλοντο μὲν ἐς αὐτὸν πρεσβεῦσαι, Ζηνοβίου δὲ κατακωλύοντος, ὅπλων τε ἀφῃρημένοι, καὶ παίδων σφίσι τῶν ἀρίστων ἐχομένων, στρατιᾶς τε βαρβαρικῆς τοσαύτης ἐφεστώσης, οἰμώζοντες ἔκ τε ἱερῶν κόσμους καὶ τὰ τῶν γυναικῶν πάντα ἐς τὸ πλήρωμα τῶν δισχιλίων ταλάντων συνέφερον. ὡς δὲ καὶ ταῦτ’ ἐπεπλήρωτο, αἰτιασάμενος τὸν σταθμὸν ἐνδεῖν ὁ Ζηνόβιος ἐς τὸ θέατρον αὐτοὺς συνεκάλει, καὶ τὴν στρατιὰν περιστήσας μετὰ γυμνῶν ξιφῶν ἀμφί τε τὸ θέατρον αὐτὸ καὶ τὰς ἀπ’ αὐτοῦ μέχρι τῆς θαλάσσης ὁδοὺς ἦγε τοὺς Χίους, ἀνιστὰς ἕκαστον ἐκ τοῦ θεάτρου, καὶ ἐνετίθετο ἐς τὰς ναῦς, ἑτέρωθι μὲν τοὺς ἄνδρας, ἑτέρωθι δ’ αὐτῶν τὰ γύναια καὶ τὰ παιδία, βαρβαρικῶς ὑπὸ τῶν ἀγόντων ὑρβιζόμενα. ἀνάσπαστοι δ’ ἐντεῦθεν ἐς Μιθριδάτην γενόμενοι διεπέμφθησαν ἐς τὸν Πόντον τὸν Εὔξεινον.", "st": "5.47"}, {"sp": "N", "t": "καὶ Χῖοι μὲν ὧδε ἐπεπράχεσαν, Ζηνόβιον δὲ Ἐφέσιοι μετὰ στρατιωτῶν προσιόντα ἐκέλευον ἐξοπλίσασθαί τε παρὰ ταῖς πύλαις καὶ σὺν ὀλίγοις ἐσελθεῖν. ὁ δ’ ὑπέστη μὲν ταῦτα, καὶ ἐσῆλθε πρὸς Φιλοποίμενα τὸν πατέρα Μονίμης τῆς ἐρωμένης Μιθριδάτου, ἐπίσκοπον Ἐφεσίων ἐκ Μιθριδάτου καθεστηκότα, καὶ συνελθεῖν οἱ τοὺς Ἐφεσίους ἐς ἐκκλησίαν ἐκήρυττεν. οἱ δὲ οὐδὲν χρηστὸν ἔσεσθαι παρ’ αὐτοῦ προσδοκῶντες ἐς τὴν ἐπιοῦσαν ἀνέθεντο, καὶ νυκτὸς ἀλλήλους ἀγείραντές τε καὶ παρακαλέσαντες, Ζηνόβιον μὲν ἐς τὸ δεσμωτήριον ἐμβαλόντες ἔκτειναν, καὶ τὰ τείχη κατεῖχον, καὶ τὸ πλῆθος συνελόχιζον, καὶ τὰ ἐκ τῶν ἀγρῶν συνέλεγον, καὶ τὴν πόλιν ὅλως διὰ χειρὸς εἶχον. ὧν πυνθανόμενοι Τραλλιανοὶ καὶ Ὑπαιπηνοὶ καὶ Μεσοπολῖται καί τινες ἄλλοι, τὰ Χίων πάθη δεδιότες, ὅμοια τοῖς Ἐφεσίοις ἔδρων. Μιθριδάτης δ’ ἐπὶ μὲν τὰ ἀφεστηκότα στρατιὰν ἐξέπεμπε, καὶ πολλὰ καὶ δεινὰ τοὺς λαμβανομένους ἔδρα· δείσας δὲ περὶ τοῖς λοιποῖς τὰς πόλεις τὰς Ἑλληνίδας ἠλευθέρου, καὶ χρεῶν ἀποκοπὰς αὐτοῖς ἐκήρυσσε, καὶ τοὺς ἐν ἑκάστῃ μετοίκους πολίτας αὐτῶν ἐποίει καὶ τοὺς θεράποντας ἐλευθέρους, ἐλπίσας, ὅπερ δὴ καὶ συνηνέχθη, τοὺς κατάχρεως καὶ υετοίκους καὶ θεράποντας, ἡγουμένους ἐν τῇ Μιθριδάτου ἀρχῇ βεβαίως τὰ δοθέντα αὐτοῖς ἕξειν, εὔνους αὑτῷ γενήσεσθαι. Μυννίων δὲ καὶ Φιλότιμος οἱ Σμυρναῖοι καὶ Κλεισθένης καὶ Ἀσκληπιόδοτος οἱ Λέσβιοι, βασιλεῖ γνώριμοι πάντες, ὁ δὲ Ἀσκληπιόδοτος αὐτὸν καὶ ξεναγήσας ποτέ, ἐπιβουλὴν ἐπὶ τὸν Μιθριδάτην συνετίθεσαν· ἧς αὐτὸς ὁ Ἀσκληπιόδοτος μηνυτὴς ἐγένετο, καὶ ἐς πίστιν ὑπὸ κλίνῃ τινὶ παρεσκεύασεν ἀκοῦσαι τοῦ Μυννίωνος. ἁλούσης δὲ τῆς ἐπιβουλῆς οἱ μὲν αἰκισθέντες ἐκολάσθησαν, ὑποψία δ’ ἐς τὰ ὅμοια πολλοὺς κατεῖχεν. ὡς δὲ καὶ Περγαμηνῶν τὰ αὐτὰ βουλεύοντες ὀγδοήκοντα ἄνδρες ἑάλωσαν, καὶ ἐν ἄλλαις πόλεσιν ἕτεροι, ζητητὰς ὁ Μιθριδάτης πανταχοῦ περιέπεμπεν, οἵ, τοὺς ἐχθροὺς ἐνδεικνύντων ἑκάστων, ἔκτειναν ἀμφὶ τοὺς χιλίους καὶ ἑξακοσίους ἄνδρας. ὧν οἱ κατηγορήσαντες οὐ πολὺ ὕστερον οἱ μὲν ὑπὸ Σύλλα ληφθέντες διεφθάρησαν, οἱ δὲ προανεῖλον ἑαυτούς, οἱ δ’ ἐς τὸν Πόντον αὐτῷ Μιθριδάτῃ συνέφευγον.", "st": "5.48"}, {"sp": "N", "t": "γιγνομένων δὲ τῶνδε περὶ τὴν Ἀσίαν, ὀκτὼ μυριάδων στρατὸς ἤθροιστο τῷ Μιθριδάτῃ, καὶ αὐτὸν Δορύλαος πρὸς Ἀρχέλαον ἦγεν ἐς τὴν Ἑλλάδα, ἔχοντα τῶν προτέρων ἔτι μυρίους. ὁ δὲ Σύλλας ἀντεστρατοπέδευε μὲν Ἀρχελάῳ περὶ Ὀρχομενόν, ὡς δὲ εἶδε τῆς ἐπελθούσης ἵππου τὸ πλῆθος, ὤρυσσε τάφρους πολλὰς ἀνὰ τὸ πεδίον, εὖρος δέκα πόδας, καὶ ἐπιόντος αὐτῷ τοῦ Ἀρχελάου ἀντιπαρέταξεν. ἀσθενῶς δὲ τῶν Ῥωμαίων διὰ δέος τῆς ἵππου μαχομένων, ἐς πολὺ μὲν αὐτοὺς παριππεύων παρεκάλει καὶ ἐπέσπερχε σὺν ἀπειλῇ, οὐκ ἐπιστρέφων δ’ αὐτοὺς ἐς τὸ ἔργον οὐδ’ ὥς, ἐξήλατο τοῦ ἵππου, καὶ σημεῖον ἁρπάσας ἀνὰ τὸ μεταίχμιον ἔθει μετὰ τῶν ὑπασπιστῶν, κεκραγώς· “εἴ τις ὑμῶν, ὦ Ῥωμαῖοι, πύθοιτο, ποῦ Σύλλαν τὸν στρατηγὸν ὑμῶν αὐτῶν προυδώκατε, λέγειν, ἐν Ὀρχομενῷ μαχόμενον.” οἱ δ’ ἡγεμόνες αὐτῷ κινδυνεύοντι συνεξέθεον ἐκ τῶν ἰδίων τάξεων, συνεξέθεον δὲ καὶ ἡ ἄλλη πληθὺς αἰδουμένη, παλίωξίν τε εἰργάσαντο. καὶ τῆς νίκης ἀρχομένης, ἀναθορὼν αὖθις ἐπὶ τὸν ἵππον ἐπῄνει τὸν στρατὸν περιιὼν καὶ ἐπέσπερχεν, ἕως τέλεον αὐτοῖς τὸ ἔργον ἐξετελέσθη. καὶ τῶν πολεμίων ἀπώλοντο μὲν ἀμφὶ τοὺς μυρίους καὶ πεντακισχιλίους, καὶ τούτων ἦσαν οἱ μύριοι ἱππεῖς μάλιστα, καὶ σὺν αὐτοῖς ὁ παῖς Ἀρχελάου Διογένης· οἱ πεζοὶ δ’ ἐς τὸ στρατόπεδον συνέφυγον.", "st": "5.49"}, {"sp": "N", "t": "καὶ δείσας ὁ Σύλλας μὴ παλιν αὐτὸν ὁ Ἀρχέλαος, οὐκ ἔχοντα ναῦς, ἐς Χαλκίδα ὡς πρότερον διαφύγοι, τὸ πεδίον ὅλον ἐκ διαστηματων ἐνυκτοφυλάκει. καὶ μεθ’ ἡμέραν, στάδιον οὐχ ὅλον ἀποσχὼν τοῦ Ἀρχελάου, τάφρον αὐτῷ περιώρυσσεν οὐκ ἐπεξιόντι. καὶ παρεκάλει τότε μάλιστα τὴν ἑαυτοῦ στρατιὰν ἐκπονῆσαι τοῦ παντὸς πολέμου τὸ ἔτι λείψανον ὡς τῶν πολεμίων αὐτὸν οὐδ’ ὑφισταμένων, καὶ ἐπῆγεν αὐτὴν ἐπὶ τὸ χαράκωμα τοῦ Ἀρχελάου. ὅμοια δ’ ἐκ μεταβολῆς ἐγίγνετο καὶ παρὰ τοῖς πολεμίοις ὑπ’ ἀνάγκης, τῶν ἡγεμόνων αὐτοὺς περιθεόντων, καὶ τὸν παρόντα κίνδυνον προφερόντων τε, καὶ ὀνειδιζόντων εἰ μηδ’ ἀπὸ χάρακος ἀπομαχοῦνται τοὺς ἐχθροὺς ὀλιγωτέρους ὄντας. ὁρμῆς δὲ καὶ βοῆς ἑκατέρωθεν γενομένης, πολλὰ μὲν ἐγίγνετο ἐπ’ ἀμφοῖν ἔργα πολέμου, γωνίαν δέ τινα τοῦ χαρακώματος οἱ Ῥωμαῖοι, τὰς ἀσπίδας σφῶν ὑπερσχόντες, ἤδη διέσπων, καὶ οἱ βάρβαροι καταθορόντες ἀπὸ τοῦ χαρακώματος ἔσω τῆς γωνίας περιέστησαν αὐτὴν ὡς τοῖς ξίφεσιν ἀμυνούμενοι τοὺς ἐστρέχοντας. οὐδέ τις ἐτόλμα, μέχρι Βάσιλλος ὁ τοῦ τέλους ταξίαρχος ἐσήλατο πρῶτος καὶ τὸν ὑπαντήσαντα ἔκτεινεν. τότε δ’ αὐτῷ συνεσέπιπτεν ὁ στρατὸς ἅπας, καὶ φυγὴ τῶν βαρβάρων ἐγίγνετο καὶ φόνος, τῶν μὲν καταλαμβανομένων, τῶν δ’ ἐς τὴν ἐγγὺς λίμνην ὠθουμένων τε καὶ νεῖν οὐκ ἐπισταμένων, ἀξύνετα βαρβαριστὶ τοὺς κτενοῦντας παρακαλούντων. Ἀρχέλαος δ’ ἐν ἕλει τινὶ ἐκρύφθη, καὶ σκάφους ἐπιτυχὼν ἐς Χαλκίδα διέπλευσεν. καὶ εἴ τις ἦν ἄλλη Μιθριδάτου στρατιὰ κατὰ μέρος ποι διατεταγμένη, πάντας αὐτοὺς ἐκάλει κατὰ σπουδήν.", "st": "5.50"}, {"sp": "N", "t": "ὁ δὲ Σύλλας τῆς ἐπιούσης τόν τε ταξίαρχον ἐστεφάνου καὶ τοῖς ἄλλοις ἀριστεῖα ἐδίδου. καὶ τὴν Βοιωτίαν συνεχῶς μετατιθεμένην διήρπαζε, καὶ ἐς Θεσσαλίαν ἐλθὼν ἐχείμαζε, τὰς ναῦς τὰς μετὰ Λευκόλλου περιμένων. ἀγνοῶν δ’ ὅπῃ ὁ Λεύκολλος εἴη, ἐναυπηγεῖτο ἑτέρας, καὶ ταῦτα μέντοι Κορνηλίου τε Κίννα καὶ Γαΐου Μαρίου, τῶν ἐχθρῶν αὐτοῦ, ἐν Ῥώμῃ ἐψηφισμένων εἶναι Ῥωμαίων πολέμιον, καὶ τὴν οἰκίαν αὐτοῦ καὶ τὰς ἐπαύλεις καθῃρηκότων, καὶ τοὺς φίλους ἀνελόντων. ὁ δὲ οὐδὲν οὐδ’ ὣς καθῄρει τῆς ἐξουσίας, τὸν στρατὸν ἔχων εὐπειθῆ καὶ πρόθυμον. Κίννας δὲ Φλάκκον ἑλόμενός οἱ συνάρχειν τὴν ὕπατον ἀρχήν, ἔπεμπεν ἐς τὴν Ἀσίαν μετὰ δύο τελῶν, ἀντὶ τοῦ Σύλλα, ὡς ἤδη πολεμίου γεγονότος, τῆς τε Ἀσίας ἄρχειν καὶ πολεμεῖν τῷ Μιθριδάτῃ. ἀπειροπολέμῳ δ’ ὄντι τῷ Φλάκκῳ συνεξῆλθεν ἑκὼν ἀπὸ τῆς βουλῆς ἀνὴρ πιθανὸς ἐς στρατηγίαν, ὄνομα Φιμβρίας. τούτοις ἐκ Βρεντεσίου διαπλέουσιν αἱ πολλαὶ τῶν νεῶν ὑπὸ χειμῶνος διελύθησαν, καὶ τὰς πρόπλους αὐτῶν ἐνέπρησε στρατὸς ἄλλος ἐπιπεμφθεὶς ἐκ Μιθριδάτου. μοχθηρὸν δ’ ὄντα τὸν Φλάκκον καὶ σκαιὸν ἐν ταῖς κολάσεσι καὶ φιλοκερδῆ ὁ στρατὸς ἅπας ἀπεστρέφετο, καὶ μέρος αὐτῶν τι, προπεμφθὲν ἐς Θεσσαλίαν, ἐς τὸν Σύλλαν μετεστρατεύσαντο. τοὺς δὲ ὑπολοίπους ὁ Φιμβρίας, στρατηγικώτερος τοῦ Φλάκκου φαινόμενος αὐτοῖς καὶ φιλανθρωπότερος κατεῖχε μὴ μεταθέσθαι.", "st": "5.51"}, {"sp": "N", "t": "ὡς δ’ ἔν τινι καταγωγῇ περὶ ξενίας ἔριδος αὐτῷ καὶ τῷ ταμίᾳ γενομένης ὁ Φλάκκος διαιτῶν οὐδὲν ἐς τιμὴν ἐπεσήμηνε τοῦ Φιμβρίου, χαλεπήνας ὁ Φιμβρίας ἠπείλησεν ἐς Ῥώμην ἐπανελεύσεσθαι. καὶ τοῦ Φλάκκου δόντος αὐτῷ διάδοχον ἐς ἃ τότε διῴκει, φυλάξας αὐτὸν ὁ Φιμβρίας ἐς Χαλκηδόνα διαπλέοντα, πρῶτα μὲν Θέρμον τὰς ῥάβδους ἀφείλετο, τὸν ἀντιστράτηγον ὑπὸ τοῦ Φλάκκου καταλελειμμένον, ὡς οἱ τοῦ στρατοῦ τὴν στρατηγίαν περιθέντος, εἶτα Φλάκκον αὐτὸν σὺν ὀργῇ μετ’ ὀλίγον ἐπανιόντα ἐδίωκεν, ἕως ὁ μὲν Φλάκκος ἔς τινα οἰκίαν καταφυγὼν καὶ νυκτὸς τὸ τεῖχος ὑπερελθὼν ἐς Χαλκηδόνα πρῶτον καὶ ἀπ’ αὐτῆς ἐς Νικομήδειαν ἔφυγε καὶ τὰς πύλας ἀπέκλεισεν, ὁ δὲ Φιμβρίας αὐτὸν ἐπελθὼν ἔκτεινεν ἐν φρέατι κρυπτόμενον, ὕπατόν τε ὄντα Ῥωμαίων καὶ στρατηγὸν τοῦδε τοῦ πολέμου ἰδιώτης αὐτὸς ὢν καὶ ὡς φίλῳ κελεύοντι συνεληλυθώς. ἐκτεμών τε τὴν κεφαλὴν αὐτοῦ μεθῆκεν ἐς θάλασσαν, καὶ τὸ λοιπὸν ἄταφον ἐκρίψας, αὑτὸν αὐτοκράτορα ἀπέφηνε τοῦ στρατοῦ. καὶ μάχας τινὰς οὐκ ἀγεννῶς ἠγωνίσατο τῷ παιδὶ τῷ Μιθριδάτου. αὐτόν τε βασιλέα συνεδίωξεν ἐς τὸ Πέργαμον, καὶ ἐς Πιτάνην ἐκ τοῦ Περγάμου διαφυγόντα ἐπελθὼν ἀπετάφρευεν, ἕως ὁ μὲν βασιλεὺς ἐπὶ νεῶν ἔφυγεν ἐς Μιτυλήνην,", "st": "5.52"}, {"sp": "N", "t": "ὁ δὲ Φιμβρίας, ἐπιὼν τὴν Ἀσίαν, ἐκόλαζε τοὺς καππαδοκίσαντας, καὶ τῶν οὐ δεχομένων αὐτὸν τὴν χώραν ἐλεηλάτει. Ἰλιεῖς δὲ πολιορκούμενοι πρὸς αὐτοῦ κατέφυγον μὲν ἐπὶ Σύλλαν, Σύλλα δὲ φήσαντος αὐτοῖς ἥξειν, καὶ κελεύσαντος ἐν τοσῷδε Φιμβρίᾳ φράζειν ὅτι σφᾶς ἐπιτετρόφασι τῷ Σύλλᾳ, πυθόμενος ὁ Φιμβρίας ἐπῄνεσε μὲν ὡς ἤδη Ῥωμαίων φίλους, ἐκέλευσε δὲ καὶ αὑτὸν ὄντα Ῥωμαῖων ἔσω δέχεσθαι, κατειρωνευσάμενός τι καὶ τῆς συγγενείας τῆς οὔσης ἐς Ῥωμαίους Ἰλιεῦσιν. ἐσελθὼν δὲ τοὺς ἐν ποσὶ πάντας ἔκτεινε καὶ πάντα ἐνεπίμπρη, καὶ τοὺς πρεσβεύσαντας ἐς τὸν Σύλλαν ἐλυμαίνετο ποικίλως, οὔτε τῶν ἱερῶν φειδόμενος οὔτε τῶν ἐς τὸν νεὼν τῆς Ἀθηνᾶς καταφυγόντων, οὓς αὐτῷ νεῷ κατέπρησεν. κατέσκαπτε δὲ καὶ τὰ τείχη, καὶ τῆς ἐπιούσης ἠρεύνα περιιὼν μή τι συνέστηκε τῆς πόλεως ἔτι. ἡ μὲν δὴ χείρονα τῶν ἐπὶ Ἀγαμέμνονος παθοῦσα ὑπὸ συγγενοῦς διωλώλει, καὶ οἰκόπεδον οὐδὲν αὐτῆς οὐδ’ ἱερὸν οὐδ’ ἄγαλμα ἔτι ἦν· τὸ δὲ τῆς Ἀθηνᾶς ἕδος, ὃ Παλλάδιον καλοῦσι καὶ διοπετὲς ἡγοῦνται, νομίζουσί τινες εὑρεθῆναι τότε ἄθραυστον, τῶν ἐπιπεσόντων τειχῶν αὐτὸ περικαλυψάντων, εἰ μὴ Διομήδης αὐτὸ καὶ Ὀδυσσεὺς ἐν τῷ Τρωϊκῷ ἔργῳ μετήνεγκαν ἐξ Ἰλίου.", "st": "5.53"}, {"sp": "N", "t": "τάδε μὲν δὴ Φιμβρίας ἐς Ἴλιον εἰργάζετο, ληγούσης ἄρτι τῆς τρίτης καὶ ἑβδομηκοστῆς καὶ ἑκατοστῆς ὀλυμπιάδος. καί τινες ἡγοῦνται τὸ πάθος αὐτῇ τόδε μετ’ Ἀγαμέμνονα χιλίοις καὶ πεντήκοντα ἔτεσι γενέσθαι μάλιστα.", "st": "5.53"}, {"sp": "N", "t": "ὁ δὲ Μιθριδάτης ἐπεὶ καὶ τῆς περὶ Ὀρχομενὸν ἥττης ἐπύθετο, διαλογιζόμενος τὸ πλῆθος ὅσον ἐξ ἀρχῆς ἐς τὴν Ἑλλάδα ἐπεπόμφει, καὶ τὴν συνεχῆ καὶ ταχεῖαν αὐτοῦ φθοράν, ἐπέστελλεν Ἀρχελάῳ διαλύσεις ὡς δύναιτο εὐπρεπῶς ἐργάσασθαι. ὁ δὲ Σύλλᾳ συνελθὼν ἐς λόγους εἶπε· “φίλος ὢν ὑμῖν πατρῷος, ὦ Σύλλα, Μιθριδάτης ὁ βασιλεὺς ἐπολέμησε μὲν διὰ στρατηγῶν ἑτέρων πλεονεξίαν, διαλύσεται δὲ διὰ τὴν σὴν ἀρετήν, ἢν τὰ δίκαια προστάσσῃς.” καὶ ὁ Σύλλας ἀπορίᾳ τε νεῶν, καὶ χρήματα οὐκ ἐπιπεμπόντων οὐδ’ ἄλλο οὐδὲν οἴκοθεν αὐτῷ τῶν ἐχθρῶν ὡς πολεμίῳ, ἁψάμενος ἤδη τῶν ἐν Πυθοῖ καὶ Ὀλυμπίᾳ καὶ Ἐπιδαύρῳ χρημάτων, καὶ ἀντιδοὺς πρὸς λόγον τοῖς ἱεροῖς τὸ ἥμισυ τῆς Θηβαίων γῆς πολλάκις ἀποστάντων, ἔς τε τὴν στάσιν αὐτὴν τῶν ἐχθρῶν ἐπειγόμενος ἀκραιφνῆ καὶ ἀπαθῆ τὸν στρατὸν μεταγαγεῖν, ἐνεδίδου πρὸς τὰς διαλύσεις, καὶ εἶπεν· “ἀδικουμένου μὲν ἦν, ὦ Ἀρχέλαε, Μιθριδάτου, περὶ ὧν ἠδικεῖτο πρεσβεύειν, ἀδικοῦντος δὲ γῆν τοσήνδε ἀλλοτρίαν ἐπιδραμεῖν, καὶ κτεῖναι πολὺ πλῆθος ἀνδρῶν, τά τε κοινὰ καὶ ἱερὰ τῶν πόλεων καὶ τὰ ἴδια τῶν ἀνῃρημένων σφετερίσασθαι. τῷ δ’ αὐτῷ λόγῳ καὶ ἐς τοὺς ἰδίους φίλους, ᾧ περὶ ἡμᾶς, ἄπιστος γενόμενος, ἔκτεινε καὶ τῶνδε πολλούς, καὶ τῶν τετραρχῶν οὓς ὁμοδιαίτους εἶχε, νυκτὸς μιᾶς, μετὰ γυναικῶν καὶ παίδων τῶν οὐ πεπολεμηκότων. ἐπὶ δὲ ἡμῖν καὶ φύσεως ἔχθραν μᾶλλον ἢ πολέμου χρείαν ἐπεδείξατο, παντοίαις ἰδέαις κακῶν τοὺς περὶ τὴν Ἀσίαν Ἰταλιώτας, σὺν γυναιξὶ καὶ παισὶ καὶ θεράπουσι τοῖς οὖσι γένους Ἰταλικοῦ, λυμηνάμενός τε καὶ κτείνας. τοσοῦτον ἐξήνεγκεν ἐς τὴν Ἰταλίαν μῖσος ὁ νῦν ἡμῖν ὑποκρινόμενος φιλίαν πατρῴαν, ἧς οὐ πρὶν ἑκκαίδεκα μυριάδας ὑμῶν ὑπ’ ἐμοῦ συγκοπῆναι ἐμνημονεύετε.", "st": "5.54"}, {"sp": "N", "t": "“ἀνθ’ ὧν δίκαιον μὲν ἦν ἄσπειστα αὐτῷ τὰ παρ’ ἡμῶν γενέσθαι, σοῦ δὲ χάριν ὑποδέχομαι συγγνώμης αὐτὸν τεύξεσθαι παρὰ Ῥωμαίων, ἂν τῷ ὄντι μεταγιγνώσκῃ. εἰ δὲ ὑποκρίνοιτο καὶ νῦν, ὥρα σοι τὸ σαυτοῦ σκοπεῖν, ὦ Ἀρχέλαε, ἐνθυμουμένῳ μὲν ὅπως ἔχει τὰ παρόντα σοί τε κἀκείνῳ, σκοποῦντι δ’ ὅν τινα τρόπον ἐκεῖνός τε ἑτέροις κέχρηται φίλοις καὶ ἡμεῖς Εὐμένει καὶ Μασσανάσσῃ.”", "st": "5.55"}, {"sp": "N", "t": "ὁ δ’ ἔτι λέγοντος αὐτοῦ τὴν πεῖραν ἀπεσείετο, καὶ δυσχεράνας ἔφη τὸν ἐγχειρίσαντά οἱ τὴν στρατηγίαν οὔ ποτε προδώσειν· “ἐλπίζω δέ σοι διαλλάξειν, ἢν μέτρια προστάσσῃς.” διαλιπὼν οὖν ὁ Σύλλας ὀλίγον, εἶπεν· “ἐὰν τὸν στόλον ἡμῖν, ὃν ἔχεις, ὦ Ἀρχέλαε, παραδιδῷ πάντα Μιθριδάτης, ἀποδῷ δὲ καὶ στρατηγοὺς ἡμῖν ἢ πρέσβεις ἢ αἰχμαλώτους ἢ αὐτομόλους ἢ ἀνδράποδα ἀποδράντα, καὶ Χίους ἐπὶ τοῖσδε, καὶ ὅσους ἄλλους ἀνασπάστους ἐς τὸν Πόντον ἐποιήσατο, μεθῇ, ἐξαγάγῃ δὲ καὶ τὰς φρουρὰς ἐκ πάντων φρουρίων, χωρὶς ὧν ἐκράτει πρὸ τῆσδε τῆς παρασπονδήσεως, ἐσενέγκῃ δὲ καὶ τὴν δαπάνην τοῦδε τοῦ πολέμου τὴν δι’ αὐτὸν γενομένην, καὶ στέργῃ μόνης ἄρχων τῆς πατρῴας δυναστείας. ἐλπίζω πείσειν Ῥωμαίους αὐτῷ μηδὲν ἐπιμηνῖσαι τῶν γεγονότων.” ὁ μὲν δὴ τοσάδε εἶπεν, ὁ δὲ Ἀρχέλαος τὰς μὲν φρουρὰς αὐτίκα πανταχόθεν ἐξῆγε, περὶ δὲ τῶν ἄλλων ἐπέστελλε τῷ βασιλεῖ. καὶ Σύλλας τὴν ἐν τοσῷδε ἀργίαν διατιθέμενος, Ἐνετοὺς καὶ Δαρδανέας καὶ Σιντούς, περίοικα Μακεδόνων ἔθνη, συνεχῶς ἐς Μακεδονίαν ἐμβάλλοντα, ἐπιὼν ἐπόρθει, καὶ τὸν στρατὸν ἐγύμναζε, καὶ ἐχρηματίζετο ὁμοῦ.", "st": "5.55"}, {"sp": "N", "t": "ἐλθόντων δὲ τῶν Μιθριδάτου πρέσβεων, οἳ τοῖς μὲν ἄλλοις συνετίθεντο, μόνην δ’ ἐξαιρούμενοι Παφλαγονίαν ἐπεῖπον ὅτι πλεόνων ἂν ἔτυχε Μιθριδάτης, εἰ πρὸς τὸν ἕτερον ὑμῶν στρατηγὸν διελύετο Φιμβρίαν, δυσχεράνας ὁ Σύλλας τῇ παραβολῇ, καὶ Φιμβρίαν ἔφη δώσειν δίκην, καὶ αὐτὸς ἐν Ἀσίᾳ γενόμενος εἴσεσθαι πότερα συνθηκῶν ἢ πολέμου δεῖται Μιθριδάτης. ὧδε δ’ εἰπὼν ἤλαυνεν ἐπὶ Κύψελλα διὰ Θρᾴκης, Λεύκολλον ἐς Ἄβυδον προπέμψας· ἤδη γὰρ αὐτῷ καὶ ὅδε ἀφῖκτο, κινδυνεύσας μὲν ὑπὸ λῃστῶν ἁλῶναι πολλάκις, στόλον δέ τινα νεῶν ἀγείρας ἀπό τε Κύπρου καὶ Φοινίκης καὶ Ῥόδου καὶ Παμφυλίας, καὶ πολλὰ δῃώσας τῆς πολεμίας, καὶ τῶν Μιθριδάτου νεῶν ἀποπειράσας ἐν παράπλῳ. Σύλλας μὲν οὖν ἀπὸ Κυψέλλων καὶ Μιθριδάτης ἐκ Περγάμου συιῄεσαν αὖθις ἐς λόγους, καὶ κατέβαινον ἐς πεδίον ἄμφω σὺν ὀλίγοις, ἐφορώντων τῶν στρατῶν ἑκατέρωθεν. ἦσαν δ’ οἱ λόγοι Μιθριδάτου μὲν ὑπόμνησις φιλίας καὶ συμμαχίας ἰδίας καὶ πατρῴας, καὶ ἐπὶ τοῖς Ῥωμαίων πρέσβεσι καὶ προβούλοις καὶ στρατηγοῖς κατηγορία ὧν ἐς αὐτὸν ἐπεπράχεσαν ἀδίκως, Ἀριοβαρζάνην τε κατάγοντες ἐς Καππαδοκίαν, καὶ Φρυγίας αὐτὸν ἀφαιρούμενοι, καὶ Νικομήδη περιορῶντες ἀδικοῦντα. “καὶ τάδε,” ἔφη, “πάντα ἔπραξαν ἐπὶ χρήμασι, παραλλὰξ παρ’ ἐμοῦ τε καὶ παρ’ ἐκείνων λαμβάνοντες· ὃ γὰρ δὴ μάλιστ’ ἄν τις ὑμῶν, ὦ Ῥωμαῖοι, τοῖς πλείοσιν ἐπικαλέσειεν, ἔστιν ἡ φιλοκερδία. ἀναρραγέντος δὲ ὑπὸ τῶν ὑμετέρων στρατηγῶν τοῦ πολέμου, πάντα ὅσα ἀμυνόμενος ἔπραττον, ἀνάγκῃ μᾶλλον ἢ κατὰ γνώμην ἐγίγνετο.”", "st": "5.56"}, {"sp": "N", "t": "ὁ μὲν δὴ Μιθριδάτης ὧδε εἰπὼν ἐπαύσατο, ὁ δὲ Σύλλας ὑπολαβὼν ἀπεκρίνατο· “ἐφ’ ἕτερα μὲν ἡμᾶς ἐκάλεις, ὡς τὰ προτεινόμενα ἀγαπήσων, οὐ μὴν ὁκνήσω καὶ περὶ τῶνδε διὰ βραχέων εἰπεῖν. ἐς μὲν Καππαδοκίαν ἐγὼ κατήγαγον Ἀριοβαρζάνην Κιλικίας ἄρχων, ὧδε Ῥωμαίων ψηφισαμένων· καὶ σὺ κατήκουες ἡμῶν, δέον ἀντιλέγειν καὶ ἢ μεταδιδάσκειν ἢ μηκέτι τοῖς ἐγνωσμένοις ἀντιτεῖναι. Φρυγίαν δέ σοι Μάνιος ἔδωκεν ἐπὶ δωροδοκίᾳ, ὃ κοινόν ἐστιν ἀμφοῖν ἀδίκημα. καὶ τῷδε μάλιστα αὐτὴν ὁμολογεῖς οὐ δικαίως λαβεῖν, ἐκ δωροδοκίας. ὅ τε Μάνιος καὶ τὰ ἄλλα ἠλέγχθη παρ’ ἡμῖν ἐπὶ χρήμασι πράξας, καὶ πάντα ἀνέλυσεν ἡ βουλή. ᾧ λόγῳ καὶ Φρυγίαν ἀδίκως σοι δοθεῖσαν οὐχ ἑαυτῇ συντελεῖν ἐπέταξεν ἐς τοὺς φόρους, ἀλλ’ αὐτόνομον μεθῆκεν. ὧν δὲ ἡμεῖς οἱ πολέμῳ λαβόντες οὐκ ἀξιοῦμεν ἄρχειν, τίνι λόγῳ σὺ καθέξεις; Νικομήδης δὲ αἰτιᾶται μέν σε καὶ Ἀλέξανδρον αὐτῷ τὸν τὸ σῶμα τρώσοντα ἐπιπέμψαι, καὶ Σωκράτη τὸν χρηστὸν ἐπὶ τὴν ἀρχήν, καὶ τάδε αὐτὸς ἀμυνόμενος ἐς τὴν σὴν ἐμβαλεῖν· εἰ δέ τι ὅμως ἠδικοῦ, ἐς Ῥώμην πρεσβεύειν ἔδει καὶ τὰς ἀποκρίσεις ἀναμένειν. εἰ δὲ καὶ θᾶττον ἠμύνου Νικομήδη, πῶς καὶ Ἀριοβαρζάνην ἀπήλαυνες οὐδὲν ἀδικοῦντα; ἐκβαλὼν δ’ ἀνάγκην ἐπέθηκας τοῖς παροῦσι Ῥωμαίων κατάγειν αὐτόν, καὶ καταγόμενον κωλύων σὺ τὸν πόλεμον ἐξῆψας, ἐγνωκὼς μὲν οὕτω πρὸ πολλοῦ, καὶ ἐν ἐλπίδι ἔχων γῆς ἄρξειν ἁπάσης εἰ Ῥωμαίων κρατήσειας, προφάσεις δ’ ἐπὶ τῇ γνώμῃ τάσδε ποιούμενος. καὶ τούτου τεκμήριον, ὅτι καὶ Θρᾷκας καὶ Σκύθας καὶ Σαυρομάτας, οὔπω τινὶ πολεμῶν, ἐς συμμαχίαν ὑπήγου, καὶ ἐς τοὺς ἀγχοῦ βασιλέας περιέπεμπες, ναῦς τε ἐποιοῦ, καὶ πρῳρέας καὶ κυβερνήτας συνεκάλεις.", "st": "5.57"}, {"sp": "N", "t": "“μάλιστα δ’ ὁ καιρὸς ἐλέγχει σε τῆς ἐπιβουλῆς. ὅτε γὰρ τὴν Ἰταλίαν ἀφισταμένην ἡμῶν ᾐσθάνου, τὴν ἀσχολίαν τήνδε ἡμῶν φυλάξας ἐπέθου μὲν Ἀριοβαρζάνῃ καὶ Νικομήδει καὶ Γαλάταις καὶ Παφλαγονίᾳ, ἐπέθου δὲ Ἀσίᾳ τῷ ἡμετέρῳ χωρίῳ. καὶ λαβὼν οἷα δέδρακας ἢ τὰς πόλεις, αἷς τοὺς θεράποντας καὶ χρήστας ἐπέστησας ἐλευθερίας καὶ χρεῶν ἀποκοπαῖς, ἢ τοὺς Ἕλληνας, ὧν μιᾷ προφάσει χιλίους καὶ ἑξακοσίους διέφθειρας, ἢ Γαλατῶν τοὺς τετράρχας, οὓς ὁμοδιαίτους ἔχων ἀπέκτεινας, ἢ τὸ τῶν Ἰταλιωτῶν γένος, οὓς μιᾶς ἡμέρας σὺν βρέφεσι καὶ μητράσιν ἔκτεινάς τε καὶ κατεπόντωσας, οὐκ ἀποσχόμενος οὐδὲ τῶν ἐς τὰ ἱερὰ συμφυγόντων. ὃ πόσην μὲν ὠμότητά σου, πόσην δὲ ἀσέβειαν καὶ ὑπερβολὴν μίσους ἐς ἡμᾶς προενήνοχεν. σφετερισάμενος δ’ ἁπάντων τὰ χρήματα, ἐς τὴν Εὐρώπην ἐπέρας μεγάλοις στρατοῖς, ἡμῶν ἀπειπόντων ἅπασι τῆς Ἀσίας βασιλεῦσι τῆς Εὐρώπης μηδὲ ἐπιβαίνειν. διαπλεύσας δὲ Μακεδονίαν τε ἡμετέραν οὖσαν ἐπέτρεχες καὶ τοὺς Ἕλληνας τὴν ἐλευθερίαν ἀφῃροῦ. οὐ πρίν τε ἤρξω μετανοεῖν, οὐδ’ Ἀρχέλαος ὑπὲρ σοῦ παρακαλεῖν, ἢ Μακεδονίαν μέν με ἀνασώσασθαι, τὴν δὲ Ἑλλάδα τῆς σῆς ἐκλῦσαι βίας, ἑκκαίδεκα δὲ μυριάδας τοῦ σοῦ στρατοῦ κατακόψαι, καὶ τὰ στρατόπεδά σου λαβεῖν αὐταῖς παρασκευαῖς. ὃ καὶ θαυμάζω σου δικαιολογουμένου νῦν ἐφ’ οἷς δι’ Ἀρχελάου παρεκάλεις. ἢ πόρρω μὲν ὄντα με ἐδεδοίκεις, ἀγχοῦ δὲ γενόμενον ἐπὶ δίκην ἐληλυθέναι νομίζεις; ἧς ὁ καιρὸς ἀνάλωται, σοῦ τε πολεμήσαντος ἡμῖν, καὶ ἡμῶν ἀμυναμένων ἤδη καρτερῶς καὶ ἀμυνουμένων ἐς τέλος.”", "st": "5.58"}, {"sp": "N", "t": "τοσαῦτα τοῦ Σύλλα μετ’ ὀργῆς ἔτι λέγοντος, μετέπιπτεν ὁ βασιλεὺς καὶ ἐδεδοίκει, καὶ ἐς τὰς δι’ Ἀρχελάου γενομένας συνθήκας ἐνεδίδου, τάς τε ναῦς καὶ τὰ ἄλλα πάντα παραδοὺς ἐς τὸν Πόντον ἐπὶ τὴν πατρῴαν ἀρχὴν ἐπανῄει μόνην.", "st": "5.58"}, {"sp": "N", "t": "ὧδε μὲν ὁ πρῶτος Μιθριδάτου καὶ Ῥωμαίων πόλεμος κατεπαύετο·", "st": "5.59"}, {"sp": "N", "t": "Σύλλας δὲ Φιμβρίου δύο σταδίους ἀποσχὼν ἐκέλευε παραδοῦναί οἱ τὸν στρατόν, οὗ παρανόμως ἄρχοι. ὁ δ’ ἀντεπέσκωπτε μὲν ὡς οὐδ’ ἐκεῖνος ἐννόμως ἔτι ἄρχοι, περιταφρεύοντος δ’ αὐτὸν τοῦ Σύλλα, καὶ πολλῶν οὐκ ἀφανῶς ἀποδιδρασκόντων, ἐς ἐκκλησίαν τοὺς λοιποὺς ὁ Φιμβρίας συναγαγὼν παρεκάλει παραμένειν. οὐ φαμένων δὲ πολεμήσειν πολίταις, καταρρήξας τὸν χιτωνίσκον ἑκάστοις προσέπιπτεν. ὡς δὲ καὶ τοῦτ’ ἀπεστρέφοντο, καὶ πλείους ἐγίγνοντο αἱ αὐτομολίαι, τὰς σκηνὰς τῶν ἡγεμόνων περιῄει, καί τινας αὐτῶν χρήμασι διαφθείρας ἐς ἐκκλησίαν αὖθις συνεκάλει, καὶ συνόμνυσθαί οἱ προσέτασσεν. ἐκβοησάντων δὲ τῶν ἐνετῶν ὅτι δέοι καλεῖν ἐπὶ τὸν ὅρκον ἐξ ὀνόματος, ὁ μὲν ἐκήρυττε τοὺς εὖ τι παθόντας ὑφ’ ἑαυτοῦ, καὶ Νώνιον πρῶτον ἐκάλει, κοινωνόν οἱ πάντων γεγονότα. οὐκ ὀμνύντος δ’ οὐδ’ ἐκείνου, τὸ ξίφος ἐπισπάσας ἠπείλει κτενεῖν αὐτόν, μέχρι βοῆς ἐκ πάντων γενομένης καταπλαγεὶς καὶ τοῦδ’ ἐπαύσατο. θεράποντα δὲ χρήμασι καὶ ἐλπίσιν ἐλευθερίας ἀναπείσας ἔπεμψεν ὡς αὐτόμολον ἐπιχειρεῖν τῷ Σύλλα σώματι. ὁ δὲ τῷ ἔργῳ πλησιάζων καὶ ταρασσόμενος, καὶ ἐκ τοῦδε ὕποπτος γενόμενος, συνελήφθη τε καὶ ὡμολόγησεν. καὶ ὁ στρατὸς ὁ τοῦ Σύλλα, σὺν ὀργῇ καὶ καταφρονήσει περιστάντες τὸ τοῦ Φιμβρίου χαράκωμα, κατελοιδόρουν αὐτὸν καὶ Ἀθηνίωνα ἐκάλουν, ὃς δραπετῶν τῶν ἐν Σικελίᾳ ποτὲ ἀποστάντων ὀλιγήμερος ἐγεγένητο βασιλεύς.", "st": "5.59"}, {"sp": "N", "t": "ἐφ’ οἷς ὁ Φιμβρίας πάντα ἀπογνοὺς ἐπὶ τὴν τάφρον προῆλθε, καὶ Σύλλαν αὑτῷ παρεκάλει συνελθεῖν ἐς λόγους. ὁ δὲ ἀνθ’ αὑτοῦ Ῥουτίλιον ἔπεμπε· καὶ τόδε πρῶτον ἐλύπει τὸν Φιμβρίαν, οὐδὲ συνόδου, διδομένης καὶ τοῖς πολεμίοις, ἀξιωθέντα. δεομένῳ δ’ αὐτῷ συγγνώμης τυχεῖν εἴ τι νέος ὢν ἐξήμαρτεν, ὁ Ῥουτίλιος ὑπέστη Σύλλαν ἀφήσειν ἐπὶ θάλασσαν ἀπαθῆ διελθεῖν, εἰ μέλλοι τῆς Ἀσίας, ἧς ἐστὶν ὁ Σύλλας ἀνθύπατος, ἀποπλευσεῖσθαι. ὁ δὲ εἰπὼν ἑτέραν ὁδὸν ἔχειν κρείττονα, ἐπανῆλθεν ἐς Πέργαμον, καὶ ἐς τὸ τοῦ Ἀσκληπιοῦ ἱερὸν παρελθὼν ἐχρήσατο τῷ ξίφει. οὐ καιρίου δ’ αὐτῷ τῆς πληγῆς γενομένης, ἐκέλευσε τὸν παῖδα ἐπερεῖσαι. ὁ δὲ καὶ τὸν δεσπότην ἔκτεινε καὶ αὑτὸν ἐπὶ τῷ δεσπότῃ.", "st": "5.60"}, {"sp": "N", "t": "οὕτω μὲν καὶ Φιμβρίας ἀπέθανε, πολλὰ τὴν Ἀσίαν ἐπὶ Μιθριδάτῃ λελυμασμένος. καὶ αὐτὸν ὁ Σύλλας ἐφῆκε τοῖς ἀπελευθέροις θάψαι, καὶ ἐπεῖπεν οὐ μιμεῖσθαι Κίνναν καὶ Μάριον ἐν Ῥώμῃ θάνατόν τε πολλῶν καὶ ἀταφίαν ἐπὶ τῷ θανάτῳ καταγνόντας. τὸν δὲ στρατὸν τοῦ Φιμβρίου προσιόντα οἱ δεξιωσάμενός τε καὶ τῷ σφετέρῳ συναγαγών, Κουρίωνι προσέταξε Νικομήδην ἐς Βιθυνίαν καὶ Ἀριοβαρζάνην ἐς Καππαδοκίαν καταγαγεῖν, τῇ τε βουλῇ περὶ πάντων ἐπέστελλεν, οὐχ ὑποκρινόμενος ἐψηφίσθαι πολέμιος.", "st": "5.60"}, {"sp": "N", "t": "αὐτὴν δὲ τὴν Ἀσίαν καθιστάμενος, Ἰλιέας μὲν καὶ Χίους καὶ Λυκίους καὶ Ῥοδίους καὶ Μαγνησίαν καί τινας ἄλλους, ἢ συμμαχίας ἀμειβόμενος, ἢ ὧν διὰ προθυμίαν ἐπεπόνθεσαν οὗ ἕνεκα, ἐλευθέρους ἠφίει καὶ Ῥωμαίων ἀνέγραφε φίλους, ἐς δὲ τὰ λοιπὰ πάντα στρατιὰν περιέπεμπεν. καὶ τοὺς θεράποντας, οἷς ἐλευθερίαν ἐδεδώκει Μιθριδάτης, ἐκήρυττεν αὐτίκα ἐς τοὺς δεσπότας ἐπανιέναι. πολλῶν δὲ ἀπειθούντων, καὶ πόλεων τινῶν ἀφισταμένων, ἐγίγνοντο σφαγαὶ κατὰ πλῆθος ἐλευθέρων τε καὶ θεραπόντων ἐπὶ ποικίλαις προφάσεσι, τείχη τε πολλῶν καθῃρεῖτο, καὶ συχνὰ τῆς Ἀσίας ἠνδραποδίζετο καὶ διηρπάζετο. οἵ τε καππαδοκίσαντες ἄνδρες ἢ πόλεις ἐκολάζοντο πικρῶς, καὶ μάλιστα αὐτῶν Ἐφέσιοι, σὺν αἰσχρᾷ κολακείᾳ ἐς τὰ Ῥωμαίων ἀναθήματα ὑβρίσαντες. ἐπὶ δὲ τοῖσδε καὶ κήρυγμα περιῄει, τοὺς ἐν ἀξιώσει κατὰ πόλιν ἐς ἡμέραν ῥητὴν πρὸς τὸν Σύλλαν ἀπαντᾶν ἐς Ἔφεσον. καὶ συνελθοῦσιν αὐτοῖς ἐπὶ βήματος ἐδημηγόρησεν οὕτως.", "st": "5.61"}, {"sp": "N", "t": "“ἡμεῖς στρατῷ πρῶτον ἐς Ἀσίαν παρήλθομεν Ἀντιόχου τοῦ Σύρων βασιλέως πορθοῦντος ὑμᾶς. ἐξελάσαντες δ’ αὐτόν, καὶ τὸν Ἅλυν καὶ Ταῦρον αὐτῷ θέμενοι τῆς ἀρχῆς ὅρον, οὐ κατέσχομεν ὑμῶν ἡμετέρων ἐξ ἐκείνου γενομένων, ἀλλὰ μεθήκαμεν αὐτονόμους, πλὴν εἴ τινας Εὐμένει καὶ Ῥοδίοις συμμαχήσασιν ἡμῖν ἔδομεν, οὐχ ὑποτελεῖς ἀλλ’ ἐπὶ προστάταις εἶναι. τεκμήριον δ’ ὅτι Λυκίους αἰτιωμένους τι Ῥοδίων ἀπεστήσαμεν. ἡμεῖς μὲν δὴ τοιοίδε περὶ ὑμᾶς γεγόναμεν· ὑμεῖς δέ, Ἀττάλου τοῦ φιλομήτορος τὴν ἀρχὴν ἡμῖν ἐν διαθήκαις καταλιπόντος, Ἀριστονίκῳ καθ’ ἡμῶν τέτταρσιν ἔτεσι συνεμαχεῖτε, μέχρι καὶ Ἀοιστόνικος ἑάλω καὶ ὑμῶν οἱ πλείους ες ἀνάγκην καὶ φόβον περιήλθετε. καὶ ὧδε πράσσοντες ὅμως, ἔτεσιν εἴκοσι καὶ τέτταρσιν ἐς μέγα περιουσίας καὶ κάλλους κατασκευῆς ἰδιωτικῆς τε καὶ δημοσίας προελθόντες, ὑπὸ εἰρήνης καὶ τρυφῆς ἐξυβρίσατε αὖθις, καὶ τὴν ἀσχολίαν ἡμῶν τὴν ἀμφὶ τὴν Ἰταλίαν φυλάξαντες οἱ μὲν ἐπηγάγεσθε Μιθριδάτην, οἱ δ’ ἐλθόντι συνέθεσθε. ὃ δ’ ἐστὶ πάντων μιαρώτατον, ὑπέστητε αὐτῷ μιᾶς ἡμέρας τοὺς Ἰταλιώτας ἅπαντας αὐτοῖς παισὶ καὶ μητράσιν ἀναιρήσειν, καὶ οὐδὲ τῶν ἐς τὰ ἱερὰ συμφυγόντων διὰ τοὺς ὑμετέρους θεοὺς ἐφείσασθε. ἐφ’ οἷς ἔδοτε μέν τινα καὶ αὐτῷ Μιθριδάτῃ δίκην, ἀπίστῳ τε ἐς ὑμᾶς γενομένῳ, καὶ φόνου καὶ δημεύσεων ἐμπλήσαντι ὑμᾶς, καὶ γῆς ἀναδασμοὺς ἐργασαμένῳ καὶ χρεῶν ἀποκοπὰς καὶ δούλων ἐλευθερώσεις, καὶ τυράννους ἐπ’ ἐνίοις, καὶ λῃστήρια πολλὰ ἀνά τε γῆν καὶ θάλασσαν, ὡς εὐθὺς ὑμᾶς ἔχειν ἐν πείρᾳ καὶ παραβολῇ οἵους ἀνθ’ οἵων προστάτας ἐπελέγεσθε. ἔδοσαν δέ τινα καὶ ἡμῖν δίκην οἱ τῶνδε ἄρξαντες. ἀλλὰ δεῖ καὶ κοινὴν ὑμῖν ἐπιτεθῆναι τοιάδε ἐργασαμένοις· ἣν εἰκὸς μὲν ἦν ὁμοίαν οἷς ἐδράσατε γενέσθαι, μή ποτε δὲ Ῥωμαῖοι σφαγὰς ἀσεβεῖς ἢ δημεύσεις ἀβούλους ἢ δούλων ἐπαναστάσεις, ἢ ὅσα ἄλλα βαρβαρικά, μηδ’ ἐπὶ νοῦν λάβοιεν. φειδοῖ δὲ γένους ἔτι καὶ ὀνόματος Ἑλληνικοῦ καὶ δόξης τῆς ἐπὶ τῇ Ἀσίᾳ, καὶ τῆς φιλτάτης Ῥωμαίοις εὐφημίας οὕνεκα, μόνους ὑμῖν ἐπιγράφω πέντε ἐτῶν φόρους ἐσενεγκεῖν αὐτίκα, καὶ τὴν τοῦ πολέμου δαπάνην, ὅση τε γέγονέ μοι καὶ ἔσται καθισταμένῳ τὰ ὑπόλοιπα. διαιρήσω δὲ ταῦθ’ ἑκάστοις ἐγὼ κατὰ πόλεις, καὶ τάξω προθεσμίαν ταῖς ἐσφοραῖς, καὶ τοῖς οὐ φυλάξασιν ἐπιθήσω δίκην ὡς πολεμίοις.”", "st": "5.62"}, {"sp": "N", "t": "τοσάδε εἰπὼν ἐπιδιῄρει τοῖς πρέσβεσι τὴν ζημίαν, καὶ ἐπὶ τὰ χρήματα ἔπεμπεν. αἱ δὲ πόλεις ἀποροῦσαί τε καὶ δανειζόμεναι μεγάλων τόκων, αἱ μὲν τὰ θέατρα τοῖς δανείζουσιν, αἱ δὲ τὰ γυμνάσια ἢ τεῖχος ἢ λιμένας ἢ εἴ τι δημόσιον ἄλλο, σὺν ὕβρει στρατιωτῶν ἐπειγόντων, ὑπετίθεντο. τὰ μὲν δὴ χρήματα ὧδε τῷ Σύλλᾳ συνεκομίζετο, καὶ κακῶν ἄδην εἶχεν ἡ Ἀσία· ἐπέπλει δ’ αὐτὴν καὶ λῃστήρια πολύανδρα φανερῶς, στόλοις ἐοικότα μᾶλλον ἢ λῃσταῖς, Μιθριδάτου μὲν αὐτὰ πρώτου καθέντος ἐς τὴν θάλασσαν, ὅτε πάνθ’ ὡς οὐκ ἐς πολὺ καθέξων ἐλυμαίνετο, πλεονάσαντα δ’ ἐς τότε μάλιστα, καὶ οὐ τοῖς πλέουσι μόνοις ἀλλὰ καὶ λιμέσι καὶ χωρίοις καὶ πόλεσιν ἐπιχειροῦντα φανερῶς. Ἰασσός γέ τοι καὶ Σάμος καὶ Κλαζομεναὶ καὶ Σαμοθρᾴκη Σύλλα παρόντος ἐλήφθησαν, καὶ τὸ ἱερὸν ἐσυλήθη τὸ Σαμοθρᾴκιον χιλίων ταλάντων κόσμον, ὡς ἐνομίζετο. ὁ δέ, εἴτε ἑκὼν ὡς ἁμαρτόντας ἐνυβρίζεσθαι καταλιπών, εἴτ’ ἐπὶ τὴν ἐς Ῥώμην στάσιν ἐπειγόμενος, ἐς τὴν Ἑλλάδα καὶ ἀπ’ αὐτῆς ἐς τὴν Ἰταλίαν μετὰ τοῦ πλείονος στρατοῦ διέπλει. καὶ τὰ μὲν ἀμφὶ Σύλλαν ἐν τοῖς Ἐμφυλίοις ἀναγέγραπται,", "st": "5.63"}, {"sp": "N", "t": "ἄρχεται δ’ ὁ δεύτερος Ῥωμαίων τε καὶ Μιθριδάτου πόλεμος ἐνθένδε.", "st": "5.64"}, {"sp": "N", "t": "Μουρήνας μὲν ὑπὸ Σύλλα σὺν δύο τέλεσι τοῖς Φιμβρίου καθίστασθαι τὰ λοιπὰ τῆς Ἀσίας ὑπελέλειπτο, καὶ πολέμων ἀφορμὰς ἠρεσχήλει δι’ ἐπιθυμίαν θριάμβου· Μιθριδάτης δ’ ἐς τὸν Πόντον ἐσπλεύσας Κόλχοις καὶ Βοσποριανοῖς ἀφισταμένοις ἐπολέμει. ὧν Κόλχοι τὸν υἱὸν παρ’ αὐτοῦ, Μιθριδάτην, βασιλέα σφίσιν ᾐτοῦντο δοθῆναι, καὶ λαβόντες αὐτίκα ὑπήκουσαν. ὑποπτεύσας δ’ ὁ βασιλεὺς τόδε πρὸς τοῦ παιδὸς αὐτοῦ βασιλείας ἐπιθυμοῦντος γενέσθαι, καλέσας αὐτὸν ἔδησεν ἐν πέδαις χρυσαῖς καὶ μετ’ οὐ πολὺ ἀπέκτεινε, πολλὰ χρήσιμόν οἱ περὶ τὴν Ἀσίαν ἐν τοῖς πρὸς Φιμβρίαν ἀγῶσι γενόμενον. ἐπὶ δὲ Βοσποριανοὺς ναῦς τε συνεπήγνυτο καὶ στρατὸν ἡτοιμάζετο πολύν, ὡς τὸ μέγεθος αὐτοῦ τῆς παρασκευῆς δόξαν ἐγεῖραι ταχεῖαν, οὐκ ἐπὶ Βοσποριανοῖς ἀλλ’ ἐπὶ Ῥωμαίοις τάδε συλλέγεσθαι. οὐ γάρ πω οὐδ’ Ἀριοβαρζάνῃ πᾶσαν ἐβεβαίου Καππαδοκίαν, ἀλλ’ ἔστιν αὐτῆς ἃ καὶ τότε κατεῖχεν. Ἀρχέλαόν τε ἐν ὑποψίαις ἐτίθετο ὡς πολλὰ πέρα τοῦ δέοντος κατὰ τὴν Ἑλλάδα ἐν ταῖς διαλύσεσιν ἐπιχωρήσαντα τῷ Σύλλᾳ. ὧν ὁ Ἀρχέλαος αἰσθανόμενός τε καὶ δείσας ἐς Μουρήναν ἔφυγε, καὶ παροξύνας αὐτὸν ἔπεισε Μιθριδάτῃ προεπιχειρεῖν. Μουρήνας μὲν δὴ διὰ Καππαδοκίας αὐτίκα ἐσβαλὼν ἐς Κόμανα, κώμην ὑπὸ τῷ Μιθριδάτῃ μεγίστην, σεβάσμιον ἱερὸν καὶ πλούσιον ἔχουσαν, ἱππέας τινὰς ἔκτεινε τοῦ Μιθριδάτου, καὶ πρέσβεσιν αὐτοῦ τὰς συνθήκας προτείνουσιν οὐκ ἔφη συνθήκας ὁρᾶν· οὐ γὰρ συνεγέγραπτο Σύλλας, ἀλλ’ ἔργῳ τὰ λεχθέντα βεβαιώσας ἀπήλλακτο. ταῦτα δ’ εἰπὼν ὁ Μουρήνας εὐθέως ἐλεηλάτει, καὶ οὐδὲ τῶν ἱερῶν χρημάτων ἀποσχόμενος ἐχείμαζεν ἐν Καππαδοκίᾳ.", "st": "5.64"}, {"sp": "N", "t": "Μιθριδάτης δ’ ἐς Ῥώμην ἔπεμπε πρός τε τὴν βουλὴν καὶ πρὸς Σύλλαν, αἰτιώμενος ἃ ποιεῖ Μουρήνας. ὁ δ’ ἐν τούτῳ τὸν Ἅλυν ποταμὸν περάσας, μέγαν τε ὄντα καὶ δύσπορον τότε μάλιστα αὐτῷ γενόμενον ὑπ’ ὄμβρων, τετρακοσίας τοῦ Μιθριδάτου κώμας ἐπέτρεχεν, οὐκ ἀπαντῶντος ἐς οὐδὲν αὐτῷ τοῦ βασιλέως, ἀλλὰ τὴν πρεσβείαν ἀναμένοντος. λείας δὲ πολλῆς καταγέμων ἐς Φρυγίαν καὶ Γαλατίαν ἐπανῄει, ἔνθα αὐτῷ Καλίδιος, ἐπὶ ταῖς Μιθριδάτου μέμψεσι πεμφθεὶς ἀπὸ Ῥώμης, ψήφισμα μὲν οὐδὲν ἐπέδωκεν, ἔφη δ’ ἐς ἐπήκοον ἐν μέσῳ τὴν βουλὴν αὐτῷ κελεύειν φείδεσθαι τοῦ βασιλέως ὄντος ἐνσπόνδου. ταῦτα δ’ εἰπὼν ὤφθη διαλεγόμενος αὐτῷ μόνῳ, καὶ ὁ Μουρήνας οὐδὲν ἀνεὶς τῆς ὁρμῆς καὶ τότε τὴν γῆν ἐπῄει τὴν τοῦ Μιθριδάτου. ὁ δὲ σαφῶς ὑπὸ Ῥωμαίων ἡγούμενος πολεμεῖσθαι, Γόρδιον ἐς τὰς κώμας ἐσβαλεῖν ἐκέλευσεν. καὶ αὐτίκα ὁ Γόρδιος ὑποζύγιά τε πολλὰ καὶ σκευοφόρα καὶ ἀνθρώπους, ἰδιώτας τε καὶ στρατιώτας, συνήρπαζε, καὶ αὐτῷ Μουρήνᾳ, μέσον λαβὼν ποταμόν, ἀντεκαθέζετο. μάχης δ’ οὐδέτερος ἦρχεν, ἕως ἀφίκετο Μιθριδάτης σὺν τῷ πλείονι στρατῷ. καὶ εὐθὺς ἀμφὶ τῷ ποταμῷ μάχη γίγνεται καρτερά. καὶ βιασάμενος ὁ Μιθριδάτης ἐπέρα τὸν ποταμόν, καὶ τἆλλα πολὺ κρείττων τοῦ Μουρήνα γενόμενος. ὁ δ’ ἐς λόφον καρτερὸν ἀναφυγών, ἐπιχειροῦντος αὐτῷ τοῦ βασιλέως πολλοὺς ἀποβαλὼν ἔφευγε διὰ τῶν ὀρεινῶν ἐπὶ Φρυγίας, ὁδὸν ἀτριβῆ, βαλλόμενός τε καὶ χαλεπῶς.", "st": "5.65"}, {"sp": "N", "t": "ἥ τε νίκη λαμπρὰ καὶ ὀξεῖα ἐξ ἐφόδου γενομένη ταχὺ διέπτη καὶ πολλοὺς ἐς τὸν Μιθριδάτην μετέβαλεν. ὁ δὲ καὶ τὰ ἐν Καππαδοκίᾳ φρούρια τοῦ Μουρήνα πάντα ἐπιδραμών τε καὶ ἐξελάσας ἔθυε τῷ στρατίῳ Διὶ πάτριον θυσίαν ἐπὶ ὄρους ὑψηλοῦ, κορυφὴν μείζονα ἄλλην ἀπὸ ξύλων ἐπιτιθείς. πρῶτοι δ’ ἐς αὐτὴν οἱ βασιλεῖς ξυλοφοροῦσι, καὶ περιθέντες ἑτέραν ἐν κύκλῳ βραχυτέραν τῇ μὲν ἄνω γάλα καὶ μέλι καὶ οἶνον καὶ ἔλαιον καὶ θυμιάματα πάντα ἐπιφοροῦσι, τῇ δ’ ἐπιπέδῳ σῖτόν τε καὶ ὄψον ἐς ἄριστον τοῖς παροῦσιν ἐπιτιθέντες, οἷόν τι καὶ ἐν Πασαργάδαις ἐστὶ τοῖς Περσῶν βασιλεῦσι θυσίας γένος, ἅπτουσι τὴν ὕλην. ἡ δ’ αἰθομένη διὰ τὸ μέγεθος τηλοῦ τε χιλίων σταδίων γίγνεται τοῖς πλέουσι καταφανής, καὶ πελάσαι φασὶν ἐς πολλὰς ἡμέρας, αἰθομένου τοῦ ἀέρος, οὐ δυνατὸν εἶναι.", "st": "5.66"}, {"sp": "N", "t": "ὁ μὲν δὴ τὴν θυσίαν ἦγε πατρίῳ νόμῷ· Σύλλα δ’ οὐκ ἀξιοῦντος Μιθριδάτην ἔνσπονδον πολεμεῖσθαι, Αὖλος Γαβίνιος ἐπέμφθη Μουρήνᾳ μὲν ἀληθῆ τήνδε προαγόρευσιν ἐρῶν, μὴ πολεμεῖν Μιθριδάτῃ, Μιθριδάτην δὲ καὶ Ἀριοβαρζάνην ἀλλήλοις συναλλάξων. ὁ δὲ Μιθριδάτης ἐν τῇδε τῇ συνόδῳ παιδίον τετραετὲς ἐγγυήσας τῷ Ἀριοβαρζάνῃ, καὶ ἐπὶ τῇδε προφάσει λαβὼν ἔχειν Καππαδοκίας ὅσα τε εἶχε καὶ ἕτερα ἐπ’ ἐκείνοις, εἱστία πάντας, καὶ χρυσίον ἐπὶ τε τῇ κύλικι καὶ τῇ τροφῇ καὶ ἐπὶ σκώμμασι καὶ ἐπὶ ᾠδῇ πᾶσιν, ὥσπερ εἰώθει, προυτίθει· οὗ μόνος Γαβίνιος οὐχ ἥψατο. ὁ μὲν δὴ δεύτερος Μιθριδάτῃ καὶ Ῥωμαίοις πόλεμος τρίτῳ μάλιστα ἔτει ἐς τοῦτο διελύετο.", "st": "5.66"}, {"sp": "N", "t": "καὶ σχολὴν ἄγων ὁ Μιθριδάτης Βόσπορον ἐχειροῦτο, καὶ βασιλέα αὐτοῖς τῶν υἱέων ἕνα ἀπεδείκνυ Μαχάρην. ἐς δ’ Ἀχαιοὺς τοὺς ὑπὲρ Κόλχους ἐσβαλών, οἳ δοκοῦσιν εἶναι τῶν ἐκ Τροίας κατὰ τὴν ἐπάνοδον πλανηθέντων, δύο μέρη τοῦ στρατοῦ πολέμῳ τε καὶ κρύει καὶ ἐνέδραις ἀποβαλὼν ἐπανῆλθε, καὶ ἐς Ῥώμην ἔπεμπε τοὺς συγγραψομένους τὰ συγκείμενα. ἔπεμπε δὲ καὶ Ἀριοβαρζάνης, εἴθ’ ἑκὼν εἴτε πρὸς τινῶν ἐνοχλούμενος, οὐκ ἀπολαμβάνειν Καππαδοκίαν, ἀλλὰ τὸ πλέον αὐτῆς ἔτι Μιθριδάτην ἀφαιρεῖσθαι. Μιθριδάτης μὲν οὖν, Σύλλα κελεύοντος αὐτῷ μεθεῖναι Καππαδοκίαν, μεθῆκε, καὶ ἑτέραν πρεσβείαν ἐπέπεμπεν ἐπὶ τὰς τῶν συνθηκῶν συγγραφάς· ἤδη δὲ Σύλλα τεθνεῶτος, οὐκ ἐπαγόντων αὐτὴν ὡς ἐν ἀσχολίᾳ τῶν προβούλων ἐπὶ τὸ κοινόν, Τιγράνη τὸν γαμβρὸν Μιθριδάτης ἔπεισεν ἐς Καππαδοκίαν ἐμβαλεῖν ὥσπερ ἀφ’ ἑαυτοῦ. καὶ τὸ μὲν σόφισμα οὐκ ἔλαθε Ῥωμαίους, ὁ δ’ Ἀρμένιος Καππαδοκίαν σαγηνεύσας ἐς τριάκοντα μυριάδας ἀνθρώπων ἀνασπάστους ἐς Ἀρμένιαν ἐποίησε, καὶ συνῴκιζεν αὐτοὺς μεθ’ ἑτέρων ἔς τι χωρίον ἔνθα πρῶτον Ἀρμενίας τὸ διάδημα αὐτὸς περιεθήκατο, καὶ Τιγρανόκερτα ἀφ’ ἑαυτοῦ προσεῖπεν· δύναται δ’ εἶναι Τιγρανόπολις.", "st": "5.67"}, {"sp": "N", "t": "καὶ τάδε μὲν ἦν ἐν Ἀσίᾳ· Σερτώριος δ’ Ἰβηρίας ἡγούμενος αὐτήν τε Ἰβηρίαν καὶ τὰ περίοικα πάντα ἐπὶ Ῥωμαίους ἀνίστη, καὶ βουλὴν ἐκ τῶν οἱ συνόντων, ἐς μιμημα τῆς συγκλήτου, κατέλεγεν. δύο δ’ αὐτοῦ τῶν στασιωτῶν, Λεύκιοι, Μάγιός τε καὶ Φάννιος, Μιθριδάτην ἔπειθον συμμαχῆσαι τῷ Σερτωρίῳ, πολλὰ περὶ τῆς Ἀσίας αὐτὸν καὶ τῶν ἐγγὺς ἐθνῶν ἐπελπίζοντες. ὁ μὲν δὴ πεισθεὶς ἐς τὸν Σερτώριον ἔπεμψεν· ὁ δὲ τοὺς πρέσβεις ἐς τὴν ἑαυτοῦ σύγκλητον παραγαγών τε, καὶ μεγαλοφρονησάμενος ὅτι τὸ κλέος αὐτοῦ καὶ ἐς τὸν Πόντον διίκετο καὶ Ῥωμαίους ἕξοι πολιορκεῖν ἀπό τε δύσεως καὶ ἐξ ἀνατολῆς, συνετίθετο τῷ Μιθριδάτῃ δώσειν Ἀσίαν τε καὶ Βιθυνίαν καὶ Παφλαγονίαν καὶ Καππαδοκίαν καὶ Γαλατίαν, στρατηγόν τε αὐτῷ Μᾶρκον Οὐάριον καὶ συμβούλους τοὺς Λευκίους, Μάγιόν τε καὶ Φάννιον, ἔπεμψεν. μεθ’ ὧν ὁ Μιθριδάτης ἐξέφαινε τὸν τρίτον καὶ τελευταῖόν οἱ γενόμενον ἐς Ῥωμαίους πόλεμον, ἐν ᾧ πᾶσαν ἀπώλεσε τὴν ἀρχὴν Σερτωρίου μὲν ἀποθανόντος, ἐν Ἰβηρίᾳ, ἐπιπεμφθέντων δέ οἱ στρατηγῶν ἀπὸ Ῥώμης προτέρου Λευκόλλου τοῦδε τοῦ νεναυαρχηκότος Σύλλᾳ, ὑστέρου δὲ Πομπηίου, ἐφ’ ὅτου πάντα ὅσα ἦν Μιθριδάτου καὶ ὅσα αὐτοῖς γειτονεύοντα, μέχρι ἐπὶ ποταμὸν Εὐφράτην, προφάσει καὶ ὁρμῇ τοῦ Μιθριδατείου πολέμου ἐς Ῥωμαίους ἅπαντα περιηνέχθη.", "st": "5.68"}, {"sp": "N", "t": "Μιθριδάτης μὲν οὖν, οἷα Ῥωμαίων πολλάκις ἐς πεῖραν ἐλθών, καὶ τόνδε μάλιστα τὸν πόλεμον ἡγούμενος, ἀπροφασίστως δὴ καὶ ὀξέως γενόμενον, ἄσπειστον ἕξειν, πᾶσαν ἐπενόει παρασκευὴν ὡς ἄρτι δὴ κριθησόμενος περὶ ἁπάντων. καὶ τὸ λοιπὸν τοῦ θέρους καὶ τὸν χειμῶνα ὅλον ὑλοτομῶν ἐπήγνυτο ναῦς καὶ ὅπλα, καὶ σίτου διακοσίας μεδίμνων μυριάδας ἐπὶ θαλάσσῃ διετίθει. σύμμαχοί τε αὐτῷ προσεγίγνοντο, χωρὶς τῆς προτέρας δυνάμεως, Χάλυβες Ἀρμένιοι Σκύθαι Ταῦροι Ἀχαιοὶ Ἡνίοχοι Λευκόσυροι, καὶ ὅσοι περὶ Θερμώδοντα ποταμὸν γῆν ἔχουσι τὴν Ἀμαζόνων λεγομένην. τοσαῦτα μὲν ἐπὶ τοῖς προτέροις αὐτῷ περὶ τὴν Ἀσίαν προσεγίγνετο, περάσαντι δ’ ἐς τὴν Εὐρώπην Σαυροματῶν οἵ τε βασίλειοι καὶ Ἰάζυγες καὶ Κόραλλοι, καὶ Θρᾳκῶν ὅσα γένη παρὰ τὸν Ἴστρον ἢ Ῥοδόπην ἢ τὸν Αἷμον οἰκοῦσι, καὶ ἐπὶ τοῖσδε Βαστέρναι, τὸ ἀλκιμώτατον αὐτῶν γένος. τοσάδε μὲν δὴ καὶ τῆς Εὐρώπης τότε προσελάμβανεν ὁ Μιθριδάτης. καὶ μυριάδες ἐκ πάντων ἐς τὸ μάχιμον αὐτῷ συνελέγοντο τεσσαρεσκαίδεκα μάλιστα πεζῶν, καὶ ἱππεῖς ἐπὶ μυρίοις ἑξακισχίλιοι. πολὺς δὲ καὶ ἄλλος ὅμιλος ὁδοποιῶν καὶ σκευοφόρων εἵπετο καὶ ἐμπόρων.", "st": "5.69"}, {"sp": "N", "t": "ἀρχομένου δ’ ἦρος ἀπόπειραν τοῦ ναυτικοῦ ποιησάμενος, ἔθυε τῷ στρατίῳ Διὶ τὴν συνήθη θυσίαν, καὶ Ποσειδῶνι λευκῶν ἵππων ἅρμα καθεὶς ἐς τὸ πέλαγος ἐπὶ Παφλαγονίας ἠπείγετο, στρατηγούντων αὐτῷ Ταξίλου τε καὶ Ἑρμοκράτους. ὡς δ’ ἀφίκετο, ἐδημηγόρησε τῷ στρατῷ περί τε τῶν προγόνων μάλα σεμνολόγως καὶ περὶ αὑτοῦ μεγαληγόρως, ὅτι τὴν ἀρχὴν ἐκ βραχέος ἐπὶ πλεῖστον προαγαγὼν οὔποτε Ῥωμαίων ἡττηθείη παρών. εἶτα κατηγόρησεν αὐτῶν ἐς πλεονεξίαν καὶ ἀμετρίαν, ὑφ’ ἧς, ἔφη, καὶ τὴν Ἰταλίαν καὶ τὴν πατρίδα αὐτὴν δεδούλωνται. καὶ τὰς γενομένας οἱ τελευταίας συνθήκας ἐπέφερεν ὡς οὐκ ἐθέλουσιν ἀναγράψασθαι, καιροφυλακοῦντες αὖθις ἐπιθέσθαι. καὶ τοῦτο αἴτιον τοῦ πολέμου τιθέμενος, ἐπῆγε τὴν ἑαυτοῦ στρατιὰν ὅλην καὶ παρασκευήν, καὶ Ῥωμαίων ἀσχολίαν πολεμουμένων ὑπὸ Σερτωρίου κατὰ κράτος ἐν Ἰβηρίᾳ καὶ στασιαζόντων ἐς ἀλλήλους ἀνὰ τὴν Ἰταλίαν. “διὸ καὶ τῆς θαλάσσης,” ἔφη, “καταφρονοῦσι λῃστευομένης πολὺν ἤδη χρόνον, καὶ σύμμαχος αὐτοῖς οὐδείς ἐστιν, οὐδ’ ὑπήκοος ἑκούσιος ἔτι. οὐχ ὁρᾶτε δ’ αὐτῶν,” ἔφη, “καὶ τοὺς ἀρίστους,” ἐπιδεικνὺς Οὐάριόν τε καὶ τοὺς Λευκίους, “πολευίους μὲν ὄντας τῇ πατρίδι, συμμάχους δ’ ἡμῖν;”", "st": "5.70"}, {"sp": "N", "t": "ταῦτ’ εἰπὼν καὶ τὸν στρατὸν ἐρεθίσας ἐνέβαλεν ἐς Βιθυνίαν, Νικομήδους ἄρτι τεθνεῶτος ἄπαιδος καὶ τὴν ἀρχὴν Ῥωμαίοις ἀπολιπόντος. Κόττας δ’ ἡγούμενος αὐτῆς, ἀσθενὴς τὰ πολέμια πάμπαν, ἔφυγεν ἐς Χαλκηδόνα μεθ’ ἧς εἶχε δυνάμεως. καὶ Βιθυνία μὲν ἦν αὖθις ὑπὸ τῷ Μιθριδάτῃ, τῶν πανταχοῦ Ῥωμαίων ἐς Χαλκηδόνα πρὸς Κότταν συνθεόντων. ἐπιόντος δὲ καὶ τῇ Χαλκηδόνι τοῦ Μιθριδάτου, Κόττας μὲν ὑπ’ ἀπραξίας οὐ προῄει, Νοῦδος δὲ ὁ ναύαρχος αὐτοῦ, σὺν μέρει τινὶ στρατοῦ τὰ ὀχυρώτατα τοῦ πεδίου καταλαβὼν καὶ ἐξελαθείς, ἔφυγεν ἐπὶ τὰς πύλας τῆς Χαλκηδόνος διὰ θριγκίων πολλῶν πάνυ δυσχερῶς. ἀμφί τε τὰς πύλας ὠθισμὸς ἦν ἐσπηδώντων ὁμοῦ· ὅθεν οὐδὲν τοῖς διώκουσιν αὐτοὺς βέλος ἠτύχει. ὡς δὲ καὶ περὶ τῶν πυλῶν δείσαντες οἱ φύλακες τὰ κλεῖθρα καθῆκαν ἐς αὐτὰς ἀπὸ μηχανῆς, Νοῦδον μὲν καὶ τῶν ἄλλων ἡγεμόνων τινὰς καλῳδίοις ἀνιμήσαντο, οἱ δὲ λοιποὶ μεταξὺ τῶν τε φίλων καὶ τῶν πολεμίων ἀπώλλυντο, τὰς χεῖρας ἐς ἑκατέρους ὀρέγοντες. ὅ τε Μιθριδάτης τῇ φορᾷ τῆς εὐτυχίας χρώμενος ἐπῆγεν αὐτῆς ἡμέρας ἐπὶ τὸν λιμένα τὰς ναῦς, καὶ τὸ κλεῖθρον ἁλύσει χαλκῇ δεδεμένον ἀπορρήξας τέσσαρας μὲν ἐνέπρησε τῶν πολεμίων, τὰς δὲ λοιπὰς ἑξήκοντα ἀνεδήσατο, οὐδὲν οὔτε Νούδου κωλύοντος ἔτι οὔτε Κόττα, ἀλλ’ ἐς τὰ τείχη συγκεκλεισμένων. ἀπέθανον δὲ Ῥωμαίων μὲν ἐς τρισχιλίους, καὶ Λεύκιος Μάλλιος, ἀνὴρ ἀπὸ βουλῆς, Μιθριδάτου δὲ Βαστερνῶν τῶν πρώτων ἐσπεσόντων ἐς τὸν λιμένα εἴκοσιν.", "st": "5.71"}, {"sp": "N", "t": "Λεύκιος δὲ Λεύκολλος ὑπατεύειν καὶ στρατηγεῖν αἱρεθεὶς τοῦδε τοῦ πολέμου τέλος μέν τι στρατιωτῶν ἦγεν ἐκ Ῥώμης, δύο δ’ ἄλλα τὰ Φιμβρίου καὶ ἐπ’ αὐτοῖς ἕτερα δύο προσλαβών, σύμπαντας ἔχων πεζοὺς τρισμυρίους καὶ ἱππέας ἐς χιλίους ἐπὶ ἑξακοσίοις, παρεστρατοπέδευε τῷ Μιθριδάτῃ περὶ Κύζικον. καὶ δι’ αὐτομόλων ἐπιγνοὺς εἶναι τῷ βασιλεῖ στρατιὰν μὲν ἀνδρῶν ἀμφὶ μυριάδας τριάκοντα, ἀγορὰν δὲ εἴ τι σιτολογοῦντες ἢ ἐκ θαλάσσης λάβοιεν, ἔφη πρὸς τοὺς ἀμφ’ αὑτὸν ἀμαχὶ λήψεσθαι τοὺς πολεμίους αὐτίκα, καὶ τοῦ ἐπαγγέλματος αὐτοῖς ἐνεκελεύετο μνημονεύειν. ὄρος δὲ ἰδὼν εὔκαιρον ἐς στρατοπεδείαν, ὅθεν αὐτὸς μὲν εὔπορήσειν ἔμελλεν ἀγορᾶς, τοὺς δὲ πολεμίους ἀποκλείσειν, ἐπεχείρει καταλαβεῖν ὡς ἐν τῷδε τὴν νίκην ἀκίνδυνον ἕξων. μιᾶς δ’ οὔσης ἐς αὐτὸ διόδου στενῆς, ὁ Μιθριδάτης αὐτὴν ἐφύλαττεν ἐγκρατῶς, ὧδε καὶ Ταξίλου καὶ τῶν ἄλλων ἡγεμόνων αὐτῷ παραινοῦντων. Λεύκιος δὲ Μάγιος ὁ Σερτωρίῳ καὶ Μιθριδάτῃ τὰ ἐς ἀλλήλους διαιτήσας, ἀνῃρημένου τοῦ Σερτωρίου πρὸς Λεύκολλον ἐπεπόμφει κρύφα, καὶ πίστιν λαβὼν μετέπειθε τὸν Μιθριδάτην ὑπεριδεῖν Ῥωμαίων παροδευόντων τε καὶ στρατοπεδευόντων ὅπῃ θελήσειαν. τὰ γὰρ ὑπὸ Φιμβρίᾳ γενόμενα δύο τέλη βουλεύειν αὐτομολίαν, καὶ αὐτίκα τῷ βασιλεῖ προσέσεσθαι· τί οὖν χρῄζειν αὐτὸν ἀγῶνος καὶ φόνου, δυνάμενον ἀμαχὶ κρατῆσαι τῶν πολεμίων; οἷς ὁ Μιθριδάτης συνθέμενος ἀνοήτως μάλα καὶ ἀνυπόπτως, περιεῖδε Ῥωμαίους διὰ στενοῦ παροδεύοντας ἀδεῶς καὶ ἐπιτειχίζοντας αὑτῷ μέγα ὄρος, οὗ κρατοῦντες αὐτοὶ μὲν ὄπισθεν ἔμελλον ἀγορὰν ἀδεῶς ἐπάξεσθαι, Μιθριδάτην δὲ λίμνῃ καὶ ὄρεσι καὶ ποταμοῖς ἀποκλείσειν τῶν κατὰ γῆν ἁπάντων, ὅ τι μὴ γλίσχρως ποτὲ λάβοι, οὔτε ἐξόδους εὐρείας ἔτι ἔχοντα, οὔτε βιάζεσθαι δυνάμενον ἔτι Λεύκολλον ὑπὸ τῆς δυσχωρίας, ἧς κρατῶν κατεφρόνησεν. ὅ τε χειμὼν ἤδη πλησιάζων ἔμελλε καὶ τῶν ἀπὸ τῆς θαλάσσης αὐτὸν ἐν ἀπορίᾳ καταστήσειν. ἃ θεωρῶν ὁ Λεύκολλος τοὺς φίλους ἀνεμίμνησκε τῆς ὑποσχέσεως, καὶ τὸ ἐπαγγελθὲν ὡς παρὸν ἐδείκνυ.", "st": "5.72"}, {"sp": "N", "t": "ὁ δὲ Μιθριδάτης δυνηθεὶς ἂν ἴσως καὶ τότε διὰ τὸ πλῆθος διὰ μέσων ὤσασθαι τῶν πολεμίων, τούτου μὲν ὑπερεῖδε, Κυζίκῳ δὲ οἷς παρεσκεύασε πρὸς πολιορκίαν ἐπετίθετο, νομίσας ἐν τῷδε διορθώσειν τὴν δυσχωρίαν ὁμοῦ καὶ τὴν ἀπορίαν. οἷα δὲ εὐπορῶν στρατοῦ πολλοῦ, πᾶσιν ἔργοις ἐπεχείρει, τόν τε σταθμὸν ἀποτειχίζων τείχει διπλῷ, καὶ τὰ λοιπὰ τῆς πόλεως ἀποταφρεύων. χώματά τε ἤγειρε πολλά, καὶ μηχανὰς ἐπήγνυτο, πύργους καὶ χελώνας κριοφόρους, ἑλέπολίν τε ἑκατὸν πήχεων, ἐξ ἧς ἕτερος πύργος ἐπῇρτο καταπέλτας καὶ λίθους καὶ βέλη ποικίλα ἀφιείς. κατὰ δὲ τοὺς λιμένας δύο πεντήρεις ἐζευγμέναι πύργον ἕτερον ἔφερον, ἐξ οὗ γέφυρα, ὁπότε προσπελάσειαν ἐς τὸ τεῖχος, ὑπὸ μηχανῆς ἐξήλλετο. ὡς δ’ ἕτοιμα αὐτῷ πάντα ἐγεγένητο, πρῶτα μὲν τρισχιλίους αἰχμαλώτους Κυζικηνοὺς ἐπὶ νεῶν τῇ πόλει προσῆγεν, οἳ χεῖρας ἐς τὸ τεῖχος ὀρέγοντες ἐδέοντο σφῶν κινδυνευόντων φείσασθαι τοὺς πολίτας, μέχρι Πεισίστρατος αὐτοῖς, ὁ στρατηγὸς ὁ τῶν Κυζικηνῶν, ἀπὸ τοῦ τείχους ἐκήρυξε φέρειν τὸ συμβαῖνον ἐγκρατῶς, αἰχμαλώτους γεγονότας.", "st": "5.73"}, {"sp": "N", "t": "ὁ δὲ Μιθριδάτης ὡς ἀπέγνω τῆσδε τῆς πείρας, ἐπῆγε τὴν ἐπὶ τῶν νεῶν μηχανήν· καὶ ἥ τε γέφυρα ἐς τὸ τεῖχος ἐξήλατο ἄφνω, καὶ τέσσαρες ἀπ’ αὐτῆς ἄνδρες ἐξέδραμον. ᾧ δὴ καὶ μάλιστα καινοτρόπῳ φανέντι καταπλαγέντες οἱ Κυζικηνοὶ ἐπὶ μέν τι ὑπεχώρησαν, οὐκ ὀξέως δὲ ἑτέρων ἐπιδραμόντων ἀνεθάρρησάν τε καὶ τοὺς τέσσαρας κατέωσαν ἐς τὸ ἔξω, ταῖς τε ναυσὶ πῦρ καὶ πίσσαν ἐπιχέαντες ἠνάγκασαν πρύμναν τε κρούσασθαι καὶ ὑποχωρεῖν ὀπίσω μετὰ τοῦ μηχανήματος. ὧδε μὲν δὴ τῶν κατὰ θάλασσαν ἐπενεχθέντων ἐκράτουν οἱ Κυζικηνοί· τρίτα δ’ αὐτοῖς ἐπήγετο τῆς αὐτῆς ἡμέρας τὰ ἐν τῇ γῇ μηχανήματα ὁμοῦ πάντα, πονουμένοις τε καὶ μεταθέουσιν ἐς τὸ ἀεὶ βιαζόμενον. τοὺς μὲν οὖν κριοὺς λίθοις ἀπεκαύλιζον ἢ βρόχοις ἀνέκλων ἢ φορμοῖς ἐρίων τῆς βίας ἐξέλυον, τῶν δὲ βελῶν τοῖς μὲν πυρφόροις ὑπήντων ὕδατι καὶ ὄξει, τὰ δ’ ἄλλα προβολαῖς ἱματίων ἢ ὀθόναις κεχαλασμέναις τῆς φορᾶς ἀνέλυον, ὅλως τε οὐδὲν προθυμίας ἀνδρὶ δυνατῆς ἐξέλειπον. καὶ τάδε αὐτοῖς φερεπονώτατα δὴ κακοπαθοῦσιν ὅμως γε τοῦ τείχους ἐκαύθη τι καὶ συνέπεσεν ἐς ἑσπέραν. οὐ μὴν ἔφθασέ τις ἐσαλάμενος ἔτι θερμόν, ἀλλ’ αὐτὸ νυκτὸς αὐτίκα περιῳκοδόμησαν οἱ Κυζικηνοί. τῶν δὲ αὐτῶν ἡμερῶν πνεῦμα σφοδρὸν ἐπιγενόμενον περιέκλασε τὰ λοιπὰ τῶν μηχανημάτων τοῦ βασιλέως.", "st": "5.74"}, {"sp": "N", "t": "λέγεται δ’ ἡ πόλις ἐμπροίκιον ὑπὸ Διὸς τῇ κόρῃ δοθῆναι, καὶ σέβουσιν αὐτὴν οἱ Κυζικηνοὶ μάλιστα θεῶν. ἐπελθούσης δὲ τῆς ἑορτῆς, ἐν ᾗ θύουσι βοῦν μέλαιναν, οἱ μὲν οὐκ ἔχοντες ἔπλαττον ἀπὸ σίτου, μέλαινα δὲ βοῦς ἐκ πελάγους πρὸς αὐτοὺς διενήχετο, καὶ τὸ κλεῖθρον τοῦ στόματος ὑποδῦσά τε καὶ ἐς τὴν πόλιν ἐσδραμοῦσα ὥδευσεν ἀφ’ ἑαυτῆς ἐς τὸ ἱερὸν καὶ τοῖς βωμοῖς παρέστη. ταύτην μὲν οὖν οἱ Κυζικηνοὶ μετὰ χρηστῆς ἐλπίδος ἔθυον, οἱ δὲ φίλοι τῷ Μιθριδάτῃ συνεβούλευον ὡς ἱερᾶς τῆς πόλεως ἀποπλεῦσαι. ὁ δ’ οὐ πεισθεὶς ἐπὶ τὸ Δίνδυμον ὄρος ὑπερκείμενον ἀνῄει, καὶ χῶμα ἀπ’ αὐτοῦ ἐς τὴν πόλιν ἔχου, πύργους τε ἐφίστη, καὶ ὑπονόμοις τὸ τεῖχος ἀνεκρήμνη. τοὺς δ’ ἵππους ἀχρείους οἱ τότε ὄντας, καὶ ἀσθενεῖς δι’ ἀτροφίαν καὶ χωλεύοντας ἐξ ὑποτριβῆς, ἐς Βιθυνίαν περιέπεμπεν· οἷς ὁ Λεύκολλος περῶσι τὸν Ῥύνδακον ἐπιπεσὼν ἔκτεινε πολλούς, καὶ αἰχμαλώτους ἔλαβεν ἄνδρας μὲν ἐς μυρίους καὶ πεντακισχιλίους, ἵππους δ’ ἐς ἑξακισχιλίους καὶ σκευοφόρα πολλά.", "st": "5.75"}, {"sp": "N", "t": "καὶ τάδε μὲν ἦν περὶ Κύζικον, τῷ δ’ αὐτῷ χρόνῳ Φρυγίαν Εὔμαχος Μιθριδάτου στρατηγὸς ἐπιτρέχων ἔκτεινε Ῥωμαίων πολλοὺς μετὰ παίδων καὶ γυναικῶν, Πισίδας τε καὶ Ἰσαύρους ὑπήγετο καὶ Κιλικίαν, μέχρι τῶν τις Γαλατικῶν τετραρχῶν Δηιόταρος ἐπιπολάζοντα αὐτὸν συνεδίωξε καὶ πολλοὺς διέφθειρεν.", "st": "5.75"}, {"sp": "N", "t": "καὶ περὶ μὲν Φρυγίαν τοιάδε ἐγίγνετο, Μιθριδάτου δὲ χειμὼν ἐπιγενόμενος ἀφῄρητο καὶ τὴν ἐκ τῆς θαλάττης ἀγοράν, εἴ τις ἦν, ὥστε πάμπαν ὁ στρατὸς ἐλίμωττε, καὶ πολλοὶ μὲν ἀπέθνησκον, εἰσὶ δ’ οἳ καὶ σπλάγχνων ἐγεύοντο βαρβαρικῶς· οἱ δ’ ἄλλοι ποηφαγοῦντες ἐνόσουν. καὶ τὰ νεκρὰ σφῶν ἀγχοῦ ἄταφα ῥιπτούμενα λοιμὸν ἐπῆγεν ἐπὶ τῷ λιμῷ. διεκαρτέρει δ’ ὅμως ὁ Μιθριδάτης, ἐλπίζων ἔτι τὴν Κύζικον αἱρήσειν τοῖς χώμασι τοῖς ἀπὸ τοῦ Δινδύμου. ὡς δὲ καὶ ταῦθ’ ὑπεσύροντο οἱ Κυζικηνοί, καὶ τὰς ἐπ’ αὐτῶν μηχανὰς ἐπίμπρασαν, καὶ αἰσθήσει τοῦ λιμοῦ πολλάκις ἐπεκθέοντες τοῖς πολεμίοις ἀσθενεστάτοις γεγονόσιν ἐπετίθεντο, δρασμὸν ὁ Μιθριδάτης ἐβούλευε, καὶ ἔφευγε νυκτὸς αὐτὸς μὲν ἐπὶ τῶν νεῶν ἐς Πάριον, ὁ δὲ στρατὸς αὐτοῦ κατὰ γῆν ἐς Λάμψακον. περῶντας δ’ αὐτοὺς τὸν Αἴσηπον ὅ τε ποταμὸς τότε μάλιστα ἀρθεὶς μέγας, καὶ ἐπὶ τῷ ποταμῷ Λεύκολλος ἐπιδραμὼν ἔφθειρεν. ὧδε μὲν οἱ Κυζικηνοὶ πολλὴν βασιλέως παρασκευὴν διέφυγον, αὐτοί τε γενναίως ἀγωνισάμενοι, καὶ λιμῷ πιεσθέντος ὑπὸ Λευκόλλου. ἀγῶνά τε αὐτῷ θέμενοι μέχρι νῦν τελοῦσι, τὰ Λευκόλλεια καλούμενα. Μιθριδάτης δὲ τοὺς ἐς Λάμψακον ἐσφυγόντας, ἔτι τοῦ Λευκόλλου περικαθημένου, ναῦς ἐπιπέμψας ἐξεκόμισε σὺν αὐτοῖς Λαμψακηνοῖς. μυρίους δ’ ἐπιλέκτους ἐπὶ νεῶν πεντήκοντα Οὐαρίῳ, πεμφθέντι οἱ στρατηγεῖν ὑπὸ Σερτωρίου, καὶ Ἀλεξάνδρῳ τῷ Παφλαγόνι καὶ Διονυσίῳ τῷ εὐνούχῳ καταλιπών, ταῖς πλέοσιν αὐτῶν ἐς Νικομήδειαν ἔπλει. καὶ χειμὼν ἐπιγενόμενος πολλὰς ἑκατέρων διέφθειρεν.", "st": "5.76"}, {"sp": "N", "t": "Λεύκολλος δ’ ἐπεὶ τὸ κατὰ γῆν εἴργαστο διὰ τοῦ λιμοῦ, ναῦς ἐκ τῆς Ἀσίας ἀγείρας διέδωκε τοῖς ἀμφ’ αὑτὸν στρατηγοῦσιν. καὶ Τριάριος μὲν Ἀπάμειαν εἷλεν ἐπιπλεύσας, καὶ πολλὴ τῶν Ἀπαμέων συμφυγόντων ἐς τὰ ἱερὰ ἐγένετο σφαγή· Βάρβας δὲ Προυσιάδα εἷλε τὴν πρὸς τῷ ὄρει, καὶ Νίκαιαν ἔλαβε, τῶν Μιθριδάτου φρουρῶν ἐκφυγόντων. Λεύκολλος δὲ περὶ τὸν Ἀχαιῶν λιμένα τρισκαίδεκα ναῦς εἷλε τῶν πολεμίων. Οὐάριον δὲ καὶ Ἀλέξανδρον καὶ Διονύσιον περὶ Λῆμνον ἐν ἐρήμῃ νήσῳ καταλαβών, ἔνθα δείκνυται βωμὸς Φιλοκτήτου καὶ χαλκοῦς ὄφις καὶ τόξα καὶ θώραξ ταινίαις περίδετος, μνῆμα τῆς ἐκείνου πάθης, ἐπέπλει μὲν αὐτοῖς ῥοθίῳ τε πολλῷ καὶ μετὰ καταφρονήσεως, εὐσταθῶς δ’ ἐκείνων ὑπομενόντων ἔστησε τὴν εἰρεσίαν, καὶ κατὰ δύο ναῦς ἐπιπέμπων ἠρέθιζεν ἐς ἔκπλουν. οὐ σαλευόντων δ’ ἐκείνων ἀλλ’ ἀπὸ γῆς ἀμυνομένων, περιέπλευσε τὴν νῆσον ἑτέραις ναυσί, καὶ πεζοὺς ἐς αὐτὴν ἐκβιβάσας συνήλασε τοὺς ἐχθροὺς ἐπὶ τὰς ναῦς. οἱ δ’ ἐς μὲν τὸ πέλαγος οὐκ ἠφίεσαν, τὸν Λευκόλλου στρατὸν δεδιότες, παρὰ δὲ τὴν γῆν πλέοντες, ἔκ τε τῆς γῆς καὶ τῆς θαλάσσης ἀμφίβολοι γιγνόμενοι κατετιτρώσκοντο, καὶ φόνος πολὺς ἦν αὐτῶν καὶ φυγή. ἐλήφθησαν δ’ ἐν σπηλαίῳ κρυπτόμενοι Οὐάριός τε καὶ Ἀλέξανδρος καὶ Διονύσιος ὁ εὐνοῦχος. καὶ αὐτῶν ὁ μὲν Διονύσιος, πιὼν ὅπερ ἤγετο φάρμακον, αὐτίκα ἀπέθανε, Οὐάριον δ’ ἀναιρεθῆναι προσέταξε Λεύκολλος· οὐ γὰρ ἐδόκει Ῥωμαῖον ἄνδρα βουλευτὴν θριαμβεύειν. Ἀλέξανδρος δὲ ἐς τὴν πομπὴν ἐφυλάσσετο. καὶ Λεύκολλος περὶ τῶνδε Ῥωμαίοις ἐπέστελλε, τὰ γράμματα δάφνῃ περιβαλών, ὡς ἔθος ἐστὶν ἐπὶ νίκαις· αὐτὸς δὲ ἠπείγετο ἐς Βιθυνίαν.", "st": "5.77"}, {"sp": "N", "t": "Μιθριδάτῃ δ’ ἐς Πόντον ἐσπλέοντι χειμὼν ἐς δὶς ἐπιγίγνεται, καὶ τῶν ἀνδρῶν ἀμφὶ τοὺς μυρίους καὶ νῆες ἀμφὶ τὰς ἑξήκοντα διεφθάρησαν· αἱ δὲ λοιπαὶ διερρίφησαν, ὡς ἑκάστην ὁ χειμὼν ἐξήνεγκεν. αὐτὸς δὲ ῥηγνυμένης τῆς στρατηγίδος ἐς λῃστῶν σκάφος, ἀπαγορευόντων τῶν φίλων, ὅμως ἐνέβη. καὶ ἐς Σινώπην αὐτὸν οἱ λῃσταὶ διέσωσαν. ὅθεν ὁ μὲν ἐς Ἀμισὸν ἀπὸ κάλω διαπλέων, πρός τε τὸν κηδεστὴν Τιγράνην τὸν Ἀρμένιον καὶ ἐς Μαχάρην τὸν υἱόν, ἄρχοντα Βοσπόρου, περιέπεμπεν, ἐπικουρεῖν ἐπείγων ἑκάτερον. ἔς τε Σκύθας τοὺς ὁμόρους χρυσὸν καὶ δῶρα πολλὰ Διοκλέα φέρειν ἐκέλευεν. ἀλλ’ ὁ μὲν αὐτοῖς τε δώροις καὶ αὐτῷ χρυσίῳ πρὸς Λεύκολλον ηὐτομόλησε, Λεύκολλος δ’ ἐπὶ τῇ νίκῃ θρασέως προϊὼν ἐς τὸ πρόσθεν καὶ τὰ ἐν ποσὶν ἅπαντα χειρούμενος προυνόμευεν. οἷα δ’ εὐδαίμονος χώρας καὶ πολὺν χρόνον ἀπολεμήτου, τὸ μὲν ἀνδράποδον τεττάρων δραχμῶν αὐτίκα ἐγίγνετο, ὁ δὲ βοῦς μιᾶς, αἶγες δὲ καὶ πρόβατα καὶ ἐσθὴς καὶ τὰ λοιπὰ τούτων κατὰ λόγον. Λεύκολλος δ’ Ἀμισόν τε καὶ Εὐπατορίαν, ἥν τινα τῇ Ἀμισῷ παρῳκοδόμησεν ὁ Μιθριδάτης Εὐπατορίαν τε ὠνόμαζεν ἀφ’ ἑαυτοῦ καὶ βασίλεια ἡγεῖτο, περικαθήμενος ἐπολιόρκει, καὶ ἑτέρῳ στρατῷ Θεμίσκυραν, ἣ τῶν Ἀμαζόνων τινὸς ἐπώνυμος οὖσα παρὰ τὸν Θερμώδοντα ποταμὸν ἔστιν. τούτων δ’ οἱ μὲν τοῖς Θεμισκυρίοις ἐπικαθήμενοι πύργους ἐπῆγον αὐτοῖς καὶ χώματα ἐχώννυον καὶ ὑπονόμους ὤρυττον, οὕτω δή τι μεγάλους ὡς ἐν αὐτοῖς ὑπὸ τὴν γῆν ἀλλήλοις κατὰ πλῆθος ἐπιχειρεῖν· καὶ οἱ Θεμισκύριοι ὀπὰς ἄνωθεν ἐς αὐτοὺς ὀρύττοντες, ἄρκτους τε καὶ θηρία ἕτερα καὶ σμήνη μελισσῶν ἐς τοὺς ἐργαζομένους ἐνέβαλλον. οἱ δ’ ἀμφὶ τὴν Ἀμισὸν ἕτερον τρόπον ἐμόχθουν, ἀπομαχομένων αὐτοὺς τῶν Ἀμισέων καὶ πολλάκις ἐκθεόντων καὶ ἐς μονομαχίας προκαλουμένων. Μιθριδάτης δ’ αὐτοῖς πολλὴν ἀγορὰν καὶ ὅπλα καὶ στρατιὰν ἔπεμπεν ἐκ Καβείρων, ἔνθα χειμάζων στρατὸν ἄλλον συνέλεγεν. καὶ συνῆλθον αὐτῷ πεζοὶ μὲν ἐς τετρακισμυρίους, ἱππεῖς δὲ ἐς τετρακισχιλίους.", "st": "5.78"}, {"sp": "N", "t": "ἱσταμένου δ’ ἦρος ὁ μὲν Λεύκολλος διὰ τῶν ὀρῶν ἐπὶ τὸν Μιθριδάτην ἐχώρει. προφυλακαὶ δ’ ἦσαν ἐκείνῳ κωλύειν τε Λεύκολλον, καὶ διαπυρσεύειν οἱ συνεχῶς, εἴ τι γίγνοιτο. καὶ ἦρχε τῆσδε τῆς φυλακῆς ἐκ Μιθριδάτου τις ἀνὴρ τοῦ βασιλείου γένους, ὄνομα Φοῖνιξ· ὅς, ἐπεὶ Λεύκολλος ἐπέλαζε, Μιθριδάτῃ μὲν διεπύρσευσεν, ἐς δὲ Λεύκολλον ηὐτομόλησε μετὰ τῆς δυνάμεως. καὶ ὁ Λεύκολλος ἀδεῶς ἤδη τὰ ὄρη διεξελθὼν ἐς Κάβειρα κατέβη. γενομένης δ’ αὐτῷ τε καὶ Μιθριδάτῃ τινὸς ἱππομαχίας, ἡττώμενος αὖθις ἐς τὸ ὄρος ἀνέθορεν. ὁ δὲ ἵππαρχος αὐτοῦ Πομπώνιος ἐς Μιθριδάτην τετρωμένος ἀνήχθη· καὶ πυθομένῳ βασιλεῖ τίνα χάριν οἱ περισωθεὶς δύναιτο ἀποδοῦναι, “εἰ μέν,” ἔφη, “σὺ φίλος γένοιο Λευκόλλῳ, πάνυ πολλοῦ ἀξίαν· εἰ δ’ ἐχθρὸς εἴης, οὐδὲ βουλεύσομαι.” ὧδε μὲν ὁ Πομπώνιος ἀπεκρίνατο· καὶ αὐτὸν τῶν βαρβάρων κτείνειν ἀξιούντων, ὁ βασιλεὺς εἶπεν οὐκ ἐξυβριεῖν ἐς ἀτυχοῦσαν ἀρετήν. ἐκτάσσων δὲ συνεχῶς, οὐ κατιόντος ἐς μάχην τοῦ Λευκόλλου, περιιὼν ἀνάβασιν ἐπ’ αὐτὸν ἐζήτει. καί τις ἀνὴρ ἐν τούτῳ Σκύθης, ὄνομα Ὀλκάβας, αὐτόμολος ὢν ἐς Λεύκολλον ἐκ πολλοῦ, καὶ παρὰ τήνδε τὴν ἱππομαχίαν πολλοὺς περισώσας, καὶ δι’ αὐτὸ παρὰ τοῦ Λευκόλλου τραπέζης τε καὶ γνώμης καὶ ἀπορρήτων ἀξιούμενος, ἧκεν ἐπὶ τὴν σκηνὴν αὐτοῦ περὶ μεσημβρίαν ἀναπαυομένου, καὶ ἐσελθεῖν ἐβιάζετο, βραχὺ καὶ σύνηθες ἐπὶ τοῦ ζωστῆρος ἐγχειρίδιον περικείμενος. κωλυόμενος δ’ ἠγανάκτει, καὶ χρείαν τινὰ ἐπείγειν ἔλεγεν ἐξαναστῆσαι τὸν στρατηγόν. τῶν δὲ θεραπευτήρων οὐδὲν εἰπόντων χρησιμώτερον εἶναι Λευκόλλῳ τῆς σωτηρίας, ἐπέβη τὸν ἵππον αὐτίκα καὶ ἐς τὸν Μιθριδάτην ἐξήλασεν, εἴτε ἐπιβουλεύων καὶ δόξας ὑποπτεύεσθαι, εἴτε σὺν ὀργῇ, περιυβρίσθαι νομίζων. ἕτερόν τε Σκύθην, ὄνομα Σοβάδακον, ἐνέφηνε τῷ Μιθριδάτῃ βουλεύειν ἐς Λεύκολλον αὐτομολίαν. Σοβάδακος μὲν δὴ συνελαμβάνετο,", "st": "5.79"}, {"sp": "N", "t": "Λεύκολλος δὲ τὴν κάθοδον τὴν ἐς τὸ πεδίον ἱπποκρατούντων τῶν πολεμίων ἐκτρεπόμενος, καὶ περίοδον ἑτέραν οὐχ ὁρῶν, ηὗρεν ἐν σπηλαίῳ κυνηγὸν ὀρείων ἀτραπῶν ἐπιστήμονα, ᾧ χρώμενος ἡγεμόνι κατὰ ὁδοὺς ἀτριβεῖς περιῆλθεν ὑπὲρ κεφαλῆς τοῦ Μιθριδάτου, καὶ κατῄει μὲν ἐκκλίνας καὶ τότε τὸ πεδίον διὰ τοὺς ἵππους, χαράδραν δὲ ὕδατος ἐν προβολῇ θέμενος ἐστρατοπέδευσεν. ἀπορῶν δ’ ἀγορᾶς ἐς Καππαδοκίαν ἔπεμπεν ἐπὶ σῖτον, καὶ ἐς τοὺς πολεμίους ἠκροβολίζετο, μέχρι, φευγόντων ποτὲ τῶν βασιλικῶν, ὁ Μιθριδάτης ἀπὸ τοῦ χάρακος ἐπιδραμὼν καὶ ἐπιπλήξας ἐπέστρεφεν αὐτούς, καὶ Ῥωμαίους οὕτω κατεφόβησεν ὡς ἄνω διὰ τῶν ὀρῶν φεύγοντας οὐδ’ ἀποστάντων αἰσθέσθαι τῶν πολεμίων ἐς πολύ, ἀλλ’ ἕκαστον ἡγεῖσθαι τὸν συμφεύγοντά οἱ καὶ ἐπιόντα ὄπισθεν εἶναι πολέμιον· οὕτω πάνυ κατεπεπλήγεσαν. καὶ ὁ Μιθριδάτης περὶ τῆσδε τῆς νίκης πανταχοῦ γράφων περιέπεμπεν. τῶν δ’ ἱππέων πολὺ μέρος, καὶ μάλιστα δὴ τὸ μαχιμώτατον, ἐφεδρεύειν ἔταξε τοῖς ἐκ τῆς Καππαδοκίας τὴν ἀγορὰν τῷ Λευκόλλῳ φέρουσιν, ἐλπίζων ἐν ἀπορίᾳ τροφῶν αὐτὸν γενόμενον πείσεσθαι οἷον αὐτὸς ἔπαθε περὶ Κύζικον.", "st": "5.80"}, {"sp": "N", "t": "καὶ τὸ μὲν ἐνθύμημα μεγα ἦν, ἀποκλεῖσαι τροφῶν Λεύκολλον, ἐκ μόνης ἔχοντα Καππαδοκίας· οἱ δ’ ἱππεῖς οἱ βασιλέως τοῖς προδρόμοις τῶν σιτοφόρων ἐν στενῷ περιτυχόντες, καὶ οὐκ ἀναμείναντες ἐς εὐρυχωρίαν προελθεῖν, ἀχρεῖον ὡς ἐν στενῷ σφίσι τὴν ἵππον ἐποίησαν. ἐν ᾧ καὶ Ῥωμαῖοι φθάσαντες ἐξ ὁδοιπορίας ἐς μάχην παρασκευάσασθαι, τοὺς μὲν ἔκτειναν τῶν βασιλικῶν, βοηθούσης οἷα πεζοῖς τῆς δυσχωρίας, τοὺς δὲ ἐς τὰς πέτρας κατήραξαν, τοὺς δὲ διέρριψαν ὑποφεύγοντας. ὀλίγοι δὲ νυκτὸς ἐς τὸ στρατόπεδον διαδραμόντες τε καὶ μόνοι περιγενέσθαι λέγοντες, μέγα ὂν σφίσι τὸ συμβὰν μειζόνως διεθρόησαν. Μιθριδάτης δ’ αὐτὸ πρὸ τοῦ Λευκόλλου πυθόμενός τε, καὶ Λεύκολλον ἐλπίσας ἐπὶ τοσῇδε ἱππέων ἀπωλείᾳ αὐτίκα οἱ προσπεσεῖσθαι, φυγὴν ὑπ’ ἐκπλήξεως ἐπενόει, καὶ τόδε τοῖς φίλοις εὐθὺς ἐξέφερεν ἐν τῇ σκηνῇ. οἱ δέ, πρίν τι γενέσθαι παράγγελμα, νυκτὸς ἔτι, σπουδῇ τὰ ἴδια ἕκαστος ἐξέπεμπεν ἐκ τοῦ στρατοπέδου· καὶ ὠθουμένων περὶ τὰς πύλας σκευοφόρων πολὺ πλῆθος ἦν. ὅπερ ἡ στρατιὰ θεωμένη καὶ τοὺς φέροντας ἐπιγιγνώσκουσα, καὶ τοπάζουσα πολλὰ ἀτοπώτερα, σὺν δέει, καὶ ἀγανακτήσει τοῦ μηδὲν αὑτοῖς ἐπηγγέλθαι, τὸν χάρακα σφῶν ἐπιδραμόντες ἔλυον, καὶ διέφευγον ὡς ἐκ πεδίου πάντοθεν ἀκόσμως, ὅπῃ δύναιτο ἕκαστος αὐτῶν, ἄνευ στρατηγοῦ καὶ ἐπιστάτου παραγγέλματος. ὧν ὁ Μιθριδάτης ὀξύτερόν τε καὶ σὺν ἀταξίᾳ γιγνομένων αἰσθόμενος, ἐξέδραμεν ἐκ τῆς σκηνῆς ἐς αὐτοὺς καὶ λέγειν τι ἐπεχείρει, οὐδενὸς δ’ ἐσακούοντος ἔτι, συνθλιβεὶς ὡς ἐν πλήθει κατέπεσε, καὶ ἐς τὸν ἵππον ἀναβληθεὶς ἐς τὰ ὄρη σὺν ὀλίγοις ἐφέρετο.", "st": "5.81"}, {"sp": "N", "t": "Λεύκολλος δὲ τῆς περὶ τὴν ἀγορὰν εὐπραγίας πυθόμενος, καὶ τὴν φυγὴν τῶν πολεμίων ἰδών, ἐπὶ μὲν τοὺς ἐκφυγόντας ἔπεμπε διώκειν ἱππέας πολλούς, τοῖς δὲ συσκευαζομένοις ἔτι κατὰ τὸ στρατόπεδον τοὺς πεζοὺς περιστήσας ἐκέλευε μὴ διαρπάζειν ἐν τῷ τότε μηδέν, ἀλλὰ κτείνειν ἀφειδῶς. οἱ δὲ σκεύη τε χρυσᾶ καὶ ἀργυρᾶ πολλὰ καὶ ἐσθῆτας πολυτελεῖς θεώμενοι ἐξέστησαν τοῦ παραγγέλματος. αὐτόν τε τὸν Μιθριδάτην οἱ καταλαμβάνοντες, ἡμίονόν τινα τῶν χρυσοφόρων ἐς τὸ σάγμα πατάξαντες, προπεσόντος τοῦ χρυσίου περὶ τόδε γενόμενοι διαφυγεῖν ἐς Κόμανα περιεῖδον· ὅθεν ἐς Τιγράνην ἔφυγε σὺν ἱππεῦσι δισχιλίοις. ὁ δὲ αὐτὸν ἐς ὄψιν οὐ προσέμενος, ἐν χωρίοις ἐκέλευσε διαίτης βασιλικῆς ἀξιοῦσθαι, ὅτε δὴ καὶ μάλιστα τῆς ἀρχῆς ἀπογνοὺς ὁ Μιθριδάτης Βάκχον εὐνοῦχων ἔπεμπεν ἐς τὰ βασίλεια, τὰς ἀδελφὰς αὐτοῦ καὶ τὰς γυναῖκας καὶ παλλακάς, ὅπῃ δύναιτο, ἀνελοῦντα. αἱ μὲν δὴ διεφθείροντο ξίφεσι καὶ φαρμάκοις καὶ βρόχοις, δεινὰ ποιοῦσαι· ταῦτα δ’ ὁρῶντες οἱ φρούραρχοι τοῦ Μιθριδάτου ἀθρόως ἐς τὸν Λεύκολλον μετετίθεντο, χωρὶς ὀλίγων. καὶ ὁ Λεύκολλος αὐτοὺς ἐπιὼν καθίστατο, καὶ τὰς ἐπὶ τοῦ Πόντου πόλεις περιπλέων ᾕρει, Ἄμαστρίν τε καὶ Ἡράκλειαν καὶ ἑτέρας.", "st": "5.82"}, {"sp": "N", "t": "Σινώπη δ’ ἀντεῖχεν ἔτι καρτερῶς, καὶ διεναυμάχησεν οὐ κακῶς. πολιορκούμενοι δὲ τὰς ναῦς τὰς βαρυτέρας σφῶν διέπρησαν, καὶ ἐς τὰς κουφοτέρας ἐμβάντες ἀπέδρασαν. Λεύκολλος δὲ τὴν πόλιν εὐθὺς ἐλευθέραν ἠφίει δι’ ἐνύπνιον, ὃ τοιόνδε ἦν. Αὐτόλυκόν φασιν, ἐπὶ τὰς Ἀμαζόνας Ἡρακλεῖ συστρατεύοντα, ὑπὸ χειμῶνος ἐς Σινώπην καταχθῆναι καὶ τῆς πόλεως κρατῆσαι· ἀνδριάς τε σεβάσμιος τοῖς Σινωπεῦσιν ἔχρα, ὃν οἱ μὲν Σινωπεῖς οὐ φθάσαντες ἐς φυγὴν ἐπαγαγέσθαι, ὀθόναις καὶ καλῳδίοις περιέδησαν· οὐδὲν δ’ ὁ Λεύκολλος εἰδὼς οὐδὲ προμαθὼν ἔδοξεν ὑπ’ αὐτοῦ κληθεὶς ὁρᾶν αὐτόν, καὶ τῆς ἐπιούσης τὸν ἀνδριάντα τινῶν περιβεβλημένον παραφερόντων ἐκλῦσαι κελεύσας, εἶδεν οἷον ἔδοξε νυκτὸς ἑωρακέναι. τὸ μὲν δὴ ἐνύπνιον τοιόνδε ἦν, Λεύκολλος δὲ καὶ Ἀμισὸν ἐπὶ τῇ Σινώπῃ συνῴκιζεν, ἐκφυγόντων μὲν ὁμοίως τῶν Ἀμισέων διὰ θαλάσσης, πυνθανόμενος δ’ ὑπ’ Ἀθηναίων αὐτοὺς θαλασσοκρατούντων συνῳκίσθαι, καὶ δημοκρατίᾳ χρησαμένους ἐπὶ πολὺ τοῖς Περσικοῖς βασιλεῦσιν ὑπακοῦσαι, ἀναγαγόντος δ’ αὐτοὺς ἐς τὴν δημοκρατίαν ἐκ προστάγματος Ἀλεξάνδρου πάλιν δουλεῦσαι τοῖς Ποντικοῖς. ἐφ’ οἷς ἄρα συμπαθὴς ὁ Λεύκολλος γενόμενός τε, καὶ φιλοτιμούμενός γε καὶ ὅδε ἐπὶ Ἀλεξάνδρῳ περὶ γένος Ἀττικόν, αὐτόνομον ἠφίει τὴν πόλιν καὶ τοὺς Ἀμισέας κατὰ τάχος συνεκάλει. ὧδε μὲν δὴ Σινώπην καὶ Ἀμισὸν Λεύκολλος ἐπόρθει τε καὶ συνῴκιζε, καὶ Μαχάρῃ τῷ παιδὶ τῷ Μιθριδάτου, Βοσπόρου τε βασιλεύοντι καὶ στέφανόν οἱ πέμψαντι ἀπὸ χρυσοῦ, φιλίαν συνέθετο, Μιθριδάτην δ’ ἐξῄτει παρὰ Τιγράνους. καὶ ἐς τὴν Ἀσίαν αὐτὸς ἐπανελθών, ὀφείλουσαν ἔτι τῶν Συλλείων ἐπιβολῶν, τέταρτα μὲν ἐπὶ τοῖς καρποῖς, τέλη δ’ ἐπὶ τοῖς θεράπουσι καὶ ταῖς οἰκίαις ὥριζεν. καὶ ἐπινίκια ἔθυεν ὡς δὴ τὸν πόλεμον κατωρθωκώς.", "st": "5.83"}, {"sp": "N", "t": "ἐπὶ δὲ ταῖς θυσίαις ἐπὶ τὸν Τιγράνην, οὐκ ἐκδιδόντα οἱ τὸν Μιθριδάτην, ἐστράτευε σὺν δύο τέλεσιν ἐπιλέκτοις καὶ ἱππεῦσι πεντακοσίοις. καὶ τὸν Εὐφράτην περάσας, μόνα τὰ χρήσιμα τοὺς βαρβάρους αἰτῶν διώδευεν· οἱ γὰρ ἄνδρες οὐκ ἐπολέμουν, οὐδ’ ἠξίουν τι πάσχειν, ἔστε Λεύκολλον καὶ Τιγράνην ἐπ’ ἀλλήλοις διακριθῆναι. Τιγράνῃ δ’ οὐδεὶς ἐμήνυεν ἐπιόντα Λεύκολλον· ὁ γάρ τοι πρῶτος εἰπὼν ἐκεκρέμαστο ὑπ’ αὐτοῦ, συνταράσσειν αὐτὸν τὰς πόλεις νομίσαντος. ὡς δέ ποτε ᾔσθετο, Μιθροβαρζάνην προύπεμπε μετὰ δισχιλίων ἱππέων, Λεύκολλον ἐπισχεῖν τοῦ δρόμου. Μαγκαίῳ δὲ Τιγρανόκερτα φυλάττειν ἐπέτρεψεν, ἥν τινα πόλιν, ὥς μοι προείρηται, ἐπὶ τιμῇ τῇ ἑαυτοῦ βασιλεὺς ἐν ἐκείνῳ γενέσθαι τῷ χωρίῳ συνῴκιζε, καὶ τοὺς ἀρίστους ἐς αὐτὴν συνεκάλει, ζημίαν ἐπιτιθείς, ὅσα μὴ μεταφέροιεν, δεδημεῦσθαι. τείχη τε αὐτοῖς περιέβαλε πεντηκονταπήχη τὸ ὕψος, ἱπποστασίων ἐν τῷ βάθει γέμοντα, καὶ βασίλεια καὶ παραδείσους κατὰ τὸ προάστειον ἐποίει μακρούς, καὶ κυνηγέσια πολλὰ καὶ λίμνας· ἀγχοῦ δὲ καὶ φρούριον ἀνίστη καρτερόν. καὶ πάντα τότε Μαγκαίῳ ταῦτ’ ἐπιτρέψας, περιῄει στρατιὰν ἀγείρων. Μιθροβαρζάνην μὲν οὖν ὁ Λεύκολλος εὐθὺς ἐκ τῆς πρώτης συμβολῆς τρεψάμενος ἐδίωκε, Μαγκαῖον δὲ Σεξτίλιος ἐς Τιγρανόκερτα κατακλείσας τὰ μὲν βασίλεια αὐτίκα, ἀτείχιστα ὄντα, διήρπασε, τὴν δὲ πόλιν καὶ τὸ φρούριον ἀπετάφρευε, καὶ μηχανὰς ἐφίστη, καὶ ὑπονόμοις ἀνεκρήμνη τὸ τεῖχος.", "st": "5.84"}, {"sp": "N", "t": "καὶ Σεξτίλιος μὲν ἀμφὶ ταῦτα ἐγίγνετο, Τιγράνης δέ, πεζῶν ἐς πέντε καὶ εἴκοσι μυριάδας ἀγείρας καὶ ἱππέας ἐς πεντακισμυρίους, προύπεμψεν αὐτῶν ἐς Τιγρανόκερτα περὶ ἑξακισχιλίους, οἳ διὰ μέσων Ῥωμαίων ἐς τὸ φρούριον ὠσάμενοί τε καὶ τὰς παλλακὰς τοῦ βασιλέως ἐξαρπάσαντες ἐπανῆλθον. τῷ δὲ λοιπῷ στρατῷ Τιγράνης αὐτὸς ἤλαυνεν ἐπὶ Λεύκολλον. καὶ αὐτῷ τότε πρῶτον Μιθριδάτης ἐς ὄψιν ἐλθὼν συνεβούλευε μὴ συμπλέκεσθαι Ῥωμαίοις, ἀλλὰ τῷ ἱππικῷ μόνῳ περιτρέχοντα καὶ τὴν γῆν λυμαινόμενον ἐς λιμὸν αὐτούς, εἰ δύναιτο, περικλεῖσαι, ᾧ τρόπῳ καὶ αὐτὸς ὑπὸ Λευκόλλου περὶ Κύζικον ἀμαχὶ κάμνων τὸν στρατὸν ἀπολέσαι. ὁ δὲ γελάσας αὐτοῦ τὴν στρατηγίαν, προῄει συνεσκευασμένος ἐς μάχην· καὶ τὴν Ῥωμαίων ὀλιγότητα ἰδὼν ἐπέσκωψεν οὕτως· “εἰ μὲν πρέσβεις εἰσὶν οἵδε, πολλοί, εἰ δὲ πολέμιοι, πάμπαν ὀλίγοι.” Λεύκολλος δὲ λόφον εὔκαιρον ἰδὼν ὄπισθεν τοῦ Τιγράνους, τοὺς μὲν ἱππέας ἐκ μετώπου προσέτασσεν ἐνοχλεῖν αὐτῷ καὶ περισπᾶν ἐφ’ ἑαυτοὺς καὶ ὑποχωρεῖν ἑκόντας, ἵνα τῶν βαρβάρων διωκόντων ἡ τάξις παραλυθείη· τοῖς δὲ πεζοῖς αὐτὸς ἐς τὸν λόφον περιοδεύσας ἀνῄει λαθών. καὶ ὡς εἶδε τοὺς πολεμίους ὑπὸ τῆς διώξεως οἷα νικῶντας ἐς πολλὰ διεσκεδασμένους, τὰ δὲ σκευοφόρα αὐτῶν πάντα ὑποκείμενα, ἀνεβόησε· “νικῶμεν, ὦ ἄνδρες,” καὶ ἐπὶ τὰ σκευοφόρα πρῶτος ἵετο δρόμῳ. τὰ δὲ αὐτίκα σὺν θορύβῳ φεύγοντα τοῖς πεζοῖς ἐνέπιπτε, καὶ τοῖς ἱππεῦσιν οἱ πεζοί. τροπή τε ἦν εὐθὺς ὁλοσχερής· οἵ τε γὰρ ἐν τῇ διώξει μακρὰν ἀπεσπασμένοι τῶν Ῥωμαϊκῶν ἱππέων ἐπιστρεψάντων ἐς αὐτοὺς ἀπώλλυντο, καὶ τὰ σκευοφόρα τοῖς ἄλλοις ἐνέπιπτεν ὡς ἐνοχλούμενα. πάντων τε ὡς ἐν τοσῷδε πλήθει θλιβομένων, καὶ τὸ ἀκριβὲς οὐκ εἰδότων, ὁπόθεν ἡ ἧσσα αὐτοῖς ἄρχοιτο, πολὺς ἦν φόνος, οὐδενὸς σκυλεύοντος οὐδέν· ἀπηγόρευτο γὰρ ἐκ Λευκόλλου μετ’ ἀπειλῆς, ὥστε καὶ ψέλια καὶ περιαυχένια παροδεύοντες ἔκτεινον ἐπὶ σταδίους ἑκατὸν καὶ εἴκοσιν, ἔστε νὺξ ἐπέλαβε. τότε δ’ ἀναστρέφοντες ἐσκύλευον· ἐδίδου γὰρ ὁ Λεύκολλος ἤδη.", "st": "5.85"}, {"sp": "N", "t": "γιγνομένην δὲ τὴν ἧτταν ὁ Μαγκαῖος ἐφορῶν ἀπὸ Τιγρανοκέρτων, τοὺς Ἕλληνας, οἳ ἐμισθοφόρουν αὐτῷ, πάντας ἐξώπλισεν ὑποπτεύων· οἳ σύλληψιν δεδιότες, ἀθρόοι σκυτάλας ἔχοντες ἐβάδιζόν τε καὶ ηὐλίζοντο. Μαγκαίου δὲ τοὺς βαρβάρους ἐπάγοντος αὐτοῖς ὡπλισμένους, διαδησάμενοι τὰ ἱμάτια ταῖς λαιαῖς ἀντὶ ἀσπίδων, μετὰ τόλμης ἐσέδραμον ἐς αὐτούς· καὶ ὅσους ἀνέλοιεν, εὐθὺς ἐμερίζοντο τὰ ὅπλα. ὡς δὲ ἐκ τῶν δυνατῶν εἶχον αὐτάρκως, μεσοπύργιά τινα κατέλαβον, καὶ Ῥωμαίους ἔξωθεν ἐκάλουν τε καὶ ἀναβαίνοντας ἐδέχοντο. οὕτω μὲν ἑάλω Τιγρανόκερτα, καὶ πλοῦτος διηρπάζετο πολύς, οἷα πόλεως νεοκατασκεύου, φιλοτίμως συνῳκισμένης.", "st": "5.86"}, {"sp": "N", "t": "Τιγράνης δὲ καὶ Μιθριδάτης στρατὸν ἄλλον ἤθροιζον περιιόντες, οὗ τὴν στρατηγίαν ἐπετέτραπτο Μιθριδάτης, ἡγουμένου Τιγράνους αὐτῷ γεγονέναι τὰ παθήματα διδάγματα. ἔπεμπον δὲ καὶ ἐς τὸν Παρθυαῖον, ἐπικουρεῖν σφίσι παρακαλοῦντες. ἀντιπρεσβεύοντος δὲ Λευκόλλου, καὶ ἀξιοῦντος ἢ οἷ συμμαχῆσαι ἢ ἀμφοτέροις ἐκστῆναι τοῦ ἀγῶνος, ὁ μὲν κρύφα συντιθέμενος ἑκατέροις, οὐκ ἔφθασεν οὐδετέροις ἀμῦναι, ὁ δὲ Μιθριδάτης ὅπλα τε εἰργάζετο κατὰ πόλιν ἑκάστην, καὶ ἐστρατολόγει σχεδὸν ἅπαντας Ἀρμενίους. ἐπιλεξάμενος δ’ αὐτῶν τοὺς ἀρίστους, ἐς ἑπτακισμυρίους πεζοὺς καὶ ἱππέας ἡμίσεας, τοὺς μὲν ἄλλους ἀπέλυσε, τοὺς δ’ ἐς ἴλας τε καὶ σπείρας ἀγχοτάτω τῆς Ἰταλικῆς συντάξεως καταλέγων Ποντικοῖς ἀνδράσι γυμνάζειν παρεδίδου. προσιόντος δ’ αὐτοῖς τοῦ Λευκόλλου, ὁ μὲν Μιθριδάτης τὸ πεζὸν ἅπαν καὶ μέρος τι τῶν ἱππέων ἐπὶ λόφου συνεῖχε, τῇ λοιπῇ δ’ ἵππῳ Τιγράνης τοῖς σιτολογοῦσι Ῥωμαίοις περιπεσὼν ἡσσᾶτο. καὶ μᾶλλον ἀδεῶς ἀπὸ τοῦδε οἱ Ῥωμαῖοι πλησίον αὐτοῦ Μιθριδάτου ἐσιτολόγουν τε καὶ ἐστρατοπέδευον. κονιορτὸς δ’ αὖθις ἠγείρετο πολὺς ὡς ἐπιόντος τοῦ Τιγράνους· καὶ τὸ ἐνθύμημα ἦν ἐν μέσῳ Λεύκολλον ἀμφοῖν γενέσθαι. ὁ δ’ αἰσθόμενος τοὺς μὲν ἀρίστους τῶν ἱππέων προύπεμψε πορρωτάτω συμπλέκεσθαι τῷ Τιγράνῃ καὶ κωλύειν αὐτὸν ἐξ ὁδοιπορίας ἐς τάξιν καθίστασθαι, αὐτὸς δὲ τὸν Μιθριδάτην προκαλούμενος ἐς μάχην … καὶ περιταφρεύων οὐκ ἠρέθιζεν, ἕως χειμὼν ἐπιπεσὼν διέλυσε τὸ ἔργον ἅπασιν.", "st": "5.87"}, {"sp": "N", "t": "καὶ Τιγράνης μὲν ἐξ ὅλης Ἀρμενίας ἐς τὰ ἐντὸς ἀνεζεύγνυεν, ὁ δὲ Μιθριδάτης ἐς τὸν Πόντον ἐπὶ τὰ λοιπὰ τῆς ἰδίας ἀρχῆς ἠπείγετο, τετρακισχιλίους οἰκείους ἔχων, καὶ τοσούσδε ἑτέρους παρὰ Τιγράνους λαβών. ἐφείπετο δ’ αὐτῷ καὶ ὁ Λεύκολλος, ἀναζευγνὺς καὶ ὅδε διὰ τὴν ἀπορίαν. φθάσας δ’ αὐτὸν ὁ Μιθριδάτης ἐπέθετο Φαβίῳ τῷ δεῦρο ἐκ Λευκόλλου στρατηγεῖν ὑπολελειμμένῳ, καὶ τρεψάμενος αὐτὸν ἔκτεινε πεντακοσίους. ἐλευθερώσαντος δὲ τοῦ Φαβίου θεράποντας ὅσοι ἦσαν ἐν τῷ στρατοπέδῳ, καὶ δι’ ὅλης ἡμέρας αὖθις ἀγωνιζομένου, παλίντροπος ἦν ὁ ἀγών, μέχρι τὸν Μιθριδάτην, πληγέντα λίθῳ τε ἐς τὸ γόνυ καὶ ὑπὸ τὸν ὀφθαλμὸν βέλει, κατὰ σπουδὴν ἀποκομισθῆναι, καὶ πολλὰς ἡμέρας τοὺς μὲν φόβῳ τοῦ βασιλέως τῆς σωτηρίας, τοὺς δὲ ὑπὸ πλήθους τραυμάτων ἠρεμῆσαι. Μιθριδάτην μὲν οὖν ἐθεράπευον Ἄγαροι, Σκυθικὸν ἔθνος, ἰοῖς ὄφεων ἐς τὰς θεραπείας χρώμενοι καὶ ἐπὶ τῷδε ἀεὶ βασιλεῖ συνόντες· Φαβίῳ δὲ Τριάριος, ἕτερος Λευκόλλου στρατηγός, ἐπελθὼν μετ’ οἰκείου στρατοῦ, τήν τε ἀρχὴν παρὰ τοῦ Φαβίου καὶ τὸ ἀξίωμα παρελαμβανεν. καὶ μετ’ οὐ πολὺ χωρούντων ἐς μάχην αὐτοῦ τε καὶ Μιθριδάτου, πνεῦμα, οἷον οὐκ ἐμνημονεύετο γενέσθαι, τάς τε σκηνὰς ἀμφοτέρων διέρριψε καὶ τὰ ὑποζύγια παρέσυρε καὶ τῶν ἀνδρῶν ἔστιν οὓς κατεκρήμνισεν.", "st": "5.88"}, {"sp": "N", "t": "καὶ τότε μὲν ἀνεχώρουν ἑκάτεροι, ἀπαγγελλομένου δὲ Λευκόλλου προσιέναι, προλαβεῖν τὸ ἔργον ὁ Τριάριος ἐπειγόμενος ἔτι νυκτὸς ἐπεχείρει ταῖς Μιθριδάτου προφυλακαῖς. ἰσομάχου δ’ ἐς πολὺ τοῦ ἀγῶνος ὄντος, ὁ βασιλεὺς ἐς τὸ καθ’ αὑτὸν μέρος ἐπιβαρήσας ἔκρινε τὴν μάχην, καὶ διασπάσας τοὺς πολεμίους τὸ πεζὸν αὐτῶν κατέκλεισεν ἐς διώρυχα πηλοῦ, ἔνθα διεφθείροντο στῆναι μὴ δυνάμενοι. τοὺς δ’ ἱππέας ἀνὰ τὸ πεδίον ἐδίωκεν, ἐκθύμως τῇ φορᾷ τῆς εὐτυχίας καταχρώμενος, ἔστε τις αὐτὸν Ῥωμαῖος λοχαγός, οἷα θεράπων αὐτῷ συντροχάζων, ἐς τὸν μηρὸν ἐπάταξε ξίφει πληγὴν βαθεῖαν, οὐκ ἐλπίσας ἐς τὰ νῶτα διὰ τοῦ θώρακος ἐφίξεσθαι. καὶ τόνδε μὲν εὐθὺς οἱ πλησίον συνέκοπτον, ὁ δὲ Μιθριδάτης ἀπεφέρετο ὀπίσω, καὶ οἱ φίλοι τὴν στρατιὰν ἀπὸ νίκης λαμπρᾶς ἀνεκάλουν σὺν ἐπείξει βαρείᾳ. ἐνέπιπτε δὲ τοῖς μαχομένοις ἐπὶ τῷ παραλόγῳ τῆς ἀνακλήσεως θόρυβός τε καὶ ἀπορία, μή τι δεινὸν ἑτέρωθεν εἴη, μέχρι μαθόντες εὐθὺς ἐν τῷ πεδίῳ τὸ σῶμα περιίσταντο καὶ ἐθορύβουν, ἕως Τιμόθεος αὐτοῖς ὁ ἰατρός, ἐπισχὼν τὸ αἷμα, ἐπέδειξεν αὐτὸν ἐκ μετεώρου, οἷόν τι καὶ Μακεδόσιν ἐν Ἰνδοῖς, ὑπὲρ Ἀλεξάνδρου δεδιόσιν, ὁ Ἀλέξανδρος αὑτὸν ἐπὶ νεῶς θεραπευόμενον ἐπέδειξεν. ὁ δὲ Μιθριδάτης ὡς ἀνήνεγκεν, αὐτίκα τοῖς ἀνακαλέσασιν ἐκ τῆς μάχης κατεμέμφετο, καὶ τὸν στρατὸν αὐτῆς ἡμέρας ἦγεν αὖθις ἐπὶ τὸ Ῥωμαίων στρατόπεδον. οἱ δὲ καὶ ἐκ τοῦδε ἐπεφεύγεσαν ἤδη σὺν δέει. σκυλευομένων δὲ τῶν νεκρῶν ἐφαίνοντο χιλίαρχοι μὲν εἴκοσι καὶ τέσσαρες, ἑκατόνταρχοι δὲ πεντήκοντα καὶ ἑκατόν, ὅσον ἡγεμόνων πλῆθος οὐ ῥᾳδίως συνέπεσε Ῥωμαίοις ἐν ἥττῃ μιᾷ.", "st": "5.89"}, {"sp": "N", "t": "ὁ δὲ Μιθριδάτης ἐς Αρμενίαν, ἣν δὴ νῦν Ῥωμαῖοι βραχυτέραν Ἀρμενίαν καλοῦσιν, ἀνεζεύγνυ, τὰ μὲν εὐκόμιστα πάντα σιτολογῶν, τὰ δὲ δυσχερῆ διαφθείρων τε καὶ Λεύκολλον ἐπιόντα προαφαιρούμενος. καί τις ἀνὴρ Ῥωμαῖος, ἀπὸ βουλῆς, Ἀττίδιος ὄνομα, διὰ δίκην φυγὼν ἐκ τῆς πατρίδος ἐς Μιθριδάτην πρὸ πολλοῦ καὶ φιλίας ἀξιούμενος, ἑάλω τότε ἐπιβουλεύων αὐτῷ. καὶ τόνδε μὲν ὁ βασιλεὺς οὐ δικαιῶν βασανίσαι, Ῥωμαίων ποτὲ βουλευτὴν γενόμενον, ἔκτεινε, τοὺς δὲ συναμαρτόντας ᾐκίσατο δεινῶς. ἀπελεύθεροι δ’ ὅσοι τῷ Ἀττιδίῳ συνεγνώκεσαν, ἀπαθεῖς ἀφῆκεν ὡς δεσπότῃ διακονησαμένους. Λευκόλλου δ’ ἤδη τῷ Μιθριδάτῃ παραστρατοπεδεύοντος, ὁ τῆς Ἀσίας στρατηγὸς περιπέμπων ἐκήρυσσε Ῥωμαίους ἐπικαλεῖν Λευκόλλῳ πέρα τοῦ δέοντος πολεμοῦντι, καὶ τοὺς ὑπ’ αὐτῷ τῆς στρατείας ἀφιέναι, καὶ τῶν οὐ πειθομένων τὰ ὄντα δημεύσειν. ὧν ἐξαγγελθέντων ὁ στρατὸς αὐτίκα διελύετο, χωρὶς ὀλίγων. ὅσοι πάνυ πένητες ὄντες καὶ τὴν ζημίαν οὐ δεδιότες τῷ Λευκόλλῳ παρέμενον.", "st": "5.90"}, {"sp": "N", "t": "ὧδε μὲν δὴ καὶ ὁ Λευκόλλου πρὸς Μιθριδάτην πόλεμος ἐς οὐδὲν βέβαιον οὐδὲ κεκριμένον τέλος ἔληξεν· ἀφισταμένης γὰρ τῆς Ἰταλίας ἐνοχλούμενοι, καὶ λῃστευομένης τῆς θαλάσσης λιμῷ πιεζόμενοι, οὐκ ἐν καιρῷ σφίσιν ἡγοῦντο πολεμεῖν ἄλλον τοσόνδε πόλεμον, πρὶν τὰ ἐνοχλοῦντα διαθέσθαι. ὧν καὶ ὁ Μιθριδάτης αἰσθανόμενος ἐς Καππαδοκίαν ἐσέβαλε καὶ τὴν ἰδίαν ἀρχὴν ὠχύρου. καὶ τάδε αὐτὸν πράσσοντα οἱ Ῥωμαῖοι περιεώρων ἐφ’ ὅσον αὐτοῖς ἡ θάλασσα ἐκαθαίρετο. ὡς δ’ ἐκεκάθαρτο καὶ ὁ καθήρας Πομπήιος ἔτι ἦν ἐν Ἀσίᾳ, τὸν Μιθριδάτειον πόλεμον ἀνελάμβανον αὐτίκα, καὶ ἐπέστελλον καὶ τοῦδε τῷ Πομπηίῳ στρατηγῆσαι. διό μοι δοκεῖ μέρος ὄντα τῆς Πομπηίου στρατείας τὰ περὶ τὴν θάλασσαν αὐτῷ πρὸ Μιθριδάτου κατειργασμένα, καὶ ἐς οὐδεμίαν συγγραφὴν οἰκείαν ἄλλην ἀπαντῶντα, ἐς τόδε τὸ μέρος συναγαγεῖν τε καὶ ἐπιδραμεῖν, ὡς ἐγένετο.", "st": "5.91"}, {"sp": "N", "t": "Μιθριδάτης ὅτε πρῶτον Ῥωμαίοις ἐπολέμει καὶ τῆς Ἀσίας ἐκράτει, Σύλλα περὶ τὴν Ἑλλάδα πονουμένου, ἡγούμενος οὐκ ἐς πολὺ καθέξειν τῆς Ἀσίας, τά τε ἄλλα, ὥς μοι προείρηται, πάντα ἐλυμαίνετο, καὶ ἐς τὴν θάλασσαν πειρατὰς καθῆκεν, οἳ τὸ μὲν πρῶτον ὀλίγοις σκάφεσι καὶ μικροῖς οἷα λῃσταὶ περιπλέοντες ἐλύπουν, ὡς δὲ ὁ πόλεμος ἐμηκύνετο, πλέονες ἐγίγνοντο καὶ ναυσὶ μεγάλαις ἐπέπλεον. γευσάμενοι δὲ κερδῶν μεγάλων, οὐδ’ ἡττωμένου καὶ σπενδομένου τοῦ Μιθριδάτου καὶ ἀναχωροῦντος ἔτι ἐπαύοντο· οἱ γὰρ βίου καὶ πατρίδων διὰ τὸν πόλεμον ἀφῃρημένοι, καὶ ἐς ἀπορίαν ἐμπεσόντες ἀθρόαν, ἀντὶ τῆς γῆς ἐκαρποῦντο τὴν θάλασσαν, μυοπάρωσι πρῶτον καὶ ἡμιολίαις, εἶτα δικρότοις καὶ τριήρεσι κατὰ μέρη περιπλέοντες, ἡγουμένων λῃστάρχων οἷα πολέμου στρατηγῶν. ἔς τε ἀτειχίστους πόλεις ἐμπίπτοντες, καὶ ἑτέρων τὰ τείχη διορύττοντες ἢ κόπτοντες ἢ πολιορκίᾳ λαμβάνοντες, ἐσύλων· καὶ τοὺς ἄνδρας, οἷς τι πλέον εἴη, ἐς ναυλοχίαν ἐπὶ λύτροις ἀπῆγον. καὶ τάδε τὰ λήμματα, ἀδοξοῦντες ἤδη τὸ τῶν λῃστῶν ὄνομα, μισθοὺς ἐκάλουν στρατιωτικούς. χειροτέχνας τε εἶχον ἐπ’ ἔργοις δεδεμένους, καὶ ὕλην ξύλου καὶ χαλκοῦ καὶ σιδήρου συμφέροντες οὔποτε ἐπαύοντο· ἐπαιρόμενοι γὰρ ὑπὸ τοῦ κέρδους, καὶ τὸ λῃστεύειν οὐκ ἐγνωκότες ἔτι μεθεῖναι, βασιλεῦσι δ’ ἤδη καὶ τυράννοις ἢ στρατοπέδοις μεγάλοις ἑαυτοὺς ὁμοιοῦντες, καὶ νομίζοντες, ὅτε συνέλθοιεν ἐς τὸ αὐτὸ πάντες, ἄμαχοι γενήσεσθαι, ναῦς τε καὶ ὅπλα πάντα ἐτεκταίνοντο, μάλιστα περὶ τὴν τραχεῖαν λεγομένην Κιλικίαν, ἣν κοινὸν σφῶν ὕφορμον ἢ στρατόπεδον ἐτίθεντο εἶναι, φρούρια μὲν καὶ ἄκρας καὶ νήσους ἐρήμους καὶ ναυλοχίας ἔχοντες πολλαχοῦ, κυριωτάτας δὲ ἀφέσεις ἡγούμενοι τὰς περὶ τήνδε τὴν Κιλικίαν, τραχεῖάν τε καὶ ἀλίμενον οὖσαν καὶ κορυφαῖς μεγάλαις ἐξέχουσαν. ὅθεν δὴ καὶ πάντες ὀνόματι κοινῷ Κίλικες ἐκαλοῦντο, ἀρξαμένου μὲν ἴσως τοῦ κακοῦ παρὰ τῶν Τραχεωτῶν Κιλίκων, συνεπιλαβόντων δὲ Σύρων τε καὶ Κυπρίων καὶ Παμφύλων καὶ τῶν Ποντικῶν καὶ σχεδὸν ἁπάντων τῶν ἑῴων ἐθνῶν οἳ πολλοῦ καὶ χρονίου σφίσιν ὄντος τοῦ Μιθριδατείου πολέμου δρᾶν τι μᾶλλον ἢ πάσχειν αἱρούμενοι τὴν θάλασσαν ἀντὶ τῆς γῆς ἐπελέγοντο,", "st": "5.92"}, {"sp": "N", "t": "ὥστε πολλαὶ τάχιστα αὐτῶν μυριάδες ἦσαν, καὶ οὐ μόνης ἔτι τῆς ἑῴας θαλάσσης ἐκράτουν, ἀλλὰ καὶ τῆς ἐντὸς Ἡρακλείων στηλῶν ἁπάσης· καὶ γάρ τινας ἤδη Ῥωμαίων στρατηγοὺς ναυμαχίᾳ ἐνενικήκεσαν, ἄλλους τε καὶ τὸν τῆς Σικελίας περὶ αὐτῇ Σικελίᾳ. ἄπλωτά τε ἤδη πάντα ἦν, καὶ ἡ γῆ τῶν ἔργων ἐνδεὴς διὰ τὴν ἀνεπιμιξίαν. ἥ τε πόλις ἡ Ῥωμαίων ᾔσθετο μάλιστα τοῦ κακοῦ, τῶν τε ὑπηκόων σφίσι καμνόντων, καὶ αὐτοὶ διὰ πλῆθος ἴδιον ἐπιπόνως λιμώττοντες. τὸ δ’ ἔργον αὐτοῖς ἐφαίνετο μέγα καὶ δυσχερές, ἐξελεῖν τοσάδε στρατόπεδα ἀνδρῶν ναυτικῶν, μεμερισμένα μὲν ἐς πᾶσαν ἐν κύκλῳ γῆν καὶ θάλασσαν, κοῦφα δὲ ταῖς κατασκευαῖς ἐς τὸ ὑποφεύγειν, οὐκ ἐκ πατρίδων ἢ φανερᾶς χώρας ὁρμώμενα, οὐδ’ οἰκεῖον οὐδὲν ἢ ἴδιον ἀλλ’ ἀεὶ τὸ προστυχὸν ἔχοντα. ὥστε πολὺς ὢν ὁ τοῦδε τοῦ πολέμου παράλογος, ἔννομον οὐδὲν ἔχοντος οὐδὲ βέβαιον οὐδὲ φανερόν, ἀμηχανίαν ὁμοῦ καὶ φόβον εἰργάζετο. Μουρήνας τε ἐγχειρήσας αὐτοῖς οὐδὲν ἐξείργαστο μέγα. ἀλλ’ οὐδὲ Σερουίλιος Ἰσαυρικὸς ἐπὶ τῷ Μουρήνᾳ, ἀλλ’ ἤδη καὶ τῆς γῆς τῆς Ἰταλικῆς τοῖς παραλίοις, ἀμφί τε τὸ Βρεντέσιον καὶ τὴν Τυρρηνίαν, ἐπέβαινον οἱ λῃσταὶ σὺν καταφρονήσει, καὶ γύναια παροδεύοντα τῶν εὐπατριδῶν καὶ δύο στρατηγοὺς αὐτοῖς σημείοις συνηρπάκεσαν.", "st": "5.93"}, {"sp": "N", "t": "ὧν οὔτε τὴν βλάβην οὔτε τὴν αἰσχύνην ἔτι φέροντες οἱ Ῥωμαῖοι τὸν τότε σφῶν ἐπὶ δόξης ὄντα μεγίστης Γναῖον Πομπήιον αἱροῦνται νόμῳ στρατηγὸν ἐπὶ τριετὲς αὐτοκράτορα εἶναι θαλάσσης τε ἁπάσης ἣ στηλῶν Ἡρακλείων ἐντός ἐστι, καὶ γῆς ἀπὸ θαλάσσης ἐπὶ σταδίους τετρακοσίους ἄνω. βασιλεῦσί τε καὶ δυνάσταις καὶ ἔθνεσι καὶ πόλεσι πάσαις ἐπέστελλον ἐς πάντα συλλαμβάνειν τῷ Πομπηίῳ, καὶ αὐτῷ στρατιὰν καταλέγειν ἔδοσαν καὶ χρήματα ἀγείρειν. συνέπεμψαν δὲ καὶ παρὰ σφῶν στρατὸν πολὺν ἐκ καταλόγου, καὶ ναῦς ὅσας εἶχον, καὶ χρημάτων ἐς ἑξακισχίλια τάλαντα Ἀττικά. οὕτω μέγα καὶ δυσεργὲς ἡγοῦντο εἶναι τοσῶνδε κρατῆσαι στρατοπέδων, ἐν τοσῇδε θαλάσσῃ καὶ μυχοῖς τοσοῖσδε διαλανθανόντων τε εὐμαρῶς καὶ ὑποχωρούντων ῥᾳδίως καὶ ἐμπιπτόντων αὖθις ἀφανῶς. ἀνήρ τε οὐδείς πω πρὸ τοῦ Πομπηίου ἐπὶ τοσήνδε ἀρχὴν αἱρεθεὶς ὑπὸ Ῥωμαίων ἐξέπλευσεν, ᾧ στρατιὰ μὲν αὐτίκα ἦν ἐν δώδεκα μυριάσι πεζῶν καὶ ἱππεῖς τετρακισχίλιοι, νῆες δὲ σὺν ἡμιολίαις ἑβδομήκοντα καὶ διακόσιαι, ὑπηρέται δ’ ἀπὸ τῆς βουλῆς, οὓς καλοῦσι πρεσβευτάς, πέντε καὶ εἴκοσιν· οἷς ὁ Πομπήιος ἐπιδιῄρει τὴν θάλασσαν, καὶ ναῦς ἐδίδου καὶ ἱππέας ἑκάστῳ καὶ στρατὸν πεζόν, καὶ στρατηγίας σημεῖα περικεῖσθαι, ἵν’ αὐτοκράτωρ ἐντελὴς οὗ πιστεύοιτο μέρους ἕκαστος ὑπάρχοι, αὐτὸς δ’, οἷα δὴ βασιλεὺς βασιλέων, αὐτοὺς περιθέοι καὶ ἐφορῴη μένοντας ἐφ’ ὧν ἐτάχθησαν, μηδὲ μεταδιώκων τοὺς λῃστὰς περιφέροιτο ἐξ ἔργων ἀτελῶν ἔτι ὄντων ἐς ἕτερα, ἀλλ’ εἶεν οἱ πανταχόθεν αὐτοῖς ἀπαντῶντές τε καὶ τὰς ἐς ἀλλήλους διαδρομὰς ἀποκλείοντες.", "st": "5.94"}, {"sp": "N", "t": "οὕτω διαθεὶς ὁ Πομπήιος ἅπαντα, ἐπέστησεν Ἰβηρίᾳ μὲν καὶ ταῖς Ἡρακλείοις στήλαις Τιβέριον Νέρωνα καὶ Μάλλιον Τορκουᾶτον, ἀμφὶ δὲ τὴν Λιγυστικήν τε καὶ Κελτικὴν θάλασσαν Μᾶρκον Πομπώνιον, Λιβύῃ δὲ καὶ Σαρδόνι καὶ Κύρνῳ, καὶ ὅσαι πλησίον νῆσοι, Λέντλον τε Μαρκελλῖνον καὶ Πόπλιον Ἀτίλιον, περὶ δὲ αὐτὴν Ἰταλίαν Λεύκιον Γέλλιον καὶ Γναῖον Λέντλον. Σικελίαν δὲ καὶ τὸν Ἰόνιον ἐφύλασσον αὐτῷ Πλώτιός τε Οὐᾶρος καὶ Τερέντιος Οὐάρρων μέχρι Ἀκαρνανίας, Πελοπόννησον δὲ καὶ τὴν Ἀττικήν, ἔτι δ’ Εὔβοιαν καὶ Θεσσαλίαν καὶ Μακεδονίαν καὶ Βοιωτίαν Λεύκιος Σισιννᾶς, τὰς δὲ νήσους καὶ τὸ Αἰγαῖον ἅπαν καὶ τὸν Ἑλλήσποντον ἐπ’ ἐκείνῳ Λεύκιος Λόλλιος, Βιθυνίαν δὲ καὶ Θρᾴκην καὶ τὴν Προποντίδα καὶ τὸ τοῦ Πόντου στόμα Πούπλιος Πείσων, Λυκίαν δὲ καὶ Παμφυλίαν καὶ Κύπρον καὶ Φοινίκην Μέτελλος Νέπως. ὧδε μὲν αὐτῷ διετετάχατο οἱ στρατηγοὶ ἐπιχειρεῖν τε καὶ ἀμύνεσθαι, καὶ φυλάσσειν τὰ τεταγμένα, καὶ τοὺς παρ’ ἀλλήλων ἐκφεύγοντας ὑπολαμβάνειν, ἵνα μὴ διώκοντες ἀφίσταιντο μακράν, μηδὲ ὡς ἐν δρόμῳ περιφέροιντο, καὶ χρόνιον εἴη τὸ ἔργον, αὐτὸς δ’ ἅπαντας ἐπέπλει. καὶ τὰ ἐς δύσιν πρῶτα ἡμέραις τεσσαράκοντα ἐπιδὼν ἐς Ῥώμην παρῆλθεν. ὅθεν ἐς Βρεντέσιον, καὶ ἐκ Βρεντεσίου τοσῷδε διαστήματι τὴν ἕω περιπλεύσας, ἐξέπληξεν ἅπαντας τάχει τε ἐπίπλου καὶ μεγέθει παρασκευῆς καὶ φόβῳ δόξης, ὥστε τοὺς λῃστὰς ἐλπίσαντας αὐτῷ προεπιχειρήσειν, ἢ οὐκ εὐμαρές γε τὸ κατὰ σφῶν ἔργον ἀποδείξειν, δείσαντας εὐθὺς τῶν τε πόλεων ἃς ἐπολιόρκουν ἐξαναχθῆναι, καὶ ἐς τὰς συνήθεις ἄκρας καὶ ναυλοχίας ὑποφεύγειν, καὶ Πομπηίῳ τὴν μὲν θάλασσαν αὐτίκα ἀμαχὶ κεκαθάρθαι, τοὺς δὲ λῃστὰς ὑπὸ τῶν στρατηγῶν ἁλίσκεσθαι πανταχοῦ κατὰ μέρη.", "st": "5.95"}, {"sp": "N", "t": "αὐτὸς δὲ ἐς Κιλικίαν ἠπείγετο μετὰ ποικίλου στρατοῦ καὶ μηχανημάτων πολλῶν, ἐλπίσας παντοίας μάχης καὶ πολιορκίας αὐτῷ δεήσειν ἐπὶ ἄκρας ἀποκρήμνους. οὐδενὸς δὲ ἐδέησε· τὸ γὰρ κλέος αὐτοῦ καὶ τὴν παρασκευὴν οἱ λῃσταὶ καταπλαγέντες, καὶ ἐλπίσαντες, εἰ μὴ διὰ μάχης ἔλθοιεν, τεύξεσθαι φιλανθρώπου, πρῶτοι μὲν οἳ Κράγον καὶ Ἀντίκραγον εἶχον, φρούρια μέγιστα, μετὰ δ’ ἐκείνους οἱ ὄρειοι Κίλικες καὶ ἐφεξῆς ἅπαντες ἑαυτοὺς ἐνεχείρισαν, ὅπλα τε ὁμοῦ πολλά, τὰ μὲν ἕτοιμα τὰ δὲ χαλκευόμενα, παρέδωκαν, καὶ ναῦς τὰς μὲν ἔτι πηγνυμένας τὰς δ’ ἤδη πλεούσας, χαλκόν τε καὶ σίδηρον ἐς ταῦτα συνενηνεγμένον καὶ ὀθόνας καὶ κάλως καὶ ὕλην ποικίλην, αἰχμαλώτων τε πλῆθος, τῶν μὲν ἐπὶ λύτροις τῶν δὲ ἐπὶ ἔργοις δεδεμένων. ὧν ὁ Πομπήιος τὴν μὲν ὕλην ἐνέπρησε, τὰς δὲ ναῦς ἀπήγαγε, τοὺς δ’ αἰχμαλώτους ἐς τὰς πατρίδας ἀφῆκε· καὶ πολλοὶ κενοτάφια σφῶν κατέλαβον ὡς ἐπὶ νεκροῖς γενόμενα. τοὺς δὲ πειρατὰς οἳ μάλιστα ἐδόκουν οὐχ ὑπὸ μοχθηρίας ἀλλ’ ἀπορίᾳ βίου διὰ τὸν πόλεμον ἐπὶ ταῦτα ἐλθεῖν, ἐς Μαλλὸν καὶ Ἄδανα καὶ Ἐπιφάνειαν, ἢ εἴ τι ἄλλο πόλισμα ἔρημον ἢ ὀλιγάνθρωπον ἦν τῆσδε τῆς τραχείας Κιλικίας, συνῴκιζε· τοὺς δέ τινας αὐτῶν καὶ ἐς Δύμην τῆς Ἀχαΐας ἐξέπεμπεν. ὧδε μὲν ὁ λῃστρικὸς πόλεμος, χαλεπώτατος ἔσεσθαι νομισθείς, ὀλιγήμερος ἐγένετο τῷ Πομπηίῳ· καὶ ναῦς ἔλαβε τὰς μὲν ἁλούσας μίαν καὶ ἑβδομήκοντα, τὰς δὲ ὑπ’ αὐτῶν παραδοθείσας ἓξ καὶ τριακοσίας, πόλεις δὲ καὶ φρούρια καὶ ὁρμητήρια ἄλλα αὐτῶν ἐς εἴκοσι καὶ ἑκατόν. λῃσταὶ δ’ ἀνῃρέθησαν ἐν ταῖς μάχαις ἀμφὶ τοὺς μυρίους.", "st": "5.96"}, {"sp": "N", "t": "ἐπὶ δὴ τούτοις ὀξέως τε οὕτω καὶ παραδόξως γενομένοις οἱ Ῥωμαῖοι τὸν Πομπήιον μέγα ἐπαίροντες, ἔτι ὄντα περὶ Κιλικίαν εἵλοντο τοῦ πρὸς Μιθριδάτην πολέμου στρατηγὸν ἐπὶ τῆς ὁμοίας ἐξουσίας, αὐτοκράτορα ὄντα, ὅπῃ θέλοι, συντίθεσθαί τε καὶ πολεμεῖν, καὶ φίλους ἢ πολεμίους Ῥωμαίοις οὓς δοκιμάσειε ποιεῖσθαι· στρατιᾶς τε πάσης, ὅση πέραν ἐστὶ τῆς Ἰταλίας, ἄρχειν ἔδωκαν. ἅπερ οὐδενί πω παντάπασι πρὸ τοῦδε ὁμοῦ πάντα ἐδόθη. καὶ ἴσως αὐτὸν καὶ διὰ τάδε μέγαν ὀνομάζουσιν· ὁ γάρ τοι πόλεμος ὁ τοῦ Μιθριδάτου καὶ ὑπὸ τῶν προτέρων στρατηγῶν ἐξήνυστο ἤδη.", "st": "5.97"}, {"sp": "N", "t": "Πομπήιος μὲν οὖν εὐθὺς ἐκ τῆς Ἀσίας στρατὸν ἀγείρας μετεστρατοπέδευσεν ἐπὶ τοὺς ὅρους τοῦ Μιθριδάτου· Μιθριδάτῃ δὲ ἦν ἐπίλεκτος οἰκεῖος στρατός, τρισμύριοι πεζοὶ καὶ ἱππεῖς τρισχίλιοι, καὶ προὐκάθητο τῆς χώρας. ἄρτι δ’ αὐτὴν Λευκόλλου διεφθαρκότος ἀπόρως εἶχεν ἀγορᾶς· ὅθεν αὐτομολίαις ἐπετίθεντο πολλοί. καὶ τούσδε μὲν ὁ Μιθριδάτης ἐρευνώμενος ἐκρήμνη καὶ ὀφθαλμοὺς ἀνώρυττε καὶ ἔκαιεν. καὶ τὰ μὲν τῶν αὐτομολιῶν ἧσσον ἠνώχλει διὰ φόβον τῶν κολάσεων, ἐπέτριβε δ’ ἡ ἀπορία.", "st": "5.97"}, {"sp": "N", "t": "πρέσβεις οὖν ἐς Πομπήιον πέμψας ἠξίου μαθεῖν, τίς ἂν εἴη τοῦ πολέμου διάλυσις. ὁ δ’ “ἐὰν τοὺς αὐτομόλους ἡμῖν παραδῷς” ἔφη, “καὶ σεαυτὸν ἡμῖν ἐπιτρέψῃς.” ὧν ὁ Μιθριδάτης πυθόμενος τοῖς αὐτομόλοις τὸ περὶ αὐτῶν ἔφρασε, καὶ δεδιότας ὁρῶν ὤμοσεν ὅτι οἱ τὰ πρὸς Ῥωμαίους ἐστὶν ἄσπονδα διὰ τὴν πλεονεξίαν αὐτῶν, καὶ οὐκ ἐκδώσει τινά, οὐδὲ πράξει ποτὲ ὃ μὴ κοινῇ πᾶσι συνοίσει. ὁ μὲν δὴ ὧδε εἶπεν, ὁ δὲ Πομπήιος ἐνέδραν ποι καθεὶς ἱππέων, ἑτέρους ἔπεμπεν ἐκ φανεροῦ τοῖς προφύλαξι τοῦ βασιλέως ἐνοχλεῖν· καὶ εἴρητο αὐτοῖς … ἐρεθίζειν καὶ ὑποφεύγειν ὥσπερ ἡττωμένους, … ἔστε περ οἱ ἐκ τῆς ἐνέδρας περιλαβόντες αὐτοὺς ἐτρέψαντο. καὶ φεύγουσι τάχ’ ἂν καὶ ἐς τὸ στρατόπεδον συνεσεπήδησαν, εἰ μὴ δείσας ὁ βασιλεὺς προήγαγε τὸ πεζόν. οἱ δ’ ἀπεχώρουν. καὶ τέλος ἦν τοῦτο τῇ πρώτῃ Πομπηίου καὶ Μιθριδάτου πείρᾳ ἐς ἀλλήλους καὶ ἱππομαχίᾳ.", "st": "5.98"}, {"sp": "N", "t": "ἐνοχλούμενος δ’ ὑπὸ τῆς ἀπορίας ὁ βασιλεὺς ἄκων ὑπεχώρει, καὶ ἐσεδέχετο Πομπήιον ἐς τὴν ἑαυτοῦ, ἐλπίζων καθήμενον ἐν τῇδε τῇ διεφθαρμένῃ κακοπαθήσειν. ὁ δὲ ἀγορὰν μὲν ἐπακτὸν ἐκ τῶν ὄπισθεν εἶχε, περιελθὼν δὲ τὰ πρὸς ἕω τοῦ Μιθριδάτου, καὶ φρούρια αὐτῷ καὶ στρατόπεδα πολλὰ ἐς ἑκατὸν καὶ πεντήκοντα σταδίους περιθεὶς ἀπετάφρευε τοῦ μὴ σιτολογεῖν αὐτὸν ἔτι εὐμαρῶς. καὶ ὁ βασιλεὺς ἀποταφρεύοντι μὲν οὐκ ἐπετίθετο, εἴθ’ ὑπὸ δέους εἴθ’ ὑπ’ ἀνοίας, ἣ νᾶσιν ἐγγίγνεται πλησιαζόντων τῶν κακῶν, κάμνων δ’ αὖθις ἐξ ἀπορίας τὰ ὑποζύγια ὅσα εἶχε κατέκοπτε, τοὺς ἵππους μόνους περιποιούμενος, ἔστε μόλις ἐς πεντήκοντα διαρκέσας ἡμέρας νυκτὸς ἀπεδίδρασκε σὺν σιωπῇ βαθείᾳ δι’ ὁδῶν δυσχερῶν. ὡς δὲ αὐτὸν μόλις ἡμέρας ὁ Πομπήιος καταλαβὼν εἴχετο τῶν ὑστάτων, ὁ μὲν καὶ τότε τῶν φίλων ἐκτάξαι κελευόντων οὐκ ἐμάχετο, ἀλλὰ τοῖς ἱππεῦσι μόνοις τοὺς πλησιάζοντας ἀνακόπτων ἑσπέρας ἐν ὕλαις ηὐλίσατο πυκναῖς. τῇ δ’ ἐπιούσῃ χωρίον κατέλαβε περίκρημνον, οὗ μία ἐς αὐτὸ ἄνοδος ἦν, καὶ τέσσαρες αὐτὴν σπεῖραι προὐφύλασσον. ἀντεφύλασσον δὲ καὶ Ῥωμαῖοι μὴ διαφυγεῖν Μιθριδάτην.", "st": "5.99"}, {"sp": "N", "t": "ἅμα δ’ ἡμέρᾳ τὸν μὲν στρατὸν αὑτῶν ὥπλιζεν ἑκάτερος, οἱ προφύλακες δ’ ἀλλήλων κατὰ τὸ πρανὲς ἀπεπειρῶντο· καί τινες ἱππεῖς τοῦ Μιθριδάτου χωρίς τε τῶν ἵππων καὶ χωρὶς ἐπαγγέλματος ἐβοήθουν τοῖς σφετέροις προφύλαξιν. πλειόνων δέ σφισι Ῥωμαίων ἱππέων ἐπιόντων, οἱ ἄνιπποι τῶν Μιθριδατείων οἵδε ἀθρόως ἐς τὸ στρατόπεδον ἀνεπήδων, ἀναβησόμενοί τε τοὺς ἵππους καὶ ἐξ ἴσου τοῖς ἐπιοῦσι Ῥωμαίοις συνοισόμενοι. κατιδόντες δ’ αὐτοὺς οἱ ἄνω ἔτι ὁπλιζόμενοι σὺν δρόμῳ καὶ βοῇ προσθέοντας, καὶ τὸ γιγνόμενον οὐκ εἰδότες ἀλλὰ φεύγειν αὐτοὺς ὑπολαβόντες, ὡς εἰλημμένου σφῶν ἤδη καθ’ ἑκάτερα τοῦ στρατοπέδου, τὰ ὅπλα μεθέντες ἔφευγον. ἀδιεξόδου δ’ ὄντος τοῦ χωρίου προσέπταιον ἀλλήλοις ἀναστρεφόμενοι, μέχρι καθήλαντο κατὰ τῶν κρημνῶν. οὕτω μὲν ἡ στρατιὰ τῷ Μιθριδάτῃ διὰ προπέτειαν τῶν ἄνευ προστάγματος τοῖς προμάχοις ἐπικουρεῖν ἑλομένων θορυβηθεῖσα διέφθαρτο, καὶ τὸ λοιπὸν ἔργον εὔκολον ἦν τῷ Πομπηίῳ, κτείνοντι καὶ συλλαμβάνοντι ἀνόπλους ἔτι καὶ ἐν περικρήμνῳ συγκεκλεισμένους. καὶ ἀνῃρέθησαν ἐς μυρίους, καὶ τὸ στρατόπεδον ὅλῃ τῇ παρασκευῇ κατελήφθη.", "st": "5.100"}, {"sp": "N", "t": "Μιθριδάτης δὲ μετὰ τῶν ὑπασπιστῶν μόνων ὠσάμενος ἐς τὰ κατάκρημνα καὶ διαφυγὼν ἐνέτυχέ τισιν ἱππεῦσι μισθοφόροις καὶ πεζοῖς ὡς τρισχιλίοις, οἳ εὐθὺς αὐτῷ συνείμοντο ἐς Σινόρηγα φρούριον, ἔνθα αὐτῷ χρήματα πολλὰ ἐσεσώρευτο· καὶ δωρεὰν καὶ μισθὸν ἐνιαυτοῦ τοῖς συμφυγοῦσι διέδωκεν. φέρων δ’ ἐς ἑξακισχίλια τάλαντα ἐπὶ τὰς τοῦ Εὐφράτου πηγὰς ἠπείγετο ὡς ἐκεῖθεν ἐς Κόλχους περάσων. δρόμῳ δ’ ἀπαύστῳ χρώμενος τὸν μὲν Εὐφράτην ὑπερῆλθεν ἡμέρᾳ μάλιστα τετάρτῃ, τρισὶ δ’ ἄλλαις καθιστάμενος καὶ ὁπλίζων τοὺς συνόντας ἢ προσιόντας ἐς τὴν Χωτηνὴν Ἀρμενίαν ἐνέβαλεν, ἔνθα Χωτηνοὺς μὲν καὶ Ἴβηρας, κωλύοντας αὐτὸν βέλεσι καὶ σφενδόναις, ἐλαύνων διῆλθεν ἐπὶ τὸν Ἄψαρον ποταμόν. Ἴβηρας δὲ τοὺς ἐν Ἀσίᾳ οἱ μὲν προγόνους οἱ δ’ ἀποίκους ἡγοῦνται τῶν Εὐρωπαίων Ἰβήρων, οἱ δὲ μόνον ὁμωνύμους· ἔθος γὰρ οὐδὲν ἦν ὅμοιον, ἢ γλῶσσα. Μιθριδάτης δ’ ἐν Διοσκούροις χειμάζων, ἥν τινα πόλιν οἱ Κόλχοι σύμβολον ἡγοῦνται τῆς Διοσκούρων σὺν Ἀργοναύταις ἐπιδημίας, οὐδὲν σμικρόν, οὐδ’ οἷον ἐν φυγῇ, διενοεῖτο, ἀλλὰ τὸν Πόντον ὅλον ἐν κύκλῳ καὶ Σκύθας ἐπὶ τῷ Πόντῳ καὶ τὴν Μαιώτιδα λίμνην ὑπερελθὼν ἐς Βόσπορον ἐμβαλεῖν, τήν τε Μαχάρους τοῦ παιδὸς ἀρχήν, ἀχαρίστου περὶ αὐτὸν γενομένου, παραλαβὼν αὖθις ἐκ μετώπου Ῥωμαίοις γενέσθαι, καὶ πολεμεῖν ἐκ τῆς Εὐρώπης οὖσιν ἐν τῇ Ἀσίᾳ, τὸν πόρον ἐν μέσῳ θέμενος, ὃν κληθῆναι νομίζουσι Βόσπορον Ἰοῦς διανηξαμένης, ὅτε βοῦς γενομένη κατὰ ζηλοτυπίαν Ἥρας ἔφευγεν.", "st": "5.101"}, {"sp": "N", "t": "ἐς τοσοῦτο παραδοξολογίας ἐπειγόμενος ὁ Μιθριδάτης ἐφικέσθαι ὅμως ἐπενόει, καὶ διώδευεν ἔθνη Σκυθικὰ καὶ πολεμικὰ καὶ ἀλλότρια πείθων ἢ βιαζόμενος· οὕτω καὶ φεύγων καὶ ἀτυχῶν αἰδέσιμος ἔτι καὶ φοβερὸς ἦν. ἡνιόχους μὲν οὖν δεχομένους αὐτὸν παρώδευεν, Ἀχαιοὺς δ’ ἐτρέψατο διώκων· οὓς ἀπὸ Τροίας ἐπανιόντας φασὶν ἐς τὸν Πόντον ὑπὸ χειμῶνος ἐκπεσεῖν, καὶ πολλὰ παθεῖν ὡς Ἕλληνας ὑπὸ βαρβάρων, πέμψαντας δ’ ἐπὶ ναῦς ἐς τὰς πατρίδας καὶ ὑπεροφθέντας μηνῖσαι τῷ Ἑλληνικῷ γένει, καὶ Σκυθικῶς ὅσους ἕλοιεν Ἑλλήνων καταθύειν, πρῶτα μὲν ἅπαντας ὑπ’ ὀργῆς, σὺν χρόνῳ δὲ τοὺς καλλίστους αὐτῶν μόνους, μετὰ δὲ τοὺς κληρουμένους. καὶ τάδε μὲν περὶ Ἀχαιῶν τῶν Σκυθικῶν· ὁ δὲ Μιθριδάτης ἐς τὴν Μαιῶτιν ἐμβαλών, ἧς εἰσὶ πολλοὶ δυνάσται, πάντων αὐτὸν κατὰ κλέος ἔργων τε καὶ ἀρχῆς, καὶ δυνάμεως ἔτι οἱ παρούσης ἀξιολόγου, δεχομένων τε καὶ παραπεμπόντων, καὶ δῶρα πολλὰ φερόντων καὶ κομιζομένων ἕτερα, ὁ δὲ καὶ συμμαχίαν αὐτοῖς ἐτίθετο, ἐπινοῶν ἕτερα καινότερα, διὰ Θρᾴκης ἐς Μακεδονίαν καὶ διὰ Μακεδόνων ἐς Παίονας ἐμβαλὼν ὑπερελθεῖν ἐς τὴν Ἰταλίαν τὰ Ἄλπεια ὄρη· γάμους τε θυγατέρων ἐπὶ τῇδε τῇ συμμαχίᾳ τοῖς δυνατωτέροις αὐτῶν ἠγγύα. Μαχάρης δ’ αὐτὸν ὁ παῖς πυνθανόμενος ὁδόν τε τοσαύτην ὀλίγῳ χρόνῳ καὶ ἄγρια ἔθνη καὶ τὰ καλούμενα κλεῖθρα Σκυθῶν, οὐδενί πω γεγονότα περατά, διοδεῦσαι, πρέσβεις μέν τινας ἐς αὐτὸν ἔπεμπεν ἀπολογησομένους ὡς ἀνάγκῃ θεραπεύσειε Ῥωμαίους, ὀργὴν δὲ ἄκρον εἰδὼς ἔφευγεν ἐς τὴν ἐν τῷ Πόντῳ χερρόνησον, τὰς ναῦς διαπρήσας, ἵνα μὴ διώξειεν αὐτὸν ὁ πατήρ. ἑτέρας δ’ ἐπιπέμψαντος ἐκείνου, προλαβὼν ἑαυτὸν ἔκτεινεν. ὁ δὲ Μιθριδάτης αὐτοῦ τῶν φίλων οὓς μὲν αὐτὸς ἐς τὴν ἀρχὴν ἀπιόντι ἐδεδώκει, πάντας ἔκτεινε, τοὺς δὲ τοῦ παιδὸς ἀπαθεῖς ὡς ὑπηρέτας ἰδίου φίλου γενομένους ἀφῆκεν.", "st": "5.102"}, {"sp": "N", "t": "καὶ τάδε μὲν ἦν ἀμφὶ τὸν Μιθριδάτην, ὁ δὲ Πομπήιος αὐτὸν εὐθὺς μὲν ἐπὶ τῇ φυγῇ μέχρι Κόλχων ἐδίωξε, μετὰ δέ, οὐδαμὰ δόξας αὐτὸν οὔτε τὸν Πόντον οὔτε τὴν Μαιώτιδα λίμνην περιελεύσεσθαι, οὐδὲ μεγάλοις ἔτι πράγμασιν ἐγχειρήσειν ἐκπεσόντα, τοὺς Κόλχους ἐπῄει καθ’ ίστορίαν τῆς Ἀργοναυτῶν καὶ Διοσκούρων καὶ Ἡρακλέους ἐπιδημίας, τὸ πάθος μάλιστα ἰδεῖν ἐθέλων ὃ Προμηθεῖ φασὶ γενέσθαι περὶ τὸ Καύκασον ὄρος. χρυσοφοροῦσι δ’ ἐκ τοῦ Καυκάσου πηγαὶ πολλαὶ ψῆγμα ἀφανές· καὶ οἱ περίοικοι κῴδια τιθέντες ἐς τὸ ῥεῦμα βαθύμαλλα, τὸ ψῆγμα ἐνισχόμενον αὐτοῖς ἐκλέγουσιν. καὶ τοιοῦτον ἦν ἴσως καὶ τὸ χρυσόμαλλον Αἰήτου δέρος. τὸν οὖν Πομπήιον ἐπὶ τῇ ἱστορίᾳ ἀνιόντα οἱ μὲν ἄλλοι παρέπεμπον, ὅσα ἔθνη γείτονα· Ὀροίζης δ’ ὁ τῶν Ἀλβανῶν βασιλεὺς καὶ Ἀρτώκης ὁ Ἰβήρων ἑπτὰ μυριάσιν ἐλόχων ἀμφὶ τὸν Κύρτον ποταμόν, ὃς δώδεκα στόμασι πλωτοῖς ἐς τὴν Κασπίαν θάλασσαν ἐρεύγεται, πολλῶν ἐς αὐτὸν ἐμβαλόντων ποταμῶν, καὶ μεγίστου πάντων Ἀράξου. αἰσθόμενος δὲ τῆς ἐνέδρας ὁ Πομπήιος τὸν ποταμὸν ἐζεύγνυ, καὶ τοὺς βαρβάρους συνελάσας ἐς λόχμην βαθεῖαν (ὑλομαχῆσαι δ’ εἰσὶ δεινοί, κρυπτόμενοί τε καὶ ἐπιόντες ἀφανῶς) αὐτῇ λόχμῃ τὸν στρατὸν περιστήσας ἐνέπρησε, καὶ τοὺς ἐκφεύγοντας ἐδίωκεν, ἕως ἅπαντες ὅμηρά τε καὶ δῶρα ἤνεγκαν. καὶ ἐθριάμβευσεν ἐς Ῥώμην καὶ ἀπὸ τῶνδε. πολλαὶ δὲ ἔν τε τοῖς ὁμήροις καὶ τοῖς αἰχμαλώτοις ηὑρέθησαν γυναῖκες, οὐ μείονα τῶν ἀνδρῶν τραύματα ἔχουσαι· καὶ ἐδόκουν Ἀμαζόνες εἶναι, εἴτε τι ἔθνος ἐστὶν αὐτοῖς γειτονεῦον αἱ Ἀμαζόνες, ἐπίκλητοι τότε ἐς συμμαχίαν γενόμεναι, εἴτε τινὰς πολεμικὰς ὅλως γυναῖκας οἱ τῇδε βάρβαροι καλοῦσιν Ἀμαζόνας.", "st": "5.103"}, {"sp": "N", "t": "ἐπανιὼν δ’ ἐντεῦθεν ὁ Πομπήιος ἐστράτευσεν ἐς Ἀρμενίαν, ἔγκλημα ἐς Τιγράνη τιθέμενος ὅτι συνεμάχει Μιθριδάτῃ· καὶ ἦν ἤδη περὶ Ἀρτάξατα τὴν βασίλειον. Τιγράνῃ δὲ οὐκ ἔγνωστο μὲν πολεμεῖν ἔτι, παῖδες δ’ ἐκ τῆς Μιθριδάτου θυγατρὸς αὐτῷ ἐγεγένηντο, ὧν δύο μὲν αὐτὸς ὁ Τιγράνης ἀνῃρήκει, τὸν μὲν ἐν μάχῃ, πολεμοῦντά οἱ, τὸν δ’ ἐν κυνηγεσίοις, αὐτοῦ πεσόντος ἀμελήσαντα καὶ τὸ διάδημα περιθέμενον ἔτι κειμένου. ὁ δὲ τρίτος, Τιγράνης, ἐν μὲν τοῖς κυνηγεσίοις ὑπεραλγήσας τοῦ πατρὸς ἐστεφάνωτο ὑπ’ αὐτοῦ, μικρὸν δὲ διαλιπὼν ἀπέστη καὶ ὅδε, καὶ πολεμῶν τῷ πατρὶ καὶ ἡττώμενος ἐς Φραάτην ἐπεφεύγει τὸν Παρθυαίων βασιλέα, ἄρτι τὴν Σιντρίκου τοῦ πατρὸς ἀρχὴν διαδεδεγμένον. πλησιάσαντος δὲ τοῦ Πομπηίου κοινωσάμενος Φραάτῃ, συγχωροῦντός τι κἀκείνου καὶ φιλίαν ἰδίαν ἐς τὸν Πομπήιον μνωμένου, κατέφυγεν ὁ παῖς ἱκέτης ἐς τὸν Πομπήιον, καὶ ταῦτα ὢν Μιθριδάτου θυγατριδοῦς. ἀλλὰ μέγα δικαιοσύνης καὶ πίστεως κλέος ἦν τοῦ Πομπηίου παρὰ τοῖς βαρβάροις, ᾧ δὴ πίσυνος καὶ ὁ πατὴρ Τιγράνης οὐδ’ ἐπικηρυκευσάμενος ᾔει, τά τε ἄλλα πάντα ἑαυτὸν ἐπιτρέψας ἐς τὰ δίκαια Πομπηίῳ, καὶ κατηγορήσων τοῦ παιδὸς ἐπὶ Πομπηίου. χιλιάρχους δὲ αὐτῷ καὶ ἱππάρχους ἐπὶ τιμῇ κελεύσαντος ὑπαντᾶν τοῦ Πομπηίου, οἱ μὲν ὄντες ἀμφὶ τὸν Τιγράνη τὸ ἀκήρυκτον τῆς ὁδοῦ δεδιότες ἔφευγον ὀπίσω, ὁ δὲ Τιγράνης ἦλθε, καὶ τὸν Πομπήιον ὡς κρείττονα βαρβαρικῶς προσεκύνησεν. εἰσὶ δ’ οἳ λέγουσιν ὑπὸ ῥαβδούχοις αὐτὸν ἀχθῆναι, μετάπεμπτον ὑπὸ τοῦ Πομπηίου γενόμενον. ὁποτέρως δ’ ἦλθεν, ἐξελογεῖτο περὶ τῶν γεγονότων, καὶ ἐδίδου Πομπηίῳ μὲν αὐτῷ τάλαντα ἑξακισχίλια, τῇ στρατιᾷ δὲ δραχμὰς πεντήκοντα ἑκάστῳ, καὶ λοχαγῷ χιλίας, καὶ χιλιάρχῳ μυρίας.", "st": "5.104"}, {"sp": "N", "t": "καὶ ὁ Πομπήιος αὐτῷ συνεγίγνωσκε τῶν γεγονότων καὶ συνήλασσε τῷ παιδί, καὶ διῄτησε τὸν μὲν υἱὸν ἄρχειν τῆς Σωφηνῆς καὶ Γορδυηνῆς, αἳ νῦν ἄρα εἰσὶν Ἀρμενία βραχυτέρα, τὸν δὲ πατέρα τῆς ἄλλης Ἀρμενίας ἐπὶ τῷδε τῷ παιδὶ κληρονόμῳ. τὴν δὲ ἐπίκτητον αὐτὸν ἀρχὴν ἐκέλευεν ἤδη μεθεῖναι. καὶ μεθίει Συρίαν τὴν ἀπ’ Εὐφράτου μέχρι τῆς θαλάσσης· εἶχε γὰρ δὴ καὶ τήνδε καὶ Κιλικίας τινὰ ὁ Τιγράνης, Ἀντίοχον ἐκβαλὼν τὸν εὐσεβῆ προσαγορευθέντα. Ἀρμενίων δ’ ὅσοι τὸν Τιγράνη πρὸς Πομπήιον ὁδεύοντα ἐγκατελελοίπεσαν, ἐν ὑποψίᾳ τοῦτ’ ἔχοντες, τὸν παῖδα αὐτοῦ παρὰ τῷ Πομπηίῳ ἔτι ὄντα πείθουσιν ἐπιθέσθαι τῷ πατρί. καὶ ὁ μὲν ἐλήφθη καὶ ἐδέθη, καὶ μεταξὺ Παρθυαίους ἐρεθίζων ἐπὶ τὸν Πομπήιον ἐθριαμβεύθη καὶ ἀνῃρέθη· ὁ δὲ Πομπήιος ἐκτετελέσθαι οἱ τὸν πάντα πόλεμον ἡγούμενος, ᾤκιζε πόλιν ἔνθα τὴν μάχην ἐνίκα Μιθριδάτην, ἣ ἀπὸ τοῦ ἔργου Νικόπολις κλῄζεται, καὶ ἔστιν Ἀρμενίας τῆς βραχυτέρας λεγομένης. Ἀριοβαρζάνῃ δ’ ἀπεδίδου βασιλεύειν Καππαδοκίας, καὶ προσεπέδωκε Σωφηνὴν καὶ Γορδυηνήν, ἃ τῷ παιδὶ ἐμεμέριστο τῷ Τιγράνους· καὶ στρατηγεῖται νῦν ἅμα τῇ Καππαδοκίᾳ καὶ τάδε. ἔδωκε δὲ καὶ τῆς Κιλικίας πόλιν Καστάβαλα καὶ ἄλλας. Ἀριοβαρζάνης μὲν οὖν τὴν βασιλείαν ὅλην τῷ παιδὶ περιὼν ἐνεχείρισε. καὶ πολλαὶ μεταβολαὶ μέχρι Καίσαρος ἐγένοντο τοῦ Σεβαστοῦ, ἐφ’ οὗ, καθάπερ τὰ λοιπά, καὶ ἥδε ἡ βασιλεία περιῆλθεν ἐς στρατηγίαν.", "st": "5.105"}, {"sp": "N", "t": "ὁ δὲ Πομπήιος καὶ τὸν Ταῦρον ὑπερελθὼν ἐπολέμησε ⟨μὲν⟩ Ἀντιόχῳ τῷ Κομμαγηνῷ, ἕως ἐς φιλίαν ὁ Ἀντίοχος αὐτῷ συνῆλθεν, ἐπολέμησε δὲ καὶ Δαρείῳ τῷ Μήδῳ, μέχρι ἔφυγεν, εἴτε Ἀντιόχῳ συμμαχῶν εἴτε Τιγράνῃ πρότερον. ἐπολέμησε δὲ καὶ Ἄραψι τοῖς Ναβαταίοις, Ἀρέτα βασιλεύοντος αὐτῶν, καὶ Ἰουδαίοις, Ἀριστοβούλου τοῦ βασιλέως ἀποστάντος, ἕως εἷλεν Ἱεροσόλυμα τὴν ἁγιωτάτην αὐτοῖς πόλιν. καὶ Κιλικίας δὲ ὅσα οὔπω Ῥωμαίοις ὑπήκουε, καὶ τὴν ἄλλην Συρίαν, ὅση τε περὶ Εὐφράτην ἐστὶ καὶ κοίλη καὶ Φοινίκη καὶ Παλαιστίνη λέγεται, καὶ τὴν Ἰδουμαίων καὶ Ἰτουραίων, καὶ ὅσα ἄλλα ὀνόματα Συρίας, ἐπιὼν ἀμαχὶ Ῥωμαίοις καθίστατο, ἔγκλημα μὲν οὐδὲν ἔχων ἐς Ἀντίοχον τὸν εὐσεβοῦς, παρόντα καὶ δεόμενον ὑπὲρ ἀρχῆς πατρῴας, ἡγούμενος δέ, Τιγράνη τὸν κρατήσαντα τοῦ Ἀντιόχου τῆς γῆς ἀπελάσας, Ῥωμαίοις αὐτὴν κατὰ τόδε προσκεκτῆσθαι. ταῦτα δ’ αὐτῷ διοικουμένῳ πρέσβεις ἀφίκοντο Φραάτου καὶ Τιγράνους ἐς πόλεμον ἀλλήλοις συμπεσόντων, οἱ μὲν Τιγράνους ὡς φίλῳ συμμαχεῖν τὸν Πομπήιον ἀξιοῦντες, οἱ δὲ τοῦ Παρθυαίου φιλίαν αὐτῷ πρὸς Ῥωμαίους τιθέμενοι. καὶ ὁ Πομπήιος οὐκ ἀξιῶν Παρθυαίοις πολεμεῖν ἄνευ Ῥωμαίων ψηφίσματος, ἔπεμψεν ἀμφοτέροις διαλλακτάς.", "st": "5.106"}, {"sp": "N", "t": "καὶ ὁ μὲν ἀμφὶ ταῦτα ἦν, Μιθριδάτῃ δὲ ἡ περίοδος ἤνυστο τοῦ Πόντου· καὶ Παντικάπαιον, ἐμπόριον Εὐρωπαίων ἐπὶ τῆς ἐκβολῆς τοῦ Πόντου καταλαβὼν κτείνει τῶν υἱέων Ξιφάρην ἐπὶ τοῦ πόρου διὰ μητρὸς ἁμάρτημα τοιόνδε. φρούριον ἦν τι Μιθριδάτῃ, ἔνθα λανθάνοντες ὑπόγειοι θησαυροὶ πολλῶν σιδηροδέτων χαλκέων πολλὰ χρήματα ἔκρυπτον. Στρατονίκη δέ, μία τῶν Μιθριδάτου παλλακῶν ἢ γυναικῶν, ἣ τοῦδε τοῦ φρουρίου τὴν ἐπιστήμην καὶ φυλακὴν ἐπετέτραπτο, περιιόντος ἔτι τὸν Πόντον τοῦ Μιθριδάτου τὸ φρούριον ἐνεχείρισε τῷ Πομπηίῳ καὶ τοὺς θησαυροὺς ἀγνοουμένους ἐμήνυσεν, ἐπὶ συνθήκῃ μόνῃ τῇδε, ὅτι οἱ τὸν υἱὸν Ξιφάρην ὁ Πομπήιος, εἰ λάβοι, περισώσει. καὶ ὁ μὲν τοῖς χρήμασιν ἐπιτυχὼν ὑπέσχητο αὐτῇ τὸν Ξιφάρην καὶ ἐδεδώκει φέρεσθαι καὶ τὰ ἴδια· αἰσθόμενος δὲ τῶν γεγονότων ὁ Μιθριδάτης κτείνει τὸν Ξιφάρην ἐπὶ τοῦ πόρου, ἐφορώσης τῆς μητρὸς πέραθεν, καὶ ἐξέρριψεν ἄταφον. καὶ ὁ μὲν υἱοῦ κατεφρόνησεν ἐς ἀνίαν τῆς ἁμαρτούσης, καὶ πρέσβεις ἐς τὸν Πομπήιον, ἔτι περὶ Συρίαν ὄντα καὶ οὐκ αἰσθανόμενον αὐτοῦ παρόντος, ἔπεμπεν, οἳ τῆς πατρῴας ἀρχῆς αὐτὸν Ῥωμαίοις τελέσειν φόρους ὑπισχνοῦντο· Πομπηίου δ’ αὐτὸν ἐλθόντα δεῖσθαι τὸν Μιθριδάτην κελεύοντος, καθὰ καὶ Τιγράνης ἀφίκετο, τοῦτο μὲν οὐκ ἔφη ποτὲ ὑποστήσεσθαι, Μιθριδάτης γε ὤν, πέμψειν δὲ τῶν παίδων τινὰς καὶ φίλους. ἅμα δὲ ταῦτ’ ἔλεγε, καὶ στρατιὰν ἀθρόως κατέλεγεν ἐλευθέρων τε καὶ δούλων, ὅπλα τε πολλὰ καὶ βέλη καὶ μηχανὰς ἐπήγνυ, φειδόμενος οὔτε τινὸς ὕλας οὔτε βοῶν ἀροτήρων ἐς τὰ νεῦρα, ἐσφοράς τε πᾶσιν ἐς τὰ βραχύτατα τῆς περιουσίας ἐπέγραφεν. οἱ δὲ ὑπηρέται τούτου πολλοὺς ἐνύβριζον, οὐκ αἰσθανομένου τοῦ Μιθριδάτου· νόσον γάρ τινα ἑλκώδη τοῦ προσώπου νοσῶν ὑπὸ τριῶν εὐνούχων ἐθεραπεύετο καὶ ἑωρᾶτο.", "st": "5.107"}, {"sp": "N", "t": "ὡς δ’ ἔληγε τὸ πάθος, καὶ ὁ στρατὸς αὐτῷ ἀγήγερτο ἤδη, ἐπίλεκτοι μὲν ἑξήκοντα σπεῖραι, ἀνὰ ἑξακοσίους ἄνδρας, πολὺς δὲ καὶ ἄλλος ὅμιλος καὶ νῆες, καὶ χωρία ὅσα οἱ στρατηγοὶ παρὰ τὴν νόσον ᾑρήκεσαν, ἐπέρα τοῦ στρατοῦ μέρος ἐς Φαναγόρειαν, ἕτερον ἐμπόριον ἐπὶ τοῦ στόματος, ὡς ἑκατέρωθεν ἕξων τὰς ἐσβολάς, ἔτι Πομπηίου περὶ Συρίαν ὄντος. Κάστωρ δὲ Φαναγορεὺς ᾐκισμένος ποτὲ ὑπὸ Τρύφωνος εὐνούχου βασιλικοῦ, τὸν Τρύφωνα ἐσιόντα κτείνει προσπεσών, καὶ τὸ πλῆθος ἐς ἐλευθερίαν συνεκάλει. οἱ δέ, καίπερ ἤδη τῆς ἀκροπόλεως ἐχομένης ὑπὸ Ἀρταφέρνους τε καὶ ἑτέρων υἱέων τοῦ Μιθριδάτου, ξύλα περιθέντες τὴν ἄκραν ἐνεπίμπρασαν, ἕως ὁ μὲν Ἀρταφέρνης καὶ Δαρεῖος καὶ Ξέρξης καὶ Ὀξάθρης καὶ Εὐπάτρα, παῖδες τοῦ Μιθριδάτου, δείσαντες ἐπὶ τῷ πυρὶ παρέδοσαν ἑαυτοὺς ἄγεσθαι. καὶ ἦν αὐτῶν Ἀρταφέρνης ἀμφὶ τεσσαράκοντα ἔτη μόνος, οἱ δὲ λοιποὶ παῖδες εὔμορφοι. Κλεοπάτρα δὲ ἀντεῖχεν, ἑτέρα παῖς τοῦ Μιθριδάτου· καὶ αὐτὴν ὁ πατὴρ ἀγάμενος τῆς εὐψυχίας, δίκροτα πολλὰ ἐπιπέμψας ἐξήρπασεν. ὅσα δὲ ἐγγὺς ἦν φρούρια, ἀρτίληπτα τῷ Μιθριδάτῃ γενόμενα, πρὸς τὴν θερμουργίαν τῶν Φαναγορέων ἀφίστατο τοῦ Μιθριδάτου, Χερρόνησός τε καὶ Θεοδοσία καὶ Νύμφαιον, καὶ ὅσα ἄλλα περὶ τὸν Πόντον ἐστὶν εὔκαιρα ἐς πόλεμον. ὁ δὲ τὰς ἀποστάσεις ὁρῶν πυκνάς, καὶ τὸν στρατὸν ἐν ὑποψίᾳ ἔχων μὴ οὐ βέβαιος ᾖ διὰ τὴν ἀνάγκην τῆς στρατείας καὶ δι’ ἐσφορῶν βαρύτητα καὶ τὴν ἀεὶ τοῖς στρατοῖς ἐς ἡγεμόνας ἀτυχοῦντας ἀπιστίαν, ἔπεμπεν ἐς τοὺς Σκύθας δι’ εὐνουχων τοῖς δυνάσταις τὰς θυγατέρας ἐς γάμόυς, αἰτῶν στρατιὰν κατὰ τάχος ἤδη οἱ παρεῖναι. πεντακόσιοι δ’ αὐτὰς ἀπὸ τοῦ στρατοῦ παρέπεμπον ἄνδρες· οἳ Μιθριδάτου βραχὺ διασχόντες ἔκτεινάν τε τοὺς ἄγοντας εὐνούχους, ἀεὶ πρὸς εὐνούχους κρατοῦντας τοῦ Μιθριδάτου πεπολεμωμένοι, καὶ τὰς κόρας ἐς τὸν Πομπήιον ἀπήγαγον.", "st": "5.108"}, {"sp": "N", "t": "ὁ δὲ καὶ τέκνων τοσῶνδε καὶ φρουρίων καὶ τῆς ἀρχῆς ὅλης ἀφῃρημένος, καὶ ἐς οὐδὲν ἀξιόμαχος ἔτι ὤν, οὐδὲ τῆς Σκυθῶν συμμαχίας ἡγούμενος ἂν τυχεῖν, ὅμως οὐδὲν οὐδὲ τότε ἢ ταπεινὸν ἢ συμφορῶν ἄξιον ἐνεθυμεῖτο, ἀλλ’ ἐς Κελτούς, ἐκ πολλοῦ φίλους ἐπὶ τῷδέ οἱ γεγονότας, ἐπενόει διελθὼν ἐς τὴν Ἰταλίαν σὺν ἐκείνοις ἐμβαλεῖν, ἐλπίζων οἱ πολλὰ καὶ τῆς Ἰταλίας αὐτῆς ἔχθει Ῥωμαίων προσέσεσθαι, πυνθανόμενος ὧδε καὶ Ἀννίβαν πρᾶξαι πολεμούμενον ἐν Ἰβηρίᾳ, καὶ ἐπιφοβώτατον ἐκ τοῦδε Ῥωμαίοις γενέσθαι. ᾔδει δὲ καὶ ἔναγχος τὴν Ἰταλίαν σχεδὸν ἅπασαν ἀπὸ Ῥωμαίων ἀποστᾶσαν ὑπὸ ἔχθους, καὶ ἐπὶ πλεῖστον αὐτοῖς πεπολεμηκυῖαν, Σπαρτάκῳ τε μονομάχῳ συστᾶσαν ἐπ’ αὐτούς, ἀνδρὶ ἐπ’ οὐδεμιᾶς ἀξιώσεως ὄντι. ταῦτα ἐνθυμούμενος ἐς Κελτοὺς ἠπείγετο. τοῦ δὲ τολμήματος ἂν αὐτῷ λαμπροτάτου γενομένου, ὁ στρατὸς ὤκνει δι’ αὐτὸ μάλιστα τῆς τόλμης τὸ μέγεθος, ἐπί τε χρόνιον στρατείαν καὶ ἐς ἀλλοτρίαν γῆν ἀγόμενοι, καὶ ἐπὶ ἄνδρας ὧν οὐδ’ ἐν τῇ σφετέρᾳ κρατοῦσιν. αὐτόν τε τὸν Μιθριδάτην ἡγούμενοι, πάντων ἀπογιγνώσκοντα, βούλεσθαί τι δρῶντα καὶ βασιλιζόμενον μᾶλλον ἢ δι’ ἀργίας ἀποθανεῖν, ὅμως ἐνεκαρτέρουν καὶ ἡσύχαζον· οὐ γάρ τοι σμικρὸς οὐδ’ εὐκαταφρόνητος ἦν ὁ βασιλεὺς οὐδ’ ἐν ταῖς συμφοραῖς.", "st": "5.109"}, {"sp": "N", "t": "ὧδε δ’ ἐχόντων ἁπάντων, Φαρνάκης ὁ τῶν παίδων αὐτῷ τιμιώτατός τε καὶ πολλάκις ὑπ’ αὐτοῦ τῆς ἀρχῆς ἀποδεδειγμένος ἔσεσθαι διάδοχος, εἴτε δείσας περὶ τοῦδε τοῦ στόλου καὶ τῆς ἀρχῆς, ὡς νῦν μὲν ἔτι συγγνωσομένων τι Ῥωμαίων, ἀπολουμένης δὲ πάμπαν ὁλοκλήρως εἰ ἐπὶ τὴν Ἰταλίαν ὁ πατὴρ στρατεύσειεν, εἴθ’ ἑτέραις αἰτίαις καὶ λογισμῶν ἐπιθυμίαις, ἐπεβούλευε τῷ πατρί. ληφθέντων δὲ τῶν συνεγνωκότων αὐτῷ καὶ ἐς βασάνους ἀγομένων, Μηνοφάνης μετέπεισε τὸν Μιθριδάτην ὡς οὐ δέον, ἀποπλέοντα ἤδη, τὸν ἔτι οἱ τιμιώτατον υἱὸν ἀνελεῖν· εἶναι δ’ ἔφη τὰς τοιαύτας τροπὰς ἔργα πολέμων, ὧν παυσαμένων καὶ τάδε καθίστασθαι. ὁ μὲν δὴ πεισθεὶς προὔτεινε τῷ παιδὶ συγγνώμην. ὁ δὲ δείσας τι μήνιμα καὶ τὸν στρατὸν εἰδὼς κατοκνοῦντα τὴν στρατείαν, νυκτὸς ἐς πρώτους τοὺς Ῥωμαίων αὐτομόλους, ἀγχοτάτω τοῦ Μιθριδάτου στρατοπεδεύοντας, ἐσῆλθε, καὶ τὸν κίνδυνον αὐτοῖς ἰοῦσιν ἐπὶ τὴν Ἰταλίαν, ὅσος εἴη, σαφῶς εἰδόσιν ὑπερεπαίρων, πολλὰ δὲ μένουσιν ἐπελπίσας ἔσεσθαι παρ’ ἑαυτοῦ, προήγαγεν ἐς ἀπόστασιν ἀπὸ τοῦ πατρός. ὡς δ’ ἐπείσθησαν οἵδε, τῆς αὐτῆς νυκτὸς ἐς τὰ ἐγγὺς ἄλλα στρατόπεδα ἔπεμπεν ὁ Φαρνάκης. συνθεμένων δὲ κἀκείνων, πρῶτοι μὲν ἅμα ἕῳ ἠλάλαξαν οἱ αὐτόμολοι, ἐπὶ δ’ ἐκείνοις οἱ ἀεὶ πλησίον τὴν βοὴν μετελάμβανον. καὶ τὸ ναυτικὸν αὐτοῖς ἐπήχησεν, οὐ προειδότες μὲν ἅπαντες ἴσως, ὀξύρροποι δ’ ὄντες ἐς μεταβολὰς καὶ τὸ δυστυχοῦν ὑπερορῶντες, ἐν δὲ τῷ καινῷ τὸ εὔελπι ἀεὶ τιθέμενοι. οἱ δὲ καὶ ἀγνοίᾳ τῶν συνεγνωκότων, ἡγούμενοι πάντας διεφθάρθαι καὶ μόνοι ἔτι ὄντες ἔσεσθαι τοῖς πλείοσιν εὐκαταφρόνητοι, φόβῳ καὶ ἀνάγκῃ μᾶλλον ἢ ἑκουσίῳ γνώμῃ συνεπήχουν. Μιθριδάτης δ’ ἐγρόμενος ὑπὸ τῆς βοῆς ἔπεμπέ τινας ἐρησομένους ὅ τι χρῄζοιεν οἱ βοῶντες. οἱ δ’ οὐκ ἐγκαλυψάμενοι, “τὸν υἱόν,” ἔφασαν, “βασιλεύειν, νέον ἀντὶ γέροντος εὐνούχοις τε ἐκδεδομένου καὶ κτείναντος ἤδη πολλοὺς υἱέας τε καὶ ἡγεμόνας καὶ φίλους.”", "st": "5.110"}, {"sp": "N", "t": "ὧν ὁ Μιθριδάτης πυθόμενος, ἐξῄει διαλεξόμενος αὐτοῖς. καί τι πλῆθος ἐκ φρουρίου τοῖς αὐτομόλοις συνέτρεχεν. οἱ δ’ οὐκ ἔφασαν αὐτοὺς προσήσεσθαι πρίν τι ἀνήκεστον ἐς πίστιν ἐργάσασθαι, δεικνύντες ὁμοῦ τὸν Μιθριδάτην. οἱ μὲν δὴ τὸν ἵππον ἔφθασαν αὐτοῦ κτεῖναι φυγόντος, καὶ τὸν Φαρνάκην ὡς ἤδη κρατοῦντες ἀνεῖπον βασιλέα· καὶ βύβλον τις πλατεῖαν φέρων ἐξ ἱεροῦ ἐστεφάνωσεν αὐτὸν ἀντὶ διαδήματος. ἅπερ ἄνωθεν ἐκ περιπάτου θεώμενος ἔπεμπεν ἐς τὸν Φαρνάκην ἄλλον ἐπ’ ἄλλοῳ, φυγὴν αἰτῶν ἀσφαλῆ. οὐδενὸς δὲ τῶν πεμπομένων ἐπανιόντος, δείσας μὴ Ῥωμαίοις ἐκδοθείη, τοὺς μὲν σωματοφύλακας αὑτοῦ καὶ φίλους ἔτι παραμένοντας ἐπαινέσας ἔπεμψεν ἐς τὸν νέον βασιλέα, καὶ αὐτῶν τινας προσιόντας ἔκτεινεν ἡ στρατιὰ παραλόγως, αὐτὸς δὲ παραλύσας ὃ περὶ τῷ ξίφει φάρμακον ἀεὶ περιέκειτο ἐκίρνη. δύο δ’ αὐτῷ θυγατέρες ἔτι κόραι συντρεφόμεναι, Μιθριδᾶτίς τε καὶ Νύσσα, τοῖς Αἰγύπτου καὶ Κύπρου βασιλεῦσιν ἠγγυημέναι, προλαβεῖν τοῦ φαρμάκου παρεκάλουν, καὶ σφόδρα εἴχοντο, καὶ πίνοντα κατεκώλυον ἕως ἔπιον λαβοῦσαι. καὶ τῶν μὲν αὐτίκα τὸ φάρμακον ἥπτετο, τοῦ δὲ Μιθριδάτου, καίτοι συντόνως ἐξεπίτηδες βαδίζοντος, οὐκ ἐφικνεῖτο δι’ ἔθος καὶ συντροφίαν ἑτέρων φαρμάκων, οἷς ἐς ἄμυναν δηλητηρίων ἐχρῆτο συνεχῶς· καὶ νῦν ἔτι φάρμακα Μιθριδάτεια λέγεται. Βίτοιτον οὖν τινὰ ἰδών, ἡγεμόνα Κελτῶν, “πολλὰ μὲν ἐκ τῆς σῆς,” ἔφη, “δεξιᾶς ἐς πολεμίους ὠνάμην, ὀνήσομαι δὲ μέγιστον εἰ νῦν με κατεργάσαιο, κινδυνεύοντα ἐς πομπὴν ἀπαχθῆναι θριάμβου τὸν μέχρι πολλοῦ τοσῆσδε ἀρχῆς αὐτοκράτορα καὶ βασιλέα, ἀδυνατοῦντα ἐκ φαρμάκων ἀποθανεῖν δι’ εὐήθη προφυλακὴν ἑτέρων φαρμάκων· τὸ γὰρ δὴ χαλεπώτατον καὶ σύνοικον ἀεὶ βασιλεῦσι φάρμακον, ἀπιστίαν στρατοῦ καὶ παίδων καὶ φίλων, οὐ προειδόμην ὁ τὰ ἐπὶ τῇ διαίτῃ πάντα προϊδὼν καὶ φυλαξάμενος.” ὁ μὲν δὴ Βίτοιτος ἐπικλασθεὶς ἐπεκούρησε χρῄζοντι τῷ βασιλεῖ,", "st": "5.111"}, {"sp": "N", "t": "καὶ ὁ Μιθριδάτης ἀπέθνησκεν, ἑκκαιδέκατος ὢν ἐκ Δαρείου τοῦ Ὑστάσπου Περσῶν βασιλέως, ὄγδοος δ’ ἀπὸ Μιθριδάτου τοῦ Μακεδόνων ἀποστάντος τε καὶ κτησαμένου τὴν Ποντικὴν ἀρχήν. ἐβίω δ’ ὀκτὼ ἢ ἐννέα ἐπὶ τοῖς ἑξήκοντα ἔτεσι, καὶ τούτων ἑπτὰ καὶ πεντήκοντα ἔτεσιν ἐβασίλευσεν· ἐς γὰρ ὀρφανὸν ὄντα περιῆλθεν ἡ ἀρχή. ἐχειρώσατο δὲ τὰ περίοικα τῶν βαρβάρων, καὶ Σκυθῶν ὑπηγάγετο πολλούς, Ῥωμαίοις τεσσαρακοντούτη πόλεμον ἐγκρατῶς ἐπολέμησεν, ἐν ᾧ Βιθυνίας ἐκράτησε πολλάκις καὶ Καππαδοκίας, Ἀσίαν τε ἐπέδραμε καὶ Φρυγίαν καὶ Παφλαγονίαν καὶ Γαλατίαν καὶ Μακεδόνας, ἔς τε τὴν Ἑλλάδα ἐμβαλὼν πολλὰ καὶ μεγάλα ἔδρασε, καὶ τῆς θαλάσσης ἀπὸ Κιλικίας ἐπὶ τὸν Ἰόνιον ἦρξε, μέχρι Σύλλας αὐτὸν αὖθις ἐς τὴν πατρῴαν ἀρχὴν συνέκλεισεν, ἑκκαίδεκα στρατοῦ μυριάδας ἀποβαλόντα. καὶ τοσῷδε πταίσματι συμπεσὼν ὅμως ἀνεκίνησε τὸν πόλεμον εὐμαρῶς. στρατηγοῖς τε συνενεχθεὶς ἐς μάχας τοῖς ἀρίστοις, Σύλλα μὲν ἡττᾶτο καὶ Λευκόλλου καὶ Πομπηίου, πολλὰ καὶ τῶνδε πλεονεκτήσας πολλάκις, Λεύκιον δὲ Κάσσιον καὶ Ὄππιον Κόιντον καὶ Μάνιον Ἀκύλιον αἰχμαλώτους ἑλὼν περιήγετο, μέχρι τὸν μὲν ἔκτεινεν, αἴτιον τοῦ πολέμου γενόμενον, τοὺς δὲ ἀπέδωκε τῷ Σύλλᾳ. ἐνίκα δὲ καὶ Φιμβριαν καὶ Μουρήναν καὶ Κότταν ὕπατον καὶ Φάβιον καὶ Τριάριον. τὸ φρόνημα δ’ ἦν ἀεί, κἀν ταῖς συμφοραῖς, μέγας καὶ φερέπονος. οὐδεμίαν γέ τοι κατὰ Ῥωμαίων ὁδὸν ἐς ἐπιχείρησιν, οὐδ’ ἡττώμενος, παρέλειπεν, ὃς καὶ Σαυνιταις καὶ Κελτοῖς συνετίθετο, καὶ ἐς Σερτώριον ἔπεμπεν ἐς Ἰβηρίαν. τρωθείς τε τὸ σῶμα πολλάκις ὑπὸ πολεμίων, καὶ ἑτέρων κατ’ ἐπιβουλάς, οὐκ ἀπέστη τινὸς οὐδ’ ὥς, καίπερ ὢν πρεσβύτης. οὐ μὴν οὐδὲ τῶν ἐπιβουλῶν τις αὐτὸν ἔλαθεν, οὐδ’ ἡ τελευταία, ἀλλ’ ἑκὼν ταύτην ὑπεριδὼν ἀπώλετο δι’ αὐτήν· οὕτως ἀχάριστον ἡ πονηρία συγγνώμης τυγχάνουσα. φονικὸς δὲ καὶ ὠμὸς ἐς πάντας ἦν, καὶ τὴν μητέρα ἔκτεινε καὶ τὸν ἀδελφὸν καὶ τῶν παίδων τρεῖς υἱοὺς καὶ τρεῖς θυγατέρας. τὸ σῶμα δ’ ἦν μέγας μέν, ὡς ὑποδεικνύουσιν ὅσα ὅπλα αὐτὸς ἔπεμψεν ἐς Νεμέαν τε καὶ Δελφούς, εὔρωστος δέ, ὡς μέχρι τέλους ἱππεῦσαί τε καὶ ἀκοντίσαι καὶ χίλια στάδια τῆς ἡμέρας, περιμενόντων αὐτὸν ἐκ διαστημάτων ἵππων, δραμεῖν. καὶ ἅρμα ἤλαυνεν ἑκκαίδεκα ἵππων ὁμοῦ. καὶ παιδείας ἐπεμέλετο Ἑλληνικῆς, διὸ καὶ τῶν ἱερῶν ᾔσθετο τῶν Ἑλληνικῶν, καὶ μουσικὴν ἠγάπα. καὶ σώφρων ἐς πολλὰ καὶ φερέπονος ὢν περὶ μόνας ἡττᾶτο τὰς τῶν γυναικῶν ἡδόνας.", "st": "5.112"}, {"sp": "N", "t": "ὁ μὲν δὴ εὐπάτωρ τε καὶ Διόνυσος ἐπικληθεὶς Μιθριδάτης ὧδε ἐτελεύτα, καὶ Ῥωμαῖοι μαθόντες ἑώρταζον ὡς ἐχθροῦ δυσχεροῦς ἀπηλλαγμένοι· Φαρνάκης δὲ Πομπηίῳ τὸν νέκυν τοῦ πατρὸς ἐς Σινώπην ἐπὶ τριήρους ἔπεμπε, καὶ τοὺς Μάνιον ἑλόντας, ὅμηρά τε πολλὰ ὅσα ἦν Ἑλληνικά τε καὶ βαρβαρικά, δεόμενος ἢ τῆς πατρῴας ἀρχῆς ἢ Βοσπόρου γε βασιλεύειν μόνου, ἥν τινα καὶ Μαχάρης ὁ ἀδελφὸς αὐτοῦ βασιλείαν παρὰ Μιθριδάτου παρειλήφει. Πομπήιος δ’ ἐς μὲν τὸ σῶμα τοῦ Μιθριδάτου χορηγίαν ἔδωκε, καὶ θάψαι βασιλείῳ ταφῇ τοῖς θεραπευτῆρσιν αὐτοῦ προσέταξε, καὶ ἐν Σινώπῃ τοῖς βασιλείοις ἐνθέσθαι τάφοις, ἀγάμενος αὐτὸν τῆς μεγαλουργίας ὡς τῶν καθ’ αὑτὸν βασιλέων ἄριστον· Φαρνάκην δὲ ἀπαλλάξαντα πόνου πολλοῦ τὴν Ἰταλίαν φίλον καὶ σύμμαχον Ῥωμαίοις ἐποιήσατο, καὶ βασιλεύειν ἔδωκεν αὐτῷ Βοσπόρου, χωρὶς Φαναγορέων, οὓς ἐλευθέρους καὶ αὐτονόμους ἀφῆκεν, ὅτι πρῶτοι μάλιστα οἵδε ἀναρρωννυμένῳ τῷ Μιθριδάτῃ, καὶ ναῦς καὶ στρατὸν ἄλλον καὶ ὁρμητήρια ἔχοντι, ἐπεχείρησαν, ἡγεμόνες τε τοῖς ἄλλοις ἀποστάσεως ἐγένοντο, καὶ Μιθριδάτῃ καταλύσεως αἴτιοι.", "st": "5.113"}, {"sp": "N", "t": "αὐτὸς δὲ ἑνὶ τῷδε πολέμῳ τά τε λῃστήρια καθήρας καὶ βασιλέα καθελὼν μέγιστον, καὶ συνενεχθεὶς ἐς μάχας, ἄνευ τοῦ Ποντικοῦ πόλεμου, Κόλχοις τε καὶ Ἀλβανοῖς καὶ Ἴβηρσι καὶ Ἀρμενίοις καὶ Μήδοις καὶ Ἄραψι καὶ Ἰουδαίοις καὶ ἑτέροις ἔθνεσιν ἑῴοις, τὴν ἀρχὴν ὡρίσατο Ῥωμαίοις μέχρι Αἰγύπτου. ἐς δὲ Αἴγυπτον αὐτὴν οὐ παρῆλθε, καίτοι στασιάζουσαν ἐς τὸν βασιλέα, καὶ καλοῦντος αὐτὸν αὐτοῦ βασιλέως, καὶ πέμψαντος αὐτῷ δῶρα καὶ χρήματα καὶ ἐσθῆτας ἐς τὸν στρατὸν ἅπαντα, εἴτε δείσας μέγεθος ἀρχῆς ἔτι εὐτυχούσης, εἴτε φυλαξάμενος ἐχθρῶν φθόνον ἢ χρησμῶν ἀπαγόρευσιν, εἴτε ἑτέροις λογισμοῖς, οὓς ἐξοίσω κατὰ τὰ Αἰγύπτια. τῶν δὲ εἰλημμένων ἐθνῶν τὰ μὲν αὐτόνομα ἠφίει συμμμαχίας οὕνεκα, τὰ δὲ ὑπὸ Ῥωμαίοις εὐθὺς ἐγίγνετο, τὰ δ’ ἐς βασίλεια διεδίδου, Τιγράνει μὲν Ἀρμενίαν καὶ Φαρνάκῃ Βόσπορον καὶ Ἀριοβαρζάνῃ Καππαδοκίαν, καὶ ὅσα προεῖπον ἕτερα. Ἀντιόχῳ δὲ τῷ Κομμαγηνῷ Σελεύκειαν ἐπέτρεψε, καὶ ὅσα τῆς Μεσοποταμίας ἄλλα κατέδραμεν. ἐποίει δὲ καὶ τετράρχας, Γαλλογραικῶν μέν, οἳ νῦν εἰσὶ Γαλάται Καππαδόκαις ὅμοροι, Δηιόταρον καὶ ἑτέρους, Παφλαγονίας δὲ Ἄτταλον καὶ Κόλχων Ἀρίσταρχον δυνάστην. ἀπέφηνε δὲ καὶ τῆς ἐν Κομάνοις θεᾶς Ἀρχέλαον ἱερέα, ὅπερ ἐστὶ δυναστεία βασιλική, καὶ τὸν Φαναγορέα Κάστορα Ῥωμαίων φίλον. πολλὴν δὲ καὶ ἑτέροις χώραν τε καὶ χρήματα ἔδωκεν.", "st": "5.114"}, {"sp": "N", "t": "καὶ πόλεις ᾤκισεν ἐν μὲν Ἀρμενίᾳ τῇ βραχυτέρᾳ Νικόπολιν ἐπὶ τῇ νίκῃ, ἐν δὲ Πόντῳ Εὐπατορίαν, ἣν αὐτὸς μὲν ὁ εὐπάτωρ Μιθριδάτης ἔκτισε καὶ Εὐπατορίαν ὠνόμασεν ἀφ’ ἑαυτοῦ, ὑποδεξαμένην δὲ Ῥωμαίους καθῃρήκει, καὶ ὁ Πομπήιος ἐγείρας Μαγνόπολιν ἐκάλει. ἐν δὲ Καππαδοκίᾳ Μάζακα, ὑπὸ τοῦ πολέμου λελυμασμένην ἐς τέλος, ἤγειρεν αὖθις. καὶ ἑτέρας πολλαχοῦ κατενεχθείσας ἢ βεβλαμμένας διωρθοῦτο περί τε τὸν Πόντον καὶ Παλαιστίνην καὶ κοίλην Συρίαν καὶ Κιλικίαν, ἐν ᾗ δὴ καὶ μάλιστα τοὺς λῃστὰς συνῴκιζε. καὶ ἡ πόλις ἡ πάλαι Σόλοι νῦν Πομπηιόπολις ἐστίν. ἐν δὲ Ταλαύροις, ἥν τινα πόλιν ὁ Μιθριδάτης εἶχε ταμιεῖον τῆς κατασκευῆς, δισχίλια μὲν ἐκπώματα λίθου τῆς ὀνυχίτιδος λεγομένης ηὑρέθη χρυσοκόλλητα, καὶ φιάλαι καὶ ψυκτῆρες πολλοὶ καὶ ῥυτὰ καὶ κλῖναι καὶ θρόνοι κατάκοσμοι, καὶ ἵππων χαλινοὶ καὶ προστερνίδια καὶ ἐπωμίδια, πάντα ὁμοίως διάλιθα καὶ κατάχρυσα, ὧν ἡ παράδοσις διὰ τὸ πλῆθος ἐς τριάκοντα ἡμέρας παρέτεινεν. καὶ ἦν τὰ μὲν ἐκ Δαρείου τοῦ Ὑστάσπου, τὰ δὲ ἐκ τῆς Πτολεμαίων ἀρχῆς, ὅσα Κλεοπάτρα Κῴοις παρέθετο καὶ Κῷοι Μιθριδάτῃ ἐδεδώκεσαν· τὰ δὲ καὶ ὑπ’ αὐτοῦ Μιθριδάτου κατεσκεύαστο καὶ συνείλεκτο, φιλοκάλου καὶ περὶ κατασκευὴν γενομένου.", "st": "5.115"}, {"sp": "N", "t": "λήγοντος δὲ τοῦ χειμῶνος διέδωκεν ὁ Πομπήιος ἀριστεῖα τῷ στρατῷ, καθ’ ἕκαστον ἄνδρα χιλίας πεντακοσίας Ἀττικάς, καὶ τοῖς ἡγουμένοις αὐτῶν ἀνάλογον· καί φασι γενέσθαι τάλαντα μύρια καὶ ἑξακισχίλια. αὐτὸς δ’ ἐς Ἔφεσον καταβὰς διέπλευσεν ἐς τὴν Ἰταλίαν καὶ ἐς Ῥώμην ἠπείγετο, διαφεὶς ἐν Βρεντεσίῳ τὸν στρατὸν ἐς τὰ οἰκεῖα· ἐφ’ ὅτῳ μάλιστα ὡς δημοτικῷ τοὺς Ῥωμαίους ἐξέπληξεν. καὶ αὐτῷ προσιόντι ἀπήντων κατὰ μέρος, πορρωτάτω μὲν οἱ νέοι, ἑξῆς δὲ ὡς ἐδύναντο καθ’ ἡλικίαν ἕκαστοι, καὶ ἐπὶ πᾶσιν ἡ βουλὴ θαυμάζουσα τῶν γεγονότων· οὐ γάρ πώ τις ἐχθρὸν τηλικοῦτον ἑλὼν τοσάδε ὁμοῦ καὶ μέγιστα ἔθνη προσειλήφει, καὶ τὴν Ῥωμαίων ἀρχὴν ἐπὶ τὸν Εὐφράτην ὡρίκει. ὁ δὲ ἐθριάμβευσεν ἐπὶ λαμπροτάτης καὶ ἧς οὔτις πρὸ τοῦ δόξης, ἔτη ἔχων πέντε καὶ τριάκοντα, δύο ἐφεξῆς ἡμέραις, ἐπὶ πολλοῖς ἔθνεσιν, ἀπό τε τοῦ Πόντου καὶ Ἀρμενίας καὶ Καππαδοκίας καὶ Κιλικίας καὶ Συρίας ὅλης καὶ Ἀλβανῶν καὶ Ἡνιόχων καὶ Ἀχαίων τῶν ἐν Σκύθαις καὶ Ἰβηρίας τῆς ἑῴας. καὶ παρῆγεν ἐς μὲν τοὺς λιμένας ἑπτακοσίας ναῦς ἐντελεῖς, ἐς δὲ τὴν πομπὴν τοῦ θριάμβου ζεύγη καὶ φορεῖα χρυσοφόρα καὶ ἕτερα κόσμου ποικίλου, καὶ τὴν Δαρείου τοῦ Ὑστάσπου κλίνην, καὶ τὸν τοῦ εὐπάτορος αὐτοῦ θρόνον. καὶ σκῆπτρον αὐτοῦ, καὶ εἰκόνα ὀκτάπηχυν ἀπὸ στερεοῦ χρυσίου παρῆγε, καὶ ἐπισήμου ἀργυρίου μυριάδας ἑπτακισχιλίας καὶ πεντακοσίας καὶ δέκα, ἁμάξας δὲ ὅπλων ἀπείρους τὸ πλῆθος, καὶ νεῶν ἔμβολα, καὶ πλῆθος αἰχμαλώτων τε καὶ λῃστῶν, οὐδένα δεδεμένον ἀλλ’ ἐς τὰ πάτρια ἐσταλμένους.", "st": "5.116"}, {"sp": "N", "t": "αὐτοῦ δὲ τοῦ Πομπηίου προῆγον ὅσοι τῶν πεπολεμημένων βασιλέων ἡγεμόνες ἢ παῖδες ἢ στρατηγοὶ ἦσαν, οἱ μὲν αἰχμάλωτοι ὄντες οἱ δὲ ἐς ὁμηρείαν δεδομένοι, τριακόσιοι μάλιστα καὶ εἴκοσι καὶ τέσσαρες. ἔνθα δὴ καὶ ὁ Τιγράνους ἦν παῖς Τιγράνης, καὶ πέντε Μιθριδάτου, Ἀρταφέρνης τε καὶ Κῦρος καὶ Ὀξάθρης καὶ Δαρεῖος καὶ Ξέρξης, καὶ θυγατέρες Ὀρσάβαρίς τε καὶ Εὐπάτρα. παρήγετο δὲ καὶ ὁ Κόλχων σκηπτοῦχος Ὀλθάκης, καὶ Ἰουδαίων βασιλεὺς Ἀριστόβουλος, καὶ οἱ Κιλίκων τύραννοι, καὶ Σκυθῶν βασίλειοι γυναῖκες, καὶ ἡγεμόνες τρεῖς Ἰβήρων καὶ Ἀλβανῶν δύο, καὶ Μένανδρος ὁ Λαοδικεύς, ἵππαρχος τοῦ Μιθριδάτου γενόμενος. τῶν δὲ οὐκ ἀφικομένων εἰκόνες παρεφέροντο, Τιγράνους καὶ Μιθριδάτου, μαχομένων τε καὶ νικωμένων καὶ φευγόντων. Μιθριδάτου δὲ καὶ ἡ πολιορκία, καὶ ἡ νὺξ ὅτε ἔφευγεν, εἴκαστο, καὶ ἡ σιωπή. ἐπὶ τέλει δὲ ἐδείχθη καὶ ὡς ἀπέθανεν αἵ τε παρθένοι αἱ συναποθανεῖν αὐτῷ ἑλόμεναι παρεζωγράφηντο, καὶ τῶν προαποθανόντων υἱέων καὶ θυγατέρων ἦσαν γραφαί, θεῶν τε βαρβαρικῶν εἰκόνες καὶ κόσμοι πάτριοι. παρεφέρετο δὲ καὶ πίναξ ἐγγεγραμμένων τῶνδε· “νῆες ἑάλωσαν χαλκέμβολοι ὀκτακόσιαι· πόλεις ἐκτίσθησαν Καππαδοκῶν ὀκτώ, Κιλίκων δὲ καὶ κοίλης Συρίας εἴκοσι, Παλαιστίνης δὲ ἡ νῦν Σελευκίς· βασιλεῖς ἐνικήθησαν Τιγράνης Ἀρμένιος, Ἀρτώκης Ἴβηρ, Ὀροίζης Ἀλβανός, Δαρεῖος Μῆδος, Ἀρέτας Ναβαταῖος, Ἀντίοχος Κομμαγηνός.” τοσαῦτα μὲν ἐδήλου τὸ διάγραμμα, αὐτὸς δὲ ὁ Πομπήιος ἐπὶ ἅρματος ἦν, καὶ τοῦδε λιθοκολλήτου, χλαμύδα ἔχων, ὥς φασιν, Ἀλεξάνδρου τοῦ Μακεδόνος, εἴ τῳ πίστον ἐστιν· ἔοικε δ’ αὐτὴν εὑρεῖν ἐν Μιθριδάτου, Κῴων παρὰ Κλεοπάτρας λαβόντων. εἵποντο δὲ αὐτῷ μετὰ τὸ ἅρμα οἱ συστρατευσάμενοι τῶν ἡγεμόνων, οἱ μὲν ἐπὶ ἵππων οἱ δὲ πεζοί. παρελθὼν δ’ ἐς τὸ Καπιτώλιον οὐδένα τῶν αἰχμαλώτων ἔκτεινεν ὡς ἕτεροι τῶν θριάμβους παραγόντων, ἀλλ’ ἐς τὰς πατρίδας ἔπεμψε δημοσίοις δαπανήμασι, χωρὶς τῶν βασιλικῶν. καὶ τούτων μόνος Ἀριστόβουλος εὐθὺς ἀνῃρέθη, καὶ Τιγράνης ὕστερον. ὁ μὲν δὴ θρίαμβος ἦν τοιόσδε.", "st": "5.117"}, {"sp": "N", "t": "ὧδε μὲν Ῥωμαῖοι Βιθυνοὺς καὶ Καππαδόκας ὅσα τε αὐτοῖς ὅμορα ἔθνη ἐπὶ τὸν Πόντον κατοικεῖ τὸν Εὔξεινον, βασιλέα Μιθριδάτην τεσσαράκοντα δύο ἔτεσι μάλιστα καθελόντες, ὑπηγάγοντο σφίσιν ὑπήκοα εἶναι. τῷ δὲ αὐτῷ πολέμῳ καὶ Κιλικίας τὰ μήπω σφίσι κατήκοα καὶ Συρίας τήν τε Φοινίκην καὶ κοίλην καὶ Παλαιστίνην καὶ τὴν ἐς τὸ μεσόγειον ἐπὶ ποταμὸν Εὐφράτην, οὐδὲν ἔτι τῷ Μιθριδάτῃ προσήκοντα, ῥύμῃ τῆσδε τῆς νίκης προσέλαβον, καὶ φόρους τοῖς μὲν αὐτίκα τοῖς δὲ ὕστερον ἔταξαν. Παφλαγονίαν τε καὶ Γαλατίαν καὶ Φρυγίαν καὶ τὴν ὅμορον τῇ Φρυγίᾳ Μυσίαν, καὶ ἐπὶ τοῖσδε Λυδίαν καὶ Καρίαν καὶ Ἰωνίαν καὶ ὅσα ἄλλα Ἀσίας τῆς περὶ τὸ Πέργαμόν ἐστι, καὶ τὴν ἀρχαίαν Ἑλλάδα καὶ Μακεδονίαν, Μιθριδάτου περισπάσαντος ὀξέως ἀνελάβοντο· καὶ τοῖς πολλοῖς αὐτῶν, οὔπω σφίσιν ὑποτελέσιν οὖσιν, ἐπέθηκαν φόρους. δι’ ἅ μοι καὶ μάλιστα δοκοῦσι τόνδε τὸν πόλεμον ἡγεῖσθαι μέγαν, καὶ τὴν ἐπ’ αὐτῷ νίκην μεγάλην καλεῖν, καὶ τὸν στρατηγήσαντα Πομπήιον μέγαν τῇ ἰδίᾳ φωνῇ μέχρι νῦν ἐπονομάζειν, ἐθνῶν τε πλήθους ἕνεκα ὧν ἀνέλαβον ἢ προσέλαβον, καὶ χρόνου μήκους, τεσσαρακονταετοῦς γενομένου, τόλμης τε αὐτοῦ Μιθριδάτου καὶ φερεπονίας, δυνατοῦ σφίσιν ἐς ἅπαντα ὀφθέντος,", "st": "5.118"}, {"sp": "N", "t": "ᾧ νῆες μὲν ἦσαν οἰκεῖαι πολλάκις πλείους τετρακοσίων, ἱππεῖς δ’ ἔστιν ὅτε πεντακισμύριοι καὶ πεζῶν μυριάδες πέντε καὶ εἴκοσι καὶ μηχαναὶ καὶ βέλη κατὰ λόγον, συνεμάχουν δὲ βασιλεῖς καὶ δυνάσται ὅ τε Ἀρμένιος καὶ Σκυθῶν τῶν περὶ τὸν Πόντον, ἐπί τε Μαιώτιδα λίμνην καὶ ἀπ’ ἐκείνης ἐπὶ τὸν Θρᾴκιον Βόσπορον περιπλέοντι. ἔς τε τοὺς Ῥωμαίων δυνατούς, στασιάζοντας ἀλλήλοις τότε μάλιστα καὶ Ἰβηρίαν ἀνιστάντας ἐπὶ Ῥωμαίους, περιέπεμπε, καὶ Κελτοῖς φιλίαν ἐτίθετο ὡς καὶ τῇδε ἐσβαλῶν ἐς τὴν Ἰταλίαν, λῃστῶν τε ἐνεπίμπλη τὴν θάλασσαν ἀπὸ Κιλικίας ἐπὶ στήλας Ἡρακλείους, οἳ πάντα ἄμικτα καὶ ἄπλωτα ταῖς πόλεσιν ἐς ἀλλήλους ἐποίουν, καὶ λιμὸν ἐπίπονον ἐξειργάσαντο ἐπὶ πλεῖστον. ὅλως τε οὐδὲν ἀνδρὶ δυνατὸν ἐξέλιπεν ἢ πράττων ἢ διανοούμενος, ὡς μέγιστον δὴ τόδε τὸ κίνημα ἐξ ἀνατολῆς ἐπὶ δύσιν γενόμενον ἐνοχλῆσαι πᾶσιν ὡς ἔπος εἰπεῖν, ἢ πολεμουμένοις ἢ συμμαχοῦσιν ἢ λῃστευομένοις ἢ γειτονεύουσιν. τοσόσδε εἷς οὗτος πόλεμος καὶ ποικίλος ἐγένετο. καὶ ἐς τὰ μάλιστα λήγων συνήνεγκε Ῥωμαίοις· ὡρίσαντο γὰρ ἐπὶ τῷδε τὴν ἡγεμονίαν ἐκ δύσεως ἐπὶ ποταμὸν Εὐφράτην. διελεῖν δ’ αὐτὰ κατὰ ἔθνος οὐκ ἦν, ὁμοῦ τε πραχθέντα καὶ ἀλλήλοις ἀναπεπλεγμένα. ἃ δὲ καὶ ὣς ἐδύνατο αὐτῶν κεχωρίσθαι, κατὰ μέρη τέτακται.", "st": "5.119"}, {"sp": "N", "t": "Φαρνάκης δ’ ἐπολιόρκει Φαναγορέας καὶ τὰ περίοικα τοῦ Βοσπόρου, μέχρι τῶν Φαναγορέων διὰ λιμὸν ἐς μάχην προελθόντων ἐκράτει τῇ μάχῃ, καὶ βλάψας οὐδέν, ἀλλὰ φίλους ποιησάμενος καὶ λαβὼν ὅμηρα, ἀνεχώρει. μετ’ οὐ πολὺ δὲ καὶ Σινώπην εἷλε καὶ Ἀμισὸν ἐνθυμιζόμενος καὶ Καλουίνῳ στρατηγοῦντι ἐπολέμησεν, ᾧ χρόνῳ Πομπήιος καὶ Καῖσαρ ἐς ἀλλήλους ᾖσαν, ἕως αὐτὸν Ἄσανδρος ἐχθρὸς ἴδιος, Ῥωμαίων οὐ σχολαζόντων, ἐξήλασε τῆς Ἀσίας. ἐπολέμησε δὲ καὶ αὐτῷ Καίσαρι καθελόντι Πομπήιον, ἐπανιόντι ἀπ’ Αἰγύπτου, περὶ τὸ Σκότιον ὄρος, ἔνθα ὁ πατὴρ αὐτοῦ Ῥωμαίων τῶν ἀμφὶ Τριάριον ἐκεκρατήκει· καὶ ἡττηθεὶς ἔφευγε σὺν χιλίοις ἱππεῦσιν ἐς Σινώπην. Καίσαρος δ’ αὐτὸν ὑπ’ ἀσχολίας οὐ διώξαντος, ἀλλ’ ἐπιπέμψαντος αὐτῷ Δομίτιον, παραδοὺς τὴν Σινώπην Δομιτίῳ ὑπόσπονδος ἀφείθη μετὰ τῶν ἱππέων. καὶ τοὺς ἵππους ἔκτεινε πολλὰ δυσχεραινόντων τῶν ἱππέων, ναυσὶ δ’ ἐπιβὰς ἐς τὸν Πόντον ἔφυγε, καὶ Σκυθῶν τινας καὶ Σαυροματῶν συναγαγὼν Θεοδοσίαν καὶ Παντικάπαιον κατέλαβεν. ἐπιθεμένου δ’ αὖθις αὐτῷ κατὰ τὸ ἔχθος Ἀσάνδρου, οἱ μὲν ἱππεῖς ἀπορίᾳ τε ἵππων καὶ ἀμαθίᾳ πεζομαχίας ἐνικῶντο, αὐτὸς δὲ ὁ Φαρνάκης μόνος ἠγωνίζετο καλῶς, μέχρι κατατρωθεὶς ἀπέθανε, πεντηκοντούτης ὢν καὶ βασιλεύσας Βοσπόρου πεντεκαίδεκα ἔτεσιν.", "st": "5.120"}, {"sp": "N", "t": "ὧδε μὲν δὴ καὶ Φαρνάκης ἐξέπεσε τῆς ἀρχῆς, καὶ αὐτοῦ τὴν βασιλείαν Γάιος μὲν Καῖσαρ ἔδωκε Μιθριδάτῃ τῷ Περγαμηνῷ συμμαχήσαντί οἱ προθύμως ἐν Αἰγύπτῳ· νῦν δ’ εἰσὶν οἰκεῖοι, Πόντου δὲ καὶ Βιθυνίας πέμπεταί τις ἀπὸ τῆς βουλῆς στρατηγὸς ἐτήσιος τὰ δ’ ἑτέροις ὑπὸ τοῦ Πομπηίου δεδομένα ὁ μὲν Γάιος, ἐπιμεμψάμενος τοῖς ἔχουσιν ὅτι Πομπηίῳ καθ’ αὑτοῦ συνεμάχουν, ὅμως ἐφύλαξε, πλὴν τῆς ἐν Κομάνοις ἱερωσύνης, ἣν ἐς Λυκομήδην μετήνεγκεν ἀπὸ Ἀρχελάου· πάντα δὲ οὐ πολὺ ὕστερον, καὶ τάδε καὶ ὅσα Γάιος Καῖσαρ ἢ Μᾶρκος Ἀντώνιος ἔχειν ἑτέροις ἐδεδώκεσαν, ἐς στρατηγίας Ῥωμαίων περιῆλθεν, ἀπὸ τοῦ Σεβαστοῦ Καίσαρος ἑλόντος Αἴγυπτον, ὀλίγης ἔτι Ῥωμαίων προφάσεως ἐς ἑκάστους δεομένων. ὅθεν αὐτοῖς τῆς ἡγεμονίας ἐπὶ τῷδε τῷ Μιθριδατείῳ πολέμῳ προελθούσης ἔς τε τὸν Πόντον τὸν Εὔξεινον καὶ ἐπὶ ψάμμον τὴν πρὸ Αἰγύπτου καὶ ἐς ποταμὸν Εὐφράτην ἀπὸ Ἰβήρων τῶν παρὰ στήλαις Ἡρακλείοις, εἰκότως ἥ τε νίκη μεγάλη καὶ ὁ στρατηγήσας Πομπήιος μέγας ἐκλήθη. ἔχουσι δ’ αὐτοῖς καὶ Λιβύην, ὅση μέχρι Κυρήνης Κ̔υρήνην γὰρ αὐτὴν Ἀπίων βασιλεὺς τοῦ Λαγιδῶν γένους νόθος ἐν διαθήκαις ἀπέλιπεν̓, Αἴγυπτος ἐς περίοδον τῆς ἐντὸς θαλάσσης ἔτι ἔλειπεν.", "st": "5.121"}], []);})();
